				_startupRegistrationService = StartupRegistrationService.CreateForCurrentUser(executablePath);
				_startupRegistrationService.Synchronize(appSettings.General.RunAtWindowsStartup);
				LexiconStore lexiconStore = LexiconLoader.LoadFromFiles(DictionaryPaths.BuiltinEnglish, DictionaryPaths.BuiltinPersian, DictionaryPaths.UserDictionary, DictionaryPaths.Metadata);
				_userDictionaryService = new UserDictionaryService(lexiconStore);
				_manualConversionReviewService = new ManualConversionReviewService();
				_forcedConversionLearningService = new ForcedConversionLearningService(_userDictionaryService, _manualConversionReviewService);
				_typingAssistantController = new TypingAssistantController(appSettings, lexiconStore);
				_typingAssistantController.ManualConversionUndone += OnManualConversionUndone;
				_typingAssistantController.ManualConversionsCompleted += OnManualConversionsCompleted;
				_typingAssistantController.Start();
				_translationFeature = new TranslationFeature(new TranslationProviderRouter(() => new FoundryLocalTranslationProvider(), () => new AzureTranslationProvider(new WindowsTranslationCredentialStore())), _typingAssistantController.TranslationSelectionEditor, () => _typingAssistantController.GetSettingsSnapshot().Translation, (TranslationSettings translation) =>
				{
					SaveSettings((AppSettings current) => current with
					{
						Translation = translation
					});
				});
				_updateService = new ManifestUpdateService(appSettings.General.UpdateFeedUrl);
				MainWindow mainWindow = new MainWindow(ConvertPreviousWord, () =>
				{
					TranslationActionResult translationActionResult = _translationFeature.UndoLastTranslation();
					return (translationActionResult.State != TranslationActionState.NothingToUndo) ? translationActionResult.Succeeded : _typingAssistantController.UndoLastConversion();
				}, () => _typingAssistantController.ToggleSelectedText(), () => AddSelectedToDictionary(), () =>
