				}, () => _typingAssistantController.GetSettingsSnapshot().General.PersianKeyboardLayout, (PersianKeyboardLayout layout) =>
				{
					SaveSettings((AppSettings s) => s with
					{
						General = s.General with
						{
							PersianKeyboardLayout = layout
