		protected override void OnExit(ExitEventArgs e)
		{
			_trayIconController?.Dispose();
			_updateService?.Dispose();
			_translationFeature?.Dispose();
			if (_typingAssistantController != null)
			{
				_typingAssistantController.ManualConversionUndone -= OnManualConversionUndone;
				_typingAssistantController.ManualConversionsCompleted -= OnManualConversionsCompleted;
			}
			_typingAssistantController?.Dispose();
			_instanceMutex?.ReleaseMutex();
			_instanceMutex?.Dispose();
			base.OnExit(e);
		}

		private void SaveSettings(Func<AppSettings, AppSettings> update)
		{
			if (_typingAssistantController != null && _settingsStore != null)
			{
				AppSettings settingsSnapshot = _typingAssistantController.GetSettingsSnapshot();
				AppSettings appSettings = update(settingsSnapshot);
				_typingAssistantController.UpdateCorrectionSettings(appSettings.Correction);
				_typingAssistantController.UpdateDictionarySettings(appSettings.Dictionary);
				_typingAssistantController.UpdateGeneralSettings(appSettings.General);
				_typingAssistantController.UpdateHotkeys(appSettings.Hotkeys);
				_typingAssistantController.UpdateTranslationSettings(appSettings.Translation);
				_settingsStore.Save(appSettings);
			}
		}

		private StartupRegistrationResult SetStartupRegistration(bool enabled)
		{
			if (_startupRegistrationService == null)
			{
				return new StartupRegistrationResult(IsEnabled: false, Succeeded: false, "Windows startup is not available.");
			}
			StartupRegistrationResult startupRegistrationResult = _startupRegistrationService.SetEnabled(enabled);
			if (startupRegistrationResult.Succeeded)
			{
				SaveSettings((AppSettings settings) => settings with
				{
					General = settings.General with
					{
						RunAtWindowsStartup = enabled
					}
				});
			}
			return startupRegistrationResult;
		}

		private int AddSelectedToDictionary()
		{
			if (_typingAssistantController == null || _userDictionaryService == null)
			{
				return 0;
			}
			string[] array = _typingAssistantController.GetSelectedText().Split(new char[6] { ' ', '\t', '\r', '\n', ',', ';' }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
			if (array.Length != 0)
			{
				int result = _userDictionaryService.AddTerms(array);
				ManualConversionReviewService? manualConversionReviewService = _manualConversionReviewService;
				if (manualConversionReviewService != null)
				{
					manualConversionReviewService.RemoveWords(array);
					return result;
				}
				return result;
			}
			ManualConversionResult latestManualConversion = _typingAssistantController.GetLatestManualConversion(TimeSpan.FromMinutes(10L));
			if ((object)latestManualConversion == null)
			{
				return 0;
			}
			int result2 = _userDictionaryService.AddTerms(new <>z__ReadOnlySingleElementList<string>(latestManualConversion.PersianWord), EntryLanguage.Persian);
			_manualConversionReviewService?.RemoveWords(new <>z__ReadOnlySingleElementList<string>(latestManualConversion.PersianWord));
			_typingAssistantController.ClearLatestManualConversion();
			return result2;
		}

		private bool ConvertPreviousWord()
		{
			return _typingAssistantController?.ConvertPreviousWord() ?? false;
		}

		private void OnManualConversionsCompleted(IReadOnlyList<ManualConversionResult> conversions)
		{
			if (_typingAssistantController != null && _forcedConversionLearningService != null && conversions.Count != 0)
			{
				ForcedConversionLearningResult forcedConversionLearningResult = _forcedConversionLearningService.Process(conversions, _typingAssistantController.GetSettingsSnapshot().Dictionary.AutoAddForcedConversions);
				_lastAutomaticallyAddedWord = forcedConversionLearningResult.AutomaticallyAddedWord;
			}
		}

		private void OnManualConversionUndone(object? sender, ManualConversionResult conversion)
		{
			_manualConversionReviewService?.RemoveWords(new <>z__ReadOnlySingleElementList<string>(conversion.PersianWord));
			if (_lastAutomaticallyAddedWord == null || !string.Equals(_lastAutomaticallyAddedWord, conversion.PersianWord, StringComparison.Ordinal))
			{
				return;
			}
			try
			{
				_userDictionaryService?.RemoveTerms(new <>z__ReadOnlySingleElementList<string>(conversion.PersianWord));
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
			}
			finally
			{
				_lastAutomaticallyAddedWord = null;
			}
		}

		private void ShowSettings(Window window)
		{
			if (!window.IsVisible)
			{
				window.Show();
			}
			if (window.WindowState == WindowState.Minimized)
			{
				window.WindowState = WindowState.Normal;
			}
			window.Activate();
			window.Topmost = true;
			window.Topmost = false;
			window.Focus();
		}

		private void ExitApplication()
		{
			_allowWindowClose = true;
			MainWindow?.Close();
			Shutdown();
		}

