		private async void OnLoaded(object sender, RoutedEventArgs e)
		{
			UpdateEnabledUi(_getEnabled());
			ApplyStartupRegistrationStatus(_getStartupRegistration());
			SelectMode(_getMode());
			MixedDirectionCheckBox.IsChecked = _getMixedDirectionStabilization();
			PersianAmountCheckBox.IsChecked = _getPersianAmountFormatting();
			AutoAddForcedConversionsCheckBox.IsChecked = _getAutoAddForcedConversions();
			UpdateReviewWordCount();
			SelectCapsLockBehavior(_getCapsLockBehavior());
			SelectCapsLockEnglishTypingStyle(_getCapsLockEnglishTypingStyle());
			UpdateCapsLockEnglishTypingStyleAvailability(_getCapsLockBehavior());
			SelectPersianKeyboardLayout(_getPersianKeyboardLayout());
			LoadFontOptions(_getTypingFontFamily());
			LoadHotkeyFields(_getHotkeys());
			LoadTranslationSettings();
			LoadUpdateSettings();
			string text = typeof(MainWindow).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion;
			VersionInfoText.Text = (string.IsNullOrWhiteSpace(text) ? "0.5.0-alpha.1" : text);
			ShowPage("General");
			if (_translationFeature.GetSettings().Enabled)
			{
				await RefreshTranslationModelStatusAsync();
			}
			else
			{
				TranslationModelStatusText.Text = "Translation is off";
			}
			await RefreshApplicationFontTargetsAsync();
			if (_updateService != null && _getAutomaticUpdateChecks())
			{
				await CheckForUpdatesAsync(userInitiated: false);
			}
		}

		private void OnSourceInitialized(object? sender, EventArgs e)
		{
			if (!_enableGlobalHotkeys)
			{
				return;
			}
			_hwndSource = (HwndSource)PresentationSource.FromVisual(this);
			if (_hwndSource == null)
			{
				LogShortcutDiagnostic("Source initialization did not provide an HWND");
				return;
			}
			_hotkeyRegistrar = new GlobalHotkeyRegistrar(_hwndSource.Handle);
			_hwndSource.AddHook(WndProc);
			_activeHotkeys = _getHotkeys();
			if (!TryRegisterHotkeys(_activeHotkeys, out string error))
			{
				LogShortcutDiagnostic(error);
				Title = "CoCo Typing - shortcuts unavailable";
				ShortcutStatusText.Text = error;
			}
			else
			{
				LogShortcutDiagnostic($"Shortcuts registered; Handle={_hwndSource.Handle}");
			}
		}

		private void OnClosed(object? sender, EventArgs e)
		{
			_translationSetupCancellation?.Cancel();
			_manualConversionReviewService.Changed -= OnManualConversionReviewChanged;
			UnregisterHotkeys();
			if (_hwndSource != null)
			{
				_hwndSource.RemoveHook(WndProc);
				_hwndSource = null;
			}
		}

		private nint WndProc(nint hwnd, int msg, nint wParam, nint lParam, ref bool handled)
		{
			if (msg != 786)
			{
				return IntPtr.Zero;
			}
			handled = true;
			if (_isCapturingShortcut)
			{
				return IntPtr.Zero;
			}
			int num = ((IntPtr)wParam).ToInt32();
			if (num == 20486)
			{
				DispatchConvertNonDictionaryWordsAfterModifierReleaseAsync();
			}
			else
			{
				DispatchHotkeyAfterModifierReleaseAsync(num);
			}
			return IntPtr.Zero;
		}

		private void DispatchConvertNonDictionaryWords()
		{
			LogShortcutDiagnostic("Convert non-dictionary words shortcut received");
			LogShortcutDiagnostic(_onConvertNonDictionaryWords() ? "Convert non-dictionary words shortcut completed" : "Convert non-dictionary words shortcut made no change");
		}

		private async Task DispatchConvertNonDictionaryWordsAfterModifierReleaseAsync()
		{
			await WaitForShortcutModifiersReleasedAsync();
			DispatchConvertNonDictionaryWords();
		}

		private async Task DispatchHotkeyAfterModifierReleaseAsync(int hotkeyId)
		{
			await WaitForShortcutModifiersReleasedAsync();
			switch (hotkeyId)
			{
			case 20481:
				_onConvertPreviousWord();
				break;
			case 20482:
				_onUndoLastConversion();
				break;
			case 20483:
				_onToggleSelectedText();
				break;
			case 20484:
				_onAddSelectedToDictionary();
				RefreshWordList();
				break;
			case 20485:
				TranslateSelectionAsync();
				break;
			}
		}

		private static async Task WaitForShortcutModifiersReleasedAsync()
		{
			for (int attempt = 0; attempt < 40; attempt++)
			{
				if (GlobalHotkeyRegistrar.AreShortcutModifiersReleased())
				{
					break;
				}
				await Task.Delay(15);
			}
		}

