		private void ShowSettingsSection(string targetName)
		{
			System.Windows.Controls.Button button = targetName switch
			{
				"TranslationPanel" => SettingsTranslationNavButton, 
				"TypingSettingsPanel" => SettingsTypingNavButton, 
				"ApplicationFontsPanel" => SettingsFontsNavButton, 
				"ShortcutsPanel" => SettingsShortcutsNavButton, 
				_ => SettingsGeneralNavButton, 
			};
			_activeSettingsSectionName = button.Tag?.ToString() ?? "SettingsGeneralPanel";
			bool flag = button == SettingsGeneralNavButton;
			SettingsGeneralPanel.Visibility = ((!flag) ? Visibility.Collapsed : Visibility.Visible);
			UpdatesPanel.Visibility = ((!flag) ? Visibility.Collapsed : Visibility.Visible);
			TranslationPanel.Visibility = ((button != SettingsTranslationNavButton) ? Visibility.Collapsed : Visibility.Visible);
			bool flag2 = button == SettingsTypingNavButton;
			TypingSettingsPanel.Visibility = ((!flag2) ? Visibility.Collapsed : Visibility.Visible);
			LanguageKeyboardPanel.Visibility = ((!flag2) ? Visibility.Collapsed : Visibility.Visible);
			ApplicationFontsPanel.Visibility = ((button != SettingsFontsNavButton) ? Visibility.Collapsed : Visibility.Visible);
			ShortcutsPanel.Visibility = ((button != SettingsShortcutsNavButton) ? Visibility.Collapsed : Visibility.Visible);
			SetActiveSettingsSection(button);
			GeneralSettingsScrollViewer.ScrollToTop();
			GeneralSettingsScrollViewer.Focus();
		}

		private void SetActiveSettingsSection(System.Windows.Controls.Button activeButton)
		{
			System.Windows.Controls.Button[] array = new System.Windows.Controls.Button[5] { SettingsGeneralNavButton, SettingsTranslationNavButton, SettingsTypingNavButton, SettingsFontsNavButton, SettingsShortcutsNavButton };
			foreach (System.Windows.Controls.Button obj in array)
			{
				obj.Style = (Style)obj.FindResource((obj == activeButton) ? "ActiveSettingsSectionNavButton" : "SettingsSectionNavButton");
			}
		}

		private void ShowPage(string page)
		{
			bool flag = string.Equals(page, "General", StringComparison.Ordinal);
			bool flag2 = string.Equals(page, "Dictionary", StringComparison.Ordinal);
			bool flag3 = string.Equals(page, "Help", StringComparison.Ordinal);
			bool flag4 = string.Equals(page, "About", StringComparison.Ordinal);
			PageGeneral.Visibility = ((!flag) ? Visibility.Collapsed : Visibility.Visible);
			PageDictionary.Visibility = ((!flag2) ? Visibility.Collapsed : Visibility.Visible);
			PageHelp.Visibility = ((!flag3) ? Visibility.Collapsed : Visibility.Visible);
			PageAbout.Visibility = ((!flag4) ? Visibility.Collapsed : Visibility.Visible);
			NavGeneral.Style = (Style)FindResource(flag ? "ActiveNavButton" : "NavButton");
			NavDictionary.Style = (Style)FindResource(flag2 ? "ActiveNavButton" : "NavButton");
			NavHelp.Style = (Style)FindResource(flag3 ? "ActiveNavButton" : "NavButton");
			NavAbout.Style = (Style)FindResource(flag4 ? "ActiveNavButton" : "NavButton");
			if (flag2 && _showReviewWords)
			{
				RefreshReviewWordList();
			}
			else if (flag2 && !_dictionaryLoaded)
			{
				RefreshWordList();
			}
			if (flag3)
			{
				ShowHelpLanguage(_showPersianHelp);
			}
			if (flag)
			{
				ShowSettingsSection(_activeSettingsSectionName);
			}
		}

