		private void LoadUpdateSettings()
		{
			AutomaticUpdateCheckBox.IsChecked = _getAutomaticUpdateChecks();
			UpdateChannelComboBox.SelectedIndex = (_getIncludePreviewUpdates() ? 1 : 0);
			UpdateFeedUrlTextBox.Text = _updateService?.FeedUri.AbsoluteUri ?? _getUpdateFeedUrl();
			SetUpdateFeedEditing(isEditing: false);
			CheckForUpdatesButton.IsEnabled = _updateService != null;
			TextBlock updateStatusText = UpdateStatusText;
			string text;
			if (_updateService == null)
			{
				text = "Update checks are unavailable in this build.";
			}
			else
			{
				text = (_getAutomaticUpdateChecks() ? "CoCo Typing checks for updates when it starts." : "Automatic update checks are off.");
			}
			updateStatusText.Text = text;
		}

