		private void OnCancelUpdateFeedClicked(object sender, RoutedEventArgs e)
		{
			UpdateFeedUrlTextBox.Text = _updateService?.FeedUri.AbsoluteUri ?? _getUpdateFeedUrl();
			UpdateFeedUrlValidationText.Visibility = Visibility.Collapsed;
			SetUpdateFeedEditing(isEditing: false);
