		private void OnSaveUpdateFeedClicked(object sender, RoutedEventArgs e)
		{
			if (_updateService == null)
			{
				ShowUpdateFeedValidation("Update checks are unavailable in this build.");
				return;
			}
			if (!_updateService.TrySetFeedUri(UpdateFeedUrlTextBox.Text, out string error))
			{
				ShowUpdateFeedValidation(error);
				UpdateFeedUrlTextBox.Focus();
				UpdateFeedUrlTextBox.SelectAll();
				return;
			}
			string absoluteUri = _updateService.FeedUri.AbsoluteUri;
			UpdateFeedUrlTextBox.Text = absoluteUri;
			_onUpdateFeedUrlChanged(absoluteUri);
			UpdateFeedUrlValidationText.Visibility = Visibility.Collapsed;
			UpdateStatusText.Text = "Update URL saved. Choose Check now to verify it.";
			SetUpdateFeedEditing(isEditing: false);
		}

		private void SetUpdateFeedEditing(bool isEditing)
		{
			UpdateFeedUrlTextBox.IsReadOnly = !isEditing;
			EditUpdateFeedButton.Visibility = (isEditing ? Visibility.Collapsed : Visibility.Visible);
			SaveUpdateFeedButton.Visibility = ((!isEditing) ? Visibility.Collapsed : Visibility.Visible);
			CancelUpdateFeedButton.Visibility = ((!isEditing) ? Visibility.Collapsed : Visibility.Visible);
			if (isEditing)
			{
				UpdateFeedUrlValidationText.Visibility = Visibility.Collapsed;
				UpdateFeedUrlTextBox.Focus();
				UpdateFeedUrlTextBox.SelectAll();
			}
		}

