		private void OnOpenUpdatePageClicked(object sender, RoutedEventArgs e)
		{
			if ((object)_availableUpdatePageUri != null)
			{
				Process.Start(new ProcessStartInfo(_availableUpdatePageUri.AbsoluteUri)
				{
					UseShellExecute = true
				});
			}
		}

		internal async Task CheckForUpdatesAsync(bool userInitiated)
		{
			if (_updateService == null)
			{
				return;
			}
			CheckForUpdatesButton.IsEnabled = false;
			OpenUpdatePageButton.Visibility = Visibility.Collapsed;
			if (userInitiated)
			{
				UpdateStatusText.Text = "Checking for updates...";
			}
			try
			{
				UpdateCheckResult updateCheckResult = await _updateService.CheckAsync(_getIncludePreviewUpdates(), CancellationToken.None);
				if (updateCheckResult.Status == UpdateCheckStatus.UpdateAvailable && (object)updateCheckResult.Release != null)
				{
					_availableUpdatePageUri = updateCheckResult.Release.ReleasePageUri;
					UpdateStatusText.Text = updateCheckResult.Message;
					OpenUpdatePageButton.Visibility = Visibility.Visible;
					_onUpdateAvailable(updateCheckResult);
				}
				else if (userInitiated || updateCheckResult.Status == UpdateCheckStatus.UpToDate)
				{
					UpdateStatusText.Text = updateCheckResult.Message;
				}
			}
			finally
			{
				CheckForUpdatesButton.IsEnabled = true;
			}
		}

