		private async void OnApplyApplicationFontsClicked(object sender, RoutedEventArgs e)
		{
			if (_applicationFontsBusy)
			{
				return;
			}
			string[] array = (from target in _applicationFontTargets
				where target.IsSelected && target.CanApply
				select target.Id).ToArray();
			if (array.Length == 0)
			{
				ApplicationFontSummaryText.Text = "Select at least one available application.";
				return;
			}
			SetApplicationFontsBusy(busy: true);
			try
			{
				IReadOnlyList<ApplicationFontTargetInfo> results = await _applicationFontService.ApplyAsync(array, GetSelectedUiFontId());
				SetApplicationFontsBusy(busy: false);
				await RefreshApplicationFontTargetsAsync();
				ApplicationFontSummaryText.Text = SummarizeApplicationFontResults(results, "Applied");
			}
			finally
			{
				SetApplicationFontsBusy(busy: false);
			}
		}

