		private void OnSelectAllApplicationFontsChanged(object sender, RoutedEventArgs e)
		{
			if (!_applicationFontsInitialized)
			{
				return;
			}
			bool valueOrDefault = SelectAllApplicationFontsCheckBox.IsChecked == true;
			foreach (ApplicationFontTargetItem item in _applicationFontTargets.Where((ApplicationFontTargetItem target) => target.CanApply))
			{
				item.IsSelected = valueOrDefault;
			}
			ApplicationFontTargetsList.Items.Refresh();
		}

		private async Task RefreshApplicationFontTargetsAsync()
		{
			if (_applicationFontsBusy)
			{
				return;
			}
			HashSet<string> selectedIds = (from target in _applicationFontTargets
				where target.IsSelected
				select target.Id).ToHashSet(StringComparer.OrdinalIgnoreCase);
			bool preserveSelection = _applicationFontsInitialized;
			SetApplicationFontsBusy(busy: true);
			try
			{
				_applicationFontTargets = (await _applicationFontService.InspectAsync(GetSelectedUiFontId())).Select((ApplicationFontTargetInfo target) => new ApplicationFontTargetItem
				{
					Id = target.Id,
					DisplayName = target.DisplayName,
					Scope = target.Scope,
					Status = target.Status,
					CanApply = target.CanApply,
					State = target.State,
					IsSelected = (target.CanApply && (!preserveSelection || selectedIds.Contains(target.Id)))
				}).ToArray();
				_applicationFontsInitialized = false;
				ApplicationFontTargetsList.ItemsSource = _applicationFontTargets;
				int num = Enumerable.Count(_applicationFontTargets, (ApplicationFontTargetItem target) => target.CanApply);
				int num2 = Enumerable.Count(_applicationFontTargets, (ApplicationFontTargetItem target) => target.CanApply && target.IsSelected);
				SelectAllApplicationFontsCheckBox.IsEnabled = num > 0;
				SelectAllApplicationFontsCheckBox.IsChecked = num > 0 && num2 == num;
				_applicationFontsInitialized = true;
				int value = Enumerable.Count(_applicationFontTargets, (ApplicationFontTargetItem target) => target.State == ApplicationFontTargetState.ManualSetup);
				int value2 = Enumerable.Count(_applicationFontTargets, (ApplicationFontTargetItem target) => target.State == ApplicationFontTargetState.NotInstalled);
				ApplicationFontSummaryText.Text = $"{num} supported, {value} manual, {value2} not installed";
			}
			finally
			{
				_applicationFontsInitialized = true;
				SetApplicationFontsBusy(busy: false);
			}
		}

