		{
			return (TypingFontFamilyComboBox.SelectedItem as AppFontOption)?.Id ?? "Shabnam";
		}

		private static string SummarizeApplicationFontResults(IReadOnlyList<ApplicationFontTargetInfo> results, string action)
		{
			int num = Enumerable.Count(results, (ApplicationFontTargetInfo result) =>
			{
				ApplicationFontTargetState state = result.State;
				return (uint)state <= 2u;
			});
			int num2 = Enumerable.Count(results, (ApplicationFontTargetInfo result) => result.State == ApplicationFontTargetState.CloseApplication);
			int num3 = results.Count - num - num2;
			List<string> list = new List<string> { $"{action}: {num}" };
			if (num2 > 0)
			{
				list.Add($"close app: {num2}");
			}
			if (num3 > 0)
			{
				list.Add($"failed: {num3}");
			}
			return string.Join(", ", list);
		}

