		private void OnShortcutRecorderFieldPreviewKeyDown(object sender, System.Windows.Input.KeyEventArgs e)
		{
			Key key = ((e.Key == Key.System) ? e.SystemKey : e.Key);
			bool flag = ((key == Key.Return || key == Key.Space) ? true : false);
			if (flag && sender is System.Windows.Controls.TextBox target)
			{
				e.Handled = true;
				OpenShortcutRecorder(target);
			}
		}

		private void OpenShortcutRecorder(System.Windows.Controls.TextBox target)
		{
			if (!_isCapturingShortcut)
			{
				_shortcutCaptureTarget = target;
				_pendingShortcut = null;
				_isCapturingShortcut = true;
				UnregisterHotkeys();
				ShortcutRecorderActionText.Text = (target.Tag as string) ?? "Keyboard command";
				ShortcutRecorderCurrentText.Text = target.Text;
				ShortcutRecorderValueText.Text = "Press keys...";
				ShortcutRecorderFeedbackText.Foreground = (System.Windows.Media.Brush)FindResource("MutedBrush");
				ShortcutRecorderFeedbackText.Text = "Escape also cancels recording.";
				UseRecordedShortcutButton.IsEnabled = false;
				ShortcutRecorderOverlay.Visibility = Visibility.Visible;
				Dispatcher.BeginInvoke((Action)(() =>
				{
					ShortcutRecorderOverlay.Focus();
					Keyboard.Focus(ShortcutRecorderOverlay);
				}), DispatcherPriority.Input);
			}
		}

		private void OnShortcutRecorderOverlayPreviewKeyDown(object sender, System.Windows.Input.KeyEventArgs e)
		{
			Key key = ((e.Key == Key.System) ? e.SystemKey : e.Key);
			if (key == Key.Escape)
			{
				e.Handled = true;
				CloseShortcutRecorder("Shortcut recording cancelled");
			}
			else
			{
				if (Keyboard.FocusedElement is System.Windows.Controls.Button)
				{
					return;
				}
				e.Handled = true;
				if (HotkeyGesture.IsModifierKey(key))
				{
					ShortcutRecorderValueText.Text = FormatModifierPreview(Keyboard.Modifiers);
					ShortcutRecorderFeedbackText.Foreground = (System.Windows.Media.Brush)FindResource("MutedBrush");
					ShortcutRecorderFeedbackText.Text = "Keep holding the modifier keys and press one more key.";
					return;
				}
				if (!HotkeyGesture.TryFormat(key, Keyboard.Modifiers, out string shortcut, out string error))
				{
					_pendingShortcut = null;
					UseRecordedShortcutButton.IsEnabled = false;
					ShortcutRecorderValueText.Text = "Press keys...";
					ShortcutRecorderFeedbackText.Foreground = (System.Windows.Media.Brush)FindResource("WarmBrush");
					ShortcutRecorderFeedbackText.Text = error;
					return;
				}
				System.Windows.Controls.TextBox textBox = GetShortcutFields().FirstOrDefault((System.Windows.Controls.TextBox field) => field != _shortcutCaptureTarget && string.Equals(field.Text.Trim(), shortcut, StringComparison.OrdinalIgnoreCase));
				if (textBox != null)
				{
					_pendingShortcut = null;
					UseRecordedShortcutButton.IsEnabled = false;
					ShortcutRecorderValueText.Text = shortcut.Replace("+", " + ", StringComparison.Ordinal);
					ShortcutRecorderFeedbackText.Foreground = (System.Windows.Media.Brush)FindResource("WarmBrush");
					ShortcutRecorderFeedbackText.Text = $"Already used by {textBox.Tag}.";
				}
				else
				{
					_pendingShortcut = shortcut;
					ShortcutRecorderValueText.Text = shortcut.Replace("+", " + ", StringComparison.Ordinal);
					ShortcutRecorderFeedbackText.Foreground = (System.Windows.Media.Brush)FindResource("AccentBrush");
					ShortcutRecorderFeedbackText.Text = "Shortcut ready.";
					UseRecordedShortcutButton.IsEnabled = true;
				}
			}
		}

		private void OnCancelShortcutRecorderClicked(object sender, RoutedEventArgs e)
		{
			CloseShortcutRecorder("Shortcut recording cancelled");
		}

		private void OnUseRecordedShortcutClicked(object sender, RoutedEventArgs e)
		{
			if (_shortcutCaptureTarget != null && !string.IsNullOrWhiteSpace(_pendingShortcut))
			{
				string pendingShortcut = _pendingShortcut;
				_shortcutCaptureTarget.Text = pendingShortcut;
				CloseShortcutRecorder("Captured " + pendingShortcut + ". Save shortcuts to apply changes.");
			}
		}

		private void CloseShortcutRecorder(string status)
		{
			ShortcutRecorderOverlay.Visibility = Visibility.Collapsed;
			_shortcutCaptureTarget = null;
			_pendingShortcut = null;
			_isCapturingShortcut = false;
			Keyboard.ClearFocus();
			ShortcutStatusText.Foreground = (System.Windows.Media.Brush)FindResource("AccentBrush");
			ShortcutStatusText.Text = status;
			UnregisterHotkeys();
			if (!TryRegisterHotkeys(_activeHotkeys, out string error))
			{
				ShortcutStatusText.Foreground = (System.Windows.Media.Brush)FindResource("WarmBrush");
				ShortcutStatusText.Text = error;
			}
		}

		private IReadOnlyList<System.Windows.Controls.TextBox> GetShortcutFields()
		{
			return new <>z__ReadOnlyArray<System.Windows.Controls.TextBox>(new System.Windows.Controls.TextBox[6] { ConvertPreviousWordShortcut, UndoShortcut, ToggleSelectionShortcut, AddSelectionShortcut, TranslateSelectionShortcut, ConvertNonDictionaryWordsShortcut });
		}

		private static string FormatModifierPreview(ModifierKeys modifiers)
		{
			List<string> list = new List<string>(4);
			if (modifiers.HasFlag(ModifierKeys.Control))
			{
				list.Add("Ctrl");
			}
			if (modifiers.HasFlag(ModifierKeys.Alt))
			{
				list.Add("Alt");
			}
			if (modifiers.HasFlag(ModifierKeys.Shift))
			{
				list.Add("Shift");
			}
			if (modifiers.HasFlag(ModifierKeys.Windows))
			{
				list.Add("Win");
			}
			if (list.Count == 0)
			{
				return "Press keys...";
			}
			return string.Join(" + ", list) + " + ...";
		}

		private void OnAddWordClicked(object sender, RoutedEventArgs e)
		{
			IReadOnlyList<string> readOnlyList = SplitTerms(NewWordBox.Text);
			if (readOnlyList.Count == 0)
			{
				DictStatusText.Text = "Enter one or more words";
				return;
			}
			Guid? editingEntryId = _editingEntryId;
			if (editingEntryId.HasValue)
			{
				Guid editingId = editingEntryId.GetValueOrDefault();
				if (readOnlyList.Count != 1)
				{
					DictStatusText.Text = "Edit one word at a time";
					return;
				}
				SmartInput.Core.Dictionaries.DictionaryEntry dictionaryEntry = _userDictionaryService.GetAll().FirstOrDefault((SmartInput.Core.Dictionaries.DictionaryEntry entry) => entry.Id == editingId);
				if ((object)dictionaryEntry == null)
				{
					CancelDictionaryEdit();
					DictStatusText.Text = "The word no longer exists";
					return;
				}
				EntryLanguage entryLanguage = GetSelectedLanguage() ?? UserDictionaryService.DetectLanguage(readOnlyList[0]);
				bool flag = entryLanguage != dictionaryEntry.Language;
				SmartInput.Core.Dictionaries.DictionaryEntry dictionaryEntry2 = dictionaryEntry with
				{
					Term = readOnlyList[0],
					Language = entryLanguage,
					PreventConversion = (flag ? (entryLanguage == EntryLanguage.English) : dictionaryEntry.PreventConversion)
				};
				if (!_userDictionaryService.Update(dictionaryEntry2))
				{
					DictStatusText.Text = "Another entry already uses this word";
					return;
				}
				CancelDictionaryEdit();
				RefreshWordList();
				DictStatusText.Text = "Updated " + dictionaryEntry2.Term;
			}
			else
			{
				EntryLanguage? selectedLanguage = GetSelectedLanguage();
				int num = _userDictionaryService.AddTerms(readOnlyList, selectedLanguage);
				NewWordBox.Clear();
				RefreshWordList();
				DictStatusText.Text = ((num == 0) ? "Already in dictionary" : $"Added {num} word{((num == 1) ? string.Empty : "s")}");
			}
		}

