		private int AddReviewCandidates(IReadOnlyCollection<ManualConversionCandidate> candidates)
		{
			if (candidates.Count == 0)
			{
				return 0;
			}
			int result = _userDictionaryService.AddTerms(candidates.Select((ManualConversionCandidate candidate) => candidate.PersianWord), EntryLanguage.Persian);
			_manualConversionReviewService.RemoveMany(candidates.Select((ManualConversionCandidate candidate) => candidate.Id));
			_dictionaryLoaded = false;
			RefreshReviewWordList();
			return result;
		}

