		private void OnRemoveWordClicked(object sender, RoutedEventArgs e)
		{
			List<DictionaryCatalogItem> list = WordDataGrid.SelectedItems.Cast<DictionaryCatalogItem>().ToList();
			List<DictionaryCatalogItem> list2 = list.Where((DictionaryCatalogItem item) => !item.IsBuiltIn && item.UserEntryId.HasValue).ToList();
			if (list2.Count == 0)
			{
				DictStatusText.Text = "Built-in words are read-only";
			}
			else
			{
				if (System.Windows.MessageBox.Show(this, $"Delete {list2.Count} selected personal word{((list2.Count == 1) ? string.Empty : "s")}? This cannot be undone.", "Delete dictionary words", MessageBoxButton.YesNo, MessageBoxImage.Exclamation, MessageBoxResult.No) != MessageBoxResult.Yes)
				{
					return;
				}
				int num = _userDictionaryService.RemoveMany(list2.Select((DictionaryCatalogItem item) => item.UserEntryId.Value));
				Guid? editingEntryId = _editingEntryId;
				if (editingEntryId.HasValue)
				{
					Guid editingId = editingEntryId.GetValueOrDefault();
					if (list2.Any((DictionaryCatalogItem item) => item.UserEntryId == editingId))
					{
						CancelDictionaryEdit();
					}
				}
				RefreshWordList();
				int num2 = list.Count - list2.Count;
				DictStatusText.Text = ((num2 == 0) ? $"Deleted {num} word{((num == 1) ? string.Empty : "s")}" : $"Deleted {num}; kept {num2} built-in word{((num2 == 1) ? string.Empty : "s")}");
			}
		}

