		private void BeginDictionaryEdit(DictionaryCatalogItem item)
		{
			if (!item.IsBuiltIn)
			{
				Guid? userEntryId = item.UserEntryId;
				if (userEntryId.HasValue)
				{
					Guid id = userEntryId.GetValueOrDefault();
					SmartInput.Core.Dictionaries.DictionaryEntry dictionaryEntry = _userDictionaryService.GetAll().FirstOrDefault((SmartInput.Core.Dictionaries.DictionaryEntry candidate) => candidate.Id == id);
					if ((object)dictionaryEntry != null)
					{
						BeginDictionaryEdit(dictionaryEntry);
					}
					return;
				}
			}
			DictStatusText.Text = "Built-in words are read-only";
		}

