		private void OnImportDictionaryClicked(object sender, RoutedEventArgs e)
		{
			LogDictionaryImport("Import command invoked.");
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Title = "Import dictionary",
				Filter = "Dictionary files (*.json;*.csv;*.txt)|*.json;*.csv;*.txt|CoCo Typing JSON (*.json)|*.json|CSV files (*.csv)|*.csv|Text files (*.txt)|*.txt",
				CheckFileExists = true,
				Multiselect = false
			};
			bool? value = openFileDialog.ShowDialog(this);
			LogDictionaryImport($"File dialog completed with result {value}.");
			if (value != true)
			{
				return;
			}
			try
			{
				DictionaryImportResult dictionaryImportResult = _dictionaryImportService.Import(openFileDialog.FileName, _userDictionaryService);
				RefreshWordList();
				List<string> list = new List<string> { $"Imported {dictionaryImportResult.AddedCount}" };
				if (dictionaryImportResult.DuplicateCount > 0)
				{
					list.Add($"skipped {dictionaryImportResult.DuplicateCount} duplicate{((dictionaryImportResult.DuplicateCount == 1) ? string.Empty : "s")}");
				}
				if (dictionaryImportResult.InvalidCount > 0)
				{
					list.Add($"ignored {dictionaryImportResult.InvalidCount} invalid row{((dictionaryImportResult.InvalidCount == 1) ? string.Empty : "s")}");
				}
				DictStatusText.Text = string.Join("; ", list);
				DictStatusText.ToolTip = dictionaryImportResult.Errors.FirstOrDefault();
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException || ex is NotSupportedException) ? true : false)
			{
				DictStatusText.Text = "Import failed";
				DictStatusText.ToolTip = ex.Message;
				LogDictionaryImport("Import failed: " + ex.Message);
			}
		}

		private void OnExportDictionaryClicked(object sender, RoutedEventArgs e)
		{
			List<SmartInput.Core.Dictionaries.DictionaryEntry> list = (from entry in _userDictionaryService.GetAll()
				orderby entry.Term
				select entry).ToList();
			if (list.Count == 0)
			{
				DictStatusText.Text = "The dictionary is empty";
				return;
			}
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Title = "Export dictionary",
				Filter = "CoCo Typing JSON (*.json)|*.json|CSV files (*.csv)|*.csv|Text files (*.txt)|*.txt",
				DefaultExt = ".json",
				AddExtension = true,
				FileName = $"CoCo-Typing-dictionary-{DateTime.Now:yyyy-MM-dd}.json",
				OverwritePrompt = true
			};
			if (saveFileDialog.ShowDialog(this) != true)
			{
				return;
			}
			try
			{
				int num = _dictionaryExportService.Export(saveFileDialog.FileName, list);
				DictStatusText.Text = $"Exported {num} word{((num == 1) ? string.Empty : "s")}";
				DictStatusText.ToolTip = saveFileDialog.FileName;
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException || ex is NotSupportedException) ? true : false)
			{
				DictStatusText.Text = "Export failed";
				DictStatusText.ToolTip = ex.Message;
			}
		}

		private static void LogDictionaryImport(string message)
		{
