		private bool TryRegisterHotkeys(HotkeySettings settings, out string error)
		{
			error = string.Empty;
			if (_hotkeyRegistrar == null)
			{
				return true;
			}
			(int, string, string)[] array = new (int, string, string)[6]
			{
				(20481, "Convert previous word", settings.ConvertPreviousWord),
				(20482, "Undo last conversion", settings.UndoLastConversion),
				(20483, "Toggle selected text", settings.ToggleSelectedText),
				(20484, "Add selection", settings.AddSelectedToDictionary),
				(20485, "Translate selected text", settings.TranslateSelectedText),
				(20486, "Convert non-dictionary words", settings.ConvertNonDictionaryWords)
			};
			HashSet<HotkeyGesture> hashSet = new HashSet<HotkeyGesture>();
			(int, string, string)[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				var (id, text, text2) = array2[i];
				if (!HotkeyGesture.TryParse(text2, out HotkeyGesture gesture, out string error2))
				{
					error = text + ": " + error2;
					return false;
				}
				if (!hashSet.Add(gesture))
				{
					error = "Duplicate shortcut: " + text2;
					return false;
				}
				if (!_hotkeyRegistrar.Register(id, gesture.Modifiers, gesture.VirtualKey))
				{
					error = "Shortcut unavailable: " + text2;
					return false;
				}
			}
			return true;
		}

		private void UnregisterHotkeys()
		{
			_hotkeyRegistrar?.Unregister(20481);
			_hotkeyRegistrar?.Unregister(20482);
			_hotkeyRegistrar?.Unregister(20483);
			_hotkeyRegistrar?.Unregister(20484);
			_hotkeyRegistrar?.Unregister(20485);
			_hotkeyRegistrar?.Unregister(20486);
		}

