		private void SaveTranslationSettings()
		{
			if (!_loadingTranslationSettings && IsLoaded)
			{
				TranslationSettings settings = _translationFeature.GetSettings();
				bool flag = AzureTranslationConfiguration.TryNormalizeRegion(AzureRegionTextBox.Text, out string region, out string _);
				TranslationSettings translationSettings = settings with
				{
					Enabled = (TranslationEnabledCheckBox.IsChecked == true),
					Provider = (TranslationProviderComboBox.SelectedValue?.ToString() ?? settings.Provider),
					TargetLanguage = (TranslationLanguageComboBox.SelectedValue?.ToString() ?? settings.TargetLanguage),
					ModelAlias = (TranslationModelComboBox.SelectedValue?.ToString() ?? settings.ModelAlias),
					UpdateParagraphDirection = (TranslationDirectionCheckBox.IsChecked == true),
					UndoWithUndoShortcut = (TranslationUndoCheckBox.IsChecked == true),
					AzureRegion = (flag ? region : settings.AzureRegion)
				};
				_translationFeature.UpdateSettings(translationSettings);
				UpdateTranslationControls(translationSettings.Enabled);
				UpdateTranslationProviderUi(translationSettings);
				if (!string.Equals(settings.ModelAlias, translationSettings.ModelAlias, StringComparison.Ordinal))
				{
					TranslationModelStatusText.Text = "Check the selected model";
					TranslationSetupButton.Content = "Set up model";
					TranslationSetupButton.IsEnabled = true;
				}
			}
		}

		private void UpdateTranslationControls(bool enabled)
		{
			TranslationLanguageComboBox.IsEnabled = enabled;
			TranslationProviderComboBox.IsEnabled = enabled;
			TranslationModelComboBox.IsEnabled = enabled && _translationSetupCancellation == null;
			TranslationDirectionCheckBox.IsEnabled = enabled;
			TranslationUndoCheckBox.IsEnabled = enabled;
			AzureApiKeyBox.IsEnabled = enabled;
			AzureRegionTextBox.IsEnabled = enabled;
			SaveAzureCredentialButton.IsEnabled = enabled;
			TestAzureConnectionButton.IsEnabled = enabled && _translationFeature.HasCloudCredential();
		}

		private void UpdateTranslationProviderUi(TranslationSettings settings)
		{
			TranslationProviderOption translationProviderOption = TranslationProviderCatalog.Resolve(settings.Provider);
			bool flag = string.Equals(translationProviderOption.Id, "azure", StringComparison.Ordinal);
			TranslationPrivacyText.Text = translationProviderOption.PrivacyLabel;
			LocalTranslationModelPanel.Visibility = (flag ? Visibility.Collapsed : Visibility.Visible);
			LocalTranslationActionPanel.Visibility = (flag ? Visibility.Collapsed : Visibility.Visible);
			TranslationModelStatusPanel.Visibility = (flag ? Visibility.Collapsed : Visibility.Visible);
			AzureTranslationPanel.Visibility = ((!flag) ? Visibility.Collapsed : Visibility.Visible);
			bool flag2 = _translationFeature.HasCloudCredential();
			TestAzureConnectionButton.IsEnabled = settings.Enabled & flag2;
			SetAzureCredentialStatus(flag2 ? "API key stored securely for this Windows user. Test the connection after changing the region." : "No API key is saved for this Windows user.", flag2 ? SettingsFeedback.Success : SettingsFeedback.Neutral);
		}

		private void OnSaveAzureCredentialClicked(object sender, RoutedEventArgs e)
		{
			string text = AzureApiKeyBox.Password.Trim();
			if (text.Length == 0)
			{
				SetAzureCredentialStatus("Enter Key 1 or Key 2 from the Azure Keys and Endpoint page.", SettingsFeedback.Error);
				AzureApiKeyBox.Focus();
				return;
			}
			if (!AzureTranslationConfiguration.TryNormalizeRegion(AzureRegionTextBox.Text, out string region, out string error))
			{
				SetAzureCredentialStatus(error, SettingsFeedback.Error);
				AzureRegionTextBox.Focus();
				return;
			}
			SaveAzureCredentialButton.IsEnabled = false;
			try
			{
				TranslationSettings settings = _translationFeature.GetSettings() with
				{
					AzureRegion = region
				};
				_translationFeature.UpdateSettings(settings);
				AzureRegionTextBox.Text = region;
				if (!_translationFeature.SaveCloudCredential(text) || !_translationFeature.HasCloudCredential())
				{
					SetAzureCredentialStatus("Windows Credential Manager could not store the API key.", SettingsFeedback.Error);
					return;
				}
				AzureApiKeyBox.Clear();
				TestAzureConnectionButton.IsEnabled = true;
				SetAzureCredentialStatus("Connection details saved securely. Select Test connection to verify the key and region.", SettingsFeedback.Success);
			}
			catch
			{
				SetAzureCredentialStatus("The connection details could not be saved. Try again.", SettingsFeedback.Error);
			}
			finally
			{
				SaveAzureCredentialButton.IsEnabled = TranslationEnabledCheckBox.IsChecked == true;
			}
		}

		private async void OnTestAzureConnectionClicked(object sender, RoutedEventArgs e)
		{
			if (!AzureTranslationConfiguration.TryNormalizeRegion(AzureRegionTextBox.Text, out string region, out string error))
			{
				SetAzureCredentialStatus(error, SettingsFeedback.Error);
				AzureRegionTextBox.Focus();
				return;
			}
			if (!_translationFeature.HasCloudCredential())
			{
				SetAzureCredentialStatus("Save an API key before testing the connection.", SettingsFeedback.Error);
				return;
			}
			TranslationSettings settings = _translationFeature.GetSettings() with
			{
				AzureRegion = region
			};
			_translationFeature.UpdateSettings(settings);
			AzureRegionTextBox.Text = region;
			SaveAzureCredentialButton.IsEnabled = false;
			TestAzureConnectionButton.IsEnabled = false;
			SetAzureCredentialStatus("Testing the Azure connection...", SettingsFeedback.Busy);
			try
			{
				TranslationModelStatus translationModelStatus = await _translationFeature.TestCloudConnectionAsync();
				SetAzureCredentialStatus(translationModelStatus.Message, translationModelStatus.IsReady ? SettingsFeedback.Success : SettingsFeedback.Error);
			}
			catch (OperationCanceledException)
			{
				SetAzureCredentialStatus("Connection test cancelled.", SettingsFeedback.Neutral);
			}
			finally
			{
				SaveAzureCredentialButton.IsEnabled = TranslationEnabledCheckBox.IsChecked == true;
				TestAzureConnectionButton.IsEnabled = TranslationEnabledCheckBox.IsChecked == true && _translationFeature.HasCloudCredential();
			}
		}

		private void OnDeleteAzureCredentialClicked(object sender, RoutedEventArgs e)
		{
			if (!_translationFeature.HasCloudCredential())
			{
				SetAzureCredentialStatus("No API key is currently saved.", SettingsFeedback.Neutral);
			}
			else if (System.Windows.MessageBox.Show(this, "Remove the saved Azure Translator API key from Windows Credential Manager?", "Remove Azure connection", MessageBoxButton.YesNo, MessageBoxImage.Exclamation, MessageBoxResult.No) == MessageBoxResult.Yes)
			{
				try
				{
					_translationFeature.DeleteCloudCredential();
					AzureApiKeyBox.Clear();
					TestAzureConnectionButton.IsEnabled = false;
					SetAzureCredentialStatus("API key removed from Windows Credential Manager.", SettingsFeedback.Neutral);
					TranslationModelStatusText.Text = "Add your Azure Translator API key";
				}
				catch
				{
					SetAzureCredentialStatus("The API key could not be removed. Try again.", SettingsFeedback.Error);
				}
			}
		}

		private void SetAzureCredentialStatus(string message, SettingsFeedback feedback)
		{
			var (resourceKey, resourceKey2, text) = feedback switch
			{
				SettingsFeedback.Success => ("AccentSoftBrush", "AccentBrush", "\ue73e"), 
				SettingsFeedback.Error => ("WarmSoftBrush", "WarmBrush", "\uea39"), 
				SettingsFeedback.Busy => ("InsetBrush", "AccentBrush", "\ue895"), 
				_ => ("InsetBrush", "MutedBrush", "\ue946"), 
			};
			AzureCredentialStatusPanel.Background = (System.Windows.Media.Brush)FindResource(resourceKey);
			AzureCredentialStatusIcon.Foreground = (System.Windows.Media.Brush)FindResource(resourceKey2);
			AzureCredentialStatusIcon.Text = text;
			AzureCredentialStatusText.Foreground = (System.Windows.Media.Brush)FindResource(resourceKey2);
			AzureCredentialStatusText.Text = message;
		}

