		private async void OnSetupTranslationModelClicked(object sender, RoutedEventArgs e)
		{
			if (_translationSetupCancellation != null)
			{
				return;
			}
			bool setupReady = false;
			TranslationModelOption translationModelOption = TranslationModelCatalog.Resolve(_translationFeature.GetSettings().ModelAlias);
			if (System.Windows.MessageBox.Show($"Download the {translationModelOption.DisplayName} local translation model ({translationModelOption.DownloadSize})?\n\n" + "Internet is required only for this setup. Translations run on this computer after the model is cached.", "Set up local translation", MessageBoxButton.YesNo, MessageBoxImage.Asterisk, MessageBoxResult.No) != MessageBoxResult.Yes)
			{
				return;
			}
			_translationSetupCancellation = new CancellationTokenSource();
			TranslationSetupButton.IsEnabled = false;
			TranslationCancelSetupButton.Visibility = Visibility.Visible;
			TranslationProgressBar.Visibility = Visibility.Visible;
			TranslationProgressBar.Value = 0.0;
			UpdateTranslationControls(TranslationEnabledCheckBox.IsChecked == true);
			Progress<float> progress = new Progress<float>((float value) =>
			{
				float value2 = ((value <= 1f) ? (value * 100f) : value);
				TranslationProgressBar.Value = Math.Clamp(value2, 0f, 100f);
				TranslationModelStatusText.Text = $"Downloading {TranslationProgressBar.Value:0}%";
			});
			try
			{
				TranslationModelStatus translationModelStatus = await _translationFeature.SetupModelAsync(progress, _translationSetupCancellation.Token);
				setupReady = translationModelStatus.IsReady;
				ApplyTranslationModelStatus(translationModelStatus);
			}
			catch (OperationCanceledException)
			{
				TranslationModelStatusText.Text = "Model setup cancelled";
			}
			finally
			{
				_translationSetupCancellation.Dispose();
				_translationSetupCancellation = null;
				TranslationSetupButton.IsEnabled = !setupReady;
				TranslationCancelSetupButton.Visibility = Visibility.Collapsed;
				TranslationProgressBar.Visibility = Visibility.Collapsed;
				UpdateTranslationControls(TranslationEnabledCheckBox.IsChecked == true);
			}
		}

		private void OnCancelTranslationSetupClicked(object sender, RoutedEventArgs e)
		{
			_translationSetupCancellation?.Cancel();
		}

		private void ApplyTranslationModelStatus(TranslationModelStatus status)
		{
			TranslationModelStatusText.Text = status.Message;
			TranslationSetupButton.Content = (status.IsReady ? "Model ready" : "Set up model");
			TranslationSetupButton.IsEnabled = !status.IsReady && _translationSetupCancellation == null;
		}

