		}

		private void RefreshWordList()
		{
			_dictionaryPage = _userDictionaryService.QueryCatalog(DictionarySearchBox.Text, GetDictionaryFilterLanguage(), _dictionaryPageIndex, 250);
			if (_dictionaryPageIndex >= _dictionaryPage.PageCount)
			{
				_dictionaryPageIndex = _dictionaryPage.PageCount - 1;
				_dictionaryPage = _userDictionaryService.QueryCatalog(DictionarySearchBox.Text, GetDictionaryFilterLanguage(), _dictionaryPageIndex, 250);
			}
			_dictionaryLoaded = true;
			WordDataGrid.ItemsSource = _dictionaryPage.Items;
			DictionaryPageText.Text = $"Page {_dictionaryPageIndex + 1} of {_dictionaryPage.PageCount}";
			PreviousDictionaryPageButton.IsEnabled = _dictionaryPageIndex > 0;
			NextDictionaryPageButton.IsEnabled = _dictionaryPageIndex + 1 < _dictionaryPage.PageCount;
			UpdateDictionaryActionState();
		}

		private EntryLanguage? GetDictionaryFilterLanguage()
		{
			if (!Enum.TryParse<EntryLanguage>((DictionaryLanguageFilter.SelectedItem as ComboBoxItem)?.Tag?.ToString(), out var result))
			{
				return null;
			}
			return result;
		}

		private void SelectDictionaryLanguage(EntryLanguage language)
		{
			foreach (ComboBoxItem item in NewWordLanguage.Items.OfType<ComboBoxItem>())
			{
				if (string.Equals(item.Tag?.ToString(), language.ToString(), StringComparison.OrdinalIgnoreCase))
				{
					NewWordLanguage.SelectedItem = item;
					break;
				}
			}
		}

		private void UpdateDictionaryActionState()
		{
			int count = WordDataGrid.Items.Count;
			int count2 = WordDataGrid.SelectedItems.Count;
			int num = WordDataGrid.SelectedItems.Cast<DictionaryCatalogItem>().Count((DictionaryCatalogItem item) => !item.IsBuiltIn);
			int count3 = _userDictionaryService.GetAll().Count;
			SelectAllWordsButton.IsEnabled = count > 0;
			SelectAllWordsCheckBox.IsEnabled = count > 0;
			System.Windows.Controls.CheckBox selectAllWordsCheckBox = SelectAllWordsCheckBox;
			bool? isChecked;
			if (count2 != 0)
			{
				isChecked = ((count2 != count) ? ((bool?)null) : new bool?(true));
			}
			else
			{
				isChecked = false;
			}
			selectAllWordsCheckBox.IsChecked = isChecked;
			EditWordButton.IsEnabled = count2 == 1 && num == 1;
			RemoveSelectedWordsButton.IsEnabled = num > 0;
			RemoveAllWordsButton.IsEnabled = count3 > 0;
			ExportDictionaryButton.IsEnabled = count3 > 0;
			SelectionStatusText.Text = ((count2 == 0) ? $"{_dictionaryPage.TotalCount:N0} word{((_dictionaryPage.TotalCount == 1) ? string.Empty : "s")}" : $"{count2} selected on this page");
		}

