			};
			SystemEvents.UserPreferenceChanged += OnUserPreferenceChanged;
			_notifyIcon.DoubleClick += (object? _, EventArgs _) =>
			{
				Guarded(onOpenSettings);
			};
			_notifyIcon.BalloonTipClicked += (object? _, EventArgs _) =>
			{
				Guarded(trayIconController.OnBalloonClicked);
			};
		}

		public void SetLanguage(UiLanguage language)
		{
			language = TextCatalog.Resolve(language);
			if (language != _language)
			{
				_language = language;
				ContextMenuStrip? contextMenuStrip = _notifyIcon.ContextMenuStrip;
				_notifyIcon.ContextMenuStrip = BuildContextMenu(_onOpenSettings, _onCheckForUpdates, _onExit, language, _onTogglePause, _paused);
				_notifyIcon.Text = Tooltip();
				DisposeMenu(contextMenuStrip);
			}
		}

		public void SetPaused(bool paused)
		{
			if (!_disposed && paused != _paused)
			{
				_paused = paused;
				_notifyIcon.Icon = (paused ? _pausedIcon : _applicationIcon);
				_notifyIcon.Text = Tooltip();
				ToolStripItem toolStripItem = _notifyIcon.ContextMenuStrip?.Items["pause"];
				if (toolStripItem != null)
				{
					toolStripItem.Text = PauseLabel(_language, paused);
				}
			}
		}

		internal string Tooltip()
		{
			if (!_paused)
			{
				return "Diyar";
			}
			return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TrayPausedTooltip, _language);
		}

		private static string PauseLabel(UiLanguage language, bool paused)
		{
			return SmartInput.Core.Text.Localization.MessageText.Get(paused ? MessageKey.TrayResume : MessageKey.TrayPause, language);
		}

		private static void DisposeMenu(ContextMenuStrip? menu)
		{
			if (menu != null)
			{
				Font font = menu.Font;
				menu.Dispose();
				font.Dispose();
			}
		}

		internal void OnBalloonClicked()
		{
			_balloonClick?.Invoke();
		}

		internal static ContextMenuStrip BuildContextMenu(Action onOpenSettings, Action onCheckForUpdates, Action onExit, UiLanguage? language = null, Action? onTogglePause = null, bool paused = false)
		{
			UiLanguage uiLanguage = TextCatalog.Resolve(language ?? TextCatalog.Language);
			bool flag = uiLanguage == UiLanguage.Persian;
			ContextMenuStrip contextMenu = new ContextMenuStrip
			{
				RightToLeft = (flag ? RightToLeft.Yes : RightToLeft.No),
				ShowImageMargin = false,
				ShowCheckMargin = false,
				DropShadowEnabled = true,
				Font = MenuFont(flag),
				Padding = new Padding(0, 6, 0, 6),
				ShowItemToolTips = false
			};
			Padding padding = ItemPadding(contextMenu.Font, flag);
			if (onTogglePause != null)
			{
				AddCommand(contextMenu, PauseLabel(uiLanguage, paused), onTogglePause, padding).Name = "pause";
				contextMenu.Items.Add(new ToolStripSeparator
				{
					Margin = new Padding(0, 4, 0, 4)
				});
			}
			AddCommand(contextMenu, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TrayOpen, uiLanguage), onOpenSettings, padding);
			AddCommand(contextMenu, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TrayCheckForUpdates, uiLanguage), onCheckForUpdates, padding);
			contextMenu.Items.Add(new ToolStripSeparator
			{
				Margin = new Padding(0, 4, 0, 4)
			});
			AddCommand(contextMenu, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TrayExit, uiLanguage), onExit, padding);
			contextMenu.Opening += (object? _, CancelEventArgs _) =>
			{
				Guarded(() =>
				{
					contextMenu.Renderer = new TrayMenuRenderer(TrayMenuPalette.ForSystem());
					if (contextMenu.IsHandleCreated)
					{
						WindowCorners.Round(contextMenu.Handle);
					}
				});
			};
			contextMenu.HandleCreated += (object? _, EventArgs _) =>
			{
				Guarded(() =>
				{
					WindowCorners.Round(contextMenu.Handle);
				});
			};
			return contextMenu;
		}

		private static ToolStripMenuItem AddCommand(ContextMenuStrip menu, string text, Action invoke, Padding padding)
		{
			ToolStripMenuItem toolStripMenuItem = new ToolStripMenuItem(text, null, (object? _, EventArgs _) =>
			{
				Guarded(invoke);
			})
			{
				Padding = padding,
				Margin = new Padding(0)
			};
			menu.Items.Add(toolStripMenuItem);
			return toolStripMenuItem;
		}

		internal static Padding ItemPadding(Font font, bool persian)
		{
			var (above, below) = MeasureInk(font, persian);
			var (top, bottom) = BalancedVertical(above, below);
			if (!persian)
			{
				return new Padding(10, top, 28, bottom);
			}
			return new Padding(20, top, 20, bottom);
		}

		internal static (int Top, int Bottom) BalancedVertical(int above, int below)
		{
			int num = Math.Clamp((below - above) / 2, -3, 3);
			return (Top: 7 + num, Bottom: 7 - num);
		}

		internal static (int Above, int Below) MeasureInk(Font font, bool persian)
		{
			string text = (persian ? "Agپژلگ" : "Ag");
			TextFormatFlags flags = (TextFormatFlags)(0x10000020 | (persian ? 131072 : 0));
			try
			{
				System.Drawing.Size size = TextRenderer.MeasureText(text, font, System.Drawing.Size.Empty, flags);
				if (size.Width <= 0 || size.Height <= 0)
				{
					return (Above: 0, Below: 0);
				}
				using Bitmap bitmap = new Bitmap(size.Width, size.Height);
				using (Graphics graphics = Graphics.FromImage(bitmap))
				{
					graphics.Clear(System.Drawing.Color.Black);
					TextRenderer.DrawText(graphics, text, font, new System.Drawing.Rectangle(System.Drawing.Point.Empty, size), System.Drawing.Color.White, System.Drawing.Color.Black, flags);
				}
				int num = -1;
				int num2 = -1;
				for (int i = 0; i < bitmap.Height; i++)
				{
					if (num >= 0)
					{
						break;
					}
					for (int j = 0; j < bitmap.Width; j++)
					{
						if (bitmap.GetPixel(j, i).GetBrightness() > 0.35f)
						{
							num = i;
							break;
						}
					}
				}
				int num3 = bitmap.Height - 1;
				while (num3 >= 0 && num2 < 0)
				{
					for (int k = 0; k < bitmap.Width; k++)
					{
						if (bitmap.GetPixel(k, num3).GetBrightness() > 0.35f)
						{
							num2 = num3;
							break;
						}
					}
					num3--;
				}
				return (num < 0 || num2 < num) ? (Above: 0, Below: 0) : (Above: num, Below: bitmap.Height - 1 - num2);
			}
			catch (Exception ex) when ((ex is ArgumentException || ex is InvalidOperationException || ex is ExternalException) ? true : false)
			{
				return (Above: 0, Below: 0);
			}
		}

		private static Font MenuFont(bool persian = false)
		{
			if (persian)
			{
				Font font = new Font("Shabnam FD", 10f);
				if (string.Equals(font.Name, "Shabnam FD", StringComparison.OrdinalIgnoreCase))
				{
					return font;
				}
				font.Dispose();
				return new Font("Segoe UI", 10f);
			}
			Font font2 = new Font("Segoe UI Variable Text", 10f);
			if (string.Equals(font2.Name, "Segoe UI Variable Text", StringComparison.OrdinalIgnoreCase))
			{
				return font2;
			}
			font2.Dispose();
			return new Font("Segoe UI", 10f);
		}

		public void ShowUpdateAvailable(string version)
		{
			_balloonClick = _onOpenUpdates;
			_notifyIcon.BalloonTipTitle = Balloon(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TrayUpdateTitle));
			_notifyIcon.BalloonTipText = Balloon((_onOpenUpdates == null) ? SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.TrayUpdateText, version) : SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.TrayUpdateClickText, version));
			_notifyIcon.BalloonTipIcon = ToolTipIcon.Info;
			_notifyIcon.ShowBalloonTip(8000);
		}

		public void ShowShortcutNotice(string message)
		{
			_balloonClick = null;
			_notifyIcon.BalloonTipTitle = "Diyar";
			_notifyIcon.BalloonTipText = Balloon(message);
			_notifyIcon.BalloonTipIcon = ToolTipIcon.Info;
			_notifyIcon.ShowBalloonTip(5000);
		}

		internal static string Balloon(string text)
		{
			if (!TextCatalog.IsPersian || text.Length <= 0 || text[0] == '\u200f')
			{
				return text;
			}
			return "\u200f" + text;
		}

		internal static void Guarded(Action action)
		{
			try
			{
				action();
			}
			catch (Exception ex)
			{
				FaultRing.Note(FaultSite.Tray, ex);
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(29, 2, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("A tray handler failed (");
					message.AppendFormatted(ex.GetType().FullName);
					message.AppendLiteral(", 0x");
					message.AppendFormatted(ex.HResult, "X8");
					message.AppendLiteral(").");
				}
				DiagnosticLog.Write("Tray", ref message);
			}
		}

		private void OnUserPreferenceChanged(object? sender, UserPreferenceChangedEventArgs e)
		{
			if (e.Category == UserPreferenceCategory.General)
			{
				Guarded(RefreshIcons);
			}
		}

		private void RefreshIcons()
		{
			Icon applicationIcon = _applicationIcon;
			Icon pausedIcon = _pausedIcon;
			_applicationIcon = LoadApplicationIcon();
			_pausedIcon = TrayPausedIcon.Create(_applicationIcon);
			_notifyIcon.Icon = (_paused ? _pausedIcon : _applicationIcon);
			applicationIcon.Dispose();
			pausedIcon.Dispose();
		}

		public void Dispose()
		{
			_disposed = true;
			SystemEvents.UserPreferenceChanged -= OnUserPreferenceChanged;
			_notifyIcon.Visible = false;
			ContextMenuStrip? contextMenuStrip = _notifyIcon.ContextMenuStrip;
			_notifyIcon.ContextMenuStrip = null;
			DisposeMenu(contextMenuStrip);
			_notifyIcon.Dispose();
			_applicationIcon.Dispose();
			_pausedIcon.Dispose();
		}

		private static Icon LoadApplicationIcon()
		{
			try
			{
				string text = System.IO.Path.Combine(AppContext.BaseDirectory, "Assets", "Branding", TrayIconTheme.FileForSystem());
				if (File.Exists(text))
				{
					return new Icon(text, SystemInformation.SmallIconSize);
				}
			}
			catch (Exception ex) when ((ex is ArgumentException || ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
			}
			try
			{
				if (!string.IsNullOrWhiteSpace(Environment.ProcessPath))
				{
					Icon icon = Icon.ExtractAssociatedIcon(Environment.ProcessPath);
					if (icon != null)
					{
						return icon;
					}
				}
			}
			catch (ArgumentException)
			{
			}
			return (Icon)SystemIcons.Application.Clone();
		}
	}
	internal static class TrayIconTheme
	{
		internal const string Neutral = "diyar-tray.ico";

		internal const string ForLightTaskbar = "diyar-tray-light-theme.ico";

		internal const string ForDarkTaskbar = "diyar-tray-dark-theme.ico";

		internal static string FileFor(int? systemUsesLightTheme)
		{
			if (systemUsesLightTheme.HasValue)
			{
				if (systemUsesLightTheme.GetValueOrDefault() == 0)
				{
					return "diyar-tray-dark-theme.ico";
				}
				return "diyar-tray-light-theme.ico";
			}
			return "diyar-tray.ico";
		}

		internal static string FileForSystem()
		{
			return FileFor(SystemUsesLightTheme());
		}

		private static int? SystemUsesLightTheme()
		{
			try
			{
				using RegistryKey registryKey = Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize");
				return registryKey?.GetValue("SystemUsesLightTheme") as int?;
			}
			catch (Exception ex) when ((ex is SecurityException || ex is UnauthorizedAccessException) ? true : false)
			{
				return null;
			}
		}
	}
	internal sealed record TrayMenuPalette(System.Drawing.Color Background, System.Drawing.Color Border, System.Drawing.Color Text, System.Drawing.Color Hover, System.Drawing.Color Separator)
	{
		private static readonly TrayMenuPalette Dark = new TrayMenuPalette(System.Drawing.Color.FromArgb(43, 43, 43), System.Drawing.Color.FromArgb(58, 58, 58), System.Drawing.Color.FromArgb(255, 255, 255), System.Drawing.Color.FromArgb(59, 59, 59), System.Drawing.Color.FromArgb(56, 56, 56));

		private static readonly TrayMenuPalette Light = new TrayMenuPalette(System.Drawing.Color.FromArgb(249, 249, 249), System.Drawing.Color.FromArgb(229, 229, 229), System.Drawing.Color.FromArgb(27, 27, 27), System.Drawing.Color.FromArgb(237, 237, 237), System.Drawing.Color.FromArgb(224, 224, 224));

		public static TrayMenuPalette ForSystem()
		{
			return ForSystemTheme(AppsUseLightTheme());
		}

		internal static TrayMenuPalette ForSystemTheme(bool appsUseLightTheme)
		{
			if (!appsUseLightTheme)
			{
				return Dark;
			}
			return Light;
		}

		private static bool AppsUseLightTheme()
		{
			try
			{
				using RegistryKey registryKey = Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize");
				return !(registryKey?.GetValue("AppsUseLightTheme") is int num) || num != 0;
			}
			catch (Exception ex) when ((ex is SecurityException || ex is UnauthorizedAccessException) ? true : false)
			{
				return true;
			}
		}
	}
	internal sealed class TrayMenuRenderer(TrayMenuPalette palette) : ToolStripRenderer
	{
		private const int HighlightInset = 4;

		private const int HighlightRadius = 6;

		protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e)
		{
			using SolidBrush brush = new SolidBrush(palette.Background);
			e.Graphics.FillRectangle(brush, e.AffectedBounds);
		}

		protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e)
		{
			using System.Drawing.Pen pen = new System.Drawing.Pen(palette.Border);
			System.Drawing.Rectangle affectedBounds = e.AffectedBounds;
			e.Graphics.DrawRectangle(pen, 0, 0, affectedBounds.Width - 1, affectedBounds.Height - 1);
		}

		protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e)
		{
			if (!e.Item.Selected || !e.Item.Enabled)
			{
				return;
			}
			System.Drawing.Rectangle bounds = new System.Drawing.Rectangle(4, 0, Math.Max(0, e.Item.Bounds.Width - 8), e.Item.Bounds.Height);
			if (bounds.Width <= 0 || bounds.Height <= 0)
			{
				return;
			}
			SmoothingMode smoothingMode = e.Graphics.SmoothingMode;
			e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
			using SolidBrush brush = new SolidBrush(palette.Hover);
			using GraphicsPath path = RoundedRectangle(bounds, 6);
			e.Graphics.FillPath(brush, path);
			e.Graphics.SmoothingMode = smoothingMode;
		}

		protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e)
		{
			e.TextColor = palette.Text;
			if (!string.IsNullOrEmpty(e.Text) && e.TextFont != null)
			{
				int num = InkCentring.Shift(e.Text, e.TextFont, e.TextRectangle, e.TextFormat, e.Item.Height);
				if (num != 0)
				{
					System.Drawing.Rectangle textRectangle = e.TextRectangle;
					textRectangle.Offset(0, num);
					e.TextRectangle = textRectangle;
				}
			}
			base.OnRenderItemText(e);
		}

		protected override void OnRenderSeparator(ToolStripSeparatorRenderEventArgs e)
		{
			using System.Drawing.Pen pen = new System.Drawing.Pen(palette.Separator);
			int num = e.Item.Bounds.Height / 2;
			e.Graphics.DrawLine(pen, 4, num, e.Item.Bounds.Width - 4, num);
		}

		protected override void OnRenderImageMargin(ToolStripRenderEventArgs e)
		{
		}

		private static GraphicsPath RoundedRectangle(System.Drawing.Rectangle bounds, int radius)
		{
			int num = Math.Min(radius * 2, Math.Min(bounds.Width, bounds.Height));
			GraphicsPath graphicsPath = new GraphicsPath();
			if (num <= 0)
			{
				graphicsPath.AddRectangle(bounds);
				return graphicsPath;
			}
			System.Drawing.Rectangle rect = new System.Drawing.Rectangle(bounds.Location, new System.Drawing.Size(num, num));
			graphicsPath.AddArc(rect, 180f, 90f);
			rect.X = bounds.Right - num;
			graphicsPath.AddArc(rect, 270f, 90f);
			rect.Y = bounds.Bottom - num;
			graphicsPath.AddArc(rect, 0f, 90f);
			rect.X = bounds.Left;
			graphicsPath.AddArc(rect, 90f, 90f);
			graphicsPath.CloseFigure();
			return graphicsPath;
		}
	}
	internal static class InkCentring
	{
		private static readonly ConcurrentDictionary<(string, string, float, System.Drawing.FontStyle, System.Drawing.Size, TextFormatFlags), (int First, int Last)> Cache = new ConcurrentDictionary<(string, string, float, System.Drawing.FontStyle, System.Drawing.Size, TextFormatFlags), (int, int)>();

		public static int Shift(string text, Font font, System.Drawing.Rectangle box, TextFormatFlags flags, int rowHeight)
		{
			if (box.Width <= 0 || box.Height <= 0 || rowHeight <= 0)
			{
				return 0;
			}
			var (num, num2) = Cache.GetOrAdd((text, font.Name, font.Size, font.Style, box.Size, flags), ((string, string, float, System.Drawing.FontStyle, System.Drawing.Size, TextFormatFlags) _) => InkRows(text, font, box.Size, flags));
			if (num < 0)
			{
				return 0;
			}
			int value = (int)Math.Round((double)(rowHeight - 1 - (2 * box.Top + num + num2)) / 2.0, MidpointRounding.AwayFromZero);
			int num3 = -(box.Top + num);
			int num4 = rowHeight - 1 - (box.Top + num2);
			if (num3 <= num4)
			{
				return Math.Clamp(value, num3, num4);
			}
			return 0;
		}

		internal static (int First, int Last) InkRows(string text, Font font, System.Drawing.Size size, TextFormatFlags flags)
		{
			try
			{
				using Bitmap bitmap = new Bitmap(size.Width, size.Height);
				using (Graphics graphics = Graphics.FromImage(bitmap))
				{
					graphics.Clear(System.Drawing.Color.Black);
					TextRenderer.DrawText(graphics, text, font, new System.Drawing.Rectangle(System.Drawing.Point.Empty, size), System.Drawing.Color.White, System.Drawing.Color.Black, flags);
				}
				int num = -1;
				int item = -1;
				for (int i = 0; i < bitmap.Height; i++)
				{
					for (int j = 0; j < bitmap.Width; j++)
					{
						if (bitmap.GetPixel(j, i).GetBrightness() > 0.35f)
						{
							if (num < 0)
							{
								num = i;
							}
							item = i;
							break;
						}
					}
				}
				return (First: num, Last: item);
			}
			catch (Exception ex) when ((ex is ArgumentException || ex is InvalidOperationException || ex is ExternalException) ? true : false)
			{
				return (First: -1, Last: -1);
			}
		}
	}
	internal static class WindowCorners
	{
		private const int DwmWindowCornerPreference = 33;

		private const int RoundedPreference = 2;

		[DllImport("dwmapi.dll")]
		private static extern int DwmSetWindowAttribute(nint window, int attribute, ref int value, int size);

		public static void Round(nint window)
		{
			if (window == IntPtr.Zero)
			{
				return;
			}
			try
			{
				int value = 2;
				DwmSetWindowAttribute(window, 33, ref value, 4);
			}
			catch (DllNotFoundException)
			{
			}
			catch (EntryPointNotFoundException)
			{
			}
		}
	}
	internal static class TrayPausedIcon
	{
		private const float Strength = 0.55f;

		[DllImport("user32.dll", SetLastError = true)]
		[return: MarshalAs(UnmanagedType.Bool)]
		private static extern bool DestroyIcon(nint handle);

		public static Icon Create(Icon source)
		{
			try
			{
				using Bitmap bitmap = Render(source);
				nint hicon = bitmap.GetHicon();
				try
				{
					using Icon icon = Icon.FromHandle(hicon);
					return (Icon)icon.Clone();
				}
				finally
				{
					DestroyIcon(hicon);
				}
			}
			catch (Exception ex) when ((ex is ArgumentException || ex is ExternalException || ex is InvalidOperationException) ? true : false)
			{
				return (Icon)source.Clone();
			}
		}

		internal static Bitmap Render(Icon source)
		{
			int num = Math.Max(16, source.Width);
			int num2 = Math.Max(16, source.Height);
			Bitmap bitmap = new Bitmap(num, num2, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
			using Graphics graphics = Graphics.FromImage(bitmap);
			graphics.Clear(System.Drawing.Color.Transparent);
			graphics.SmoothingMode = SmoothingMode.AntiAlias;
			graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
			ColorMatrix colorMatrix = new ColorMatrix(new float[5][]
			{
				new float[5] { 0.3f, 0.3f, 0.3f, 0f, 0f },
				new float[5] { 0.59f, 0.59f, 0.59f, 0f, 0f },
				new float[5] { 0.11f, 0.11f, 0.11f, 0f, 0f },
				new float[5] { 0f, 0f, 0f, 0.55f, 0f },
				new float[5] { 0f, 0f, 0f, 0f, 1f }
			});
			using ImageAttributes imageAttributes = new ImageAttributes();
			imageAttributes.SetColorMatrix(colorMatrix);
			using (Bitmap bitmap2 = source.ToBitmap())
			{
				graphics.DrawImage(bitmap2, new System.Drawing.Rectangle(0, 0, num, num2), 0, 0, bitmap2.Width, bitmap2.Height, GraphicsUnit.Pixel, imageAttributes);
			}
			int num3 = (int)Math.Round((double)Math.Min(num, num2) * 0.56);
			System.Drawing.Rectangle rect = new System.Drawing.Rectangle(num - num3, num2 - num3, num3, num3);
			using (SolidBrush brush = new SolidBrush(System.Drawing.Color.FromArgb(50, 50, 50)))
			{
				graphics.FillEllipse(brush, rect);
			}
			int num4 = Math.Max(2, num3 / 5);
			int num5 = Math.Max(4, num3 / 2);
			int num6 = Math.Max(1, num3 / 8);
			int num7 = rect.X + (num3 - (2 * num4 + num6)) / 2;
			int y = rect.Y + (num3 - num5) / 2;
			using (SolidBrush brush2 = new SolidBrush(System.Drawing.Color.White))
			{
				graphics.FillRectangle(brush2, num7, y, num4, num5);
				graphics.FillRectangle(brush2, num7 + num4 + num6, y, num4, num5);
			}
			return bitmap;
		}
	}
}
namespace SmartInput.App.Services
{
	internal sealed record AppFontOption(string Id, string DisplayName, System.Windows.Media.FontFamily FontFamily);
	internal static class AppFontCatalog
	{
		private sealed record BundledFont(string Id, string DisplayName, string ResourceFamily);

		private static readonly BundledFont[] BundledFonts = new BundledFont[3]
		{
			new BundledFont("Shabnam", "Shabnam (recommended)", "Shabnam"),
			new BundledFont("Shabnam Light", "Shabnam Light", "Shabnam Light"),
			new BundledFont("Shabnam Thin", "Shabnam Thin", "Shabnam Thin")
		};

		public static IReadOnlyList<AppFontOption> GetOptions(Uri applicationBaseUri)
		{
			return CreateOptions(Fonts.SystemFontFamilies, applicationBaseUri);
		}

		internal static IReadOnlyList<AppFontOption> CreateOptions(IEnumerable<System.Windows.Media.FontFamily> systemFonts, Uri applicationBaseUri)
		{
			ArgumentNullException.ThrowIfNull(applicationBaseUri, "applicationBaseUri");
			List<AppFontOption> list = BundledFonts.Select((BundledFont font) => new AppFontOption(font.Id, font.DisplayName, CreateBundledFontFamily(applicationBaseUri, font.ResourceFamily))).ToList();
			HashSet<string> hashSet = new HashSet<string>(list.Select((AppFontOption option) => option.Id), StringComparer.OrdinalIgnoreCase);
			foreach (System.Windows.Media.FontFamily item in systemFonts.OrderBy((System.Windows.Media.FontFamily font) => font.Source, StringComparer.CurrentCultureIgnoreCase))
			{
				if (!string.IsNullOrWhiteSpace(item.Source) && hashSet.Add(item.Source))
				{
					list.Add(new AppFontOption(item.Source, item.Source, item));
				}
			}
			return list;
		}

		public static AppFontOption Resolve(string? fontId, IReadOnlyList<AppFontOption> options)
		{
			if (!string.IsNullOrWhiteSpace(fontId))
			{
				AppFontOption appFontOption = options.FirstOrDefault((AppFontOption option) => string.Equals(option.Id, fontId, StringComparison.OrdinalIgnoreCase));
				if ((object)appFontOption != null)
				{
					return appFontOption;
				}
			}
			return options[0];
		}

		private static System.Windows.Media.FontFamily CreateBundledFontFamily(Uri applicationBaseUri, string familyName)
		{
			return new System.Windows.Media.FontFamily(applicationBaseUri, "./Assets/Fonts/#" + familyName);
		}
	}
	internal sealed class AppSettingsStore
	{
		private static readonly JsonSerializerOptions SerializerOptions = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			WriteIndented = true
		};

		private readonly string _settingsDirectoryPath;

		private readonly string _settingsFilePath;

		private readonly Func<string?> _installerLanguageReader;

		public string? LoadProblem { get; private set; }

		public string DirectoryPath => _settingsDirectoryPath;

		public AppSettingsStore(string? settingsDirectoryPath = null, Func<string?>? installerLanguageReader = null)
		{
			string text = settingsDirectoryPath ?? Environment.GetEnvironmentVariable("SMARTINPUT_SETTINGS_DIRECTORY");
			_installerLanguageReader = installerLanguageReader ?? (string.IsNullOrWhiteSpace(text) ? new Func<string>(InstallerLanguage.ReadRegistryValue) : ((Func<string>)(() => (string?)null)));
			string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
			_settingsDirectoryPath = (string.IsNullOrWhiteSpace(text) ? System.IO.Path.Combine(folderPath, "SmartInput") : text);
			_settingsFilePath = System.IO.Path.Combine(_settingsDirectoryPath, "settings.json");
		}

		public UiLanguage PeekUiLanguage()
		{
			try
			{
				if (!File.Exists(_settingsFilePath))
				{
					return FirstRunUiLanguage();
				}
				using FileStream stream = new FileStream(_settingsFilePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
				using StreamReader streamReader = new StreamReader(stream);
				return TextCatalog.Resolve((JsonSerializer.Deserialize<AppSettings>(streamReader.ReadToEnd(), SerializerOptions)?.General?.UiLanguage).GetValueOrDefault());
			}
			catch
			{
				return UiLanguage.English;
			}
		}

		private UiLanguage FirstRunUiLanguage()
		{
			try
			{
				return InstallerLanguage.Parse(_installerLanguageReader()).GetValueOrDefault();
			}
			catch
			{
				return UiLanguage.English;
			}
		}

		public AppSettings Load()
		{
			LoadProblem = null;
			try
			{
				if (!File.Exists(_settingsFilePath))
				{
					AppSettings appSettings = new AppSettings
					{
						General = new GeneralSettings
						{
							UiLanguage = FirstRunUiLanguage()
						},
						LastWord = new LastWordSettings
						{
							Enabled = true,
							SaveToPersonalDictionary = true
						},
						SelectedWord = new SelectedWordSettings
						{
							SaveToPersonalDictionary = true
						}
					};
					Save(appSettings);
					return appSettings;
				}
				AppSettings appSettings2 = JsonSerializer.Deserialize<AppSettings>(File.ReadAllText(_settingsFilePath), SerializerOptions) ?? throw new JsonException(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.SettingsFileHoldsNoSettings));
				HotkeySettings hotkeySettings = appSettings2.Hotkeys ?? new HotkeySettings();
				CorrectionSettings correctionSettings = appSettings2.Correction ?? new CorrectionSettings();
				DictionarySettings dictionary = appSettings2.Dictionary ?? new DictionarySettings();
				TranslationSettings translation = appSettings2.Translation ?? new TranslationSettings();
				bool flag = false;
				if (string.Equals(hotkeySettings.UndoLastConversion, "Alt+Shift+Z", StringComparison.OrdinalIgnoreCase))
				{
					hotkeySettings = hotkeySettings with
					{
						UndoLastConversion = "Ctrl+Alt+Z"
					};
					flag = true;
				}
				if (string.Equals(hotkeySettings.ConvertPreviousWord, "Ctrl+Space", StringComparison.OrdinalIgnoreCase))
				{
					hotkeySettings = hotkeySettings with
					{
						ConvertPreviousWord = "Ctrl+Alt+Space"
					};
					flag = true;
				}
				if (correctionSettings.UndoBackspaceWindowMs == 3000)
				{
					correctionSettings = correctionSettings with
					{
						UndoBackspaceWindowMs = 1200
					};
					flag = true;
				}
				if (correctionSettings.Mode == CorrectionMode.Safe)
				{
					correctionSettings = correctionSettings with
					{
						Mode = CorrectionMode.Automatic
					};
					flag = true;
				}
				if (correctionSettings.HoldLanguage == HoldLanguage.Persian)
				{
					HoldKeyBindings holdKeyBindings = HoldKeyBindings.From(correctionSettings);
					correctionSettings = correctionSettings with
					{
						EnglishHoldKey = holdKeyBindings.English,
						PersianHoldKey = holdKeyBindings.Persian,
						HoldLanguage = HoldLanguage.English
					};
					flag = true;
				}
				int num = appSettings2.SchemaVersion;
				if (num < 2)
				{
					correctionSettings = correctionSettings with
					{
						AmbiguousInputPriority = AmbiguousInputPriority.Normal
					};
					num = 2;
					flag = true;
				}
				if (!Enum.IsDefined(correctionSettings.AmbiguousInputPriority))
				{
					correctionSettings = correctionSettings with
					{
						AmbiguousInputPriority = AmbiguousInputPriority.Normal
					};
				}
				LastWordSettings lastWordSettings = appSettings2.LastWord ?? new LastWordSettings();
				if (num < 3)
				{
					lastWordSettings = lastWordSettings with
					{
						Enabled = true
					};
					num = 3;
					flag = true;
				}
				GeneralSettings general = appSettings2.General ?? new GeneralSettings();
				CapsLockBehavior capsLockBehavior = CapsLockBehaviorPolicy.Normalize(general.CapsLockBehavior);
				if (capsLockBehavior != general.CapsLockBehavior)
				{
					general = general with
					{
						CapsLockBehavior = capsLockBehavior
					};
					flag = true;
				}
				if (GeneralSettings.RetiredUpdateFeedUrls.Any((string url) => string.Equals(url, general.UpdateFeedUrl?.Trim(), StringComparison.OrdinalIgnoreCase)))
				{
					general = general with
					{
						UpdateFeedUrl = "https://diyar.digital/update.json"
					};
					flag = true;
				}
				if (!Enum.IsDefined(general.UiLanguage))
				{
					general = general with
					{
						UiLanguage = UiLanguage.English
					};
				}
				AppSettings appSettings3 = appSettings2 with
				{
					SchemaVersion = num,
					General = general,
					Hotkeys = hotkeySettings,
					Correction = correctionSettings,
					Dictionary = dictionary,
					Translation = translation,
					LastWord = lastWordSettings,
					SelectedWord = (appSettings2.SelectedWord ?? new SelectedWordSettings())
				};
				if (flag)
				{
					Save(appSettings3);
				}
				return appSettings3;
			}
			catch (JsonException asideUnreadableSettings)
			{
				LoadProblem = SetAsideUnreadableSettings(asideUnreadableSettings);
				return new AppSettings();
			}
			catch
			{
				return new AppSettings();
			}
		}

		private string SetAsideUnreadableSettings(JsonException exception)
		{
			string text = $"settings.json.corrupt-{DateTime.Now:yyyyMMdd-HHmmss}";
			string text2 = SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.SettingsFileUnreadable, exception.Message.TrimEnd('.'));
			try
			{
				File.Move(_settingsFilePath, System.IO.Path.Combine(_settingsDirectoryPath, text), overwrite: true);
				return SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.SettingsFileKeptAs, text2, text, _settingsDirectoryPath);
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
				return SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.SettingsFileNotSetAside, text2);
			}
		}

		public void Save(AppSettings settings)
		{
			Directory.CreateDirectory(_settingsDirectoryPath);
			string text = _settingsFilePath + ".tmp";
			string contents = JsonSerializer.Serialize(settings, SerializerOptions);
			File.WriteAllText(text, contents);
			File.Move(text, _settingsFilePath, overwrite: true);
		}
	}
