	internal sealed class ConversionLearningStore
	{
		private sealed record LearningFile(int SchemaVersion, IReadOnlyList<RejectionRecord>? Rejections, IReadOnlyList<PersianConversionRecord>? PersianConversions = null);

		private sealed record RejectionRecord(string Typed, string SourceLayout, string TargetLayout, int Rejections, DateTimeOffset LastRejectedUtc);

		private sealed record PersianConversionRecord(string Typed, string SourceLayout, string TargetLayout, int Conversions, DateTimeOffset LastConvertedUtc);

		private static readonly JsonSerializerOptions SerializerOptions = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			WriteIndented = true,
			DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull
		};

		private readonly object _sync = new object();

		private readonly string? _path;

		private readonly Dictionary<string, RejectionRecord> _records;

		private readonly Dictionary<string, PersianConversionRecord> _conversions;

		public ConversionLearningStore(string? path)
		{
			_path = path;
			(IReadOnlyList<RejectionRecord>, IReadOnlyList<PersianConversionRecord>) tuple = Load(path);
			_records = tuple.Item1.ToDictionary((RejectionRecord record) => ConversionLearningPolicy.Key(record.Typed, record.SourceLayout, record.TargetLayout), StringComparer.Ordinal);
			_conversions = tuple.Item2.ToDictionary((PersianConversionRecord record) => ConversionLearningPolicy.Key(record.Typed, record.SourceLayout, record.TargetLayout), StringComparer.Ordinal);
		}

		public LearnedPreference RecordRejection(string typed, string sourceLayoutId, string targetLayoutId)
		{
			lock (_sync)
			{
				string key = ConversionLearningPolicy.Key(typed, sourceLayoutId, targetLayoutId);
				int rejections = (_records.TryGetValue(key, out RejectionRecord value) ? value.Rejections : 0) + 1;
				_records[key] = new RejectionRecord(typed.Trim(), sourceLayoutId, targetLayoutId, rejections, DateTimeOffset.UtcNow);
				TrySave();
				return ConversionLearningPolicy.ForRejections(rejections);
			}
		}

		public int AddRejection(string typed, string sourceLayoutId, string targetLayoutId)
		{
			lock (_sync)
			{
				string key = ConversionLearningPolicy.Key(typed, sourceLayoutId, targetLayoutId);
				int num = (_records.TryGetValue(key, out RejectionRecord value) ? value.Rejections : 0) + 1;
				_records[key] = new RejectionRecord(typed.Trim(), sourceLayoutId, targetLayoutId, num, DateTimeOffset.UtcNow);
				TrySave();
				return num;
			}
		}

		public int WithdrawRejection(string typed, string sourceLayoutId, string targetLayoutId)
		{
			lock (_sync)
			{
				string key = ConversionLearningPolicy.Key(typed, sourceLayoutId, targetLayoutId);
				if (!_records.TryGetValue(key, out RejectionRecord value))
				{
					return 0;
				}
				int num = value.Rejections - 1;
				if (num <= 0)
				{
					_records.Remove(key);
				}
				else
				{
					_records[key] = value with
					{
						Rejections = num
					};
				}
				TrySave();
				return Math.Max(num, 0);
			}
		}

		public int AddPersianConversion(string typed, string sourceLayoutId, string targetLayoutId)
		{
			lock (_sync)
			{
				string key = ConversionLearningPolicy.Key(typed, sourceLayoutId, targetLayoutId);
				int num = (_conversions.TryGetValue(key, out PersianConversionRecord value) ? value.Conversions : 0) + 1;
				_conversions[key] = new PersianConversionRecord(typed.Trim(), sourceLayoutId, targetLayoutId, num, DateTimeOffset.UtcNow);
				TrySave();
				return num;
			}
		}

		public int WithdrawPersianConversion(string typed, string sourceLayoutId, string targetLayoutId)
		{
			lock (_sync)
			{
				string key = ConversionLearningPolicy.Key(typed, sourceLayoutId, targetLayoutId);
				if (!_conversions.TryGetValue(key, out PersianConversionRecord value))
				{
					return 0;
				}
				int num = value.Conversions - 1;
				if (num <= 0)
				{
					_conversions.Remove(key);
				}
				else
				{
					_conversions[key] = value with
					{
						Conversions = num
					};
				}
				TrySave();
				return Math.Max(num, 0);
			}
		}

		public int GetPersianConversions(string typed, string sourceLayoutId, string targetLayoutId)
		{
			lock (_sync)
			{
				PersianConversionRecord value;
				return _conversions.TryGetValue(ConversionLearningPolicy.Key(typed, sourceLayoutId, targetLayoutId), out value) ? value.Conversions : 0;
			}
		}

		public void ResetPersianConversions(string typed)
		{
			lock (_sync)
			{
				if (RemoveAll(_conversions, typed) > 0)
				{
					TrySave();
				}
			}
		}

		public void Forget(string typed)
		{
			lock (_sync)
			{
				if (RemoveAll(_records, typed) + RemoveAll(_conversions, typed) > 0)
				{
					TrySave();
				}
			}
		}

		private static int RemoveAll<T>(Dictionary<string, T> records, string typed)
		{
			string suffix = "|" + typed.Trim().ToLowerInvariant();
			List<string> list = records.Keys.Where((string key) => key.EndsWith(suffix, StringComparison.Ordinal) && key.Count((char c) => c == '|') == 2).ToList();
			foreach (string item in list)
			{
				records.Remove(item);
			}
			return list.Count;
		}

		public int GetRejections(string typed, string sourceLayoutId, string targetLayoutId)
		{
			lock (_sync)
			{
				RejectionRecord value;
				return _records.TryGetValue(ConversionLearningPolicy.Key(typed, sourceLayoutId, targetLayoutId), out value) ? value.Rejections : 0;
			}
		}

		private static (IReadOnlyList<RejectionRecord> Rejections, IReadOnlyList<PersianConversionRecord> Conversions) Load(string? path)
		{
			if (path == null || !File.Exists(path))
			{
				return (Rejections: Array.Empty<RejectionRecord>(), Conversions: Array.Empty<PersianConversionRecord>());
			}
			try
			{
				LearningFile? learningFile = JsonSerializer.Deserialize<LearningFile>(File.ReadAllText(path), SerializerOptions);
				List<RejectionRecord> item = learningFile?.Rejections?.Where((RejectionRecord record) => !string.IsNullOrWhiteSpace(record.Typed) && !string.IsNullOrWhiteSpace(record.SourceLayout) && !string.IsNullOrWhiteSpace(record.TargetLayout) && record.Rejections > 0).ToList() ?? new List<RejectionRecord>();
				List<PersianConversionRecord> item2 = learningFile?.PersianConversions?.Where((PersianConversionRecord record) => !string.IsNullOrWhiteSpace(record.Typed) && !string.IsNullOrWhiteSpace(record.SourceLayout) && !string.IsNullOrWhiteSpace(record.TargetLayout) && record.Conversions > 0).ToList() ?? new List<PersianConversionRecord>();
				return (Rejections: item, Conversions: item2);
			}
			catch (Exception ex) when ((ex is JsonException || ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
				return (Rejections: Array.Empty<RejectionRecord>(), Conversions: Array.Empty<PersianConversionRecord>());
			}
		}

		private void TrySave()
		{
			if (_path == null)
			{
				return;
			}
			try
			{
				string directoryName = System.IO.Path.GetDirectoryName(_path);
				if (!string.IsNullOrEmpty(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				string text = _path + ".tmp";
				File.WriteAllText(text, JsonSerializer.Serialize(new LearningFile(1, _records.Values.ToList(), (_conversions.Count == 0) ? null : _conversions.Values.ToList()), SerializerOptions));
				File.Move(text, _path, overwrite: true);
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
			}
		}
	}
	internal interface IManualWordPlan
	{
		bool Allowed { get; }

		string Replacement { get; }

		string Source { get; }

		EntryLanguage DestinationLanguage { get; }
	}
	internal enum CorrectionEditOutcome
	{
		RefusedBeforeMutation,
		CancelledBeforeMutation,
		SubmittedUnverified,
		ConfirmedSuccess,
		FailedOrUncertain
	}
	internal enum CorrectionLearningOutcome
	{
		SkippedSettingOff,
		SkippedNotConfirmed,
		SkippedReversal,
		Added,
		AlreadyInPersonalDictionary,
		AlreadyInBuiltInDictionary,
		RejectedWord,
		ConvertedButNotSaved,
		KeptEnglishForSession
	}
	internal sealed record EnglishLearningRecord(bool Restore, string Keys, bool Forgotten);
	internal sealed record CorrectionLearningResult(CorrectionLearningOutcome Outcome, string Word, EntryLanguage Language, Guid? ContributionId)
	{
		public EnglishLearningRecord? English { get; init; }

		public string Message
		{
			get
			{
				CorrectionLearningOutcome outcome = Outcome;
				if (outcome == CorrectionLearningOutcome.KeptEnglishForSession)
				{
					return SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ConvertedKeptEnglishForSession, Word);
				}
				EnglishLearningRecord english = English;
				if ((object)english == null || !english.Forgotten)
				{
					return outcome switch
					{
						CorrectionLearningOutcome.Added => SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ConvertedAndAdded, Word), 
						CorrectionLearningOutcome.AlreadyInPersonalDictionary => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ConvertedAlreadyPersonal), 
						CorrectionLearningOutcome.AlreadyInBuiltInDictionary => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ConvertedAlreadyBuiltIn), 
						CorrectionLearningOutcome.RejectedWord => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ConvertedNotAdded), 
						CorrectionLearningOutcome.ConvertedButNotSaved => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ConvertedNotSaved), 
						CorrectionLearningOutcome.SkippedReversal => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ConvertedBack), 
						_ => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.Converted), 
					};
				}
				return SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ConvertedAndForgotEnglish, english.Keys);
			}
		}
	}
	internal sealed class CorrectionLearningService(UserDictionaryService dictionary, Func<DiagnosticJournal?> journalSource, string source, EnglishPreferenceLearning? english = null)
	{
		private DiagnosticJournal? journal => journalSource();

		public CorrectionLearningService(UserDictionaryService dictionary, DiagnosticJournal? journal = null, string source = "lastword")
			: this(dictionary, () => journal, source)
		{
		}

		public CorrectionLearningResult Learn(IManualWordPlan plan, CorrectionEditOutcome outcome, bool saveToPersonalDictionary, long operationId)
		{
			string word = plan.Replacement;
			EnglishLearningRecord englishRecord = null;
			if (outcome != CorrectionEditOutcome.ConfirmedSuccess || !plan.Allowed)
			{
				return Done(CorrectionLearningOutcome.SkippedNotConfirmed);
			}
			if (!saveToPersonalDictionary)
			{
				return Done(CorrectionLearningOutcome.SkippedSettingOff);
			}
			try
			{
				EnglishPreferenceLearning englishPreferenceLearning = english;
				DictionaryAddResult dictionaryAddResult;
				if (englishPreferenceLearning != null && englishPreferenceLearning.Enabled && plan.Source.Trim().Length > 0 && plan.DestinationLanguage == EntryLanguage.English)
				{
					EnglishRestoreOutcome englishRestoreOutcome = english.Restored(word, plan.Source, source);
					englishRecord = new EnglishLearningRecord(Restore: true, word.Trim(), Forgotten: false);
					if ((object)englishRestoreOutcome.Added == null)
					{
						return Done(CorrectionLearningOutcome.KeptEnglishForSession);
					}
					dictionaryAddResult = englishRestoreOutcome.Added;
				}
				else
				{
					englishPreferenceLearning = english;
					if (englishPreferenceLearning != null && englishPreferenceLearning.Enabled && plan.Source.Trim().Length > 0 && plan.DestinationLanguage == EntryLanguage.Persian)
					{
						EnglishForgetOutcome englishForgetOutcome = english.ConvertedToPersian(plan.Source, word, source);
						englishRecord = new EnglishLearningRecord(Restore: false, plan.Source.Trim(), englishForgetOutcome.Forgotten);
					}
					dictionaryAddResult = dictionary.AddTermsDetailed(new <>z__ReadOnlySingleElementList<string>(word), plan.DestinationLanguage, autoLearned: true);
				}
				Guid? id = ((dictionaryAddResult.AddedIds.Count + dictionaryAddResult.ConfirmedIds.Count > 0) ? dictionaryAddResult.ContributionId : ((Guid?)null));
				CorrectionLearningResult result;
				if (dictionaryAddResult.Added > 0)
				{
					result = Done(CorrectionLearningOutcome.Added, id);
				}
				else if (dictionaryAddResult.AlreadyBuiltIn > 0)
				{
					result = Done(CorrectionLearningOutcome.AlreadyInBuiltInDictionary);
				}
				else
				{
					result = ((dictionaryAddResult.AlreadyInPersonal > 0) ? Done(CorrectionLearningOutcome.AlreadyInPersonalDictionary, id) : Done(CorrectionLearningOutcome.RejectedWord));
				}
				return result;
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
				return Done(CorrectionLearningOutcome.ConvertedButNotSaved);
			}
			CorrectionLearningResult Done(CorrectionLearningOutcome learning, Guid? contributionId = null)
			{
				journal?.Event(source + ".learning", "operation", operationId, "editOutcome", outcome, "destination", plan.DestinationLanguage, "result", learning, "word", DiagnosticLog.Tail(word, 40), "english", ((object)englishRecord == null) ? "off" : (englishRecord.Restore ? "restore" : (englishRecord.Forgotten ? "forgot" : "conversion")));
				return new CorrectionLearningResult(learning, word, plan.DestinationLanguage, contributionId)
				{
					English = englishRecord
				};
			}
		}

		public bool Withdraw(CorrectionLearningResult contribution, long operationId)
		{
			if (english != null)
			{
				EnglishLearningRecord englishLearningRecord = contribution.English;
				if ((object)englishLearningRecord != null)
				{
					if (englishLearningRecord.Restore)
					{
						english.WithdrawRestore(englishLearningRecord.Keys);
					}
					else
					{
						english.WithdrawConversion(englishLearningRecord.Keys);
					}
				}
			}
			bool flag = false;
			Guid? contributionId = contribution.ContributionId;
			if (contributionId.HasValue)
			{
				Guid valueOrDefault = contributionId.GetValueOrDefault();
				try
				{
					UserDictionaryService.ContributionWithdrawal contributionWithdrawal = dictionary.WithdrawContribution(valueOrDefault);
					flag = contributionWithdrawal.Removed + contributionWithdrawal.Released > 0;
				}
				catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
				{
					flag = false;
				}
			}
			journal?.Event(source + ".withdraw", "operation", operationId, "removed", flag, "word", DiagnosticLog.Tail(contribution.Word, 40));
			return flag;
		}
	}
	internal sealed class DictionaryExportService
	{
		private sealed record DictionaryExportFile(int SchemaVersion, IReadOnlyList<SmartInput.Core.Dictionaries.DictionaryEntry> Entries);

		private static readonly JsonSerializerOptions JsonOptions = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			WriteIndented = true,
			Converters = { (JsonConverter)new JsonStringEnumConverter() }
		};

		public int Export(string path, IReadOnlyList<SmartInput.Core.Dictionaries.DictionaryEntry> entries)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(path, "path");
			ArgumentNullException.ThrowIfNull(entries, "entries");
			File.WriteAllText(path, System.IO.Path.GetExtension(path).ToLowerInvariant() switch
			{
				".json" => SerializeJson(entries), 
				".csv" => SerializeCsv(entries), 
				".txt" => SerializeText(entries), 
				_ => throw new NotSupportedException(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ExportUnsupportedFile)), 
			}, new UTF8Encoding(encoderShouldEmitUTF8Identifier: true));
			return entries.Count;
		}

		private static string SerializeJson(IReadOnlyList<SmartInput.Core.Dictionaries.DictionaryEntry> entries)
		{
			return JsonSerializer.Serialize(new DictionaryExportFile(1, entries), JsonOptions);
		}

		private static string SerializeText(IEnumerable<SmartInput.Core.Dictionaries.DictionaryEntry> entries)
		{
			return string.Join(Environment.NewLine, entries.Select((SmartInput.Core.Dictionaries.DictionaryEntry entry) => entry.Term)) + Environment.NewLine;
		}

		private static string SerializeCsv(IEnumerable<SmartInput.Core.Dictionaries.DictionaryEntry> entries)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("term,language,preventConversion,category,caseSensitive,enabled,autoReturnAfterWord,applicationProcessName,notes");
			foreach (SmartInput.Core.Dictionaries.DictionaryEntry entry in entries)
			{
				InlineArray9<string> buffer = default;
				buffer[0] = EscapeCsv(entry.Term);
				buffer[1] = entry.Language.ToString();
				buffer[2] = entry.PreventConversion.ToString().ToLowerInvariant();
				buffer[3] = entry.Category.ToString();
				buffer[4] = entry.CaseSensitive.ToString().ToLowerInvariant();
				buffer[5] = entry.Enabled.ToString().ToLowerInvariant();
				buffer[6] = entry.AutoReturnAfterWord.ToString().ToLowerInvariant();
				buffer[7] = EscapeCsv(entry.ApplicationProcessName);
				buffer[8] = EscapeCsv(entry.Notes);
				stringBuilder.AppendJoin(',', (ReadOnlySpan<string?>)buffer);
				stringBuilder.AppendLine();
			}
			return stringBuilder.ToString();
		}

		private static string EscapeCsv(string? value)
		{
			if (value == null)
			{
				value = string.Empty;
			}
			if (value.IndexOfAny(new char[4] { ',', '"', '\r', '\n' }) >= 0)
			{
				return "\"" + value.Replace("\"", "\"\"") + "\"";
			}
			return value;
		}
	}
	internal sealed class DictionaryImportService
	{
		private sealed record DictionaryParseResult(IReadOnlyList<SmartInput.Core.Dictionaries.DictionaryEntry> Entries, IReadOnlyList<string> Errors);

		private sealed record DictionaryImportFile(int SchemaVersion, IReadOnlyList<SmartInput.Core.Dictionaries.DictionaryEntry> Entries);

		private static readonly JsonSerializerOptions JsonOptions = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			PropertyNameCaseInsensitive = true,
			Converters = { (JsonConverter)new JsonStringEnumConverter() }
		};

		public DictionaryImportResult Import(string path, UserDictionaryService dictionary)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(path, "path");
			ArgumentNullException.ThrowIfNull(dictionary, "dictionary");
			DictionaryParseResult dictionaryParseResult = System.IO.Path.GetExtension(path).ToLowerInvariant() switch
			{
				".json" => ParseJson(path), 
				".csv" => ParseCsv(path), 
				".txt" => ParseText(path), 
				_ => throw new NotSupportedException(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ImportUnsupportedFile)), 
			};
			DictionaryAddResult dictionaryAddResult = dictionary.AddEntriesDetailed(dictionaryParseResult.Entries);
			int added = dictionaryAddResult.Added;
			int duplicateCount = dictionaryAddResult.AlreadyInPersonal + dictionaryAddResult.AlreadyBuiltIn;
			int invalidCount = dictionaryParseResult.Errors.Count + dictionaryAddResult.RejectedCount;
			IReadOnlyList<string> errors = dictionaryParseResult.Errors;
			IReadOnlyList<string> rejected = dictionaryAddResult.Rejected;
			int num = 0;
			string[] array = new string[errors.Count + rejected.Count];
			foreach (string item in errors)
			{
				array[num] = item;
				num++;
			}
			foreach (string item2 in rejected)
			{
				array[num] = item2;
				num++;
			}
			return new DictionaryImportResult(added, duplicateCount, invalidCount, new <>z__ReadOnlyArray<string>(array))
			{
				AlreadyBuiltInCount = dictionaryAddResult.AlreadyBuiltIn
			};
		}

		private static DictionaryParseResult ParseJson(string path)
		{
			try
			{
				DictionaryImportFile dictionaryImportFile = JsonSerializer.Deserialize<DictionaryImportFile>(File.ReadAllText(path, Encoding.UTF8), JsonOptions);
				if (dictionaryImportFile?.Entries == null)
				{
					return new DictionaryParseResult(Array.Empty<SmartInput.Core.Dictionaries.DictionaryEntry>(), new <>z__ReadOnlySingleElementList<string>(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ImportJsonNoEntries)));
				}
				List<SmartInput.Core.Dictionaries.DictionaryEntry> list = new List<SmartInput.Core.Dictionaries.DictionaryEntry>();
				List<string> errors = new List<string>();
				for (int i = 0; i < dictionaryImportFile.Entries.Count; i++)
				{
					SmartInput.Core.Dictionaries.DictionaryEntry dictionaryEntry = dictionaryImportFile.Entries[i];
					string term = dictionaryEntry.Term?.Trim() ?? string.Empty;
					if (ValidateTerm(term, i + 1, errors))
					{
						list.Add(dictionaryEntry with
						{
							Id = ((dictionaryEntry.Id == Guid.Empty) ? Guid.NewGuid() : dictionaryEntry.Id),
							Term = term,
							AutoLearned = false,
							AutoLearnedBy = null
						});
					}
				}
				return new DictionaryParseResult(list, errors);
			}
			catch (JsonException ex)
			{
				return new DictionaryParseResult(Array.Empty<SmartInput.Core.Dictionaries.DictionaryEntry>(), new <>z__ReadOnlySingleElementList<string>(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ImportJsonError, ex.Message)));
			}
		}

		private static DictionaryParseResult ParseCsv(string path)
		{
			List<SmartInput.Core.Dictionaries.DictionaryEntry> list = new List<SmartInput.Core.Dictionaries.DictionaryEntry>();
			List<string> list2 = new List<string>();
			using TextFieldParser textFieldParser = new TextFieldParser(path, Encoding.UTF8, detectEncoding: true)
			{
				TextFieldType = FieldType.Delimited,
				HasFieldsEnclosedInQuotes = true,
				TrimWhiteSpace = true
			};
			textFieldParser.SetDelimiters(",");
			string[] array;
			try
			{
				array = (textFieldParser.EndOfData ? null : textFieldParser.ReadFields());
			}
			catch (MalformedLineException ex)
			{
				return new DictionaryParseResult(Array.Empty<SmartInput.Core.Dictionaries.DictionaryEntry>(), new <>z__ReadOnlySingleElementList<string>(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ImportHeaderError, ex.Message)));
			}
			if (array == null || array.Length == 0)
			{
				return new DictionaryParseResult(Array.Empty<SmartInput.Core.Dictionaries.DictionaryEntry>(), new <>z__ReadOnlySingleElementList<string>(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ImportCsvNoHeader)));
			}
			Dictionary<string, int> headers = (from item in array.Select((string header, int item) => (Name: NormalizeHeader(header), Index: item))
				where item.Name.Length > 0
				select item).GroupBy(((string Name, int Index) item) => item.Name, StringComparer.OrdinalIgnoreCase).ToDictionary((IGrouping<string, (string Name, int Index)> group) => group.Key, (IGrouping<string, (string Name, int Index)> group) => group.First().Index, StringComparer.OrdinalIgnoreCase);
			if (!TryFindColumn(headers, out var index, "term", "word"))
			{
				return new DictionaryParseResult(Array.Empty<SmartInput.Core.Dictionaries.DictionaryEntry>(), new <>z__ReadOnlySingleElementList<string>(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ImportCsvNoTermColumn, "term", "word")));
			}
			while (!textFieldParser.EndOfData)
			{
				long lineNumber = textFieldParser.LineNumber;
				string[] array2;
				try
				{
					array2 = textFieldParser.ReadFields();
				}
				catch (MalformedLineException ex2)
				{
					list2.Add(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ImportLineError, lineNumber, ex2.Message));
					continue;
				}
				if (array2 == null || array2.All(string.IsNullOrWhiteSpace))
				{
					continue;
				}
				string term = GetField(array2, index).Trim();
				if (!ValidateTerm(term, lineNumber, list2))
				{
					continue;
				}
				if (!TryParseLanguage(GetOptionalField(array2, headers, "language", "lang"), term, out var language) || !TryParseEnum(GetOptionalField(array2, headers, "category"), DictionaryCategory.General, out var result) || !TryParseBoolean(GetOptionalField(array2, headers, "preventconversion", "protected"), language == EntryLanguage.English, out var result2) || !TryParseBoolean(GetOptionalField(array2, headers, "casesensitive"), defaultValue: false, out var result3) || !TryParseBoolean(GetOptionalField(array2, headers, "enabled"), defaultValue: true, out var result4) || !TryParseBoolean(GetOptionalField(array2, headers, "autoreturnafterword"), defaultValue: false, out var result5))
				{
					list2.Add(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ImportLineMetadataInvalid, lineNumber));
					continue;
				}
				string optionalField = GetOptionalField(array2, headers, "language", "lang");
				if (language == EntryLanguage.Neutral && (string.IsNullOrWhiteSpace(optionalField) || optionalField.Equals("auto", StringComparison.OrdinalIgnoreCase)))
				{
					list2.Add(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ImportLineLanguageUnclear, lineNumber));
					continue;
				}
				list.Add(new SmartInput.Core.Dictionaries.DictionaryEntry
				{
					Id = Guid.NewGuid(),
					Term = term,
					Language = language,
					Category = result,
					PreventConversion = result2,
					CaseSensitive = result3,
					Enabled = result4,
					AutoReturnAfterWord = result5,
					ApplicationProcessName = NullIfEmpty(GetOptionalField(array2, headers, "applicationprocessname", "application", "app")),
					Notes = NullIfEmpty(GetOptionalField(array2, headers, "notes", "note"))
				});
			}
			return new DictionaryParseResult(list, list2);
		}

		private static DictionaryParseResult ParseText(string path)
		{
			List<SmartInput.Core.Dictionaries.DictionaryEntry> list = new List<SmartInput.Core.Dictionaries.DictionaryEntry>();
			List<string> list2 = new List<string>();
			int num = 0;
			foreach (string item in File.ReadLines(path, Encoding.UTF8))
			{
				num++;
				string text = item.Trim();
				if (text.Length != 0 && !text.StartsWith('#') && ValidateTerm(text, num, list2))
				{
					EntryLanguage entryLanguage = UserDictionaryService.DetectLanguage(text);
					if (entryLanguage == EntryLanguage.Neutral)
					{
						list2.Add(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ImportLineLanguageUnclearText, num));
						continue;
					}
					list.Add(new SmartInput.Core.Dictionaries.DictionaryEntry
					{
						Id = Guid.NewGuid(),
						Term = text,
						Language = entryLanguage,
						Category = DictionaryCategory.General,
						PreventConversion = (entryLanguage == EntryLanguage.English),
						Enabled = true
					});
				}
			}
			return new DictionaryParseResult(list, list2);
		}

		private static bool ValidateTerm(string term, long lineNumber, ICollection<string> errors)
		{
			if (!DictionaryTermRules.TryNormalize(term, out string _, out string reason))
			{
				errors.Add(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ImportLineRejected, lineNumber, reason));
				return false;
			}
			return true;
		}

		private static bool TryParseLanguage(string? value, string term, out EntryLanguage language)
		{
			if (string.IsNullOrWhiteSpace(value) || value.Equals("auto", StringComparison.OrdinalIgnoreCase))
			{
				language = UserDictionaryService.DetectLanguage(term);
				return true;
			}
			return Enum.TryParse<EntryLanguage>(value, ignoreCase: true, out language);
		}

		private static bool TryParseEnum<T>(string? value, T defaultValue, out T result) where T : struct, Enum
		{
			if (string.IsNullOrWhiteSpace(value))
			{
				result = defaultValue;
				return true;
			}
			return Enum.TryParse<T>(value, ignoreCase: true, out result);
		}

		private static bool TryParseBoolean(string? value, bool defaultValue, out bool result)
		{
			if (string.IsNullOrWhiteSpace(value))
			{
				result = defaultValue;
				return true;
			}
			string text = value.Trim().ToLowerInvariant();
			if (text != null)
			{
				switch (text.Length)
				{
				case 1:
				{
					char c = text[0];
					if ((uint)c <= 49u)
					{
						if (c != '0')
						{
							if (c != '1')
							{
								break;
							}
							goto IL_00a5;
						}
					}
					else if (c != 'n')
					{
						if (c != 'y')
						{
							break;
						}
						goto IL_00a5;
					}
					goto IL_00aa;
				}
				case 4:
					if (!(text == "true"))
					{
						break;
					}
					goto IL_00a5;
				case 3:
					if (!(text == "yes"))
					{
						break;
					}
					goto IL_00a5;
				case 5:
					if (!(text == "false"))
					{
						break;
					}
					goto IL_00aa;
				case 2:
					{
						if (!(text == "no"))
						{
							break;
						}
						goto IL_00aa;
					}
					IL_00aa:
					result = false;
					return true;
					IL_00a5:
					result = true;
					return true;
				}
			}
			result = false;
			return false;
		}

		private static bool TryFindColumn(IReadOnlyDictionary<string, int> headers, out int index, params string[] names)
		{
			foreach (string key in names)
			{
				if (headers.TryGetValue(key, out index))
				{
					return true;
				}
			}
			index = -1;
			return false;
		}

		private static string? GetOptionalField(IReadOnlyList<string> fields, IReadOnlyDictionary<string, int> headers, params string[] names)
		{
			if (!TryFindColumn(headers, out var index, names))
			{
				return null;
			}
			return GetField(fields, index).Trim();
		}

		private static string GetField(IReadOnlyList<string> fields, int index)
		{
			if (index < 0 || index >= fields.Count)
			{
				return string.Empty;
			}
			return fields[index];
		}

		private static string NormalizeHeader(string value)
		{
			return new string(value.Where((char character) =>
			{
				bool flag = ((character == ' ' || character == '-' || character == '_') ? true : false);
				return !flag;
			}).ToArray()).ToLowerInvariant();
		}

		private static string? NullIfEmpty(string? value)
		{
			if (!string.IsNullOrWhiteSpace(value))
			{
				return value.Trim();
			}
			return null;
		}
	}
	internal sealed record DictionaryImportResult(int AddedCount, int DuplicateCount, int InvalidCount, IReadOnlyList<string> Errors)
	{
		public int AlreadyBuiltInCount { get; init; }
	}
	internal static class DictionaryPaths
	{
		private static readonly string RepoRoot = FindRepoRoot();

		public static string BuiltinEnglish { get; } = System.IO.Path.Combine(RepoRoot, "assets", "dictionaries", "builtin-english.txt");

		public static string BuiltinPersian { get; } = System.IO.Path.Combine(RepoRoot, "assets", "dictionaries", "builtin-persian.txt");

		public static string Metadata { get; } = System.IO.Path.Combine(RepoRoot, "assets", "dictionaries", "detection-metadata.json");

		public static string PersianFrequency { get; } = System.IO.Path.Combine(RepoRoot, "assets", "dictionaries", "persian-frequency.txt");

		public static string PersianCommonAdditions { get; } = System.IO.Path.Combine(RepoRoot, "assets", "dictionaries", "persian-common-additions.txt");

		public static string UserDictionary { get; } = GetUserDictionaryPath();

		public static string ManualConversionReview { get; } = GetManualConversionReviewPath();

		public static string ConversionLearning { get; } = GetConversionLearningPath();

		private static string GetConversionLearningPath()
		{
			string environmentVariable = Environment.GetEnvironmentVariable("SMARTINPUT_LEARNING_PATH");
			if (!string.IsNullOrWhiteSpace(environmentVariable))
			{
				return System.IO.Path.GetFullPath(environmentVariable);
			}
			return System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "SmartInput", "conversion-learning.json");
		}

		private static string GetUserDictionaryPath()
		{
			string environmentVariable = Environment.GetEnvironmentVariable("SMARTINPUT_USER_DICTIONARY_PATH");
			if (!string.IsNullOrWhiteSpace(environmentVariable))
			{
				return System.IO.Path.GetFullPath(environmentVariable);
			}
			return System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "SmartInput", "user-dictionary.json");
		}

		private static string GetManualConversionReviewPath()
		{
			string environmentVariable = Environment.GetEnvironmentVariable("SMARTINPUT_REVIEW_QUEUE_PATH");
			if (!string.IsNullOrWhiteSpace(environmentVariable))
			{
				return System.IO.Path.GetFullPath(environmentVariable);
			}
			return System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "SmartInput", "manual-conversion-review.json");
		}

		private static string FindRepoRoot()
		{
			string text = AppContext.BaseDirectory;
			for (int i = 0; i < 10; i++)
			{
				if (Directory.Exists(System.IO.Path.Combine(text, "assets", "dictionaries")))
				{
					return text;
				}
				string text2 = Directory.GetParent(text)?.FullName;
				if (text2 == null || text2 == text)
				{
					break;
				}
				text = text2;
			}
			return AppContext.BaseDirectory;
		}
	}
	internal static class DictionaryTermRules
	{
		public const int MaxLength = 128;

		private static readonly char[] EdgeMarks = new char[12]
		{
			'\u200e', '\u200f', '\u202a', '\u202b', '\u202c', '\u202d', '\u202e', '\u2066', '\u2067', '\u2068',
			'\u2069', '\ufeff'
		};

		public static bool TryNormalize(string? raw, out string term, out string reason)
		{
			term = string.Empty;
			string text = (raw ?? string.Empty).Trim().Trim(EdgeMarks).Trim();
			if (text.Length == 0)
			{
				reason = SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TermEmpty);
				return false;
			}
			if (text.Length > 128)
			{
				reason = SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.TermTooLong, 128);
				return false;
			}
			if (text.Any((char character) => char.IsControl(character)))
			{
				reason = SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TermHasControlCharacter);
				return false;
			}
			if (text.Any((char character) => char.IsWhiteSpace(character)))
			{
				reason = SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TermHasSpace);
				return false;
			}
			if (text.Contains("://", StringComparison.Ordinal) || text.StartsWith("www.", StringComparison.OrdinalIgnoreCase))
			{
				reason = SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TermIsLink);
				return false;
			}
			term = LexiconStore.NormalizeUserTerm(text);
			reason = string.Empty;
			return true;
		}

		public static bool HasMeaningfulMetadata(SmartInput.Core.Dictionaries.DictionaryEntry entry)
		{
			if (entry.Category == DictionaryCategory.General && string.IsNullOrWhiteSpace(entry.Notes) && string.IsNullOrWhiteSpace(entry.ApplicationProcessName) && !entry.CaseSensitive && !entry.AutoReturnAfterWord && entry.Enabled)
			{
				return entry.PreventConversion != (entry.Language == EntryLanguage.English);
			}
			return true;
		}
	}
	internal interface IEditorWorkScheduler : IDisposable
	{
		long NowMilliseconds { get; }

		void Start(Action drain, Action watchdog, Func<bool> keysHeld);

		void Signal();
	}
	internal sealed class DedicatedEditorWorker : IEditorWorkScheduler, IDisposable
	{
		private const int WatchdogPeriodMilliseconds = 25;

		private readonly AutoResetEvent _signal = new AutoResetEvent(initialState: false);

		private readonly ManualResetEventSlim _watchdogArmed = new ManualResetEventSlim(initialState: false);

		private readonly object _watchdogGate = new object();

		private readonly CancellationTokenSource _stop = new CancellationTokenSource();

		private Thread? _thread;

		private Thread? _watchdogThread;

		private Action? _drain;

		private Action? _watchdog;

		private Func<bool> _keysHeld = () => false;

		public long NowMilliseconds => Environment.TickCount64;

		public void Start(Action drain, Action watchdog, Func<bool> keysHeld)
		{
			_drain = drain;
			_watchdog = watchdog;
			_keysHeld = keysHeld;
			_thread = new Thread(Run)
			{
				IsBackground = true,
				Name = "Diyar editor work"
			};
			_thread.SetApartmentState(ApartmentState.MTA);
			_thread.Start();
			_watchdogThread = new Thread(Watch)
			{
				IsBackground = true,
				Name = "Diyar held-key watchdog",
				Priority = ThreadPriority.AboveNormal
			};
			_watchdogThread.Start();
		}

		public void Signal()
		{
			lock (_watchdogGate)
			{
				_watchdogArmed.Set();
			}
			_signal.Set();
		}

		private void Run()
		{
			WaitHandle[] waitHandles = new WaitHandle[2]
			{
				_signal,
				_stop.Token.WaitHandle
			};
			while (WaitHandle.WaitAny(waitHandles) == 0)
			{
				try
				{
					_drain?.Invoke();
				}
				catch (Exception exception)
				{
					Fault(FaultSite.EditorWork, exception, "editor work");
				}
				finally
				{
					DisarmIfNothingHeld();
				}
			}
		}

		private void Watch()
		{
			try
			{
				while (!_stop.IsCancellationRequested)
				{
					_watchdogArmed.Wait(_stop.Token);
					if (_stop.Token.WaitHandle.WaitOne(25))
					{
						break;
					}
					try
					{
						_watchdog?.Invoke();
						DisarmIfNothingHeld();
					}
					catch (Exception ex) when (!(ex is OperationCanceledException))
					{
						Fault(FaultSite.Watchdog, ex, "held-key watchdog");
					}
				}
			}
			catch (OperationCanceledException)
			{
			}
		}

		private static void Fault(FaultSite site, Exception exception, string what)
		{
			FaultRing.Note(site, exception);
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(34, 3, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("The ");
				message.AppendFormatted(what);
				message.AppendLiteral(" failed (");
				message.AppendFormatted(exception.GetType().FullName);
				message.AppendLiteral(", 0x");
				message.AppendFormatted(exception.HResult, "X8");
				message.AppendLiteral("); Diyar goes on.");
			}
			DiagnosticLog.Write("Typing", ref message);
		}

		private void DisarmIfNothingHeld()
		{
			lock (_watchdogGate)
			{
				if (!_keysHeld())
				{
					_watchdogArmed.Reset();
				}
			}
		}

		public void Dispose()
		{
			_stop.Cancel();
			_thread?.Join(TimeSpan.FromSeconds(2L));
			_watchdogThread?.Join(TimeSpan.FromSeconds(2L));
			_signal.Dispose();
			_watchdogArmed.Dispose();
			_stop.Dispose();
		}
	}
	internal sealed class HookTimingStats
	{
		private static readonly double[] BucketLimits = new double[9] { 0.1, 0.5, 1.0, 2.0, 5.0, 10.0, 50.0, 100.0, 300.0 };

		private readonly object _gate = new object();

		private readonly long[] _buckets = new long[BucketLimits.Length + 1];

		private long _count;

		private double _maxMilliseconds;

		private double _totalMilliseconds;

		public long Count
		{
			get
			{
				lock (_gate)
				{
					return _count;
				}
			}
		}

		public double MeanMilliseconds
		{
			get
			{
				lock (_gate)
				{
					return (_count == 0L) ? 0.0 : (_totalMilliseconds / (double)_count);
				}
			}
		}

		public double MaxMilliseconds
		{
			get
			{
				lock (_gate)
				{
					return _maxMilliseconds;
				}
			}
		}

		public void Record(TimeSpan duration)
		{
			double totalMilliseconds = duration.TotalMilliseconds;
			lock (_gate)
			{
				_count++;
				_totalMilliseconds += totalMilliseconds;
				if (totalMilliseconds > _maxMilliseconds)
				{
					_maxMilliseconds = totalMilliseconds;
				}
				int i;
				for (i = 0; i < BucketLimits.Length && totalMilliseconds > BucketLimits[i]; i++)
				{
				}
				_buckets[i]++;
			}
		}

		public double PercentileUpperBoundMilliseconds(double fraction)
		{
			lock (_gate)
			{
				return PercentileUnlocked(fraction);
			}
		}

		public string Describe()
		{
			lock (_gate)
			{
				double num = ((_count == 0L) ? 0.0 : (_totalMilliseconds / (double)_count));
				string text = string.Join(" ", _buckets.Select((long n, int i) => ((i < BucketLimits.Length) ? $"<={BucketLimits[i]}ms" : $">{BucketLimits[^1]}ms") + $":{n}"));
				return FormattableString.Invariant($"calls={_count} mean={num:0.000}ms p99<={PercentileUnlocked(0.99):0.###}ms max={_maxMilliseconds:0.000}ms [{text}]");
			}
		}

		private double PercentileUnlocked(double fraction)
		{
			if (_count == 0L)
			{
				return 0.0;
			}
			long num = 0L;
			for (int i = 0; i < _buckets.Length; i++)
			{
				num += _buckets[i];
				if ((double)num >= fraction * (double)_count)
				{
					if (i >= BucketLimits.Length)
					{
						return _maxMilliseconds;
					}
					return BucketLimits[i];
				}
			}
			return _maxMilliseconds;
		}

		public static long Timestamp()
		{
			return Stopwatch.GetTimestamp();
		}
	}
	internal sealed record EnglishRestoreOutcome(LearnedPreference Preference, int Rejections, bool KeysAreEnglishWord, bool PersianIsKnown, DictionaryAddResult? Added);
	internal sealed record EnglishForgetOutcome(int Conversions, bool AutomaticEntry, bool Forgotten);
	internal sealed class EnglishPreferenceLearning(ConversionLearningStore counts, LexiconStore lexicon, UserDictionaryService dictionary, Func<bool> enabled, Func<string> targetLayoutId, DecisionPolicy? policy = null)
	{
		private readonly DecisionPolicy _policy = policy ?? DecisionPolicy.Default;

		public bool Enabled => enabled();

		public EnglishRestoreOutcome Restored(string keys, string persian, string route, string? sourceLayout = null, string? targetLayout = null)
		{
			string text = sourceLayout ?? KeyboardLayoutRegistry.SourceIdentity;
			string value = targetLayout ?? targetLayoutId();
			int num = counts.AddRejection(keys, text, value);
			bool flag = dictionary.IsKnownWord(keys, EntryLanguage.English);
			bool flag2 = persian.Trim().Length > 0 && dictionary.IsKnownPersianWord(persian);
			LearnedPreference learnedPreference = ConversionLearningPolicy.ForRestore(num, flag, flag2, _policy);
			lexicon.AddSessionEnglishPreference(keys);
			DictionaryAddResult dictionaryAddResult = null;
			if (learnedPreference == LearnedPreference.PermanentEnglish)
			{
				dictionaryAddResult = dictionary.AddTermsDetailed(new <>z__ReadOnlySingleElementList<string>(keys), EntryLanguage.English, autoLearned: true, Guid.NewGuid());
				counts.ResetPersianConversions(keys);
			}
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(86, 10, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("EnglishRestore '");
				message.AppendFormatted(DiagnosticLog.Tail(keys, 40));
				message.AppendLiteral("' <- '");
				message.AppendFormatted(DiagnosticLog.Tail(persian, 40));
				message.AppendLiteral("' (");
				message.AppendFormatted(text);
				message.AppendLiteral(" -> ");
				message.AppendFormatted(value);
				message.AppendLiteral(") route=");
				message.AppendFormatted(route);
				message.AppendLiteral(" rejections=");
				message.AppendFormatted(num);
				message.AppendLiteral(" englishWord=");
				message.AppendFormatted(flag);
				message.AppendLiteral(" persianKnown=");
				message.AppendFormatted(flag2);
				message.AppendLiteral(" decision=");
				message.AppendFormatted(learnedPreference);
				message.AppendFormatted(((object)dictionaryAddResult == null) ? ": kept English for this session." : $": added as an automatic personal English word (added={dictionaryAddResult.Added}).");
			}
			DiagnosticLog.Write("Learning", ref message);
			return new EnglishRestoreOutcome(learnedPreference, num, flag, flag2, dictionaryAddResult);
		}

		public EnglishForgetOutcome ConvertedToPersian(string keys, string persian, string route, string? sourceLayout = null, string? targetLayout = null)
		{
			string text = sourceLayout ?? KeyboardLayoutRegistry.SourceIdentity;
			string value = targetLayout ?? targetLayoutId();
			bool value2 = lexicon.RemoveSessionEnglishPreference(keys);
			int num = counts.AddPersianConversion(keys, text, value);
			SmartInput.Core.Dictionaries.DictionaryEntry dictionaryEntry = FindAutomaticEnglishEntry(keys);
			bool flag = false;
			if ((object)dictionaryEntry != null && ConversionLearningPolicy.ForgetsEnglish(num, entryIsAutomatic: true, _policy))
			{
				try
				{
					flag = dictionary.RemoveMany(new <>z__ReadOnlySingleElementList<Guid>(dictionaryEntry.Id)) > 0;
				}
				catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
				{
					flag = false;
				}
				if (flag)
				{
					counts.Forget(keys);
				}
			}
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(102, 9, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("PersianConversion '");
				message.AppendFormatted(DiagnosticLog.Tail(keys, 40));
				message.AppendLiteral("' -> '");
				message.AppendFormatted(DiagnosticLog.Tail(persian, 40));
				message.AppendLiteral("' (");
				message.AppendFormatted(text);
				message.AppendLiteral(" -> ");
				message.AppendFormatted(value);
				message.AppendLiteral(") route=");
				message.AppendFormatted(route);
				message.AppendLiteral(" conversions=");
				message.AppendFormatted(num);
				message.AppendLiteral(" automaticEnglishEntry=");
				message.AppendFormatted((object)dictionaryEntry != null);
				message.AppendLiteral(" sessionPreferenceRemoved=");
				message.AppendFormatted(value2);
				string? value3;
				if (flag)
				{
					value3 = ": removed the automatic personal English entry; its counts are cleared.";
				}
				else
				{
					value3 = (((object)dictionaryEntry != null) ? $": entry kept (needs {_policy.ConversionsToForgetEnglish})." : ".");
				}
				message.AppendFormatted(value3);
			}
			DiagnosticLog.Write("Learning", ref message);
			return new EnglishForgetOutcome(num, (object)dictionaryEntry != null, flag);
		}

		public void WithdrawRestore(string keys, string? sourceLayout = null, string? targetLayout = null)
		{
			string text = sourceLayout ?? KeyboardLayoutRegistry.SourceIdentity;
			string value = targetLayout ?? targetLayoutId();
			int value2 = counts.WithdrawRejection(keys, text, value);
			lexicon.RemoveSessionEnglishPreference(keys);
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(66, 4, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("WithdrawRestore '");
				message.AppendFormatted(DiagnosticLog.Tail(keys, 40));
				message.AppendLiteral("' (");
				message.AppendFormatted(text);
				message.AppendLiteral(" -> ");
				message.AppendFormatted(value);
				message.AppendLiteral(") rejections=");
				message.AppendFormatted(value2);
				message.AppendLiteral("; session preference removed.");
			}
			DiagnosticLog.Write("Learning", ref message);
		}

		public void WithdrawConversion(string keys, string? sourceLayout = null, string? targetLayout = null)
		{
			string text = sourceLayout ?? KeyboardLayoutRegistry.SourceIdentity;
			string value = targetLayout ?? targetLayoutId();
			int value2 = counts.WithdrawPersianConversion(keys, text, value);
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(42, 4, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("WithdrawConversion '");
				message.AppendFormatted(DiagnosticLog.Tail(keys, 40));
				message.AppendLiteral("' (");
				message.AppendFormatted(text);
				message.AppendLiteral(" -> ");
				message.AppendFormatted(value);
				message.AppendLiteral(") conversions=");
				message.AppendFormatted(value2);
				message.AppendLiteral(".");
			}
			DiagnosticLog.Write("Learning", ref message);
		}

		private SmartInput.Core.Dictionaries.DictionaryEntry? FindAutomaticEnglishEntry(string keys)
		{
			string term = LexiconStore.NormalizeUserTerm(keys);
			if (term.Length != 0)
			{
				return dictionary.GetAll().FirstOrDefault((SmartInput.Core.Dictionaries.DictionaryEntry entry) => entry.Enabled && entry.AutoLearned && entry.Language == EntryLanguage.English && string.Equals(LexiconStore.NormalizeUserTerm(entry.Term), term, StringComparison.OrdinalIgnoreCase));
			}
			return null;
		}
	}
	internal enum ExplicitSelectionAttemptState
	{
		Completed,
		Busy,
		TimedOut,
		Failed
	}
	internal sealed record ExplicitSelectionAttempt(ExplicitSelectionAttemptState State, ExplicitSelectionRead? Read);
	internal sealed record WorkerAttempt<T>(ExplicitSelectionAttemptState State, T? Result) where T : class;
	internal sealed class ExplicitSelectionWorker : IDisposable
	{
		private sealed class Request(Func<object> work)
		{
			public bool Abandoned;

			public Func<object> Work { get; } = work;

			public TaskCompletionSource<(ExplicitSelectionAttemptState State, object? Result)> Result { get; } = new TaskCompletionSource<(ExplicitSelectionAttemptState, object)>(TaskCreationOptions.RunContinuationsAsynchronously);
		}

		private sealed class Slot
		{
			public readonly AutoResetEvent Signal = new AutoResetEvent(initialState: false);

			public Request? Pending;

			public bool Retired;
		}

		private const int MaximumStuckReads = 2;

		private readonly object _gate = new object();

		private Slot? _slot;

		private Request? _inFlight;

		private int _stuck;

		private bool _disposed;

		public async Task<ExplicitSelectionAttempt> ReadAsync(Func<ExplicitSelectionRead> work, TimeSpan timeout)
		{
			WorkerAttempt<ExplicitSelectionRead> workerAttempt = await RunAsync(work, timeout).ConfigureAwait(continueOnCapturedContext: true);
			return new ExplicitSelectionAttempt(workerAttempt.State, workerAttempt.Result);
		}

		public async Task<WorkerAttempt<T>> RunAsync<T>(Func<T> work, TimeSpan timeout) where T : class
		{
			Request request;
			lock (_gate)
			{
				if (_disposed || _inFlight != null || _stuck >= 2)
				{
					return new WorkerAttempt<T>(ExplicitSelectionAttemptState.Busy, null);
				}
				request = (_inFlight = new Request(() => work()));
				if (_slot == null)
				{
					_slot = new Slot();
					StartThread(_slot);
				}
				_slot.Pending = request;
				_slot.Signal.Set();
			}
			if (await Task.WhenAny(request.Result.Task, Task.Delay(timeout)).ConfigureAwait(continueOnCapturedContext: true) == request.Result.Task)
			{
				return Unwrap<T>(await request.Result.Task.ConfigureAwait(continueOnCapturedContext: true));
			}
			lock (_gate)
			{
				if (!request.Result.Task.IsCompleted)
				{
					request.Abandoned = true;
					_stuck++;
					Slot slot = _slot;
					if (slot != null)
					{
						slot.Retired = true;
						_slot = null;
					}
					if (_inFlight == request)
					{
						_inFlight = null;
					}
					return new WorkerAttempt<T>(ExplicitSelectionAttemptState.TimedOut, null);
				}
			}
			return Unwrap<T>(await request.Result.Task.ConfigureAwait(continueOnCapturedContext: true));
		}

		private static WorkerAttempt<T> Unwrap<T>((ExplicitSelectionAttemptState State, object? Result) attempt) where T : class
		{
			return new WorkerAttempt<T>(attempt.State, attempt.Result as T);
		}

		private void StartThread(Slot slot)
		{
			Thread thread = new Thread(() =>
			{
				Run(slot);
			});
			thread.IsBackground = true;
			thread.Name = "Diyar selection read";
			thread.SetApartmentState(ApartmentState.MTA);
			thread.Start();
		}

		private void Run(Slot slot)
		{
			while (true)
			{
				slot.Signal.WaitOne();
				Request pending;
				lock (_gate)
				{
					if (_disposed)
					{
						break;
					}
					pending = slot.Pending;
					slot.Pending = null;
				}
				if (pending == null)
				{
					continue;
				}
				(ExplicitSelectionAttemptState, object) result;
				try
				{
					result = (ExplicitSelectionAttemptState.Completed, pending.Work());
				}
				catch (Exception ex) when (!(ex is OutOfMemoryException))
				{
					result = (ExplicitSelectionAttemptState.Failed, null);
				}
				lock (_gate)
				{
					if (pending.Abandoned)
					{
						_stuck--;
						break;
					}
					if (_inFlight == pending)
					{
						_inFlight = null;
					}
					pending.Result.TrySetResult(result);
					if (slot.Retired)
					{
						break;
					}
				}
			}
		}

		public void Dispose()
		{
			lock (_gate)
			{
				_disposed = true;
				_slot?.Signal.Set();
			}
		}
	}
	internal enum ExplicitAdditionOutcome
	{
		NothingSelected,
		MoreThanOneWord,
		LanguageUnknown,
		Added,
		AlreadyInPersonal,
		AlreadyBuiltIn,
		Rejected,
		NotSaved
	}
	internal sealed record ExplicitAdditionResult(ExplicitAdditionOutcome Outcome, string Message, string Word, EntryLanguage Language)
	{
		public bool WordIsAvailable
		{
			get
			{
				ExplicitAdditionOutcome outcome = Outcome;
				if ((uint)(outcome - 3) <= 2u)
				{
					return true;
				}
				return false;
			}
		}
	}
	internal static class ExplicitWordAddition
	{
		public static ExplicitAdditionResult Add(string? selected, UserDictionaryService dictionary, ManualConversionReviewService review)
		{
			ExplicitAdditionResult result = AddCore(selected, dictionary, review);
			LogResult(result);
			return result;
		}

		private static ExplicitAdditionResult AddCore(string? selected, UserDictionaryService dictionary, ManualConversionReviewService review)
		{
			if (string.IsNullOrWhiteSpace(selected))
			{
				LogNothingSelected(selected);
				return new ExplicitAdditionResult(ExplicitAdditionOutcome.NothingSelected, SelectedWordPlanner.SelectFirst, string.Empty, EntryLanguage.Neutral);
			}
			string text = selected.Trim();
			if (text.Any((char character) => char.IsWhiteSpace(character) || char.IsControl(character)))
			{
				LogMoreThanOneWord(text);
				return new ExplicitAdditionResult(ExplicitAdditionOutcome.MoreThanOneWord, SelectedWordPlanner.SelectOne, text, EntryLanguage.Neutral);
			}
			EntryLanguage entryLanguage = UserDictionaryService.DetectLanguage(text);
			LogLanguage(text, entryLanguage);
			if (entryLanguage == EntryLanguage.Neutral)
			{
				return new ExplicitAdditionResult(ExplicitAdditionOutcome.LanguageUnknown, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.WordLanguageUnknownNotAdded), text, entryLanguage);
			}
			DictionaryAddResult dictionaryAddResult;
			try
			{
				dictionaryAddResult = dictionary.AddTermsDetailed(new <>z__ReadOnlySingleElementList<string>(text), entryLanguage);
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
				return new ExplicitAdditionResult(ExplicitAdditionOutcome.NotSaved, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.WordNotAddedNotSaved, ex.Message), text, entryLanguage);
			}
			ExplicitAdditionOutcome explicitAdditionOutcome = ((dictionaryAddResult.Outcomes.Count <= 0) ? ExplicitAdditionOutcome.Rejected : (dictionaryAddResult.Outcomes[0] switch
			{
				DictionaryEntryOutcome.Added => ExplicitAdditionOutcome.Added, 
				DictionaryEntryOutcome.AlreadyInPersonal => ExplicitAdditionOutcome.AlreadyInPersonal, 
				DictionaryEntryOutcome.AlreadyBuiltIn => ExplicitAdditionOutcome.AlreadyBuiltIn, 
				_ => ExplicitAdditionOutcome.Rejected, 
			}));
			ExplicitAdditionOutcome explicitAdditionOutcome2 = explicitAdditionOutcome;
			ExplicitAdditionResult explicitAdditionResult = explicitAdditionOutcome2 switch
			{
				ExplicitAdditionOutcome.Added => new ExplicitAdditionResult(explicitAdditionOutcome2, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.WordAddedToPersonal, text), text, entryLanguage), 
				ExplicitAdditionOutcome.AlreadyInPersonal => new ExplicitAdditionResult(explicitAdditionOutcome2, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.WordAlreadyPersonal), text, entryLanguage), 
				ExplicitAdditionOutcome.AlreadyBuiltIn => new ExplicitAdditionResult(explicitAdditionOutcome2, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.WordAlreadyBuiltIn), text, entryLanguage), 
				_ => new ExplicitAdditionResult(explicitAdditionOutcome2, (dictionaryAddResult.Rejected.Count > 0) ? SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.WordNotAddedBecause, dictionaryAddResult.Rejected[0]) : SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.WordRejectedNotAdded), text, entryLanguage), 
			};
			if (explicitAdditionResult.WordIsAvailable)
			{
				review.RemoveWords(new <>z__ReadOnlySingleElementList<string>(text), entryLanguage);
			}
			return explicitAdditionResult;
		}

		private static void LogResult(ExplicitAdditionResult result)
		{
			if (DiagnosticLog.IsEnabled)
			{
				DiagnosticLog.Command("cmd.add-word", "stage", "result", "outcome", result.Outcome, "dictionary", WhereItIs(result.Outcome), "language", result.Language, "word", DiagnosticLog.Escaped(result.Word), "wordLength", result.Word.Length, "availableToRecognition", result.WordIsAvailable, "rejection", (result.Outcome == ExplicitAdditionOutcome.Rejected) ? DescribeRejection(result.Word) : "none");
			}
		}

		private static void LogNothingSelected(string? selected)
		{
			if (DiagnosticLog.IsEnabled)
			{
				DiagnosticLog.Command("cmd.add-word", "stage", "validate", "valid", false, "reason", "nothing selected: the text is empty or only white space", "length", selected?.Length ?? 0);
			}
		}

		private static void LogMoreThanOneWord(string word)
		{
			if (DiagnosticLog.IsEnabled)
			{
				DiagnosticLog.Command("cmd.add-word", "stage", "validate", "valid", false, "reason", "more than one word: a white space or control character inside the trimmed text", "firstSplit", DescribeSplit(word), "trimmedLength", word.Length, "trimmed", DiagnosticLog.Escaped(word));
			}
		}

		private static void LogLanguage(string word, EntryLanguage language)
		{
			if (DiagnosticLog.IsEnabled)
			{
				DiagnosticLog.Command("cmd.add-word", "stage", "validate", "valid", language != EntryLanguage.Neutral, "reason", (language == EntryLanguage.Neutral) ? "language unknown: the letters are mixed scripts, digits only or symbols" : "one word", "language", language, "scripts", DescribeScripts(word), "trimmedLength", word.Length);
			}
		}

		private static string WhereItIs(ExplicitAdditionOutcome outcome)
		{
			return outcome switch
			{
				ExplicitAdditionOutcome.Added => "personal (added now)", 
				ExplicitAdditionOutcome.AlreadyInPersonal => "personal (an entry with this word and language exists; an English one is protected from conversion by default)", 
				ExplicitAdditionOutcome.AlreadyBuiltIn => "built-in", 
				ExplicitAdditionOutcome.NotSaved => "none (the personal dictionary file could not be saved)", 
				_ => "none", 
			};
		}

		private static string DescribeRejection(string word)
		{
			if (word.Length <= 128)
			{
				if (!word.Contains("://", StringComparison.Ordinal) && !word.StartsWith("www.", StringComparison.OrdinalIgnoreCase))
				{
					return "refused by the dictionary (see the list's own message)";
				}
				return "looks like a link";
			}
			return $"longer than {128} characters";
		}

		private static string DescribeSplit(string word)
		{
			for (int i = 0; i < word.Length; i++)
			{
				char c = word[i];
				if (char.IsWhiteSpace(c) || char.IsControl(c))
				{
					IFormatProvider invariantCulture = CultureInfo.InvariantCulture;
					DefaultInterpolatedStringHandler handler = new DefaultInterpolatedStringHandler(22, 4, invariantCulture);
					handler.AppendLiteral("index ");
					handler.AppendFormatted(i);
					handler.AppendLiteral(" U+");
					handler.AppendFormatted((int)c, "X4");
					handler.AppendLiteral(" category ");
					handler.AppendFormatted(char.GetUnicodeCategory(c));
					handler.AppendLiteral(" (");
					handler.AppendFormatted(char.IsControl(c) ? "control character" : "white space");
					handler.AppendLiteral(")");
					return string.Create(invariantCulture, ref handler);
				}
			}
			return "none";
		}

		private static string DescribeScripts(string word)
		{
			int num = word.Count((char ch) => ch >= '\u0600' && ch <= 'ۿ');
			int num2 = word.Count((char ch) =>
			{
				switch (ch)
				{
				case 'A':
				case 'B':
				case 'C':
				case 'D':
				case 'E':
				case 'F':
				case 'G':
				case 'H':
				case 'I':
				case 'J':
				case 'K':
				case 'L':
				case 'M':
				case 'N':
				case 'O':
				case 'P':
				case 'Q':
				case 'R':
				case 'S':
				case 'T':
				case 'U':
				case 'V':
				case 'W':
				case 'X':
				case 'Y':
				case 'Z':
				case 'a':
				case 'b':
				case 'c':
				case 'd':
				case 'e':
				case 'f':
				case 'g':
				case 'h':
				case 'i':
				case 'j':
				case 'k':
				case 'l':
				case 'm':
				case 'n':
				case 'o':
				case 'p':
				case 'q':
				case 'r':
				case 's':
				case 't':
				case 'u':
				case 'v':
				case 'w':
				case 'x':
				case 'y':
				case 'z':
					return true;
				default:
					return false;
				}
			});
			int value = word.Count((char ch) => char.IsDigit(ch));
			int value2 = word.Length - num - num2;
			IFormatProvider invariantCulture = CultureInfo.InvariantCulture;
			DefaultInterpolatedStringHandler handler = new DefaultInterpolatedStringHandler(57, 4, invariantCulture);
			handler.AppendLiteral("persianLetters ");
			handler.AppendFormatted(num);
			handler.AppendLiteral(", latinLetters ");
			handler.AppendFormatted(num2);
			handler.AppendLiteral(", digits ");
			handler.AppendFormatted(value);
			handler.AppendLiteral(", otherCharacters ");
			handler.AppendFormatted(value2);
			return string.Create(invariantCulture, ref handler);
		}
	}
