		private readonly ManualConversionReviewService _reviewService;

		public ForcedConversionLearningService(UserDictionaryService userDictionaryService, ManualConversionReviewService reviewService)
		{
			_userDictionaryService = userDictionaryService;
			_reviewService = reviewService;
		}

		public ForcedConversionLearningResult Process(IReadOnlyList<ManualConversionResult> conversions, bool automaticLearning)
		{
			EntryLanguage[] array = conversions.Select((ManualConversionResult conversion) => conversion.Language).Distinct().ToArray();
			if (array.Length > 1)
			{
				ForcedConversionLearningResult[] parts = array.Select((EntryLanguage language) =>
				{
					ForcedConversionLearningService forcedConversionLearningService = this;
					List<ManualConversionResult> list = new List<ManualConversionResult>();
					list.AddRange(conversions.Where((ManualConversionResult conversion) => conversion.Language == language));
					return forcedConversionLearningService.Process(new <>z__ReadOnlyList<ManualConversionResult>(list), automaticLearning);
				}).ToArray();
				return new ForcedConversionLearningResult(null, Array.Empty<string>())
				{
					Parts = parts
				};
			}
			EntryLanguage entryLanguage = ((array.Length == 1) ? array[0] : EntryLanguage.Persian);
			if (automaticLearning)
			{
				try
				{
					string[] array2 = conversions.Select((ManualConversionResult conversion) => conversion.PersianWord).Distinct(StringComparer.Ordinal).ToArray();
					DictionaryAddResult dictionaryAddResult = _userDictionaryService.AddTermsDetailed(array2, entryLanguage, autoLearned: true);
					_reviewService.RemoveWords(array2, entryLanguage);
					bool flag = dictionaryAddResult.AddedIds.Count + dictionaryAddResult.ConfirmedIds.Count > 0;
					return new ForcedConversionLearningResult((conversions.Count == 1 && dictionaryAddResult.Added > 0) ? conversions[0].PersianWord : null)
					{
						Language = entryLanguage,
						ContributionId = (flag ? dictionaryAddResult.ContributionId : ((Guid?)null)),
						AddedEntryId = ((conversions.Count == 1 && dictionaryAddResult.AddedIds.Count == 1) ? new Guid?(dictionaryAddResult.AddedIds[0]) : ((Guid?)null))
					};
				}
				catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
				{
					return new ForcedConversionLearningResult(null, RecordForReview(NotYetKnown(conversions, entryLanguage), entryLanguage))
					{
						Language = entryLanguage
					};
				}
			}
			IReadOnlyList<ManualConversionResult> readOnlyList = NotYetKnown(conversions, entryLanguage);
			if (readOnlyList.Count != 0)
			{
				return new ForcedConversionLearningResult(null, RecordForReview(readOnlyList, entryLanguage))
				{
					Language = entryLanguage
				};
			}
			return new ForcedConversionLearningResult(null)
			{
				Language = entryLanguage
			};
		}

		private IReadOnlyList<ManualConversionResult> NotYetKnown(IReadOnlyList<ManualConversionResult> conversions, EntryLanguage language)
		{
			return conversions.Where((ManualConversionResult conversion) => !_userDictionaryService.IsKnownWord(conversion.PersianWord, language)).ToArray();
		}

		public bool Withdraw(ForcedConversionLearningResult contribution)
		{
			bool flag = true;
			foreach (ForcedConversionLearningResult part in contribution.Parts)
			{
				flag &= Withdraw(part);
			}
			Guid? contributionId = contribution.ContributionId;
			if (contributionId.HasValue)
			{
				Guid valueOrDefault = contributionId.GetValueOrDefault();
				try
				{
					_userDictionaryService.WithdrawContribution(valueOrDefault);
				}
				catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
				{
					flag = false;
				}
			}
			foreach (string item in contribution.RecordedForReview)
			{
				_reviewService.Retract(item, contribution.Language);
			}
			return flag;
		}

		private List<string> RecordForReview(IEnumerable<ManualConversionResult> conversions, EntryLanguage language)
		{
			List<string> list = new List<string>();
			foreach (ManualConversionResult conversion in conversions)
			{
				ManualConversionCandidate manualConversionCandidate = _reviewService.Record(conversion.TypedText, conversion.PersianWord, language);
				if ((object)manualConversionCandidate != null)
				{
					list.Add(manualConversionCandidate.PersianWord);
				}
			}
			return list;
		}
	}
