		private bool LeftAsTypedInBatchLossEditor(string source)
		{
			if (!inner.FocusedEditorLosesUnicodeBatches())
			{
				return false;
			}
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(78, 1, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("'");
				message.AppendFormatted(source);
				message.AppendLiteral("' left as typed: this editor loses Unicode characters sent together (KL-048).");
			}
			DiagnosticLog.Write("Replace", ref message);
			return true;
		}

		private bool Change(string operation, bool needsAutomation, Func<bool> change)
		{
			if (needsAutomation && RefusedOnHook(operation))
			{
				return false;
			}
			bool flag = false;
			try
			{
				if (onHookThread())
				{
					DiagnosticJournal journal = DiagnosticLog.Journal;
					if (journal != null)
					{
						flag = Monitor.TryEnter(changeLock);
						if (!flag)
						{
							long timestamp = journal.Timestamp;
							Monitor.Enter(changeLock);
							flag = true;
							journal.RecordDuration("hook.wait.editorChangeLock", timestamp);
						}
						goto IL_0064;
					}
				}
				Monitor.Enter(changeLock);
				flag = true;
				goto IL_0064;
				IL_0064:
				bool shouldAppend;
				if (changeIsStale())
				{
					DiagnosticMessageHandler message = new DiagnosticMessageHandler(61, 1, out shouldAppend);
					if (shouldAppend)
					{
						message.AppendFormatted(operation);
						message.AppendLiteral(" refused: the key it belongs to was already sent on as typed.");
					}
					DiagnosticLog.Write("Replace", ref message);
					shouldAppend = false;
					return shouldAppend;
				}
				bool flag2 = change();
				if (flag2)
				{
					changeMade();
				}
				shouldAppend = flag2;
				return shouldAppend;
			}
			finally
			{
				if (flag)
				{
					Monitor.Exit(changeLock);
				}
				changeEnded();
			}
		}

