	internal readonly record struct HotkeyGesture(uint Modifiers, uint VirtualKey)
	{
		private const uint ModAlt = 1u;

		private const uint ModControl = 2u;

		private const uint ModShift = 4u;

		private const uint ModWindows = 8u;

		public const uint ModNoRepeat = 16384u;

		public static bool TryFormat(Key key, ModifierKeys modifiers, out string value, out string error)
		{
			value = string.Empty;
			error = string.Empty;
			bool flag = IsModifierKey(key);
			if (!flag)
			{
				bool flag2 = ((key == Key.None || key == Key.System) ? true : false);
				flag = flag2;
			}
			if (flag)
			{
				error = SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.GesturePressModifierAndKey);
				return false;
			}
			ModifierKeys modifierKeys = modifiers & (ModifierKeys.Alt | ModifierKeys.Control | ModifierKeys.Shift | ModifierKeys.Windows);
			if (modifierKeys == ModifierKeys.None)
			{
				error = SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.GestureIncludeModifier);
				return false;
			}
			List<string> list = new List<string>(5);
			if (modifierKeys.HasFlag(ModifierKeys.Control))
			{
				list.Add("Ctrl");
			}
			if (modifierKeys.HasFlag(ModifierKeys.Alt))
			{
				list.Add("Alt");
			}
			if (modifierKeys.HasFlag(ModifierKeys.Shift))
			{
				list.Add("Shift");
			}
			if (modifierKeys.HasFlag(ModifierKeys.Windows))
			{
				list.Add("Win");
			}
			list.Add(GetDisplayName(key));
			value = string.Join('+', list);
			if (TryParse(value, out var _, out error))
			{
				return true;
			}
			value = string.Empty;
			return false;
		}

		public static bool IsModifierKey(Key key)
		{
			if ((uint)(key - 70) <= 1u || (uint)(key - 116) <= 5u)
			{
				return true;
			}
			return false;
		}

		public static bool TryParse(string? value, out HotkeyGesture gesture, out string error)
		{
			gesture = default;
			error = string.Empty;
			if (string.IsNullOrWhiteSpace(value))
			{
				error = SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.GestureRequired);
				return false;
			}
			uint num = 0u;
			Key? key = null;
			string[] array = value.Split('+', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
			foreach (string text in array)
			{
				switch (text.ToLowerInvariant())
				{
				case "ctrl":
				case "control":
					num |= 2;
					continue;
				case "alt":
					num |= 1;
					continue;
				case "shift":
					num |= 4;
					continue;
				case "win":
				case "windows":
					num |= 8;
					continue;
				}
				if (key.HasValue || !TryParseKey(text, out var key2))
				{
					error = SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.GestureInvalid, value);
					return false;
				}
				key = key2;
			}
			if (num == 0 || !key.HasValue)
			{
				error = SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.GestureNeedsModifierAndKey);
				return false;
			}
			gesture = new HotkeyGesture(num | 0x4000, (uint)KeyInterop.VirtualKeyFromKey(key.Value));
			return true;
		}

		private static bool TryParseKey(string value, out Key key)
		{
			if (new Dictionary<string, Key>(StringComparer.OrdinalIgnoreCase)
			{
				["Enter"] = Key.Return,
				["Return"] = Key.Return,
				["Space"] = Key.Space,
				["Backspace"] = Key.Back,
				["Delete"] = Key.Delete,
				["Tab"] = Key.Tab,
				["Escape"] = Key.Escape
			}.TryGetValue(value, out key))
			{
				return true;
			}
			try
			{
				if (new KeyConverter().ConvertFromInvariantString(value) is Key key2 && key2 != Key.None)
				{
					key = key2;
					return true;
				}
			}
			catch (NotSupportedException)
			{
			}
			key = Key.None;
			return false;
		}

		private static string GetDisplayName(Key key)
		{
			if (key >= Key.D0 && key <= Key.D9)
			{
				return ((int)(key - 34)).ToString();
			}
			return key switch
			{
				Key.Return => "Enter", 
				Key.Back => "Backspace", 
				Key.Space => "Space", 
				Key.Delete => "Delete", 
				Key.Tab => "Tab", 
				_ => new KeyConverter().ConvertToInvariantString(key) ?? key.ToString(), 
			};
		}
	}
	internal static class InstallerLanguage
	{
