			if (StrokeMap.TryGetValue(sourceCharacter, out (int, bool) value))
			{
				return TryCreateStroke(value.Item1, value.Item2, out stroke);
			}
			stroke = default;
			return false;
		}

		private static IReadOnlyDictionary<char, (int VirtualKey, bool ShiftDown)> BuildStrokeMap()
		{
			Dictionary<char, (int, bool)> dictionary = new Dictionary<char, (int, bool)>();
			foreach (var (item, tuple2) in SymbolMap)
			{
				dictionary.TryAdd(tuple2.Item1, (item, false));
				dictionary.TryAdd(tuple2.Item2, (item, true));
			}
			return dictionary;
		}
	}
	internal enum ManualWordDirection
	{
		ToPersian,
		ToLatin,
		RestoreOriginal
	}
	internal sealed record LastWordPlan(bool Allowed, string Shown, string Replacement, ManualWordDirection Direction, EntryLanguage DestinationLanguage, string Refusal) : IManualWordPlan
	{
		string IManualWordPlan.Source => Shown;

		public static LastWordPlan Refuse(string shown, string reason)
		{
			return new LastWordPlan(Allowed: false, shown, string.Empty, ManualWordDirection.ToPersian, EntryLanguage.Persian, reason);
		}
	}
	internal static class LastWordConversionPlanner
	{
		private static readonly TechnicalPatternDetector Technical = new TechnicalPatternDetector();

		public static LastWordPlan Plan(string word, PersianKeyboardLayout mapping, string? exactOriginal = null)
		{
			if (string.IsNullOrWhiteSpace(word))
			{
				return LastWordPlan.Refuse(word ?? string.Empty, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.NoWordToConvert));
			}
			if (word.Any((char character) => char.IsWhiteSpace(character) || char.IsControl(character)))
			{
				return LastWordPlan.Refuse(word, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.LastWordHasSpace));
			}
			if (exactOriginal != null && exactOriginal.Length > 0)
			{
				return new LastWordPlan(Allowed: true, word, exactOriginal, ManualWordDirection.RestoreOriginal, ScriptOf(exactOriginal), string.Empty);
			}
			if (word.Any(char.IsDigit))
			{
				return LastWordPlan.Refuse(word, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.WordHasDigits));
			}
			if (Technical.Classify(word) != ProtectedTokenKind.None)
			{
				return LastWordPlan.Refuse(word, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.WordIsTechnical));
			}
			bool flag = word.Any(IsPersianLetter);
			bool flag2 = word.Any((char character) =>
			{
				switch (character)
				{
				case 'A':
				case 'B':
				case 'C':
				case 'D':
				case 'E':
				case 'F':
				case 'G':
				case 'H':
				case 'I':
				case 'J':
				case 'K':
				case 'L':
				case 'M':
				case 'N':
				case 'O':
				case 'P':
				case 'Q':
				case 'R':
				case 'S':
				case 'T':
				case 'U':
				case 'V':
				case 'W':
				case 'X':
				case 'Y':
				case 'Z':
				case 'a':
				case 'b':
				case 'c':
				case 'd':
				case 'e':
				case 'f':
				case 'g':
				case 'h':
				case 'i':
				case 'j':
				case 'k':
				case 'l':
				case 'm':
				case 'n':
				case 'o':
				case 'p':
				case 'q':
				case 'r':
				case 's':
				case 't':
				case 'u':
				case 'v':
				case 'w':
				case 'x':
				case 'y':
				case 'z':
					return true;
				default:
					return false;
				}
			});
			if (flag & flag2)
			{
				return LastWordPlan.Refuse(word, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.WordMixesScripts));
			}
			if (!flag && !flag2)
			{
				return LastWordPlan.Refuse(word, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.WordHasNoLetters));
			}
			if (!flag2)
			{
				return ToLatin(word, mapping);
			}
			return ToPersian(word, mapping);
		}

		private static LastWordPlan ToPersian(string word, PersianKeyboardLayout mapping)
		{
			if (!ManualWordMapper.TryToPersian(word, mapping, out string text, out string problem))
			{
				return LastWordPlan.Refuse(word, problem);
			}
			if (!(text == word))
			{
				return new LastWordPlan(Allowed: true, word, text, ManualWordDirection.ToPersian, EntryLanguage.Persian, string.Empty);
			}
			return LastWordPlan.Refuse(word, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.WordWouldNotChange));
		}

		private static LastWordPlan ToLatin(string word, PersianKeyboardLayout mapping)
		{
			if (!ManualWordMapper.TryToLatin(word, mapping, out string text, out string problem))
			{
				return LastWordPlan.Refuse(word, problem);
			}
			return new LastWordPlan(Allowed: true, word, text, ManualWordDirection.ToLatin, EntryLanguage.English, string.Empty);
		}

		private static bool IsPersianLetter(char character)
		{
			return ManualWordMapper.IsPersianLetter(character);
		}

		private static EntryLanguage ScriptOf(string text)
		{
			if (!text.Any(IsPersianLetter))
			{
				return EntryLanguage.English;
			}
			return EntryLanguage.Persian;
		}
	}
