	public sealed record ManualConversionCandidate
	{
		public Guid Id { get; init; } = Guid.NewGuid();

		public required string TypedText { get; init; }

		public required string PersianWord { get; init; }

		public EntryLanguage Language { get; init; }

		public int UseCount { get; init; } = 1;

		public DateTimeOffset FirstSeenUtc { get; init; } = DateTimeOffset.UtcNow;

		public DateTimeOffset LastSeenUtc { get; init; } = DateTimeOffset.UtcNow;

		public string LastSeenDisplay => LastSeenUtc.ToLocalTime().ToString("yyyy-MM-dd HH:mm");
	}
	public sealed class ManualConversionReviewService
	{
		private sealed record ReviewFile(int SchemaVersion, IReadOnlyList<ManualConversionCandidate> Candidates);

		private static readonly JsonSerializerOptions SerializerOptions = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			WriteIndented = true
		};

		private readonly object _sync = new object();

		private readonly string _path;

		private List<ManualConversionCandidate> _candidates;

		private const int ReviewFormatVersion = 1;

		private readonly object _stateSync = new object();

		private string? _unsavedReason;

		public string? WriteBlockedReason => UnreadableFileBackup.BlockedReason(_path);

		public string? UnsavedReason
		{
			get
			{
				lock (_stateSync)
				{
					return _unsavedReason;
				}
			}
		}

		public event EventHandler? Changed;

		public ManualConversionReviewService(string? path = null)
		{
			_path = path ?? DictionaryPaths.ManualConversionReview;
			_candidates = Load(_path);
		}

		public IReadOnlyList<ManualConversionCandidate> GetAll(string? search = null)
		{
			lock (_sync)
			{
				IEnumerable<ManualConversionCandidate> source = _candidates.AsEnumerable();
				if (!string.IsNullOrWhiteSpace(search))
				{
					string value = search.Trim();
					source = source.Where((ManualConversionCandidate candidate) => candidate.PersianWord.Contains(value, StringComparison.OrdinalIgnoreCase) || candidate.TypedText.Contains(value, StringComparison.OrdinalIgnoreCase));
				}
				return source.OrderByDescending((ManualConversionCandidate candidate) => candidate.LastSeenUtc).ToArray();
			}
		}

		public ManualConversionCandidate? Record(string typedText, string persianWord, EntryLanguage language = EntryLanguage.Persian)
		{
			string text = Normalize(typedText);
			string target = Normalize(persianWord);
			bool flag = language switch
			{
				EntryLanguage.Persian => target.Any((char character) => character >= '\u0600' && character <= 'ۿ'), 
				EntryLanguage.English => target.Any((char character) =>
				{
					switch (character)
					{
					case 'A':
					case 'B':
					case 'C':
					case 'D':
					case 'E':
					case 'F':
					case 'G':
					case 'H':
					case 'I':
					case 'J':
					case 'K':
					case 'L':
					case 'M':
					case 'N':
					case 'O':
					case 'P':
					case 'Q':
					case 'R':
					case 'S':
					case 'T':
					case 'U':
					case 'V':
					case 'W':
					case 'X':
					case 'Y':
					case 'Z':
					case 'a':
					case 'b':
					case 'c':
					case 'd':
					case 'e':
					case 'f':
					case 'g':
					case 'h':
					case 'i':
					case 'j':
					case 'k':
					case 'l':
					case 'm':
					case 'n':
					case 'o':
					case 'p':
					case 'q':
					case 'r':
					case 's':
					case 't':
					case 'u':
					case 'v':
					case 'w':
					case 'x':
					case 'y':
					case 'z':
						return true;
					default:
						return false;
					}
				}), 
				_ => false, 
			};
			if (text.Length == 0 || target.Length == 0 || !flag)
			{
				return null;
			}
			ManualConversionCandidate manualConversionCandidate;
			lock (_sync)
			{
				int num = _candidates.FindIndex((ManualConversionCandidate candidate) => candidate.Language == language && string.Equals(candidate.PersianWord, target, StringComparison.Ordinal));
				DateTimeOffset utcNow = DateTimeOffset.UtcNow;
				if (num >= 0)
				{
					manualConversionCandidate = _candidates[num] with
					{
						TypedText = text,
						UseCount = _candidates[num].UseCount + 1,
						LastSeenUtc = utcNow
					};
					_candidates[num] = manualConversionCandidate;
				}
				else
				{
					manualConversionCandidate = new ManualConversionCandidate
					{
						TypedText = text,
						PersianWord = target,
						Language = language,
						FirstSeenUtc = utcNow,
						LastSeenUtc = utcNow
					};
					_candidates.Add(manualConversionCandidate);
				}
				TrySave();
			}
			Changed?.Invoke(this, EventArgs.Empty);
			return manualConversionCandidate;
		}

		public bool Retract(string persianWord, EntryLanguage language = EntryLanguage.Persian)
		{
			string target = Normalize(persianWord);
			lock (_sync)
			{
				int num = _candidates.FindIndex((ManualConversionCandidate candidate) => candidate.Language == language && string.Equals(candidate.PersianWord, target, StringComparison.Ordinal));
				if (num < 0)
				{
					return false;
				}
				if (_candidates[num].UseCount > 1)
				{
					_candidates[num] = _candidates[num] with
					{
						UseCount = _candidates[num].UseCount - 1
					};
				}
				else
				{
					_candidates.RemoveAt(num);
				}
				TrySave();
			}
			Changed?.Invoke(this, EventArgs.Empty);
			return true;
		}

		public int RemoveMany(IEnumerable<Guid> ids)
		{
			UnreadableFileBackup.ThrowIfBlocked(_path);
			HashSet<Guid> removeIds = ids.ToHashSet();
			if (removeIds.Count == 0)
			{
				return 0;
			}
			int num;
			lock (_sync)
			{
				List<ManualConversionCandidate> list = _candidates.Where((ManualConversionCandidate candidate) => !removeIds.Contains(candidate.Id)).ToList();
				num = _candidates.Count - list.Count;
				if (num > 0)
				{
					SaveDurably(list);
					_candidates = list;
				}
			}
			if (num > 0)
			{
				Changed?.Invoke(this, EventArgs.Empty);
			}
			return num;
		}

		public int RemoveWords(IEnumerable<string> words, EntryLanguage? language = null)
		{
			HashSet<string> removeWords = (from word in words.Select(Normalize)
				where word.Length > 0
				select word).ToHashSet(StringComparer.Ordinal);
			if (removeWords.Count == 0)
			{
				return 0;
			}
			int num;
			lock (_sync)
			{
				num = _candidates.RemoveAll((ManualConversionCandidate candidate) => (!language.HasValue || candidate.Language == language) && removeWords.Contains(candidate.PersianWord));
				if (num > 0)
				{
					TrySave();
				}
			}
			if (num > 0)
			{
				Changed?.Invoke(this, EventArgs.Empty);
			}
			return num;
		}

		public int Clear()
		{
			UnreadableFileBackup.ThrowIfBlocked(_path);
			int count;
			lock (_sync)
			{
				count = _candidates.Count;
				if (count == 0)
				{
					return 0;
				}
				SaveDurably(Array.Empty<ManualConversionCandidate>());
				_candidates = new List<ManualConversionCandidate>();
			}
			Changed?.Invoke(this, EventArgs.Empty);
			return count;
		}

		private static string Normalize(string value)
		{
			return BidiControlCharacters.Remove(value).Trim();
		}

		private static List<ManualConversionCandidate> Load(string path)
		{
			try
			{
				if (!File.Exists(path))
				{
					return new List<ManualConversionCandidate>();
				}
				ReviewFile reviewFile = JsonSerializer.Deserialize<ReviewFile>(File.ReadAllText(path), SerializerOptions);
				if (reviewFile?.Candidates == null || reviewFile.SchemaVersion > 1)
				{
					if ((object)reviewFile != null)
					{
						if (reviewFile.Candidates != null)
						{
							UnreadableFileBackup.Keep(path, MessageKey.UnreadableNewerFormat, reviewFile.SchemaVersion);
						}
						else
						{
							UnreadableFileBackup.Keep(path, MessageKey.UnreadableNoCandidatesList);
						}
					}
					else
					{
						UnreadableFileBackup.Keep(path, MessageKey.UnreadableEmptyFile);
					}
					return new List<ManualConversionCandidate>();
				}
				return reviewFile.Candidates.Where((ManualConversionCandidate candidate) => !string.IsNullOrWhiteSpace(candidate.TypedText) && !string.IsNullOrWhiteSpace(candidate.PersianWord)).ToList();
			}
			catch (Exception ex) when ((ex is JsonException || ex is IOException || ex is UnauthorizedAccessException || ex is NotSupportedException) ? true : false)
			{
				UnreadableFileBackup.Keep(path, ex.GetType().Name);
				return new List<ManualConversionCandidate>();
			}
		}

		public bool TryRetryPreservation()
		{
			return UnreadableFileBackup.Retry(_path);
		}

		private void SetUnsaved(string? reason)
		{
			lock (_stateSync)
			{
				_unsavedReason = reason;
			}
		}

		private void Save(IReadOnlyList<ManualConversionCandidate> candidates)
		{
			UnreadableFileBackup.ThrowIfBlocked(_path);
			string directoryName = System.IO.Path.GetDirectoryName(_path);
			if (!string.IsNullOrEmpty(directoryName))
			{
				Directory.CreateDirectory(directoryName);
			}
			string text = _path + ".tmp";
			try
			{
				File.WriteAllText(text, JsonSerializer.Serialize(new ReviewFile(1, candidates), SerializerOptions));
				File.Move(text, _path, overwrite: true);
			}
			catch
			{
				try
				{
					File.Delete(text);
				}
				catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
				{
				}
				throw;
			}
		}

		private void SaveDurably(IReadOnlyList<ManualConversionCandidate> next)
		{
			try
			{
				Save(next);
				SetUnsaved(null);
			}
			catch (StoreWriteBlockedException)
			{
				throw;
			}
			catch (Exception ex2) when ((ex2 is IOException || ex2 is UnauthorizedAccessException) ? true : false)
			{
				throw new IOException(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ReviewQueueNotSaved, ex2.Message, System.IO.Path.GetFileName(_path)), ex2);
			}
		}

		private void TrySave()
		{
			try
			{
				Save(_candidates);
				SetUnsaved(null);
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
				SetUnsaved(ex.Message);
			}
		}
	}
	internal static class ManualWordMapper
	{
		public static bool TryToPersian(string word, PersianKeyboardLayout mapping, out string text, out string problem)
		{
			bool result = MapToPersian(word, mapping, out text, out MessageRefusal problem2);
			problem = problem2?.Text ?? string.Empty;
			return result;
		}

		public static bool MapToPersian(string word, PersianKeyboardLayout mapping, out string text, [NotNullWhen(false)] out MessageRefusal? problem)
		{
			text = string.Empty;
			problem = new MessageRefusal(MessageKey.NoPersianMapping);
			if (!KeyboardLayoutRegistry.TryGetLayout("en-us", out KeyboardLayoutDefinition layout))
			{
				problem = new MessageRefusal(MessageKey.NoEnglishMapping);
				return false;
			}
			MessageRefusal messageRefusal = null;
			foreach (KeyboardLayoutDefinition persianTarget in KeyboardLayoutRegistry.GetPersianTargets(mapping))
			{
				StringBuilder stringBuilder = new StringBuilder(word.Length);
				bool flag = true;
				int num = 0;
				while (num < word.Length)
				{
					char c = word[num];
					if (layout.TryGetReverseMapping(c, out var key))
					{
						string text2 = persianTarget.MapKey(key);
						if (text2 != null && text2.Length == 1 && KeyboardLayoutDefinition.IsWordCharacter(text2[0]))
						{
							stringBuilder.Append(text2);
							num++;
							continue;
						}
					}
					if ((object)messageRefusal == null)
					{
						messageRefusal = new MessageRefusal(MessageKey.KeyHasNoPersianLetter, c);
					}
					flag = false;
					break;
				}
				if (flag)
				{
					text = stringBuilder.ToString();
					problem = null;
					return true;
				}
			}
			problem = messageRefusal ?? problem;
			return false;
		}

		public static bool TryToLatin(string word, PersianKeyboardLayout mapping, out string text, out string problem)
		{
			bool result = MapToLatin(word, mapping, out text, out MessageRefusal problem2);
			problem = problem2?.Text ?? string.Empty;
			return result;
		}

		public static bool MapToLatin(string word, PersianKeyboardLayout mapping, out string text, [NotNullWhen(false)] out MessageRefusal? problem)
		{
			text = string.Empty;
			problem = new MessageRefusal(MessageKey.NoLatinMapping);
			if (!KeyboardLayoutRegistry.TryGetLayout("en-us", out KeyboardLayoutDefinition english))
			{
				problem = new MessageRefusal(MessageKey.NoEnglishMapping);
				return false;
			}
			MessageRefusal messageRefusal = null;
			foreach (KeyboardLayoutDefinition persianTarget in KeyboardLayoutRegistry.GetPersianTargets(mapping))
			{
				StringBuilder stringBuilder = new StringBuilder(word.Length);
				bool flag = true;
				foreach (char character in word)
				{
					string[] array = (from pair in persianTarget.Mappings
						where pair.Value.Length == 1 && pair.Value[0] == character
						select english.MapKey(pair.Key) into candidate
						where candidate != null && candidate.Length == 1 && !char.IsWhiteSpace(candidate[0])
						select candidate).Distinct().ToArray();
					if (array.Length != 1)
					{
						if ((object)messageRefusal == null)
						{
							messageRefusal = ((array.Length == 0) ? new MessageRefusal(MessageKey.LetterNotOnPersianKeys, character) : new MessageRefusal(MessageKey.LetterAmbiguousBack, character));
						}
						flag = false;
						break;
					}
					stringBuilder.Append(array[0]);
				}
				if (flag)
				{
					text = stringBuilder.ToString();
					problem = null;
					return true;
				}
			}
			problem = messageRefusal ?? problem;
			return false;
		}

		public static bool IsPersianLetter(char character)
		{
			if (character >= '\u0600' && character <= 'ۿ')
			{
				return char.IsLetter(character);
			}
			return false;
		}

