		private string DescribeLexicalSource(string target)
		{
			if (!_lexiconStore.IsUserExactMatch(target, DetectedLanguage.Persian))
			{
				if (!_lexiconStore.IsCommonPersianAddition(target))
				{
					if (!_lexiconStore.IsBuiltinWord(target, DetectedLanguage.Persian))
					{
						return "none";
					}
					return "builtin";
				}
				return "addition";
			}
			return "user";
