		public static ReadEnrichmentGate Shared { get; } = new ReadEnrichmentGate(2);

		public int Limit { get; } = limit;

		public int Pending => Volatile.Read(in pending);

		public bool TryEnter()
		{
			int num;
			do
			{
				num = Volatile.Read(in pending);
				if (num >= Limit)
				{
					return false;
				}
			}
			while (Interlocked.CompareExchange(ref pending, num + 1, num) != num);
			return true;
		}

		public void Exit()
		{
			Interlocked.Decrement(ref pending);
		}
	}
	public sealed record ReviewAcceptanceResult(int Added, int AlreadyInPersonal, int AlreadyBuiltIn, IReadOnlyList<string> RejectedReasons, int StillInQueue, string? QueueError)
	{
		public int Rejected => RejectedReasons.Count;

		public bool QueueUpdated => QueueError == null;

		private static string Join
		{
			get
			{
				if (!TextCatalog.IsPersian)
				{
					return " - ";
				}
				return ". ";
			}
		}

		public DictionaryAddResult AsAddResult()
		{
			return new DictionaryAddResult(Added, AlreadyInPersonal, AlreadyBuiltIn, RejectedReasons);
		}

		public string Summary()
		{
			string text = AsAddResult().Summary();
			if (RejectedReasons.Count > 0)
			{
				string text2 = (TextCatalog.IsPersian ? "؛ " : "; ");
				string text3 = string.Join(text2, RejectedReasons.Take(3)) + ((RejectedReasons.Count > 3) ? (text2 + "...") : string.Empty);
				text = text + Join + SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ReviewKeptInQueue, text3);
			}
			if (QueueError != null)
			{
				return text + Join + SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ReviewQueueNotUpdated, InterfaceFormat.Count(StillInQueue, TextCatalog.Language), QueueError);
			}
			return text;
		}
	}
	public static class ReviewAcceptance
	{
		internal static string LanguageName(EntryLanguage language)
		{
			return SmartInput.Core.Text.Localization.MessageText.Get((language == EntryLanguage.Neutral) ? MessageKey.EntryLanguageNeutral : MessageKey.EntryLanguageUnknown);
		}

		public static ReviewAcceptanceResult Accept(UserDictionaryService dictionary, ManualConversionReviewService review, IEnumerable<Guid> ids)
		{
			HashSet<Guid> wanted = ids.ToHashSet();
			ManualConversionCandidate[] array = (from candidate in review.GetAll()
				where wanted.Contains(candidate.Id)
				select candidate).ToArray();
			List<string> list = new List<string>();
			List<SmartInput.Core.Dictionaries.DictionaryEntry> list2 = new List<SmartInput.Core.Dictionaries.DictionaryEntry>();
			List<ManualConversionCandidate> list3 = new List<ManualConversionCandidate>();
			ManualConversionCandidate[] array2 = array;
			foreach (ManualConversionCandidate manualConversionCandidate in array2)
			{
				EntryLanguage language = manualConversionCandidate.Language;
				if ((uint)language > 1u)
				{
					list.Add(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.ReviewLanguageNotSupported, manualConversionCandidate.PersianWord, LanguageName(manualConversionCandidate.Language)));
					continue;
				}
				list2.Add(new SmartInput.Core.Dictionaries.DictionaryEntry
				{
					Id = Guid.NewGuid(),
					Term = manualConversionCandidate.PersianWord,
					Language = manualConversionCandidate.Language,
					Category = DictionaryCategory.General,
					Enabled = true,
					PreventConversion = (manualConversionCandidate.Language == EntryLanguage.English)
				});
				list3.Add(manualConversionCandidate);
			}
			DictionaryAddResult dictionaryAddResult = ((list2.Count > 0) ? dictionary.AddEntriesDetailed(list2) : new DictionaryAddResult(0, 0, 0, Array.Empty<string>()));
			list.AddRange(dictionaryAddResult.Rejected);
			List<Guid> list4 = new List<Guid>();
			for (int num2 = 0; num2 < list3.Count; num2++)
			{
				if (dictionaryAddResult.Outcomes[num2] != DictionaryEntryOutcome.Rejected)
				{
					list4.Add(list3[num2].Id);
				}
			}
			try
			{
				review.RemoveMany(list4);
				return new ReviewAcceptanceResult(dictionaryAddResult.Added, dictionaryAddResult.AlreadyInPersonal, dictionaryAddResult.AlreadyBuiltIn, list, 0, null);
			}
			catch (IOException ex)
			{
				return new ReviewAcceptanceResult(dictionaryAddResult.Added, dictionaryAddResult.AlreadyInPersonal, dictionaryAddResult.AlreadyBuiltIn, list, list4.Count, ex.Message);
			}
		}
	}
	internal sealed class SelectedTextConversionService
	{
		private const ushort VkC = 67;

		private const ushort VkV = 86;

		private readonly IInputInjector _inputInjector;

		private readonly IPersianConversionEngine _conversionEngine;

		public SelectedTextConversionService(IInputInjector inputInjector, IPersianConversionEngine conversionEngine)
		{
			_inputInjector = inputInjector;
			_conversionEngine = conversionEngine;
		}

		public bool ConvertSelectedText(PersianKeyboardLayout persianKeyboardLayout, CorrectionSettings settings)
		{
			return ToggleSelectedText(persianKeyboardLayout, settings);
		}

		public bool ToggleSelectedText(PersianKeyboardLayout persianKeyboardLayout, CorrectionSettings settings)
		{
			(bool, string) snapshot = SnapshotClipboardText();
			TryClearClipboard();
			_inputInjector.SendControlShortcutWithoutActiveModifiers(67);
			string text = WaitForClipboardText();
			if (string.IsNullOrWhiteSpace(text))
			{
				RestoreClipboardText(snapshot);
				return false;
			}
			if (!_conversionEngine.TryToggleVisibleText(text, persianKeyboardLayout, settings, out string converted))
			{
				RestoreClipboardText(snapshot);
				return false;
			}
			if (_inputInjector.ReplaceSelectedText(converted))
			{
				RestoreClipboardText(snapshot);
				return true;
			}
			if (!TrySetClipboardText(converted))
			{
				RestoreClipboardText(snapshot);
				return false;
			}
			_inputInjector.SendControlShortcutWithoutActiveModifiers(86);
			PumpUi(80);
			RestoreClipboardText(snapshot);
			return true;
		}

		public string GetSelectedText()
		{
			return CopySelectedText().Trim();
		}

		public string GetSelectedTextPreservingWhitespace()
		{
			return CopySelectedText();
		}

		public bool IsSelectedTextUnchanged(string expectedText)
		{
			return string.Equals(CopySelectedText(), expectedText, StringComparison.Ordinal);
		}

		public bool ReplaceCurrentSelection(string replacement)
		{
			if (_inputInjector.ReplaceSelectedText(replacement))
			{
				return true;
			}
			(bool, string) snapshot = SnapshotClipboardText();
			if (!TrySetClipboardText(replacement))
			{
				RestoreClipboardText(snapshot);
				return false;
			}
			bool result = _inputInjector.SendControlShortcutWithoutActiveModifiers(86);
			PumpUi(80);
			RestoreClipboardText(snapshot);
			return result;
		}

		private string CopySelectedText()
		{
			(bool, string) snapshot = SnapshotClipboardText();
			TryClearClipboard();
			_inputInjector.SendControlShortcutWithoutActiveModifiers(67);
			string result = WaitForClipboardText();
			RestoreClipboardText(snapshot);
			return result;
		}

		private static (bool hasText, string text) SnapshotClipboardText()
		{
			try
			{
				if (System.Windows.Clipboard.ContainsText())
				{
					return (hasText: true, text: System.Windows.Clipboard.GetText());
				}
			}
			catch
			{
			}
			return (hasText: false, text: string.Empty);
		}

		private static void RestoreClipboardText((bool hasText, string text) snapshot)
		{
			try
			{
				if (snapshot.hasText)
				{
					System.Windows.Clipboard.SetText(snapshot.text);
				}
				else
				{
					System.Windows.Clipboard.Clear();
				}
			}
			catch
			{
			}
		}

		private static void TryClearClipboard()
		{
			try
			{
				System.Windows.Clipboard.Clear();
			}
			catch
			{
			}
		}

		private static string WaitForClipboardText()
		{
			for (int i = 0; i < 16; i++)
			{
				PumpUi(25);
				try
				{
					if (System.Windows.Clipboard.ContainsText())
					{
						return System.Windows.Clipboard.GetText();
					}
				}
				catch
				{
				}
			}
			return string.Empty;
		}

		private static bool TrySetClipboardText(string text)
		{
			for (int i = 0; i < 5; i++)
			{
				try
				{
					System.Windows.Clipboard.SetText(text);
					return true;
				}
				catch
				{
					PumpUi(15);
				}
			}
			return false;
		}

		private static void PumpUi(int milliseconds)
		{
			DispatcherFrame frame = new DispatcherFrame();
			DispatcherTimer timer = new DispatcherTimer(DispatcherPriority.Background)
			{
				Interval = TimeSpan.FromMilliseconds(milliseconds)
			};
			timer.Tick += (object? _, EventArgs _) =>
			{
				timer.Stop();
				frame.Continue = false;
			};
			timer.Start();
			Dispatcher.PushFrame(frame);
		}
	}
	internal sealed record SelectedWordPlan(bool Allowed, string Leading, string Word, string Replacement, string Trailing, ManualWordDirection Direction, EntryLanguage DestinationLanguage, string Refusal) : IManualWordPlan
