		public static SelectedWordPlan Refuse(string selected, string reason)
		{
			return new SelectedWordPlan(Allowed: false, string.Empty, selected ?? string.Empty, string.Empty, string.Empty, ManualWordDirection.ToPersian, EntryLanguage.Persian, reason);
		}

