	internal static class SelectedWordPlanner
	{
		private static readonly TechnicalPatternDetector Technical = new TechnicalPatternDetector();

		public static string SelectFirst => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.SelectWordFirst);

		public static string SelectOne => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.SelectOneWord);

		public static string CoreOf(string? selected)
		{
			return selected?.Trim() ?? string.Empty;
		}

		public static SelectedWordPlan Plan(string? selected, PersianKeyboardLayout mapping, string? exactOriginal = null)
		{
			if (string.IsNullOrWhiteSpace(selected))
			{
				return SelectedWordPlan.Refuse(selected ?? string.Empty, new MessageRefusal(MessageKey.SelectWordFirst));
			}
			int i;
			for (i = 0; char.IsWhiteSpace(selected[i]); i++)
			{
			}
			int num = selected.Length;
			while (char.IsWhiteSpace(selected[num - 1]))
			{
				num--;
			}
			string leading = selected.Substring(0, i);
			string? text = selected;
			int num2 = i;
			string text2 = text.Substring(num2, num - num2);
			string trailing = selected.Substring(num);
			if (text2.Any((char character) => char.IsWhiteSpace(character) || char.IsControl(character)))
			{
				return SelectedWordPlan.Refuse(selected, new MessageRefusal(MessageKey.SelectOneWord));
			}
			if (exactOriginal != null && exactOriginal.Length > 0)
			{
				EntryLanguage destinationLanguage = ((!exactOriginal.Any(ManualWordMapper.IsPersianLetter)) ? EntryLanguage.English : EntryLanguage.Persian);
				return new SelectedWordPlan(Allowed: true, leading, text2, exactOriginal, trailing, ManualWordDirection.RestoreOriginal, destinationLanguage, string.Empty);
			}
			if (text2.Any(char.IsDigit))
			{
				return Refused(new MessageRefusal(MessageKey.WordHasDigits));
			}
			if (Technical.Classify(text2) != ProtectedTokenKind.None)
			{
				return Refused(new MessageRefusal(MessageKey.WordIsTechnical));
			}
			bool flag = text2.Any(ManualWordMapper.IsPersianLetter);
			bool flag2 = text2.Any(ManualWordMapper.IsLatinLetter);
			if (flag & flag2)
			{
				return Refused(new MessageRefusal(MessageKey.WordMixesScripts));
			}
			if (flag)
			{
				if (!ManualWordMapper.MapToLatin(text2, mapping, out string text3, out MessageRefusal problem))
				{
					return Refused(problem);
				}
				if (!(text3 == text2))
				{
					return new SelectedWordPlan(Allowed: true, leading, text2, text3, trailing, ManualWordDirection.ToLatin, EntryLanguage.English, string.Empty);
				}
				return Refused(new MessageRefusal(MessageKey.WordWouldNotChange));
			}
			if (!ManualWordMapper.MapToPersian(text2, mapping, out string text4, out MessageRefusal problem2))
			{
				return Refused(problem2);
			}
			if (!(text4 == text2))
			{
				return new SelectedWordPlan(Allowed: true, leading, text2, text4, trailing, ManualWordDirection.ToPersian, EntryLanguage.Persian, string.Empty);
			}
			return Refused(new MessageRefusal(MessageKey.WordWouldNotChange));
			SelectedWordPlan Refused(MessageRefusal reason)
			{
				return SelectedWordPlan.Refuse(selected, reason);
			}
		}
	}
