	internal sealed record SelectedWordResult(CorrectionEditOutcome Outcome, string Message, long OperationId, SelectedWordPlan? Plan = null, CorrectionLearningResult? Learning = null);
	internal sealed class SelectedWordOperation(ISelectedWordEditor editor, Func<PersianKeyboardLayout> mapping, Func<bool> savesToPersonalDictionary, CorrectionLearningService learning, Func<DiagnosticJournal?>? journalSource = null)
	{
		private sealed record ConfirmedConversion(long Id, string Original, string Result, object Receipt, CorrectionLearningResult Learning);

		private int _pending;

		private long _operationId;

		private ConfirmedConversion? _lastConfirmed;

		public static string Unavailable => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.SelectedWordUnavailable);

		public static string Cancelled => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.CancelledAfterShortcut);

		public static string Busy => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.SelectedWordBusy);

		public bool IsAvailable => editor.Route.Available;

		public SelectedWordResult Run(Func<bool> stillCurrent)
		{
			long id = Interlocked.Increment(ref _operationId);
			if (!editor.Route.Available)
			{
				return Done(CorrectionEditOutcome.RefusedBeforeMutation, Unavailable);
			}
			if (Interlocked.CompareExchange(ref _pending, 1, 0) != 0)
			{
				return Done(CorrectionEditOutcome.RefusedBeforeMutation, Busy);
			}
			try
			{
				ConfirmedConversion lastConfirmed = _lastConfirmed;
				_lastConfirmed = null;
				if (!stillCurrent())
				{
					return Done(CorrectionEditOutcome.CancelledBeforeMutation, Cancelled);
				}
				SelectedWordCapture selectedWordCapture = editor.Capture();
				SelectedWordSnapshot snapshot = selectedWordCapture.Snapshot;
				if ((object)snapshot == null)
				{
					return Done(CorrectionEditOutcome.RefusedBeforeMutation, Sentence(selectedWordCapture.Refusal));
				}
				bool flag = (object)lastConfirmed != null && editor.LinksToEdit(snapshot, lastConfirmed.Receipt) && string.Equals(SelectedWordPlanner.CoreOf(snapshot.SourceText), lastConfirmed.Result, StringComparison.Ordinal);
				SelectedWordPlan selectedWordPlan = SelectedWordPlanner.Plan(snapshot.SourceText, mapping(), flag ? lastConfirmed.Original : null);
				if (!selectedWordPlan.Allowed)
				{
					return Done(CorrectionEditOutcome.RefusedBeforeMutation, Sentence(selectedWordPlan.Refusal), selectedWordPlan);
				}
				if (!stillCurrent())
				{
					return Done(CorrectionEditOutcome.CancelledBeforeMutation, Cancelled, selectedWordPlan);
				}
				SelectedWordEditResult selectedWordEditResult = editor.Replace(snapshot, selectedWordPlan.FullReplacement, stillCurrent);
				switch (selectedWordEditResult.Outcome)
				{
				case CorrectionEditOutcome.ConfirmedSuccess:
				{
					CorrectionLearningResult correctionLearningResult;
					if (flag)
					{
						learning.Withdraw(lastConfirmed.Learning, lastConfirmed.Id);
						correctionLearningResult = new CorrectionLearningResult(CorrectionLearningOutcome.SkippedReversal, selectedWordPlan.Replacement, selectedWordPlan.DestinationLanguage, null);
					}
					else
					{
						correctionLearningResult = learning.Learn(selectedWordPlan, selectedWordEditResult.Outcome, savesToPersonalDictionary(), id);
						object receipt = selectedWordEditResult.Receipt;
						if (receipt != null)
						{
							_lastConfirmed = new ConfirmedConversion(id, selectedWordPlan.Word, selectedWordPlan.Replacement, receipt, correctionLearningResult);
						}
					}
					return Done(selectedWordEditResult.Outcome, correctionLearningResult.Message, selectedWordPlan, correctionLearningResult);
				}
				case CorrectionEditOutcome.SubmittedUnverified:
					return Done(selectedWordEditResult.Outcome, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ConversionNotConfirmed), selectedWordPlan);
				case CorrectionEditOutcome.CancelledBeforeMutation:
					return Done(selectedWordEditResult.Outcome, Cancelled, selectedWordPlan);
				case CorrectionEditOutcome.RefusedBeforeMutation:
					return Done(selectedWordEditResult.Outcome, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.EditorRefusedChange), selectedWordPlan);
				default:
					return Done(CorrectionEditOutcome.FailedOrUncertain, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TextMayHaveChanged), selectedWordPlan);
				}
			}
			finally
			{
				Volatile.Write(ref _pending, 0);
			}
			SelectedWordResult Done(CorrectionEditOutcome outcome, string message, SelectedWordPlan? plan = null, CorrectionLearningResult? result = null)
			{
				journalSource?.Invoke()?.Event("selectedword.operation", "operation", id, "outcome", outcome, "direction", plan?.Direction, "learning", result?.Outcome);
				return new SelectedWordResult(outcome, message, id, plan, result);
			}
		}

		internal static string Sentence(string reason)
		{
			return (reason.EndsWith('.') ? reason : (reason + ".")) + " " + SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.NothingWasChanged);
		}
	}
	public sealed record StartupRegistrationResult(bool IsEnabled, bool Succeeded, string Message);
	internal interface IStartupRegistrationBackend
	{
		string? ReadRunCommand();

		void WriteRunCommand(string command);

		void DeleteRunCommand();

		bool ShortcutExists(string path);

		void DeleteShortcut(string path);
	}
	internal sealed class StartupRegistrationService
	{
		internal const string RunValueName = "Diyar";

		internal static readonly string[] LegacyRunValueNames = new string[2] { "SmartInput", "CoCo Typing" };

		private const string StartupShortcutName = "Diyar.lnk";

		private const string LegacyStartupShortcutName = "CoCo Typing.lnk";

		private readonly IStartupRegistrationBackend _backend;

		private readonly string _startupCommand;

		private readonly IReadOnlyList<string> _legacyShortcutPaths;

		public StartupRegistrationService(IStartupRegistrationBackend backend, string executablePath, IReadOnlyList<string> legacyShortcutPaths)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(executablePath, "executablePath");
			_backend = backend;
			_startupCommand = "\"" + System.IO.Path.GetFullPath(executablePath) + "\" --startup";
			_legacyShortcutPaths = legacyShortcutPaths;
		}

		public static StartupRegistrationService CreateForCurrentUser(string executablePath)
		{
			string[] legacyShortcutPaths = new string[4]
			{
				System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup), "Diyar.lnk"),
				System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonStartup), "Diyar.lnk"),
				System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup), "CoCo Typing.lnk"),
				System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonStartup), "CoCo Typing.lnk")
			};
			return new StartupRegistrationService(new WindowsStartupRegistrationBackend(), executablePath, legacyShortcutPaths);
		}

		public StartupRegistrationResult Synchronize(bool? preference)
		{
			if (!preference.HasValue)
			{
				return GetStatus();
			}
			return SetEnabled(preference.Value);
		}

		public StartupRegistrationResult GetStatus()
		{
			try
			{
				string text = _backend.ReadRunCommand();
				bool flag = _legacyShortcutPaths.Any(_backend.ShortcutExists);
				if (string.Equals(text, _startupCommand, StringComparison.OrdinalIgnoreCase))
				{
					return new StartupRegistrationResult(IsEnabled: true, Succeeded: true, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.StartupStartsHidden));
				}
				if (flag)
				{
					return new StartupRegistrationResult(IsEnabled: true, Succeeded: true, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.StartupThroughInstaller));
				}
				return string.IsNullOrWhiteSpace(text) ? new StartupRegistrationResult(IsEnabled: false, Succeeded: true, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.StartupOff)) : new StartupRegistrationResult(IsEnabled: false, Succeeded: true, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.StartupOlderInstallation));
			}
			catch (Exception exception) when (IsRegistrationException(exception))
			{
				return new StartupRegistrationResult(IsEnabled: false, Succeeded: false, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.StartupStatusUnreadable));
			}
		}

		public StartupRegistrationResult SetEnabled(bool enabled)
		{
			try
			{
				if (enabled)
				{
					_backend.WriteRunCommand(_startupCommand);
					foreach (string item in _legacyShortcutPaths.Where(_backend.ShortcutExists))
					{
						TryDeleteLegacyShortcut(item);
					}
				}
				else
				{
					_backend.DeleteRunCommand();
					foreach (string item2 in _legacyShortcutPaths.Where(_backend.ShortcutExists))
					{
						_backend.DeleteShortcut(item2);
					}
				}
			}
			catch (Exception exception) when (IsRegistrationException(exception))
			{
				return GetStatus() with
				{
					Succeeded = false,
					Message = (enabled ? SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.StartupEnableFailed) : SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.StartupDisableNeedsPermission))
				};
			}
			StartupRegistrationResult status = GetStatus();
			if (status.IsEnabled == enabled)
			{
				return status;
			}
			return status with
			{
				Succeeded = false,
				Message = (enabled ? SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.StartupNotAccepted) : SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.StartupEntryStillActive))
			};
		}

		private static bool IsRegistrationException(Exception exception)
		{
			if (exception is IOException || exception is UnauthorizedAccessException || exception is SecurityException)
			{
				return true;
			}
			return false;
		}

		private void TryDeleteLegacyShortcut(string shortcutPath)
		{
			try
			{
				_backend.DeleteShortcut(shortcutPath);
			}
			catch (Exception exception) when (IsRegistrationException(exception))
			{
			}
		}

		internal string DescribeForLog()
		{
			try
			{
				string text = _backend.ReadRunCommand();
				int value = _legacyShortcutPaths.Where(_backend.ShortcutExists).Count();
				string value2;
				if (text == null)
				{
					value2 = "absent";
				}
				else
				{
					value2 = (string.Equals(text, _startupCommand, StringComparison.OrdinalIgnoreCase) ? "present, the command this build writes" : ("present, a different command: " + text));
				}
				return $"HKCU Run '{"Diyar"}': {value2}; StartupApproved\\Run: {StartupRegistrationDiagnostics.DescribeApproval("Diyar")}; startup-folder shortcuts: {value}";
			}
			catch (Exception ex) when (IsRegistrationException(ex))
			{
				return "could not be read: " + ex.GetType().Name;
			}
		}
	}
	internal sealed class WindowsStartupRegistrationBackend : IStartupRegistrationBackend
	{
		private const string RunKeyPath = "Software\\Microsoft\\Windows\\CurrentVersion\\Run";

		public string? ReadRunCommand()
		{
			using RegistryKey registryKey = Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Run", writable: false);
			return registryKey?.GetValue("Diyar") as string;
		}

		public void WriteRunCommand(string command)
		{
			using RegistryKey registryKey = Registry.CurrentUser.CreateSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Run", writable: true);
			registryKey.SetValue("Diyar", command, RegistryValueKind.String);
			string[] legacyRunValueNames = StartupRegistrationService.LegacyRunValueNames;
			foreach (string name in legacyRunValueNames)
			{
				registryKey.DeleteValue(name, throwOnMissingValue: false);
			}
		}

		public void DeleteRunCommand()
		{
			using RegistryKey registryKey = Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Run", writable: true);
			registryKey?.DeleteValue("Diyar", throwOnMissingValue: false);
			string[] legacyRunValueNames = StartupRegistrationService.LegacyRunValueNames;
			foreach (string name in legacyRunValueNames)
			{
				registryKey?.DeleteValue(name, throwOnMissingValue: false);
			}
		}

		public bool ShortcutExists(string path)
		{
			return File.Exists(path);
		}

		public void DeleteShortcut(string path)
		{
			File.Delete(path);
		}
	}
	internal static class StartupRegistrationDiagnostics
	{
		internal static string DescribeApproval(string valueName)
		{
			try
			{
				using RegistryKey registryKey = Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\StartupApproved\\Run", writable: false);
				if (!(registryKey?.GetValue(valueName) is byte[] array) || array.Length == 0)
				{
					return "no value (Windows recorded no choice; the entry runs)";
				}
				string result;
				switch (array[0])
				{
				case 2:
				case 6:
					result = $"enabled (first byte {array[0]})";
					break;
				case 3:
					result = "DISABLED by the user in Windows startup apps (first byte 3)";
					break;
				default:
					result = $"unrecognized (first byte {array[0]})";
					break;
				}
				return result;
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException || ex is SecurityException) ? true : false)
			{
				return "could not be read: " + ex.GetType().Name;
			}
		}
	}
	internal static class TextServiceLog
	{
		public static void Plan(TextServiceClient client, ulong op, string text, SelectedWordPlan plan, InputMarker? marker)
		{
			if (DiagnosticLog.IsEnabled)
			{
				DiagnosticLog.Command("cmd.text-service", "stage", "plan", "client", $"{client.Executable} pid {client.ProcessId}", "op", op, "sourceText", DiagnosticLog.Escaped(text), "length", text.Length, "allowed", plan.Allowed, "resultText", plan.Allowed ? DiagnosticLog.Escaped(plan.FullReplacement) : "none", "refusal", plan.Allowed ? "none" : plan.RefusalIn(UiLanguage.English), "keySeq", marker?.KeySequence ?? (-1), "epoch", marker?.TargetEpoch ?? (-1), "controllerInformed", false);
			}
		}

		public static void Outcome(TextServiceClient client, ulong op, string? command, string result, string code, string reason, bool hostAdmitted, bool confirmed, SelectedWordPlan? plan, SelectedWordPlan? refused, Func<string>? describeController, bool controllerInformed)
		{
			if (DiagnosticLog.IsEnabled)
			{
				string text = (((object)plan != null) ? plan.Selected : refused?.Selected);
				DiagnosticLog.Command("cmd.text-service", "stage", "outcome", "client", $"{client.Executable} pid {client.ProcessId}", "op", op, "command", command ?? "convert (the message names none)", "result", result, "code", code, "reason", reason, "hostAdmitted", hostAdmitted, "confirmed", confirmed, "plannedSource", (text == null) ? "none (no plan was kept for this operation)" : DiagnosticLog.Escaped(text), "plannedResult", ((object)plan == null) ? "none" : DiagnosticLog.Escaped(plan.FullReplacement), "controllerInformed", controllerInformed, "controllerNow", describeController?.Invoke() ?? "not available");
			}
		}

		public static void Learned(ulong op, string? command, CorrectionLearningResult learned, bool saves)
		{
			if (DiagnosticLog.IsEnabled)
			{
				DiagnosticLog.Command("cmd.text-service", "stage", "learned", "op", op, "command", command ?? "convert", "learning", learned.Outcome, "word", DiagnosticLog.Escaped(learned.Word), "savedToPersonalDictionary", saves);
			}
		}

		public static void NoticeReceived(IReadOnlyDictionary<string, string> message)
		{
			if (DiagnosticLog.IsEnabled)
			{
				DiagnosticLog.Command("cmd.text-service", "stage", "notice", "code", message.GetValueOrDefault("code") ?? string.Empty, "reason", message.GetValueOrDefault("reason") ?? string.Empty, "controllerInformed", false);
			}
		}
	}
