		internal TypingTargetDecision CurrentEnvironmentDecision()
		{
			return TypingTargetPolicy.Decide(_environment?.Current, _utcNow(), TypingTargetPolicy.DefaultMaxEvidenceAge);
		}

		private bool EnvironmentRestricts()
		{
			TypingTargetDecision typingTargetDecision = CurrentEnvironmentDecision();
			if (typingTargetDecision.Restricts && !string.Equals(_lastEnvironmentRestrictionLogged, typingTargetDecision.Reason, StringComparison.Ordinal))
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(65, 2, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("Typing environment: ");
					message.AppendFormatted(typingTargetDecision.Restriction);
					message.AppendLiteral(" (");
					message.AppendFormatted(typingTargetDecision.Reason);
					message.AppendLiteral("); Diyar leaves this field's keys as typed.");
				}
				Log(ref message);
			}
			_lastEnvironmentRestrictionLogged = (typingTargetDecision.Restricts ? typingTargetDecision.Reason : string.Empty);
			return typingTargetDecision.Restricts;
		}

		private bool IsTargetRestricted()
		{
			if (EnvironmentRestricts())
			{
				return true;
			}
			bool? flag = ProtectionOfFocusedField();
			if (flag.HasValue)
			{
				return flag == true;
			}
			Log("The focused field's protection is not known yet; Diyar leaves this key as typed.");
			return true;
		}

		private bool? ProtectionOfFocusedField()
		{
			if (!OnHookThread)
			{
				return _inputInjector.IsProtectedTechnicalField();
			}
			return PreparedProtection();
		}

		private bool? ManualTargetRestriction()
		{
			if (!EnvironmentRestricts())
			{
				return ProtectionOfFocusedField();
			}
			return true;
		}

