		private HotkeyStep TryToggleLastVisibleWord(string paragraphPrefix)
		{
			if (!TryExtractTrailingWord(paragraphPrefix, out string word, out string trailingText))
			{
				return HotkeyStep.NotApplicable;
			}
			bool flag = IsToggleableVisibleWord(word);
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(60, 3, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("TryToggleLastVisibleWord: word='");
				message.AppendFormatted(word);
				message.AppendLiteral("'; trailing='");
				message.AppendFormatted(trailingText);
				message.AppendLiteral("'; toggleable=");
				message.AppendFormatted(flag);
				message.AppendLiteral(".");
			}
			Log(ref message);
			if (!flag)
			{
				return HotkeyStep.NotApplicable;
			}
			if (_inputInjector.IsReadUntrustedForRewrite(paragraphPrefix))
			{
				Log("TryToggleLastVisibleWord: refused; this editor's Persian text is not faithful, so the word is left as it is.");
				return HotkeyStep.Refused;
			}
			bool flag2 = _translator.TryToggleVisibleText(word, MappingLayout, out string output);
			DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(49, 2, out shouldAppend);
			if (shouldAppend)
			{
				message2.AppendLiteral("TryToggleLastVisibleWord: toggled=");
				message2.AppendFormatted(flag2);
				message2.AppendLiteral("; converted='");
				message2.AppendFormatted(output);
				message2.AppendLiteral("'.");
			}
			Log(ref message2);
			if (!flag2 || string.Equals(output, word, StringComparison.Ordinal))
			{
				return HotkeyStep.NotApplicable;
			}
			bool flag3 = _inputInjector.ReplacePreviousToken(word + trailingText, output + trailingText, null, setRightToLeft: false, null, paragraphIsRightToLeft: false, startRightToLeftEmbedding: false, paragraphHasRightToLeftEmbedding: false, removeRightToLeftEmbedding: false, releaseActiveModifiers: true, requireExactSourceMatch: true);
			DiagnosticMessageHandler message3 = new DiagnosticMessageHandler(57, 2, out shouldAppend);
			if (shouldAppend)
			{
				message3.AppendLiteral("TryToggleLastVisibleWord: replaced=");
				message3.AppendFormatted(flag3);
				message3.AppendLiteral("; LastSendInputError=");
				message3.AppendFormatted(_inputInjector.LastSendInputError);
				message3.AppendLiteral(".");
			}
			Log(ref message3);
			NoteCommandEdit("toggle the word read at the caret between English keys and Persian", word + trailingText, output + trailingText);
			_commandDetail = $"replaced={flag3} contradictedEditor={_inputInjector.LastReplacementContradictedEditor}";
			if (!flag3)
			{
				if (!_inputInjector.LastReplacementContradictedEditor)
				{
					return HotkeyStep.NotApplicable;
				}
				return HotkeyStep.Refused;
			}
			return HotkeyStep.Done;
		}

