		public void Dispose()
		{
			lock (_sync)
			{
				WithdrawEditorOwnedCorrection("Diyar is closing");
			}
			if (_capsLockLayoutEngaged)
			{
				RestoreLayoutBeforeCapsLock();
			}
			if (_shiftLanguageSwitchActive)
			{
				_layoutService.TryRequestForegroundLayout(ToActiveLanguage(_settings.General.ShiftLanguageSwitchDefaultLanguage));
				_shiftLanguageSwitchActive = false;
			}
			_keyboardHook.Dispose();
			_mouseHook.Dispose();
			_focusMonitor.Dispose();
			lock (_inputGate)
			{
				if (_editorWorkPending && !_heldKeysReleased)
				{
					ReleaseHeldKeysLocked("Diyar is closing");
				}
			}
			_enrichmentStopped = true;
			_editorWork.Dispose();
			SelectionWorker.Dispose();
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(66, 2, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("Hook timing at exit: ");
				message.AppendFormatted(_hookTiming.Describe());
				message.AppendLiteral("; editor work attempted on the hook thread: ");
				message.AppendFormatted(EditorWorkOnHookThread);
				message.AppendLiteral(".");
			}
			Log(ref message);
		}

