		private bool HandleKeyboardEvent(KeyboardEvent keyEvent)
		{
			long startingTimestamp = HookTimingStats.Timestamp();
			try
			{
				return RouteKeyFromHook(keyEvent);
			}
			finally
			{
				TimeSpan elapsedTime = Stopwatch.GetElapsedTime(startingTimestamp);
				_hookTiming.Record(elapsedTime);
				bool shouldAppend;
				if (elapsedTime.TotalMilliseconds > 5.0)
				{
					DiagnosticMessageHandler message = new DiagnosticMessageHandler(24, 1, out shouldAppend);
					if (shouldAppend)
					{
						message.AppendLiteral("Slow hook callback: ");
						message.AppendFormatted(elapsedTime.TotalMilliseconds, "0.0");
						message.AppendLiteral(" ms.");
					}
					Log(ref message);
					if (elapsedTime.TotalMilliseconds > 50.0)
					{
						Journal?.Incident("slow-hook", "a keyboard hook callback took longer than 50 ms", "durationMs", elapsedTime.TotalMilliseconds.ToString("0.0", CultureInfo.InvariantCulture), "keyEvent", keyEvent.IsKeyDown ? "down" : "up");
					}
				}
				if (_hookTiming.Count % 100 == 0L)
				{
					DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(14, 1, out shouldAppend);
					if (shouldAppend)
					{
						message2.AppendLiteral("Hook timing: ");
						message2.AppendFormatted(_hookTiming.Describe());
						message2.AppendLiteral(".");
					}
					Log(ref message2);
				}
			}
		}

		private bool RouteKeyFromHook(KeyboardEvent keyEvent)
		{
			lock (_inputGate)
			{
				if (_heldKeysReleased)
				{
					_heldKeys.Add(new HeldKey(keyEvent, _editorWork.NowMilliseconds, 0L, delivered: true));
					return SendOnBehindOwnInput(keyEvent);
				}
				if (_editorWorkPending)
				{
					_heldKeys.Add(new HeldKey(keyEvent, _editorWork.NowMilliseconds, _gate.GetForegroundTargetIdentity(), delivered: false));
					if (Enumerable.Count(_heldKeys, (HeldKey key) => !key.Delivered) > 64)
					{
						ReleaseHeldKeysLocked($"more than {64} key events waiting");
					}
					return true;
				}
			}
			if (!Monitor.TryEnter(_sync))
			{
				return PassOnBesideCommand(keyEvent);
			}
			try
			{
				bool injectedInputAhead = _gate.InjectedInputAhead;
				_hookThreadId = Environment.CurrentManagedThreadId;
				_handlingOnHookThread = true;
				_gate.Inner.WithoutAutomation = true;
				bool flag;
				try
				{
					flag = HandleKeyboardEventInOrder(keyEvent);
				}
				finally
				{
					_gate.Inner.WithoutAutomation = false;
					_handlingOnHookThread = false;
				}
				if (keyEvent.IsKeyDown)
				{
					RequestEditorFacts();
				}
				return flag || (injectedInputAhead && _gate.Inner.ReplayKeyEvents(new <>z__ReadOnlySingleElementList<KeyboardEvent>(keyEvent)));
			}
			finally
			{
				Monitor.Exit(_sync);
			}
		}

		private bool PassOnBesideCommand(KeyboardEvent keyEvent)
		{
			Interlocked.Increment(ref _passedBesideCommand);
			Journal?.Event("hook.key-beside-command", "note", "a command on another thread held the pipeline; the key goes on as typed");
			_commandInterrupted = true;
			if (!Monitor.TryEnter(_editorChangeLock))
			{
				return HoldForEditorWork(keyEvent);
			}
			try
			{
				if (_gate.Inner.HasOpenSelection)
				{
					_gate.Inner.CollapseOpenSelection(preferKeyboard: true);
					Log("A key was typed while a command had text selected: the selection is closed with the editor's own key, and the key goes on behind it.");
				}
				lock (_inputGate)
				{
					_editorWorkPending = true;
					_heldKeysReleased = true;
					_heldKeys.Add(new HeldKey(keyEvent, _editorWork.NowMilliseconds, 0L, delivered: true));
				}
				_editorWork.Signal();
				return _gate.Inner.InjectedInputAhead && _gate.Inner.ReplayKeyEvents(new <>z__ReadOnlySingleElementList<KeyboardEvent>(keyEvent));
			}
			finally
			{
				Monitor.Exit(_editorChangeLock);
			}
		}

		private void SendOnKeysHeldBesideCommand()
		{
			if (OnHookThread || !_commandInterrupted)
			{
				return;
			}
			lock (_inputGate)
			{
				if (_keyInProgress == null && _editorWorkPending && !_heldKeysReleased && _heldKeys.Any((HeldKey key) => !key.Delivered))
				{
					ReleaseHeldKeysLocked("the command's editor call ended");
				}
			}
		}

		private bool HoldForEditorWork(KeyboardEvent keyEvent)
		{
			long foregroundTargetIdentity = _gate.GetForegroundTargetIdentity();
			lock (_inputGate)
			{
				_editorWorkPending = true;
				_heldKeys.Add(new HeldKey(keyEvent, _editorWork.NowMilliseconds, foregroundTargetIdentity, delivered: false));
			}
			_editorWork.Signal();
			return true;
		}

		private bool SendOnBehindOwnInput(KeyboardEvent keyEvent)
		{
			if (_gate.Inner.InjectedInputAhead)
			{
				return _gate.Inner.ReplayKeyEvents(new <>z__ReadOnlySingleElementList<KeyboardEvent>(keyEvent));
			}
			return false;
		}

		private void RequestEditorWork(int what)
		{
			int num;
			do
			{
				num = Volatile.Read(in _editorWorkRequested);
			}
			while (Interlocked.CompareExchange(ref _editorWorkRequested, num | what, num) != num);
			DiagnosticJournal journal = Journal;
			if (journal != null)
			{
				Interlocked.CompareExchange(ref _workRequestedAt, _editorWork.NowMilliseconds, 0L);
				journal.Count("worker.request");
				if (Volatile.Read(in _workerWatch) > 0)
				{
					journal.Event("worker.request", "what", what, "keySeq", Volatile.Read(in _keySequence), "epoch", Volatile.Read(in _targetEpoch));
				}
			}
			_editorWork.Signal();
		}

