		private void DrainHeldKeys()
		{
			_draining = true;
			try
			{
				DrainHeldKeysNow();
			}
			finally
			{
				_draining = false;
			}
		}

		private void DrainHeldKeysNow()
		{
			bool shouldAppend;
			try
			{
				int num = Interlocked.Exchange(ref _editorWorkRequested, 0);
				if ((num & 8) != 0)
				{
					WarmUpConversionEngine();
				}
				if ((num & 1) != 0)
				{
					WarmUpProcessAutomation();
				}
				if ((num & 6) != 0)
				{
					RefreshEditorFacts((num & 4) != 0);
				}
			}
			catch (Exception ex)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(33, 1, out shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("Preparing editor facts failed (");
					message.AppendFormatted(ex.GetType().FullName);
					message.AppendLiteral(").");
				}
				Log(ref message);
			}
			long nowMilliseconds = _editorWork.NowMilliseconds;
			int num2 = 0;
			long num3 = 0L;
			while (true)
			{
				HeldKey heldKey;
				lock (_inputGate)
				{
					if (_heldKeys.Count == 0)
					{
						_editorWorkPending = false;
						_heldKeysReleased = false;
						_commandInterrupted = false;
						break;
					}
					heldKey = (_keyInProgress = _heldKeys[0]);
				}
				bool flag = false;
				try
				{
					lock (_sync)
					{
						if (heldKey.Delivered)
						{
							RecordKeySentOnAsTyped(heldKey.Event);
						}
						else
						{
							flag = !HandleKeyboardEventInOrder(heldKey.Event);
						}
					}
				}
				catch (Exception ex2)
				{
					DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(54, 1, out shouldAppend);
					if (shouldAppend)
					{
						message2.AppendLiteral("Handling a held key failed (");
						message2.AppendFormatted(ex2.GetType().FullName);
						message2.AppendLiteral("); it is sent on as typed.");
					}
					Log(ref message2);
					flag = true;
					lock (_sync)
					{
						RecordKeySentOnAsTyped(heldKey.Event);
					}
				}
				if (flag)
				{
					SendHeldKeyOn(heldKey);
				}
				if (heldKey.WasHeld && heldKey.DeliveredAt > 0)
				{
					num3 = Math.Max(num3, heldKey.DeliveredAt - heldKey.ArrivedAt);
				}
				lock (_inputGate)
				{
					_heldKeys.RemoveAt(0);
					_keyInProgress = null;
				}
				num2++;
			}
			if (num2 > 0)
			{
				DiagnosticMessageHandler message3 = new DiagnosticMessageHandler(89, 3, out shouldAppend);
				if (shouldAppend)
				{
					message3.AppendLiteral("Editor work done: ");
					message3.AppendFormatted(num2);
					message3.AppendLiteral(" key event(s) handled in order in ");
					message3.AppendFormatted(_editorWork.NowMilliseconds - nowMilliseconds);
					message3.AppendLiteral(" ms; the longest a key was held: ");
					message3.AppendFormatted(num3);
					message3.AppendLiteral(" ms.");
				}
				Log(ref message3);
			}
		}

		private void SendHeldKeyOn(HeldKey key)
		{
			lock (_editorChangeLock)
			{
				lock (_inputGate)
				{
					if (key.Delivered)
					{
						return;
					}
					key.Delivered = true;
					key.DeliveredAt = _editorWork.NowMilliseconds;
				}
				if (!_gate.Inner.ReplayKeyEvents(new <>z__ReadOnlySingleElementList<KeyboardEvent>(key.Event)))
				{
					DiagnosticMessageHandler message = new DiagnosticMessageHandler(50, 1, out var shouldAppend);
					if (shouldAppend)
					{
						message.AppendLiteral("A held key could not be sent on: SendInput error ");
						message.AppendFormatted(_gate.Inner.LastSendInputError);
						message.AppendLiteral(".");
					}
					Log(ref message);
				}
			}
