		private ParagraphDirectionPlan PlanParagraphDirection(string source, ParagraphDirectionHost host)
		{
			if (_paragraphMarked)
			{
				return ParagraphDirectionPlan.AlreadyMarked;
			}
			if (!_buffer.TryGetKnownParagraphText(out string paragraphText))
			{
				return WordOnly("paragraph start not known (a click, a focus change, a navigation key or text the keys did not type since it)", considered: false);
			}
			if (!paragraphText.EndsWith(source, StringComparison.Ordinal))
			{
				return WordOnly("the word is not the end of the known paragraph text", considered: false);
			}
			string text = paragraphText;
			int length = source.Length;
			string text2 = text.Substring(0, text.Length - length);
			if (text2.Length == 0)
			{
				return new ParagraphDirectionPlan(WritesMark: true, string.Empty, "the word starts the paragraph", RewriteConsidered: false);
			}
			if (Volatile.Read(in _foreignInputSeen))
			{
				return WordOnly("another program sent input since the last key (a text expander or macro tool may have changed the start)");
			}
			ParagraphFact paragraphFact = Volatile.Read(in _paragraphFact);
			if ((object)paragraphFact == null || paragraphFact.Sequence != Volatile.Read(in _keySequence))
			{
				return WordOnly("the editor was not read since the last key, so the start is not confirmed");
			}
			if (paragraphFact.Read)
			{
				string text3 = BidiControlCharacters.Remove(paragraphFact.Prefix);
				string text4 = text3.Substring(text3.LastIndexOf('\n') + 1);
				string text5 = BidiControlCharacters.Remove(paragraphText);
				if (!text4.EndsWith(text5, StringComparison.Ordinal) && (text4.Length < text2.Length || !text5.StartsWith(text4, StringComparison.Ordinal)))
				{
					return WordOnly("the editor shows a different paragraph start (its own autocorrect, or text the keys did not type)");
				}
			}
			if (!_settings.Correction.RewriteParagraphStartForDirection)
			{
				return WordOnly("rewriteParagraphStartForDirection is off");
			}
			if (EffectiveCorrectionMode != CorrectionMode.Automatic)
			{
				return WordOnly("not Automatic correction");
			}
			if (IsTargetRestricted())
			{
				return WordOnly("protected or English-only field, or its protection is not known yet");
			}
			if (_gate.Inner.FocusedEditorLosesUnicodeBatches())
			{
				return WordOnly("this editor loses characters sent together (KL-048)");
			}
			if (host.HasFlag(ParagraphDirectionHost.OwnsParagraphDirection))
			{
				return WordOnly("this editor keeps a direction per paragraph; Ctrl+Right Shift sets it");
			}
			if (host.HasFlag(ParagraphDirectionHost.RefusesPrefixRewrite))
			{
				return WordOnly("Office, Notepad or a console: typed text may be changed by the editor");
			}
			if (CapsLockIsOn())
			{
				return WordOnly("Caps Lock is on, so the editor's letters may not be the keys' case");
			}
			if (_inputInjector.HardwareKeyboardAutocorrectIsOn())
			{
				return WordOnly("Windows hardware-keyboard autocorrect is on");
			}
			ParagraphStartRewrite paragraphStartRewrite = ParagraphDirectionPolicy.EvaluateRewrite(text2);
			if (!paragraphStartRewrite.Allowed)
			{
				return WordOnly($"the English start is not plain short text ({paragraphStartRewrite.Reason}, {text2.Length} character(s))");
			}
			return new ParagraphDirectionPlan(WritesMark: true, text2, "short plain English start typed since a known paragraph start", RewriteConsidered: true);
			static ParagraphDirectionPlan WordOnly(string reason, bool considered = true)
			{
				return new ParagraphDirectionPlan(WritesMark: true, string.Empty, "paragraph start not rewritten: " + reason, considered);
			}
		}

		private void RecordCommittedToken(BufferedToken typedToken, string boundaryText, string targetLayoutId, string? rawText = null, string? displayText = null, AmountExpansion? amount = null)
		{
			if (rawText == null)
			{
