			}
			if (amount.HasValue)
			{
				AmountExpansion valueOrDefault = amount.GetValueOrDefault();
				if (rawText.Length > valueOrDefault.Source.Length && displayText.Length > valueOrDefault.Target.Length && rawText.StartsWith(valueOrDefault.Source, StringComparison.Ordinal) && displayText.StartsWith(valueOrDefault.Target, StringComparison.Ordinal))
				{
					rawText = rawText.Substring(valueOrDefault.Source.Length);
					displayText = displayText.Substring(valueOrDefault.Target.Length);
				}
			}
			List<BufferedKeyStroke> list = new List<BufferedKeyStroke>(rawText.Length);
			string text = rawText;
			for (int i = 0; i < text.Length; i++)
			{
				if (!EnglishUsKeyRenderer.TryCreateStroke(text[i], out var stroke))
				{
					return;
				}
				list.Add(stroke);
			}
			CommittedToken committedToken = _buffer.RecordCommittedToken(typedToken with
			{
				Strokes = list
