			if ((object)committedToken != null)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(62, 7, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("TokenCommitted id=");
					message.AppendFormatted(committedToken.Id);
					message.AppendLiteral(" raw='");
					message.AppendFormatted(committedToken.RawText);
					message.AppendLiteral("' display='");
					message.AppendFormatted(committedToken.DisplayText);
					message.AppendLiteral("' range=[");
					message.AppendFormatted(committedToken.StartOffset);
					message.AppendLiteral(",");
					message.AppendFormatted(committedToken.EndOffset);
					message.AppendLiteral(") route=");
					message.AppendFormatted(committedToken.Route);
					message.AppendLiteral(" layout=");
					message.AppendFormatted(committedToken.TargetLayoutId);
					message.AppendLiteral(".");
				}
				Log(ref message);
			}
		}

