		private void RememberEnglishWord(string word)
		{
			if (IsEnglishPhrase(word))
			{
				_paragraphEnglishWords++;
				if (!UppercaseLatinPolicy.HasUppercaseLatin(word))
				{
					_paragraphEnglishProseWords++;
				}
			}
		}

		private void ForgetEnglishWord(string word)
		{
			if (IsEnglishPhrase(word))
			{
				_paragraphEnglishWords = Math.Max(0, _paragraphEnglishWords - 1);
				if (!UppercaseLatinPolicy.HasUppercaseLatin(word))
				{
					_paragraphEnglishProseWords = Math.Max(0, _paragraphEnglishProseWords - 1);
				}
			}
