		internal static bool TryCreateTrailingVisibleToken(string paragraphPrefix, out BufferedToken token, out string trailingText)
		{
			token = BufferedToken.Empty;
			trailingText = string.Empty;
			if (string.IsNullOrEmpty(paragraphPrefix))
			{
				return false;
			}
			int num = paragraphPrefix.Length;
			while (num > 0 && char.IsWhiteSpace(paragraphPrefix[num - 1]))
			{
				num--;
			}
			trailingText = paragraphPrefix.Substring(num);
			int num2 = num;
			BufferedKeyStroke stroke;
			while (num2 > 0 && EnglishUsKeyRenderer.TryCreateStroke(paragraphPrefix[num2 - 1], out stroke))
			{
				num2--;
			}
			if (num2 == num)
			{
				trailingText = string.Empty;
				return false;
			}
			List<BufferedKeyStroke> list = new List<BufferedKeyStroke>(num - num2);
			for (int i = num2; i < num; i++)
			{
				if (!EnglishUsKeyRenderer.TryCreateStroke(paragraphPrefix[i], out var stroke2))
				{
					trailingText = string.Empty;
					return false;
				}
				list.Add(stroke2);
			}
			int num3 = 0;
			int num4 = num2 - 1;
			while (num4 >= 0 && paragraphPrefix[num4] == ' ')
			{
				num3++;
				num4--;
			}
			int num5 = num2 - num3 - 1;
			bool flag = num5 < 0;
			if (!flag)
			{
				bool flag2;
				switch (paragraphPrefix[num5])
				{
				case '!':
				case '.':
				case '?':
				case '؟':
					flag2 = true;
					break;
				default:
					flag2 = false;
					break;
				}
				flag = flag2;
			}
			bool startsSentence = flag;
			token = new BufferedToken(list, startsSentence, num3 > 0, num3);
			return true;
		}

		private bool TryPrepareBoundaryConversion(BufferedToken bufferedToken, bool forcePersian, out BufferedToken conversionToken, out string source, out string target, out string detectionSource, out string detectionTarget)
		{
			conversionToken = bufferedToken;
			_replaceUsingKeyBuffer = false;
			_decisionReason = string.Empty;
			_boundaryConversionRefusedByGuard = false;
			_wordKeptAsBilingualByContext = null;
			string lastInvalidationReason = _lastInvalidationReason;
			_lastInvalidationReason = string.Empty;
			source = string.Empty;
			target = string.Empty;
			detectionSource = string.Empty;
			detectionTarget = string.Empty;
			if (bufferedToken.Count > 0 && bufferedToken.Strokes.All((BufferedKeyStroke stroke) => stroke.EmittedCharacter != '\0'))
			{
				_decisionReason = "pass-through: every key was already typed as Persian";
				NoteWordShownAsPersian();
				return false;
			}
			bool shouldAppend;
			if (!HasEmittedCharacters(bufferedToken) && ShouldAttemptVisibleFirstTokenRecovery(_visibleFirstTokenRecoveryPending, bufferedToken))
			{
				_visibleFirstTokenRecoveryPending = false;
				bool guardVisibleFirstTokenRecovery = _settings.Correction.GuardVisibleFirstTokenRecovery;
				string paragraphPrefix;
				BufferedToken token;
				string trailingText;
				if (!VisibleRecoveryMayJudge(_settings.Correction.VisibleRecoveryNeedsTypedKeys, bufferedToken.Count))
				{
					Journal?.Count("recovery.visible-first-token.no-typed-keys");
					DiagnosticMessageHandler message = new DiagnosticMessageHandler(200, 1, out shouldAppend);
					if (shouldAppend)
					{
						message.AppendLiteral("Visible first-token recovery not attempted: no key of this word was typed (invalidation since the last word: ");
						message.AppendFormatted((lastInvalidationReason.Length > 0) ? lastInvalidationReason : "none recorded");
						message.AppendLiteral("); the editor's word is not the client's typing (Correction.VisibleRecoveryNeedsTypedKeys).");
					}
					Log(ref message);
				}
				else if (guardVisibleFirstTokenRecovery && _editorTextUntrusted)
				{
					Journal?.Count("recovery.visible-first-token.skipped-distrusted");
					DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(131, 1, out shouldAppend);
					if (shouldAppend)
					{
						message2.AppendLiteral("Visible first-token recovery skipped: the editor text is distrusted, so its word cannot stand in for the typed '");
						message2.AppendFormatted(DiagnosticLog.Tail(TokenText(bufferedToken), 40));
						message2.AppendLiteral("'; the keys decide.");
					}
					Log(ref message2);
				}
				else if (_inputInjector.TryGetCurrentParagraphPrefixText(string.Empty, out paragraphPrefix) && TryCreateTrailingVisibleToken(paragraphPrefix, out token, out trailingText) && ShouldPreferVisibleFirstToken(bufferedToken, token, trailingText, requireTypedKeysAsSuffix: false))
				{
					if (!guardVisibleFirstTokenRecovery || VisibleWordEndsWithTypedKeys(token, bufferedToken))
					{
						Journal?.Count("recovery.visible-first-token.used");
						DiagnosticMessageHandler message3 = new DiagnosticMessageHandler(116, 4, out shouldAppend);
						if (shouldAppend)
						{
							message3.AppendLiteral("Visible first-token recovery: the editor's word '");
							message3.AppendFormatted(DiagnosticLog.Tail(TokenText(token), 40));
							message3.AppendLiteral("' (");
							message3.AppendFormatted(token.Count);
							message3.AppendLiteral(" keys) stands in for the typed '");
							message3.AppendFormatted(DiagnosticLog.Tail(TokenText(bufferedToken), 40));
							message3.AppendLiteral("' (");
							message3.AppendFormatted(bufferedToken.Count);
							message3.AppendLiteral(") and is judged in its place.");
						}
						Log(ref message3);
						conversionToken = token;
						if (TryPrepareConversion(token, forcePersian, out source, out target, out detectionSource, out detectionTarget))
						{
							return true;
						}
						_decisionReason = ((Journal == null) ? string.Empty : $"pass-through: the engine left the editor's word '{DiagnosticLog.Tail(TokenText(token), 40)}' as typed; the visible first-token recovery judged it in place of the typed '{DiagnosticLog.Tail(TokenText(bufferedToken), 40)}' (see its decision note)");
						return false;
					}
					Journal?.Count("recovery.visible-first-token.declined");
					DiagnosticMessageHandler message4 = new DiagnosticMessageHandler(165, 4, out shouldAppend);
					if (shouldAppend)
					{
						message4.AppendLiteral("Visible first-token recovery declined: the editor's word '");
						message4.AppendFormatted(DiagnosticLog.Tail(TokenText(token), 40));
						message4.AppendLiteral("' (");
						message4.AppendFormatted(token.Count);
						message4.AppendLiteral(" keys) does not end with the typed '");
						message4.AppendFormatted(DiagnosticLog.Tail(TokenText(bufferedToken), 40));
						message4.AppendLiteral("' (");
						message4.AppendFormatted(bufferedToken.Count);
						message4.AppendLiteral("); it is another word, so the typed word is judged from the keys.");
					}
					Log(ref message4);
				}
			}
			if (bufferedToken.Count == 0 || !TryPrepareConversion(bufferedToken, forcePersian, out source, out target, out detectionSource, out detectionTarget))
			{
				_decisionReason = ((bufferedToken.Count == 0) ? "pass-through: no keys in the word" : "pass-through: the engine left the word as typed (see its decision note)");
				return false;
			}
			VisibleTokenCheck visibleTokenCheck = ReadVisibleTokenCheck(bufferedToken, out BufferedToken completeToken);
			VisibleCheckDecision visibleCheckDecision = ResolveVisibleCheck(visibleTokenCheck, bufferedToken.StartKnown, bufferedToken.PrecedingText.Length > 0);
			DiagnosticMessageHandler message5 = new DiagnosticMessageHandler(97, 5, out shouldAppend);
			if (shouldAppend)
			{
				message5.AppendLiteral("TryPrepareBoundaryConversion: visible check=");
				message5.AppendFormatted(visibleTokenCheck);
				message5.AppendLiteral("; startKnown=");
				message5.AppendFormatted(bufferedToken.StartKnown);
				message5.AppendLiteral("; editorTextUntrusted=");
				message5.AppendFormatted(_editorTextUntrusted);
				message5.AppendLiteral("; decision=");
				message5.AppendFormatted(visibleCheckDecision);
				message5.AppendLiteral("; why=");
				message5.AppendFormatted(_lastVisibleCheckWhy);
				message5.AppendLiteral(".");
			}
			Log(ref message5);
			Journal?.Tally("visible." + visibleTokenCheck.ToString() + "." + visibleCheckDecision);
			switch (visibleCheckDecision)
			{
			case VisibleCheckDecision.Skip:
			{
				_boundaryConversionRefusedByGuard = true;
				_refusedCandidate = (source, target);
				_decisionReason = ((Journal == null) ? string.Empty : $"REFUSED-BY-GUARD ({_lastVisibleCheckWhy}): engine allowed '{DiagnosticLog.Tail(source, 40)}' -> '{DiagnosticLog.Tail(target, 40)}' but the editor text is {visibleTokenCheck} and the word start is unknown; {DescribeParagraphFact(Volatile.Read(in _paragraphFact), Volatile.Read(in _keySequence))}");
				DiagnosticMessageHandler message6 = new DiagnosticMessageHandler(201, 1, out shouldAppend);
				if (shouldAppend)
				{
					message6.AppendLiteral("Conversion skipped although the engine allowed it: the editor text is ");
					message6.AppendFormatted(visibleTokenCheck);
					message6.AppendLiteral(" and the word start is unknown after a caret move, so replacing could damage text the buffer never saw. Ctrl+Alt+Space converts it.");
				}
				Log(ref message6);
				return false;
			}
			case VisibleCheckDecision.UseKeyBuffer:
				if (_lastPreparedRoute == "IsolatedLetter" && IsFirstInEmptyText(bufferedToken))
				{
					_boundaryConversionRefusedByGuard = true;
					_decisionReason = ((Journal == null) ? string.Empty : $"REFUSED-BY-GUARD: engine allowed an isolated letter but the editor text is {visibleTokenCheck}, so the field may hold text the keys never showed");
					DiagnosticMessageHandler message7 = new DiagnosticMessageHandler(125, 1, out shouldAppend);
					if (shouldAppend)
					{
						message7.AppendLiteral("Conversion skipped: a letter typed first with the editor text ");
						message7.AppendFormatted(visibleTokenCheck);
						message7.AppendLiteral("; the field may hold text before it that the keys never showed.");
					}
					Log(ref message7);
					return false;
				}
				shouldAppend = (uint)(visibleTokenCheck - 2) <= 1u;
				if (shouldAppend)
				{
					SetEditorTextTrust(untrusted: true, $"the editor text is {visibleTokenCheck} against the typed word with no caret move; the keys decide (word start known={bufferedToken.StartKnown})");
					Log("Editor text contradicts the typed keys with no caret move; using the key buffer for this editor.");
				}
				_replaceUsingKeyBuffer = true;
				break;
			default:
				if (visibleTokenCheck == VisibleTokenCheck.Extended)
				{
					conversionToken = completeToken;
					_visibleFirstTokenRecoveryPending = false;
					return TryPrepareConversion(completeToken, forcePersian, out source, out target, out detectionSource, out detectionTarget);
				}
				break;
			}
			_visibleFirstTokenRecoveryPending = false;
			return true;
		}

		private void NoteWordShownAsPersian()
		{
			NotePreviousWord(StrongTypingLanguage.Persian);
			_paragraphPersianWords++;
		}

		internal static bool AllowsUnknownPersianWords(bool paragraphIsPersian, bool lastWordWasEnglish)
		{
			if (!paragraphIsPersian)
			{
				return !lastWordWasEnglish;
			}
			return true;
		}

		internal static VisibleCheckDecision ResolveVisibleCheck(VisibleTokenCheck check, bool startKnown, bool precedingKnown = false)
		{
			switch (check)
			{
			case VisibleTokenCheck.Confirmed:
				return VisibleCheckDecision.UseEditor;
			case VisibleTokenCheck.Extended:
				return (startKnown & precedingKnown) ? VisibleCheckDecision.UseKeyBuffer : VisibleCheckDecision.UseEditor;
			case VisibleTokenCheck.Lagging:
				return VisibleCheckDecision.UseEditor;
			case VisibleTokenCheck.Unreadable:
			case VisibleTokenCheck.Mismatch:
				return startKnown ? VisibleCheckDecision.UseKeyBuffer : VisibleCheckDecision.Skip;
			default:
				return VisibleCheckDecision.Skip;
			}
		}

		internal static bool IsStaleRead(VisibleTokenCheck check, string prefix, string token, string? previousPrefix, string previousToken)
		{
			bool flag = (uint)(check - 3) <= 1u;
			if (flag && prefix.Length > 0 && previousPrefix != null && !string.Equals(token, previousToken, StringComparison.Ordinal))
			{
				return string.Equals(prefix, previousPrefix, StringComparison.Ordinal);
			}
			return false;
		}

		private VisibleTokenCheck ReadVisibleTokenCheck(BufferedToken bufferedToken, out BufferedToken completeToken)
		{
			if (_editorTextUntrusted)
			{
				if (TryRecoverEditorTrust(bufferedToken, out completeToken, out var check))
				{
					_lastVisibleCheckWhy = "editor-trust-recovered";
					return check;
				}
				_lastVisibleCheckWhy = "editor-distrusted-and-not-recovered";
				completeToken = BufferedToken.Empty;
				return VisibleTokenCheck.Unreadable;
			}
			int num = ((OnHookThread || _inputInjector.EditorTextIsKnownStale) ? 1 : 4);
			string text = TokenText(bufferedToken);
			int num2 = 1;
			string paragraphPrefix;
			VisibleTokenCheck visibleTokenCheck;
			string why;
			while (true)
			{
				bool flag = _inputInjector.TryGetCurrentParagraphPrefixText(string.Empty, out paragraphPrefix);
				visibleTokenCheck = CheckBufferedTokenAgainstVisibleText(bufferedToken, flag, paragraphPrefix, out completeToken, out why);
				_lastVisibleCheckWhy = why;
				bool shouldAppend;
				if (DiagnosticLog.VerboseEnabled)
				{
					DiagnosticMessageHandler message = new DiagnosticMessageHandler(77, 6, out shouldAppend);
					if (shouldAppend)
					{
						message.AppendLiteral("Visible check attempt ");
						message.AppendFormatted(num2);
						message.AppendLiteral(": buffered='");
						message.AppendFormatted(text);
						message.AppendLiteral("' preceding='");
						message.AppendFormatted(bufferedToken.PrecedingText);
						message.AppendLiteral("' read=");
						message.AppendFormatted(flag);
						message.AppendLiteral(" editorText='");
						message.AppendFormatted(DiagnosticLog.Tail(paragraphPrefix));
						message.AppendLiteral("' result=");
						message.AppendFormatted(visibleTokenCheck);
						message.AppendLiteral(".");
					}
					Log(ref message);
				}
				shouldAppend = (uint)(visibleTokenCheck - 3) <= 1u;
				if (!shouldAppend || num2 >= num)
				{
					break;
				}
				Thread.Sleep(10);
				num2++;
			}
			NoteReadEvidence(visibleTokenCheck, why, bufferedToken, paragraphPrefix);
			RecordVisibleRead(visibleTokenCheck, paragraphPrefix, text);
			return visibleTokenCheck;
		}

		private void ForgetVisibleReadHistory()
		{
			_previousVisiblePrefix = null;
			_previousVisibleToken = string.Empty;
			_staleVisibleReads = 0;
		}

		private void RecordVisibleRead(VisibleTokenCheck check, string prefix, string token)
		{
			if (IsStaleRead(check, prefix, token, _previousVisiblePrefix, _previousVisibleToken))
			{
				_staleVisibleReads++;
				if (_staleVisibleReads >= 2)
				{
					_inputInjector.ObserveStaleEditorText();
				}
			}
			else if ((uint)(check - 1) <= 1u)
			{
				_staleVisibleReads = 0;
			}
			_previousVisiblePrefix = prefix;
			_previousVisibleToken = token;
		}

		internal static VisibleTokenCheck CheckBufferedTokenAgainstVisibleText(BufferedToken bufferedToken, bool visibleRead, string paragraphPrefix, out BufferedToken completeToken)
		{
			string why;
			return CheckBufferedTokenAgainstVisibleText(bufferedToken, visibleRead, paragraphPrefix, out completeToken, out why);
		}

		internal static VisibleTokenCheck CheckBufferedTokenAgainstVisibleText(BufferedToken bufferedToken, bool visibleRead, string paragraphPrefix, out BufferedToken completeToken, out string why)
		{
			completeToken = BufferedToken.Empty;
			why = "unreadable";
			if (!visibleRead)
			{
				return VisibleTokenCheck.Unreadable;
			}
			paragraphPrefix = paragraphPrefix.TrimEnd(DirectionControls);
			if (HasEmittedCharacters(bufferedToken))
			{
				why = "compared-with-shown-characters";
				return CheckShownTextAgainstVisibleText(ShownText(bufferedToken), paragraphPrefix);
			}
			if (!TryCreateTrailingVisibleToken(paragraphPrefix, out BufferedToken token, out string trailingText))
			{
				if (string.IsNullOrEmpty(paragraphPrefix))
				{
					why = "no-word-before-caret:empty-paragraph";
					return VisibleTokenCheck.Lagging;
				}
				string text = paragraphPrefix;
				if (char.IsWhiteSpace(text[text.Length - 1]))
				{
					why = "no-word-before-caret:ends-with-whitespace";
					return VisibleTokenCheck.Lagging;
				}
				if (BidiControlCharacters.EndsWithPrecedingText(paragraphPrefix, bufferedToken.PrecedingText))
				{
					why = "no-word-before-caret:ends-with-the-preceding-word";
					return VisibleTokenCheck.Lagging;
				}
				why = "no-word-before-caret:text-ends-with-something-else";
				return VisibleTokenCheck.Mismatch;
			}
			if (trailingText.Length > 0)
			{
				why = "caret-follows-whitespace";
				return VisibleTokenCheck.Lagging;
			}
			string text2 = TokenText(bufferedToken);
			string text3 = TokenText(token);
			if (PhysicalTextEquals(text3, text2))
			{
				why = "trailing-word-equals-typed-word";
				return VisibleTokenCheck.Confirmed;
			}
			if (text3.Length > text2.Length)
			{
				int length = text2.Length;
				if (PhysicalTextEquals(text3.Substring(text3.Length - length), text2))
				{
					completeToken = token;
					why = "trailing-word-ends-with-typed-word";
					return VisibleTokenCheck.Extended;
				}
			}
			if (text3.Length < text2.Length && PhysicalTextEquals(text2.Substring(0, text3.Length), text3))
			{
				why = "trailing-word-is-a-start-of-typed-word";
				return VisibleTokenCheck.Lagging;
			}
			if (BidiControlCharacters.EndsWithPrecedingText(paragraphPrefix, bufferedToken.PrecedingText))
			{
				why = "trailing-word-differs:ends-with-the-preceding-word";
				return VisibleTokenCheck.Lagging;
			}
			why = "trailing-word-differs";
			return VisibleTokenCheck.Mismatch;
		}

		internal static VisibleTokenCheck CheckShownTextAgainstVisibleText(string shown, string paragraphPrefix)
		{
			if (paragraphPrefix.Length >= shown.Length)
			{
				int length = shown.Length;
				if (PhysicalTextEquals(paragraphPrefix.Substring(paragraphPrefix.Length - length), shown))
				{
					if (paragraphPrefix.Length != shown.Length)
					{
						length = shown.Length + 1;
						if (!char.IsWhiteSpace(paragraphPrefix[paragraphPrefix.Length - length]))
						{
							goto IL_0059;
						}
					}
					return VisibleTokenCheck.Confirmed;
				}
			}
			goto IL_0059;
			IL_0059:
			int num = paragraphPrefix.Length;
			while (num > 0 && !char.IsWhiteSpace(paragraphPrefix[num - 1]))
			{
				num--;
			}
			string text = paragraphPrefix.Substring(num);
			if (text.Length >= shown.Length || !PhysicalTextEquals(shown.Substring(0, text.Length), text))
			{
				return VisibleTokenCheck.Unreadable;
			}
			return VisibleTokenCheck.Lagging;
		}

		internal static bool IsLaggingPrefixOf(BufferedToken visibleToken, BufferedToken bufferedToken)
		{
			string text = TokenText(visibleToken);
			string text2 = TokenText(bufferedToken);
			if (text.Length < text2.Length)
			{
				return PhysicalTextEquals(text2.Substring(0, text.Length), text);
			}
			return false;
		}

		private static string TokenText(BufferedToken token)
		{
			return new string(token.Strokes.Select((BufferedKeyStroke stroke) => stroke.SourceCharacter).ToArray());
		}

		private static string ShownText(BufferedToken token)
		{
			return new string(token.Strokes.Select((BufferedKeyStroke stroke) => stroke.ShownCharacter).ToArray());
		}

		private static bool HasEmittedCharacters(BufferedToken token)
		{
			return token.Strokes.Any((BufferedKeyStroke stroke) => stroke.EmittedCharacter != '\0');
		}

		private static bool PhysicalTextEquals(string actual, string expected)
		{
			if (actual.Length == expected.Length)
			{
				return actual.Zip(expected).All(((char First, char Second) pair) => pair.First == pair.Second || (char.IsAsciiLetter(pair.First) && char.IsAsciiLetter(pair.Second) && char.ToLowerInvariant(pair.First) == char.ToLowerInvariant(pair.Second)));
			}
			return false;
		}

		internal static bool ShouldAttemptVisibleFirstTokenRecovery(bool recoveryPending, BufferedToken bufferedToken)
		{
			if (recoveryPending)
			{
				if (bufferedToken.Count != 0)
				{
					return bufferedToken.StartsSentence;
				}
				return true;
			}
			return false;
		}

		internal static bool VisibleRecoveryMayJudge(bool switchOn, int typedKeys)
		{
			if (switchOn)
			{
				return typedKeys > 0;
			}
			return true;
		}

		internal static bool ShouldPreferVisibleFirstToken(BufferedToken bufferedToken, BufferedToken visibleToken, string trailingText, bool requireTypedKeysAsSuffix)
		{
			if (trailingText.Length == 0 && visibleToken.StartsSentence && visibleToken.Count > bufferedToken.Count)
			{
				if (requireTypedKeysAsSuffix)
				{
					return VisibleWordEndsWithTypedKeys(visibleToken, bufferedToken);
				}
				return true;
			}
			return false;
		}

		internal static bool VisibleWordEndsWithTypedKeys(BufferedToken visibleToken, BufferedToken bufferedToken)
		{
			if (visibleToken.Count < bufferedToken.Count)
			{
				return false;
			}
			string text = TokenText(visibleToken);
			string text2 = TokenText(bufferedToken);
			int length = text2.Length;
			return PhysicalTextEquals(text.Substring(text.Length - length), text2);
		}

		private void SynchronizeForegroundTarget()
		{
			long foregroundTargetIdentity = _inputInjector.GetForegroundTargetIdentity();
			if (foregroundTargetIdentity != 0L && foregroundTargetIdentity != _foregroundTargetIdentity)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(90, 2, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("Focus moved to another window (0x");
					message.AppendFormatted(foregroundTargetIdentity, "X");
					message.AppendLiteral("); typing context reset; language context cleared (was ");
					message.AppendFormatted(DescribeLanguageContext());
					message.AppendLiteral(").");
				}
				Log(ref message);
				if (_englishHoldDown && _holdWindow != _gate.GetForegroundWindowIdentity())
				{
					ClearHoldState("focus moved to another window");
				}
				RequestEditorFacts();
				_foregroundTargetIdentity = foregroundTargetIdentity;
				SetEditorTextTrust(untrusted: false, "focus moved to another window or field");
				ForgetVisibleReadHistory();
				_manualMode.Reset();
				ClearEnglishCapital();
				_bufferResetCause = "SynchronizeForegroundTarget: the foreground window changed, the buffer was reset with the start assumed known";
				_buffer.Reset(caretMoved: false);
				_englishWordLocked = false;
				_englishLockEndsAtNextWord = false;
				_visibleFirstTokenRecoveryPending = true;
				_lastConversion = null;
				_rightToLeftParagraph = false;
				_rightToLeftEmbeddingOpen = false;
				_paragraphMarked = false;
				ForgetPreviousWords();
				ResetParagraphLanguageCounts();
				_persianHoldWordOpen = false;
				_leftToRightMarkedPunctuationBehindCaret = null;
				_continuePersianEditAfterBackspace = false;
			}
		}

		private void ApplyCapsLockLayoutTransition(bool capsLockEnabled)
		{
			if (!_settings.General.Enabled || _settings.General.TypingMode != TypingMode.CapsLockSwitch)
			{
				return;
			}
			CapsLockBehavior capsLockBehavior = _settings.General.CapsLockBehavior;
			CapsLockLayoutTarget capsLockLayoutTarget = CapsLockBehaviorPolicy.ResolveLayoutTarget(capsLockBehavior, capsLockEnabled);
			if (capsLockEnabled)
			{
				_layoutBeforeCapsLock = _layoutService.GetActiveLayout();
				_capsLockLayoutEngaged = true;
			}
			else
			{
				if (capsLockLayoutTarget == CapsLockLayoutTarget.PreviousLayout)
				{
					RestoreLayoutBeforeCapsLock();
					return;
				}
				_capsLockLayoutEngaged = false;
			}
			ActiveLanguage activeLanguage = capsLockLayoutTarget switch
			{
				CapsLockLayoutTarget.English => ActiveLanguage.English, 
				CapsLockLayoutTarget.Persian => ActiveLanguage.Persian, 
				_ => ActiveLanguage.Unknown, 
			};
			if (activeLanguage != ActiveLanguage.Unknown)
			{
				Log(RequestForegroundLayout(activeLanguage, _settings.General.PersianKeyboardLayout, "ApplyCapsLockLayoutTransition") ? $"Caps Lock {(capsLockEnabled ? "on" : "off")} requested the installed {activeLanguage} layout ({capsLockBehavior})." : $"Caps Lock {(capsLockEnabled ? "on" : "off")} found no installed {activeLanguage} layout ({capsLockBehavior}).");
			}
		}

		private void RestoreLayoutBeforeCapsLock()
		{
			KeyboardLayoutSnapshot layoutBeforeCapsLock = _layoutBeforeCapsLock;
			_capsLockLayoutEngaged = false;
			_layoutBeforeCapsLock = default;
			if (layoutBeforeCapsLock.Handle != IntPtr.Zero && _layoutService.GetActiveLayout().Handle != layoutBeforeCapsLock.Handle)
			{
				Log(RequestForegroundLayout(layoutBeforeCapsLock, "RestoreLayoutBeforeCapsLock") ? $"Caps Lock off restored the previous {layoutBeforeCapsLock.Language} layout." : $"Caps Lock off could not restore the previous {layoutBeforeCapsLock.Language} layout.");
			}
		}

		private bool EnglishCapitalIsPending()
		{
			return _settings.General.TypingMode switch
			{
				TypingMode.ManualCorrection => _manualMode.CapitalPending, 
				TypingMode.AutomaticCorrection => _englishCapitalPending, 
				_ => false, 
			};
		}

		private string? EnglishOnlyApplicationHolding()
		{
			if (_settings.Correction.KeepEnglishInEnglishOnlyApps && _settings.General.TypingMode == TypingMode.AutomaticCorrection && EffectiveCorrectionMode == CorrectionMode.Automatic)
			{
				EnglishOnlyApplicationMatch englishOnlyApplicationMatch = _inputInjector.FocusedEnglishOnlyApplication();
				if ((object)englishOnlyApplicationMatch != null)
				{
					if (!EnglishOnlyPlaces.KeepsEnglish(_settings.Correction, englishOnlyApplicationMatch.PlaceId))
					{
						return null;
					}
					return englishOnlyApplicationMatch.Description;
				}
			}
			return null;
		}

		private string? NonTextTargetHolding()
		{
			if (!_settings.Correction.KeepNonTextTargetsUntouched || _settings.General.TypingMode != TypingMode.AutomaticCorrection || EffectiveCorrectionMode != CorrectionMode.Automatic)
			{
				return null;
			}
			string text = PreparedControlType() ?? (OnHookThread ? null : LiveControlType());
			if (!NonTextTargetPolicy.IsNonTextControl(text))
			{
				return null;
			}
			return text;
		}

		private string LiveControlType()
		{
			_inputInjector.IsProtectedTechnicalField(out string checkedControlType);
			return checkedControlType;
		}

		private void ClearEnglishCapital()
		{
			_englishCapitalPending = false;
			_englishCapitalWordEnded = false;
		}

		private bool TryTypeEnglishCapital(int virtualKey, bool capsLockEnabled, bool capsLockIsHoldKey, out char capital)
		{
			capital = '\0';
			if (!_settings.Correction.CapitalizeEnglishAfterPersian || OnlyAPersianHoldKey || !EnglishCapitalIsPending())
			{
				return false;
			}
			string text = EnglishOnlyApplicationHolding();
			bool shouldAppend;
			if (text != null)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(66, 1, out shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("English capital refused: an English-only application has focus (");
					message.AppendFormatted(text);
					message.AppendLiteral(").");
				}
				Log(ref message);
				return false;
			}
			string text2 = NonTextTargetHolding();
			if (text2 != null)
			{
				DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(110, 1, out shouldAppend);
				if (shouldAppend)
				{
					message2.AppendLiteral("English capital refused: the focused element is a ");
					message2.AppendFormatted(text2);
					message2.AppendLiteral(", not a text field (Correction.KeepNonTextTargetsUntouched).");
				}
				Log(ref message2);
				return false;
			}
			if (!EnglishCapitalPolicy.WantsCapital(previousWordPersian: true, virtualKey, _shiftDown, _controlDown, _altDown, _windowsDown, capsLockEnabled, capsLockIsHoldKey) || !EnglishCapitalPolicy.TryGetCapital(virtualKey, out capital))
			{
				capital = '\0';
				return false;
			}
			if (IsTargetRestricted())
			{
				DiagnosticMessageHandler message3 = new DiagnosticMessageHandler(64, 1, out shouldAppend);
				if (shouldAppend)
				{
					message3.AppendLiteral("English capital refused: the focused field is protected (vk=0x");
					message3.AppendFormatted(virtualKey, "X2");
					message3.AppendLiteral(").");
				}
				Log(ref message3);
				capital = '\0';
				return false;
			}
			if (!_inputInjector.SendUnicodeText(capital.ToString()))
			{
				DiagnosticMessageHandler message4 = new DiagnosticMessageHandler(101, 1, out shouldAppend);
				if (shouldAppend)
				{
					message4.AppendLiteral("English capital refused: the capital could not be typed (SendInput error ");
					message4.AppendFormatted(_inputInjector.LastSendInputError);
					message4.AppendLiteral("); the key goes on as typed.");
				}
				Log(ref message4);
				capital = '\0';
				return false;
			}
			_englishCapitalPending = false;
			Journal?.Count("capital.typed");
			DiagnosticMessageHandler message5 = new DiagnosticMessageHandler(127, 4, out shouldAppend);
			if (shouldAppend)
			{
				message5.AppendLiteral("English capital: first letter of an English run after a Persian word typed as a capital (vk=0x");
				message5.AppendFormatted(virtualKey, "X2");
				message5.AppendLiteral(", mode=");
				message5.AppendFormatted(_settings.General.TypingMode);
				message5.AppendLiteral(", holdDown=");
				message5.AppendFormatted(_englishHoldDown);
				message5.AppendLiteral(", capsLockOn=");
				message5.AppendFormatted(capsLockEnabled);
				message5.AppendLiteral(").");
			}
			Log(ref message5);
			return true;
		}

		private void NoteKeyForEnglishCapital(KeyboardEvent keyEvent, int persianWordsBeforeKey)
		{
			if (!keyEvent.IsKeyDown || _settings.General.TypingMode != TypingMode.AutomaticCorrection || OnlyAPersianHoldKey || IsModifierKey(keyEvent.VirtualKey) || keyEvent.VirtualKey == 20)
			{
				return;
			}
			if (_keyWasEnglishPassThrough)
			{
				ClearEnglishCapital();
				return;
			}
			bool flag = _paragraphPersianWords > persianWordsBeforeKey && _previousStrongLanguage == StrongTypingLanguage.Persian;
			if (flag)
			{
				int virtualKey = keyEvent.VirtualKey;
				bool flag2 = ((virtualKey == 9 || virtualKey == 13) ? true : false);
				flag = !flag2;
			}
			bool flag3 = flag;
			if (keyEvent.VirtualKey == 32)
			{
				_englishCapitalPending = flag3 || _englishCapitalWordEnded;
				_englishCapitalWordEnded = false;
				if (_englishCapitalPending)
				{
					Log("English capital: the previous word is Persian; a capital is pending for the next held letter.");
				}
			}
			else
			{
				_englishCapitalPending = false;
				_englishCapitalWordEnded = flag3;
			}
		}

		private bool TryInjectNormalCaseLetter(int virtualKey)
		{
			if (!_controlDown && !_altDown && !_windowsDown && CapsLockBehaviorPolicy.TryGetNormalCaseCharacter(virtualKey, _shiftDown, out var character) && _layoutService.GetActiveLayout().Language == ActiveLanguage.English && !IsTargetRestricted())
			{
				return _inputInjector.SendUnicodeText(character.ToString());
			}
			return false;
		}

		private void ApplyShiftLanguageSwitchTransition(bool anyShiftDown)
		{
			if (anyShiftDown)
			{
				if (_settings.General.Enabled && EffectiveShiftLanguageSwitchEnabled && !_shiftLanguageSwitchActive)
				{
					ActiveLanguage activeLanguage = ToActiveLanguage(_settings.General.ShiftLanguageSwitchSecondaryLanguage);
					_shiftLanguageSwitchActive = activeLanguage != ActiveLanguage.Unknown && RequestForegroundLayout(activeLanguage, _settings.General.PersianKeyboardLayout, "ApplyShiftLanguageSwitchTransition");
					_shiftLanguageSwitchFirstCharPending = _shiftLanguageSwitchActive;
					if (_shiftLanguageSwitchActive && _settings.General.ShiftSwitchKeepsEmbeddingOpen)
					{
						ResetTypingContext(closeRightToLeftEmbedding: false, "Shift language switch engaged");
					}
					Log(_shiftLanguageSwitchActive ? $"Shift hold requested the installed {activeLanguage} layout for the foreground editor." : $"Shift hold found no installed {activeLanguage} layout.");
				}
			}
			else
			{
				if (!_shiftLanguageSwitchActive)
				{
					return;
				}
				if (_settings.General.ShiftSwitchKeepsEmbeddingOpen)
				{
					bool mouseClickPending = _mouseClickPending;
					ResetTypingContext(!mouseClickPending, "Shift language switch released");
					if (mouseClickPending)
					{
						Log("Shift release: a click since the last key may have moved the caret; the run's direction mark is not closed here.");
					}
				}
				Log(RequestForegroundLayout(ToActiveLanguage(_settings.General.ShiftLanguageSwitchDefaultLanguage), _settings.General.PersianKeyboardLayout, "ApplyShiftLanguageSwitchTransition") ? "Shift release restored the installed default layout for the foreground editor." : "Shift release could not restore the installed default layout.");
				_shiftLanguageSwitchActive = false;
				_shiftLanguageSwitchFirstCharPending = false;
			}
		}

		internal static bool ResolveWantsShiftedForm(bool modifierKeyDown, bool isLetter, bool firstCharPending, DetectedLanguage secondaryLanguage, bool capsLockOn)
		{
			if (secondaryLanguage != DetectedLanguage.English || !isLetter)
			{
				return modifierKeyDown;
			}
			if (!capsLockOn)
			{
				return modifierKeyDown | firstCharPending;
			}
			return !modifierKeyDown;
		}

		private bool TryInjectShiftSwitchSpace(bool wantShifted)
		{
			IReadOnlyList<KeyboardLayoutDefinition> persianTargets = KeyboardLayoutRegistry.GetPersianTargets(MappingLayout);
			KeyboardLayoutKey key = new KeyboardLayoutKey(32, wantShifted ? KeyModifiers.Shift : KeyModifiers.None);
			foreach (KeyboardLayoutDefinition item in persianTargets)
			{
				string text = item.MapKey(key);
				if (text != null && text.Length == 1)
				{
					char c = text[0];
					return _inputInjector.SendUnicodeText(c.ToString());
				}
			}
			return _inputInjector.SendUnicodeText(" ");
		}

		private bool TryInjectShiftLanguageSwitchCharacter(int virtualKey)
		{
			if (_controlDown || _altDown || _windowsDown || IsTargetRestricted())
			{
				return false;
			}
			DetectedLanguage shiftLanguageSwitchSecondaryLanguage = _settings.General.ShiftLanguageSwitchSecondaryLanguage;
			bool isLetter = virtualKey >= 65 && virtualKey <= 90;
			bool flag = ResolveWantsShiftedForm((_settings.General.ShiftLanguageSwitchTriggerKey == ShiftSwitchTriggerKey.Right) ? _leftShiftPhysicallyDown : _rightShiftPhysicallyDown, isLetter, _shiftLanguageSwitchFirstCharPending, shiftLanguageSwitchSecondaryLanguage, CapsLockIsOn());
			if (virtualKey == 32 && shiftLanguageSwitchSecondaryLanguage == DetectedLanguage.Persian)
			{
				return TryInjectShiftSwitchSpace(flag);
			}
			string output;
			switch (shiftLanguageSwitchSecondaryLanguage)
			{
			case DetectedLanguage.English:
			{
				if (!EnglishUsKeyRenderer.TryCreateStroke(virtualKey, flag, out var stroke2))
				{
					return false;
				}
				output = stroke2.SourceCharacter.ToString();
				break;
			}
			case DetectedLanguage.Persian:
			{
				if (!EnglishUsKeyRenderer.TryCreateStroke(virtualKey, shiftDown: false, out var stroke))
				{
					return false;
				}
				char c = (flag ? char.ToUpperInvariant(stroke.SourceCharacter) : stroke.SourceCharacter);
				if (!_translator.TryConvertVisibleText(c.ToString(), MappingLayout, out output))
				{
					return false;
				}
				break;
			}
			default:
				return false;
			}
			if (ShouldStartShiftSwitchEmbedding(shiftLanguageSwitchSecondaryLanguage))
			{
				if (ShiftSwitchUsesParagraphPrefix)
				{
					output = ParagraphDirectionPolicy.Mark(output);
					_paragraphMarked = true;
				}
				else
				{
					output = BidiControlCharacters.StartRightToLeftEmbedding(output);
					_rightToLeftEmbeddingOpen = true;
				}
				_rightToLeftParagraph = true;
			}
			if (!_inputInjector.SendUnicodeText(output))
			{
				return false;
			}
			_shiftLanguageSwitchFirstCharPending = false;
			return true;
		}

		private bool ShouldStartShiftSwitchEmbedding(DetectedLanguage secondary)
		{
			if (secondary == DetectedLanguage.Persian && _shiftLanguageSwitchFirstCharPending && _settings.Correction.StabilizeMixedDirectionText && !(ShiftSwitchUsesParagraphPrefix ? _paragraphMarked : _rightToLeftEmbeddingOpen))
			{
				return !_gate.Inner.FocusedEditorLosesUnicodeBatches();
			}
			return false;
		}

		internal static ActiveLanguage ToActiveLanguage(DetectedLanguage language)
		{
			return language switch
			{
				DetectedLanguage.English => ActiveLanguage.English, 
				DetectedLanguage.Persian => ActiveLanguage.Persian, 
				_ => ActiveLanguage.Unknown, 
			};
		}

