		private void ResetTypingContext(bool closeRightToLeftEmbedding, string reason, bool keepLanguageContext = false, bool paragraphContinues = false)
		{
			if (closeRightToLeftEmbedding && _rightToLeftEmbeddingOpen)
			{
				_inputInjector.SendUnicodeText('\u202c'.ToString());
			}
			if (keepLanguageContext || _previousStrongLanguage != StrongTypingLanguage.Unknown || _paragraphPersianWords != 0 || _paragraphEnglishWords != 0)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(46, 3, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("Typing context reset (");
					message.AppendFormatted(reason);
					message.AppendLiteral("); language context ");
					message.AppendFormatted(keepLanguageContext ? "kept" : "cleared");
					message.AppendLiteral(" (");
					message.AppendFormatted(DescribeLanguageContext());
					message.AppendLiteral(").");
				}
				Log(ref message);
			}
			_bufferResetCause = "ResetTypingContext (Caps Lock or layout switch): the buffer was reset with the caret assumed unmoved";
			_buffer.Reset(caretMoved: false);
			_englishWordLocked = false;
			_englishLockEndsAtNextWord = false;
			_visibleFirstTokenRecoveryPending = true;
			_lastConversion = null;
			_rightToLeftParagraph = false;
			_rightToLeftEmbeddingOpen = false;
			if (!paragraphContinues)
			{
				_paragraphMarked = false;
			}
			if (!keepLanguageContext)
			{
				ForgetPreviousWords();
				ResetParagraphLanguageCounts();
			}
