			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(81, 2, out shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("The و for key 0x");
					message.AppendFormatted(virtualKey, "X2");
					message.AppendLiteral(" could not be typed (SendInput error ");
					message.AppendFormatted(_inputInjector.LastSendInputError);
					message.AppendLiteral("); the key goes on as typed.");
				}
				Log(ref message);
				return false;
			}
			_buffer.OnKeyDown(virtualKey, shiftDown: false, 'و');
			_lastConversion = null;
			Journal?.Count("waw.typed");
			DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(55, 2, out shouldAppend);
			if (shouldAppend)
			{
				message2.AppendLiteral("Typed و at once for key 0x");
				message2.AppendFormatted(virtualKey, "X2");
				message2.AppendLiteral(" (Persian priority); word='");
				message2.AppendFormatted(ShownText(_buffer.GetCurrentToken()));
				message2.AppendLiteral("'.");
			}
			Log(ref message2);
			return true;
		}

		private IReadOnlyList<WawAtOnceKey> WawAtOnceKeys(BufferedToken word)
		{
			List<WawAtOnceKey> list = new List<WawAtOnceKey>(word.Count);
			foreach (BufferedKeyStroke stroke in word.Strokes)
			{
				bool isPersianWordCharacter = stroke.EmittedCharacter != '\0' || _translator.CanMapEnglishCharacter(stroke.SourceCharacter, MappingLayout);
				bool isCapitalOnNonPersianKey = stroke.ShiftDown && char.IsAsciiLetter(stroke.SourceCharacter) && !_translator.IsShiftedPersianLetterKey(stroke.VirtualKey, MappingLayout);
				list.Add(new WawAtOnceKey(stroke.SourceCharacter, isPersianWordCharacter, isCapitalOnNonPersianKey));
			}
			return list;
		}

		private bool ShouldAutoEvaluateOnBoundary(int virtualKey)
		{
			if ((virtualKey != 32 || !_settings.Correction.CorrectOnSpace) && (virtualKey != 13 || !_settings.Correction.CorrectOnEnter))
			{
				if (virtualKey == 9)
				{
					return _settings.Correction.CorrectOnTab;
				}
				return false;
			}
			return true;
		}

		private static string GetBoundaryText(int virtualKey)
		{
			return virtualKey switch
			{
				32 => " ", 
				13 => Environment.NewLine, 
				9 => "\t", 
				_ => string.Empty, 
			};
		}

