		private bool PunctuationStaysAsTyped(BufferedToken currentToken, ImmediatePunctuation punctuation)
		{
			string text = TokenText(currentToken);
			bool flag = text.Length > 0 && (TechnicalPatterns.Classify(text) != ProtectedTokenKind.None || TechnicalPatterns.Classify(text + punctuation.SourceText) != ProtectedTokenKind.None);
			if (!flag && !IsTargetRestricted())
			{
				return false;
			}
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(34, 3, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("Punctuation '");
				message.AppendFormatted(punctuation.SourceText);
				message.AppendLiteral("' left as typed: ");
				message.AppendFormatted(flag ? "technical token" : "protected field");
				message.AppendLiteral(" '");
				message.AppendFormatted(DiagnosticLog.Tail(text, 40));
				message.AppendLiteral("'.");
			}
			Log(ref message);
			return true;
		}

		private static ImmediatePunctuation? GetImmediatePunctuation(int virtualKey, bool shiftDown)
		{
			switch (virtualKey)
			{
			case 49:
				if (shiftDown)
				{
					return new ImmediatePunctuation("!", "!", EndsSentence: true);
				}
				break;
			case 55:
				if (shiftDown)
				{
					return new ImmediatePunctuation("&", '،'.ToString(), EndsSentence: false);
				}
				break;
			case 191:
				if (shiftDown)
				{
					return new ImmediatePunctuation("?", '؟'.ToString(), EndsSentence: true);
				}
				break;
			case 190:
				return new ImmediatePunctuation(".", ".", EndsSentence: true);
			}
			return null;
		}

