			journal.AddSummarySource(() => "editor facts read (worker) " + EditorFactsTiming.Describe());
			journal.AddSummarySource(() => "worker queue delay " + WorkerQueueDelay.Describe());
			journal.AddSummarySource(() => $"editor work attempted on the hook thread={EditorWorkOnHookThread}; keys passed beside a command={PassedBesideCommandCount}");
			journal.AddSummarySource(() => "not measured: lock wait (the hook only TryEnters), replacement send time and time to a verification observation (no existing observation follows a replacement)");
		}

