			{
				"word",
				DiagnosticLog.Tail(TokenText(currentToken), 40),
				"startKnown",
				currentToken.StartKnown,
				"preceding",
				DiagnosticLog.Tail(currentToken.PrecedingText, 24),
				"known",
				DiagnosticLog.Tail(_buffer.KnownTextBeforeCaret, 24),
				"prevLang",
				_previousStrongLanguage,
				"persianWords",
				_paragraphPersianWords,
				"englishWords",
				_paragraphEnglishWords,
				"englishProse",
				_paragraphEnglishProseWords,
				"backspaces",
				_backspacesSinceLastWordOperation,
				"fact",
				DescribeParagraphFact(fact, num),
				"factRead",
				DescribeFactRead(fact),
				"protection",
				PreparedProtection()?.ToString() ?? "unknown",
				"hwnd",
				foregroundTargetIdentity.ToString("X", CultureInfo.InvariantCulture),
