		private string DescribeJournalTarget(long window)
		{
			JournalTargetReference journalTargetReference = Volatile.Read(in _journalTarget);
			if ((object)journalTargetReference == null || journalTargetReference.Journal != Journal)
			{
				return "not described yet";
			}
			IFormatProvider invariantCulture;
			if (journalTargetReference.Window != window)
			{
				invariantCulture = CultureInfo.InvariantCulture;
				IFormatProvider provider = invariantCulture;
				DefaultInterpolatedStringHandler handler = new DefaultInterpolatedStringHandler(44, 3, invariantCulture);
				handler.AppendLiteral("pending: window ");
				handler.AppendFormatted(window, "X");
				handler.AppendLiteral(" not described yet (last #");
				handler.AppendFormatted(journalTargetReference.Id);
				handler.AppendLiteral(" ");
				handler.AppendFormatted(journalTargetReference.Application);
				handler.AppendLiteral(")");
				return string.Create(provider, ref handler);
			}
			invariantCulture = CultureInfo.InvariantCulture;
			IFormatProvider provider2 = invariantCulture;
			DefaultInterpolatedStringHandler handler2 = new DefaultInterpolatedStringHandler(2, 2, invariantCulture);
			handler2.AppendLiteral("#");
			handler2.AppendFormatted(journalTargetReference.Id);
			handler2.AppendLiteral(" ");
			handler2.AppendFormatted(journalTargetReference.Application);
			return string.Create(provider2, ref handler2);
		}

		private void JournalTargetWhenItChanges(DiagnosticJournal journal, long window, long epoch)
		{
			TypingTargetFacts typingTargetFacts = _gate.Inner.DescribeTargetForJournal();
			string application = typingTargetFacts?.Application ?? "unknown";
			IFormatProvider invariantCulture = CultureInfo.InvariantCulture;
			DefaultInterpolatedStringHandler handler = new DefaultInterpolatedStringHandler(1, 2, invariantCulture);
			handler.AppendFormatted(window, "X");
			handler.AppendLiteral("|");
			handler.AppendFormatted(typingTargetFacts?.Signature);
			string text = string.Create(invariantCulture, ref handler);
			JournalTargetReference journalTargetReference = Volatile.Read(in _journalTarget);
			if ((object)journalTargetReference == null || journalTargetReference.Journal != journal || !(journalTargetReference.Signature == text))
			{
				TypingTargetDecision typingTargetDecision = CurrentEnvironmentDecision();
				int id = journal.Target(application, "window", window.ToString("X", CultureInfo.InvariantCulture), "epoch", epoch, "process", typingTargetFacts?.Process ?? "?", "windowClass", typingTargetFacts?.WindowClass ?? "?", "topClass", typingTargetFacts?.TopLevelClass ?? "?", "title", typingTargetFacts?.Title ?? "?", "element", ((object)typingTargetFacts == null) ? "not described by this engine" : $"{typingTargetFacts.ElementControlType} class='{typingTargetFacts.ElementClass}' autoId='{typingTargetFacts.ElementAutomationId}' name='{typingTargetFacts.ElementName}'", "elementSource", "as the protected-field check read it for this target; read.later records describe the element a read came from", "editorKey", typingTargetFacts?.EditorKey ?? "?", "capabilities", typingTargetFacts?.Capabilities ?? "?", "losesUnicodeBatches", typingTargetFacts?.LosesUnicodeBatches ?? false, "protection", PreparedProtection()?.ToString() ?? "unknown", "protectionReason", ((object)typingTargetFacts == null || typingTargetFacts.ProtectionReason.Length == 0) ? "unknown" : typingTargetFacts.ProtectionReason, "env", typingTargetDecision.Restriction.ToString() + ":" + typingTargetDecision.Reason, "envSnapshot", DescribeEnvironmentSnapshot(), "nonText", NonTextTargetPolicy.IsNonTextControl(PreparedControlType()));
				Volatile.Write(ref _journalTarget, new JournalTargetReference(journal, id, window, application, text));
			}
		}

		private string DescribeEnvironmentSnapshot()
		{
			TypingEnvironmentSnapshot typingEnvironmentSnapshot = _environment?.Current;
			if ((object)typingEnvironmentSnapshot != null)
			{
				return $"surface={typingEnvironmentSnapshot.SurfaceKind} role={typingEnvironmentSnapshot.Role}/{typingEnvironmentSnapshot.RoleEvidence} identity={typingEnvironmentSnapshot.IdentityStrength} protection={typingEnvironmentSnapshot.Protection} editability={typingEnvironmentSnapshot.Editability} assessment={typingEnvironmentSnapshot.Assessment.Kind}";
			}
			return "no observer";
		}

		private static string DescribeParagraphFact(ParagraphFact? fact, long sequence)
		{
			if ((object)fact != null)
			{
				if (!fact.Read)
				{
					return $"unreadable@{fact.Sequence}(now {sequence})";
				}
				if (fact.Sequence == sequence)
				{
					return $"valid@{fact.Sequence}(len {fact.Prefix.Length})";
				}
				return $"stale(read@{fact.Sequence}, now {sequence})";
			}
			return "none";
		}

		private void JournalReadAndEnrich(DiagnosticJournal journal, ParagraphReadTrace trace, long requestedAtSequence, long epoch)
		{
			WriteReadRecord(journal, "read.original", trace.ReadId, trace.Original, requestedAtSequence, epoch);
			ReadEnrichmentGate gate = EnrichmentGate;
			if (!gate.TryEnter())
			{
				trace.Skip($"enrichment-busy(limit {gate.Limit})");
				journal.Count("read.enrichment.skipped");
				WriteReadRecord(journal, "read.later", trace.ReadId, trace.Later, requestedAtSequence, epoch);
				return;
			}
			bool flag = false;
			try
			{
				flag = ThreadPool.UnsafeQueueUserWorkItem((object? _) =>
				{
					try
					{
						if (!StillThisSession())
						{
							trace.Skip("session-ended-before-start");
						}
						else
						{
							trace.Enrich(StillThisSession);
							if (StillThisSession())
							{
								WriteReadRecord(journal, "read.later", trace.ReadId, trace.Later, requestedAtSequence, epoch);
							}
						}
					}
					catch (Exception ex)
					{
						DiagnosticMessageHandler message = new DiagnosticMessageHandler(28, 1, out var shouldAppend);
						if (shouldAppend)
						{
							message.AppendLiteral("Describing a read failed (");
							message.AppendFormatted(ex.GetType().FullName);
							message.AppendLiteral(").");
						}
						Log(ref message);
					}
					finally
					{
						gate.Exit();
					}
				}, null);
			}
			finally
			{
				if (!flag)
				{
					gate.Exit();
					trace.Skip("queue-refused");
				}
			}
			bool StillThisSession()
			{
				if (!_enrichmentStopped)
				{
					return Journal == journal;
				}
				return false;
			}
		}

		private static void WriteReadRecord(DiagnosticJournal journal, string name, long readId, IReadOnlyList<KeyValuePair<string, string>> fields, long requestedAtSequence, long epoch)
		{
			List<object> list = new List<object>(fields.Count * 2 + 6) { "readId", readId, "requestedAtSeq", requestedAtSequence, "epoch", epoch };
			foreach (KeyValuePair<string, string> field in fields)
			{
				list.Add(field.Key);
				list.Add(field.Value);
			}
			journal.Event(name, list.ToArray());
		}

		private static string DescribeFactRead(ParagraphFact? fact)
		{
			if ((object)fact != null)
			{
				ParagraphReadTrace trace = fact.Trace;
				if (trace != null)
				{
					return trace.Reference;
				}
				return "not-traced";
			}
			return "none";
		}

		private void JournalInvalidation(string reason, bool startKnown)
		{
			_lastInvalidationReason = reason;
			DiagnosticJournal journal = Journal;
			if (journal != null)
			{
				object[] array = ContextFacts();
				Array.Resize(ref array, array.Length + 2);
				array[^2] = "nextStartKnown";
				array[^1] = startKnown;
				journal.Invalidate(reason, array);
				Volatile.Write(ref _workerWatch, 4);
			}
		}

		private static string InvalidationReason(int virtualKey, bool control)
		{
			if (control)
			{
				switch (virtualKey)
				{
				case 86:
					return "paste(Ctrl+V)";
				case 88:
					return "cut(Ctrl+X)";
				case 67:
					return "copy(Ctrl+C)";
				case 65:
					return "select-all(Ctrl+A)";
				case 89:
					return "redo(Ctrl+Y)";
				case 36:
					return "ctrl+home";
				case 8:
					break;
				case 46:
					goto IL_009c;
				case 27:
					goto IL_00a4;
				default:
					goto IL_00ac;
				}
			}
			else if (virtualKey != 8)
			{
				if (virtualKey == 46)
				{
					goto IL_009c;
				}
				if (virtualKey == 27)
				{
					goto IL_00a4;
				}
				goto IL_00ac;
			}
			return "backspace";
			IL_00a4:
			return "escape";
			IL_009c:
			return "delete";
			IL_00ac:
			string text = (control ? "ctrl+" : "");
			Keys keys = (Keys)virtualKey;
			return text + keys;
		}

		private int BeginWordOperation(string trigger, BufferedToken token)
		{
			DiagnosticJournal journal = Journal;
			if (journal == null)
			{
				_backspacesSinceLastWordOperation = 0;
				return 0;
			}
			_readEvidence = null;
			object[] array = ContextFacts();
			_backspacesSinceLastWordOperation = 0;
			Array.Resize(ref array, array.Length + 4);
			array[^4] = "trigger";
			array[^3] = trigger;
			array[^2] = "typed";
			array[^1] = DiagnosticLog.Tail(TokenText(token), 64);
			return journal.BeginOperation("word", array);
		}

		private void EndWordOperation(int operation, string outcome, params object?[] pairs)
		{
			if (operation != 0)
			{
				DiagnosticJournal journal = Journal;
				if (journal != null)
				{
					object[] readEvidence = _readEvidence;
					_readEvidence = null;
					journal.EndOperation(operation, outcome, (readEvidence == null) ? pairs : pairs.Concat(readEvidence).ToArray());
				}
			}
		}

		private void NoteReadEvidence(VisibleTokenCheck check, string why, BufferedToken token, string visiblePrefix)
		{
			if (Journal == null)
			{
				return;
			}
			switch (check)
			{
			case VisibleTokenCheck.Lagging:
				if (token.Count < 2 || !why.StartsWith("no-word-before-caret", StringComparison.Ordinal))
				{
					return;
				}
				break;
			default:
				return;
			case VisibleTokenCheck.Mismatch:
				break;
			}
			_readEvidence = new object[6]
			{
				"readTail",
				DiagnosticLog.Tail(visiblePrefix, 24),
				"readEndsWith",
				DescribeLastCharacter(visiblePrefix),
				"readLen",
				visiblePrefix.Length
			};
		}

		internal static string DescribeLastCharacter(string text)
		{
			if (text.Length == 0)
			{
				return "empty";
			}
			char c = text[text.Length - 1];
			if ((c == '\n' || c == '\r') ? true : false)
			{
				return "newline";
			}
			if (char.IsWhiteSpace(c))
			{
				return "space";
			}
			bool flag;
			switch (c)
			{
			case 'A':
			case 'B':
			case 'C':
			case 'D':
			case 'E':
			case 'F':
			case 'G':
			case 'H':
			case 'I':
			case 'J':
			case 'K':
			case 'L':
			case 'M':
			case 'N':
			case 'O':
			case 'P':
			case 'Q':
			case 'R':
			case 'S':
			case 'T':
			case 'U':
			case 'V':
			case 'W':
			case 'X':
			case 'Y':
			case 'Z':
			case 'a':
			case 'b':
			case 'c':
			case 'd':
			case 'e':
			case 'f':
			case 'g':
			case 'h':
			case 'i':
			case 'j':
			case 'k':
			case 'l':
			case 'm':
			case 'n':
			case 'o':
			case 'p':
			case 'q':
			case 'r':
			case 's':
			case 't':
			case 'u':
			case 'v':
			case 'w':
			case 'x':
			case 'y':
			case 'z':
				flag = true;
				break;
			default:
				flag = false;
				break;
			}
			if (flag)
			{
				return "latin";
			}
			if (c >= 'ﭐ')
			{
				if (c >= 'ﹰ')
				{
					if (c <= '\ufeff')
					{
						goto IL_009d;
					}
				}
				else if (c <= '﷿')
				{
					goto IL_009d;
				}
			}
			else if (c >= '\u0600' && c <= 'ۿ')
			{
				goto IL_009d;
			}
			flag = false;
			goto IL_00a3;
			IL_009d:
			flag = true;
			goto IL_00a3;
			IL_00a3:
			if (flag)
			{
				return "persian";
			}
			UnicodeCategory unicodeCategory = char.GetUnicodeCategory(c);
			if ((uint)(unicodeCategory - 14) > 1u)
			{
				return "other";
			}
			return "control";
		}

		private void WordStage(int operation, string stage, string? detail = null)
		{
			if (operation != 0)
			{
				Journal?.Stage(operation, stage, detail);
			}
		}

