					_lastManualConversion = conversion;
				}
				WordToggle wordToggle = (_wordToggle = new WordToggle(other, shown, conversion, !shownIsPersian, _buffer.Version, control, learnable));
				if (wordToggle.ShownIsPersian & learnable)
				{
					wordToggle.Learned = true;
				}
				if (confirmed != null)
				{
					Publish(confirmed);
				}
				return null;
			}
			}
		}

		private void Publish(Action action)
		{
			lock (_publishLock)
			{
				_published = _published.ContinueWith((Task _) =>
				{
					try
					{
						action();
					}
					catch (Exception ex)
					{
						DiagnosticMessageHandler message = new DiagnosticMessageHandler(40, 1, out var shouldAppend);
						if (shouldAppend)
						{
							message.AppendLiteral("A Convert previous word event failed (");
							message.AppendFormatted(ex.GetType().FullName);
							message.AppendLiteral(").");
						}
						Log(ref message);
					}
				}, TaskScheduler.Default);
			}
		}

