		public bool NoteTextServiceWordReplaced(TextServiceEdit edit)
		{
			string command = edit.Command;
			bool flag = ((command == "lastword" || command == "undo") ? true : false);
			if (!flag || !TextServiceTrackingApplies)
			{
				return false;
			}
			lock (_sync)
			{
				if (!TextServiceTrackingApplies)
				{
					return false;
				}
				string text = null;
				InputMarker? marker = edit.Marker;
				if (marker.HasValue)
				{
					InputMarker valueOrDefault = marker.GetValueOrDefault();
					if (valueOrDefault.TargetEpoch != Volatile.Read(in _targetEpoch))
					{
						text = "focus-changed-since-plan";
					}
					else if (valueOrDefault.KeySequence != Volatile.Read(in _keySequence))
					{
						text = "keys-since-plan";
					}
					else if (_mouseClickPending)
					{
						text = "click-since-plan";
					}
				}
				bool shouldAppend;
				if (text == null && (ApplyVerifiedExternalEdit(edit.Before, edit.After, edit.ResultIsPersian, replacesPreviousWord: true) || ApplyVerifiedExternalEdit(edit.Before + " ", edit.After + " ", edit.ResultIsPersian, replacesPreviousWord: true)))
				{
					_lastConversion = null;
					_wordToggle = null;
					_continuePersianEditAfterBackspace = false;
					DiagnosticMessageHandler message = new DiagnosticMessageHandler(85, 3, out shouldAppend);
					if (shouldAppend)
					{
						message.AppendLiteral("Text service ");
						message.AppendFormatted(edit.Command);
						message.AppendLiteral(" '");
						message.AppendFormatted(DiagnosticLog.Tail(edit.Before, 40));
						message.AppendLiteral("' -> '");
						message.AppendFormatted(DiagnosticLog.Tail(edit.After, 40));
						message.AppendLiteral("' verified by the editor: recorded as the word before the caret.");
					}
					Log(ref message);
					Journal?.Event("textservice.edit", "command", edit.Command, "recorded", true, "persian", edit.ResultIsPersian, "keySeq", Volatile.Read(in _keySequence));
					return true;
				}
				string text2 = text ?? "known-text-does-not-end-with-the-word";
				_buffer.ForgetKnownText();
				ReplacePreviousWordLanguage((!edit.ResultIsPersian) ? StrongTypingLanguage.English : StrongTypingLanguage.Persian);
				DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(109, 4, out shouldAppend);
				if (shouldAppend)
				{
					message2.AppendLiteral("Text service ");
					message2.AppendFormatted(edit.Command);
					message2.AppendLiteral(" '");
					message2.AppendFormatted(DiagnosticLog.Tail(edit.Before, 40));
					message2.AppendLiteral("' -> '");
					message2.AppendFormatted(DiagnosticLog.Tail(edit.After, 40));
					message2.AppendLiteral("' verified by the editor, not recorded: ");
					message2.AppendFormatted(text2);
					message2.AppendLiteral("; the known text before the caret was forgotten.");
				}
				Log(ref message2);
				Journal?.Event("textservice.edit", "command", edit.Command, "recorded", false, "why", text2, "forgotten", true, "planKeySeq", edit.Marker?.KeySequence ?? (-1), "keySeq", Volatile.Read(in _keySequence));
				return false;
			}
		}

		private void ReplacePreviousWordLanguage(StrongTypingLanguage language)
		{
			_keptWordContext = null;
			_previousStrongLanguage = language;
			_previousWordIsNeutralLatin = false;
			_previousPersianWordText = null;
		}

		private bool ApplyVerifiedExternalEdit(string before, string after, bool resultIsPersian, bool replacesPreviousWord = false)
		{
			if (!_buffer.ReplaceKnownTail(before, after))
			{
				return false;
			}
			if (replacesPreviousWord)
			{
				ReplacePreviousWordLanguage((!resultIsPersian) ? StrongTypingLanguage.English : StrongTypingLanguage.Persian);
				if (resultIsPersian)
				{
					_paragraphPersianWords++;
					ForgetEnglishWord(before);
				}
				else
				{
					RememberEnglishWord(after);
					_paragraphPersianWords = Math.Max(0, _paragraphPersianWords - 1);
				}
			}
			else if (resultIsPersian)
			{
				NoteWordShownAsPersian();
			}
			else
			{
				NotePreviousWord(StrongTypingLanguage.English);
				RememberEnglishWord(after);
			}
			return true;
		}
	}
