		internal static ManifestUpdateService CreateForApplication(string applicationVersion, string? savedFeedUrl, HttpMessageHandler? handler = null, UpdateCheckStateStore? state = null, bool requireSignedManifest = true, IReadOnlyList<TrustedKey>? trustRoots = null)
		{
			ManifestUpdateService manifestUpdateService = new ManifestUpdateService(CreateHttpClient(applicationVersion, handler), DefaultFeedUri, applicationVersion, ownsHttpClient: true, trustRoots, state, null, requireSignedManifest);
			if (!string.IsNullOrWhiteSpace(savedFeedUrl))
			{
				manifestUpdateService.TrySetFeedUri(savedFeedUrl, out string _);
			}
			return manifestUpdateService;
		}

		internal static HttpClient CreateHttpClient(string applicationVersion, HttpMessageHandler? handler = null)
		{
			HttpClient httpClient = ((handler == null) ? new HttpClient() : new HttpClient(handler, disposeHandler: true));
			httpClient.Timeout = RequestTimeout;
			AddUserAgent(httpClient, applicationVersion);
			return httpClient;
		}

		internal static HttpClient CreateDownloadClient(string applicationVersion, HttpMessageHandler? handler = null)
		{
			HttpClient httpClient = new HttpClient(handler ?? new HttpClientHandler
			{
				AllowAutoRedirect = false
			}, disposeHandler: true)
			{
				Timeout = Timeout.InfiniteTimeSpan
			};
			AddUserAgent(httpClient, applicationVersion);
			return httpClient;
		}

		private static void AddUserAgent(HttpClient client, string applicationVersion)
		{
			client.DefaultRequestHeaders.UserAgent.Add(ProductInfoHeaderValue.TryParse("Diyar/" + applicationVersion, out ProductInfoHeaderValue parsedValue) ? parsedValue : new ProductInfoHeaderValue("Diyar", null));
		}

		internal ManifestUpdateService(HttpClient httpClient, Uri feedUri, string currentVersion, bool ownsHttpClient = false, IReadOnlyList<TrustedKey>? trustRoots = null, UpdateCheckStateStore? state = null, TimeProvider? clock = null, bool requireSignedManifest = true)
		{
			if (feedUri.Scheme != Uri.UriSchemeHttps)
			{
				throw new ArgumentException("The update feed must use HTTPS.", "feedUri");
			}
			_httpClient = httpClient;
			_feedUri = feedUri;
			_currentVersion = currentVersion;
			_ownsHttpClient = ownsHttpClient;
			_trustRoots = trustRoots ?? UpdateTrustRoots.Keys;
			_state = state ?? new UpdateCheckStateStore(null);
			_clock = clock ?? TimeProvider.System;
			_requireSignedManifest = requireSignedManifest;
		}

		public bool TrySetFeedUri(string value, out string error)
		{
			if (!TryCreateHttpsUri(value?.Trim(), out Uri uri))
			{
				error = SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.UpdateUrlInvalid);
				return false;
			}
			_feedUri = uri;
			error = string.Empty;
			return true;
		}

		public async Task<UpdateCheckResult> CheckAsync(bool includePreviews, CancellationToken cancellationToken = default(CancellationToken))
		{
