			CheckTrace trace = new CheckTrace();
			UpdateCheckResult updateCheckResult;
			bool shouldAppend;
			try
			{
				updateCheckResult = await CheckCoreAsync(feedUri, includePreviews, trace, cancellationToken);
			}
			catch (Exception ex)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(53, 4, out shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("Check host=");
					message.AppendFormatted(feedUri.Host);
					message.AppendLiteral(" installed=");
					message.AppendFormatted(_currentVersion);
					message.AppendLiteral(" http=");
					message.AppendFormatted(((object)trace.HttpStatus) ?? "-");
					message.AppendLiteral(" outcome=Exception error=");
					message.AppendFormatted(ex.GetType().Name);
				}
				DiagnosticLog.Write("Updates", ref message);
				throw;
			}
			DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(84, 10, out shouldAppend);
			if (shouldAppend)
			{
				message2.AppendLiteral("Check host=");
				message2.AppendFormatted(feedUri.Host);
				message2.AppendLiteral(" channel=");
				message2.AppendFormatted(includePreviews ? "preview" : "stable");
				message2.AppendLiteral(" installed=");
				message2.AppendFormatted(_currentVersion);
				message2.AppendLiteral(" http=");
				message2.AppendFormatted(((object)trace.HttpStatus) ?? "-");
				message2.AppendLiteral(" newest=");
				message2.AppendFormatted(trace.NewestVersion ?? "-");
				message2.AppendLiteral(" refusedTest=");
				message2.AppendFormatted(trace.RefusedTestVersions);
				message2.AppendLiteral(" outcome=");
				message2.AppendFormatted(updateCheckResult.Status);
				message2.AppendLiteral(" failure=");
				message2.AppendFormatted(updateCheckResult.Failure);
				message2.AppendLiteral(" error=");
				message2.AppendFormatted(trace.ErrorType ?? "-");
				message2.AppendLiteral(" ");
				message2.AppendFormatted(trace.SignedFields);
