		private async Task<UpdateCheckResult> CheckCoreAsync(Uri feedUri, bool includePreviews, CheckTrace trace, CancellationToken cancellationToken)
		{
			if (!SemanticVersion.TryParse(_currentVersion, out SemanticVersion current))
			{
				return Unavailable(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.UpdateInstalledVersionInvalid), UpdateCheckFailure.InvalidInstalledVersion);
			}
			try
			{
				using HttpResponseMessage response = await _httpClient.GetAsync(feedUri, HttpCompletionOption.ResponseHeadersRead, cancellationToken);
				trace.HttpStatus = (int)response.StatusCode;
				if (!response.IsSuccessStatusCode)
				{
					return Unavailable(SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.UpdateHttpStatus, (int)response.StatusCode), UpdateCheckFailure.HttpStatus);
				}
				byte[] array = await ReadBodyAsync(response.Content, cancellationToken);
				if (array == null)
				{
					trace.ErrorType = "TooLarge";
					return Unavailable(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.UpdateFormatUnsupported), UpdateCheckFailure.InvalidManifest);
				}
				SignedManifestCheckResult signedManifestCheckResult = SignedManifestCheck.Evaluate(array, new SignedManifestCheckOptions(_trustRoots, _requireSignedManifest, current, includePreviews, _clock.GetUtcNow(), _state.ReadHighestManifestSerial()));
				trace.SignedFields = signedManifestCheckResult.LogFields;
				return (signedManifestCheckResult.Outcome == SignedManifestOutcome.ReadSchemaOne) ? ReadSchemaOne(array, current, includePreviews, trace) : FromSignedCheck(signedManifestCheckResult, trace);
			}
			catch (OperationCanceledException ex) when (!cancellationToken.IsCancellationRequested)
			{
				trace.ErrorType = ex.GetType().Name;
				return Unavailable(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.UpdateTimedOut), UpdateCheckFailure.Timeout);
			}
			catch (JsonException ex2)
			{
				trace.ErrorType = ex2.GetType().Name;
				return Unavailable(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.UpdateCheckFailed), UpdateCheckFailure.InvalidManifest);
			}
			catch (Exception ex3) when ((ex3 is HttpRequestException || ex3 is IOException) ? true : false)
			{
				trace.ErrorType = ex3.GetType().Name;
				return Unavailable(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.UpdateCheckFailed), UpdateCheckFailure.Network);
			}
		}

		private static async Task<byte[]?> ReadBodyAsync(HttpContent content, CancellationToken cancellationToken)
		{
			if (content.Headers.ContentLength > 1048576)
			{
				return null;
			}
			byte[] result;
			await using (Stream stream = await content.ReadAsStreamAsync(cancellationToken))
			{
				using MemoryStream buffer = new MemoryStream();
				byte[] chunk = new byte[16384];
				while (true)
				{
					int num;
					if ((num = await stream.ReadAsync(chunk, cancellationToken)) > 0)
					{
						if (buffer.Length + num > 1048576)
						{
							result = null;
							break;
						}
						buffer.Write(chunk, 0, num);
						continue;
					}
					result = buffer.ToArray();
					break;
				}
			}
			return result;
		}

		private UpdateCheckResult ReadSchemaOne(byte[] body, SemanticVersion current, bool includePreviews, CheckTrace trace)
		{
			UpdateManifest updateManifest = JsonSerializer.Deserialize<UpdateManifest>(body, new JsonSerializerOptions
			{
				PropertyNameCaseInsensitive = true
			});
			if ((object)updateManifest == null || updateManifest.SchemaVersion != 1)
			{
				return Unavailable(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.UpdateFormatUnsupported), UpdateCheckFailure.InvalidManifest);
			}
			SchemaOneCandidate schemaOneCandidate = (from candidate in (!includePreviews) ? new UpdateManifestRelease[1] { updateManifest.Stable } : new UpdateManifestRelease[2] { updateManifest.Stable, updateManifest.Preview }
				select TryCreateRelease(candidate, trace) into candidate
				where (object)candidate != null
				select (candidate)).OrderByDescending((SchemaOneCandidate candidate) => candidate.ParsedVersion, SemanticVersionComparer.Instance).FirstOrDefault();
			if ((object)schemaOneCandidate == null)
			{
				return Unavailable(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.UpdateNoValidRelease), UpdateCheckFailure.NoValidRelease);
			}
			trace.NewestVersion = schemaOneCandidate.Release.Version;
			if (schemaOneCandidate.ParsedVersion.CompareTo(current) > 0)
			{
				return Available(schemaOneCandidate.Release);
			}
			return UpToDate();
		}

		private UpdateCheckResult FromSignedCheck(SignedManifestCheckResult check, CheckTrace trace)
		{
			ManifestVerdict verdict = check.Verdict;
			if ((object)verdict != null)
			{
				trace.NewestVersion = verdict.Newest?.Version;
				trace.RefusedTestVersions = Enumerable.Count(verdict.RefusedEntries, (RefusedEntry entry) => entry.Reason == EntryRefusal.TestLabel);
			}
			long? acceptedSerial = check.AcceptedSerial;
			if (acceptedSerial.HasValue)
			{
				long valueOrDefault = acceptedSerial.GetValueOrDefault();
				_state.RaiseHighestManifestSerial(valueOrDefault);
			}
			switch (check.Outcome)
			{
			case SignedManifestOutcome.UpToDate:
				return UpToDate();
			case SignedManifestOutcome.Available:
			{
				UpdateCandidate candidate = check.Candidate;
				if ((object)candidate != null)
				{
					return Available(ToRelease(candidate));
				}
				break;
			}
			}
			var (failure, key) = Refusal(check);
			return Unavailable(SmartInput.Core.Text.Localization.MessageText.Get(key), failure);
		}

		internal static (UpdateCheckFailure Failure, MessageKey Message) Refusal(SignedManifestCheckResult check)
		{
			switch (check.Outcome)
			{
			case SignedManifestOutcome.Unsigned:
				return (Failure: UpdateCheckFailure.ManifestUnsigned, Message: MessageKey.UpdateManifestUnsigned);
			case SignedManifestOutcome.SignatureInvalid:
				return (Failure: UpdateCheckFailure.SignatureInvalid, Message: MessageKey.UpdateManifestSignatureInvalid);
			case SignedManifestOutcome.EnvelopeInvalid:
				if (check.Detail == "not JSON")
				{
					return (Failure: UpdateCheckFailure.InvalidManifest, Message: MessageKey.UpdateCheckFailed);
				}
				break;
			case SignedManifestOutcome.Refused:
				return check.Verdict?.Failure switch
				{
					ManifestFailure.ManifestExpired => (Failure: UpdateCheckFailure.ManifestExpired, Message: MessageKey.UpdateManifestExpired), 
					ManifestFailure.ManifestReplayed => (Failure: UpdateCheckFailure.ManifestReplayed, Message: MessageKey.UpdateManifestReplayed), 
					ManifestFailure.NoValidRelease => (Failure: UpdateCheckFailure.NoValidRelease, Message: MessageKey.UpdateNoValidRelease), 
					_ => (Failure: UpdateCheckFailure.InvalidManifest, Message: MessageKey.UpdateFormatUnsupported), 
				};
			}
			return (Failure: UpdateCheckFailure.InvalidManifest, Message: MessageKey.UpdateFormatUnsupported);
		}

		private static UpdateRelease ToRelease(UpdateCandidate candidate)
		{
			return new UpdateRelease(candidate.Version, candidate.ReleasePageUri, candidate.SetupUri, candidate.SetupSha256)
			{
				Setup = (candidate.IsInstallable ? new UpdateSetupFile(candidate.SetupUri, candidate.SetupSha256, candidate.SetupSize.Value) : null),
				ManifestSerial = candidate.Serial
			};
		}

		private UpdateCheckResult UpToDate()
		{
			return new UpdateCheckResult(UpdateCheckStatus.UpToDate, _currentVersion, null, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.UpdateUpToDate, _currentVersion));
		}

		private UpdateCheckResult Available(UpdateRelease release)
		{
			return new UpdateCheckResult(UpdateCheckStatus.UpdateAvailable, _currentVersion, release, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.UpdateAvailable, release.Version));
		}

		public void Dispose()
		{
			if (_ownsHttpClient)
			{
				_httpClient.Dispose();
			}
		}

		private static SchemaOneCandidate? TryCreateRelease(UpdateManifestRelease? manifestRelease, CheckTrace trace)
		{
			if ((object)manifestRelease != null && SemanticVersion.HasTestLabel(manifestRelease.Version))
			{
				trace.RefusedTestVersions++;
				return null;
			}
			if ((object)manifestRelease == null || !SemanticVersion.TryParse(manifestRelease.Version, out SemanticVersion version) || !TryCreateHttpsUri(manifestRelease.ReleasePageUrl, out Uri uri) || (!string.IsNullOrWhiteSpace(manifestRelease.DownloadUrl) && !TryCreateHttpsUri(manifestRelease.DownloadUrl, out Uri _)) || (!string.IsNullOrWhiteSpace(manifestRelease.Sha256) && !Sha256Pattern.IsMatch(manifestRelease.Sha256)))
			{
				return null;
			}
			Uri uri3 = null;
			if (!string.IsNullOrWhiteSpace(manifestRelease.DownloadUrl))
			{
				TryCreateHttpsUri(manifestRelease.DownloadUrl, out uri3);
			}
			return new SchemaOneCandidate(version, new UpdateRelease(manifestRelease.Version, uri, uri3, manifestRelease.Sha256?.ToLowerInvariant()));
		}

		private UpdateCheckResult Unavailable(string message, UpdateCheckFailure failure)
		{
			return new UpdateCheckResult(UpdateCheckStatus.Unavailable, _currentVersion, null, message)
			{
				Failure = failure
			};
		}

		private static bool TryCreateHttpsUri(string? value, out Uri? uri)
		{
			int num;
			if (Uri.TryCreate(value, UriKind.Absolute, out uri))
			{
				num = ((uri.Scheme == Uri.UriSchemeHttps) ? 1 : 0);
				if (num != 0)
				{
					goto IL_0024;
				}
			}
			else
			{
				num = 0;
			}
			uri = null;
			goto IL_0024;
			IL_0024:
			return (byte)num != 0;
		}

		private static string GetApplicationVersion()
		{
			return typeof(ManifestUpdateService).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion ?? "0.0.0";
		}
