	internal enum SealOutcome
	{
		Sealed,
		Missing,
		SizeMismatch,
		HashMismatch,
		Unreadable
	}
	internal sealed class SealedInstaller : IDisposable
	{
		private FileStream? _handle;

		public UpdateTarget Target { get; }

		public string Path => _handle?.Name ?? throw new ObjectDisposedException("SealedInstaller");

		public bool IsSealed => _handle != null;

		private SealedInstaller(FileStream handle, UpdateTarget target)
		{
			_handle = handle;
			Target = target;
		}

		public static (SealedInstaller? Installer, SealOutcome Outcome) Seal(string partialPath, string setupPath, UpdateTarget target)
		{
			try
			{
				if (File.Exists(partialPath))
				{
					File.Move(partialPath, setupPath, overwrite: true);
				}
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(31, 2, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("Verify version=");
					message.AppendFormatted(target.Version);
					message.AppendLiteral(" rename failed: ");
					message.AppendFormatted(ex.GetType().Name);
				}
				DiagnosticLog.Write("Updates", ref message);
				return (Installer: null, Outcome: SealOutcome.Unreadable);
			}
			return Open(setupPath, target);
		}

		public static (SealedInstaller? Installer, SealOutcome Outcome) Open(string setupPath, UpdateTarget target)
		{
			FileStream fileStream;
			bool shouldAppend;
			try
			{
				fileStream = new FileStream(setupPath, FileMode.Open, FileAccess.Read, FileShare.Read, 65536, FileOptions.SequentialScan);
			}
			catch (Exception ex) when ((ex is FileNotFoundException || ex is DirectoryNotFoundException) ? true : false)
			{
				return (Installer: null, Outcome: SealOutcome.Missing);
			}
			catch (Exception ex2) when ((ex2 is IOException || ex2 is UnauthorizedAccessException) ? true : false)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(29, 2, out shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("Verify version=");
					message.AppendFormatted(target.Version);
					message.AppendLiteral(" open failed: ");
					message.AppendFormatted(ex2.GetType().Name);
				}
				DiagnosticLog.Write("Updates", ref message);
				return (Installer: null, Outcome: SealOutcome.Unreadable);
			}
			InstallerVerdict installerVerdict;
			try
			{
				installerVerdict = InstallerVerification.Verify(fileStream, target.Size, target.Sha256);
			}
			catch (IOException ex3)
			{
				fileStream.Dispose();
				DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(29, 2, out shouldAppend);
				if (shouldAppend)
				{
					message2.AppendLiteral("Verify version=");
					message2.AppendFormatted(target.Version);
					message2.AppendLiteral(" read failed: ");
					message2.AppendFormatted(ex3.GetType().Name);
				}
				DiagnosticLog.Write("Updates", ref message2);
