	internal sealed class UpdateCheckSchedule(TimeProvider clock)
	{
		public static readonly TimeSpan StartupDelay = TimeSpan.FromSeconds(90L);

		public static readonly TimeSpan MinimumInterval = TimeSpan.FromHours(24);

		public static readonly TimeSpan RetryDelay = TimeSpan.FromMinutes(10L);

		public static readonly TimeSpan FutureTolerance = TimeSpan.FromMinutes(5L);

		public DateTimeOffset Now => clock.GetUtcNow();

		public bool IsDue(DateTimeOffset? lastCheckUtc)
		{
			if (lastCheckUtc.HasValue)
			{
				DateTimeOffset valueOrDefault = lastCheckUtc.GetValueOrDefault();
				DateTimeOffset now = Now;
				if (valueOrDefault > now + FutureTolerance)
				{
					return true;
				}
				return now - valueOrDefault >= MinimumInterval;
			}
			return true;
		}

		public static bool ShouldRetry(UpdateCheckResult result)
		{
			bool flag = result.Status == UpdateCheckStatus.Unavailable;
			if (flag)
			{
				UpdateCheckFailure failure = result.Failure;
				bool flag2 = (uint)(failure - 2) <= 1u;
				flag = flag2;
			}
			return flag;
		}

		public static bool CountsAsCheck(UpdateCheckResult result)
		{
			bool flag = result.Status != UpdateCheckStatus.Unavailable;
			if (!flag)
			{
				UpdateCheckFailure failure = result.Failure;
				bool flag2 = (((uint)(failure - 4) <= 2u || (uint)(failure - 8) <= 3u) ? true : false);
				flag = flag2;
			}
			return flag;
		}
	}
	internal sealed class UpdateCheckStateStore(string? path)
	{
		private sealed class StateFile
		{
			public DateTimeOffset? LastCheckUtc { get; set; }

			public long HighestManifestSerial { get; set; }

			public StateFile Copy()
			{
