		public const string FileName = "update-state.json";

		private static readonly JsonSerializerOptions SerializerOptions = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			WriteIndented = true
		};

		private readonly Lock _gate = new Lock();

		private StateFile _memory = new StateFile();

		public DateTimeOffset? ReadLastCheck()
		{
			using (_gate.EnterScope())
			{
				return Read().LastCheckUtc;
			}
		}

		public void WriteLastCheck(DateTimeOffset value)
		{
			using (_gate.EnterScope())
			{
				StateFile stateFile = Read();
				stateFile.LastCheckUtc = value;
				Write(stateFile);
			}
		}

		public long ReadHighestManifestSerial()
		{
			using (_gate.EnterScope())
			{
				return Math.Max(0L, Read().HighestManifestSerial);
			}
		}

		public void RaiseHighestManifestSerial(long serial)
		{
			using (_gate.EnterScope())
			{
				StateFile stateFile = Read();
				if (serial > stateFile.HighestManifestSerial)
				{
					stateFile.HighestManifestSerial = serial;
					Write(stateFile);
				}
			}
		}

		private StateFile Read()
		{
			if (path == null)
			{
				return _memory.Copy();
			}
			try
			{
				if (!File.Exists(path))
				{
					return new StateFile();
				}
				return JsonSerializer.Deserialize<StateFile>(File.ReadAllText(path), SerializerOptions) ?? new StateFile();
			}
			catch (Exception ex) when ((ex is JsonException || ex is IOException || ex is UnauthorizedAccessException || ex is NotSupportedException) ? true : false)
			{
