				_memory = state.Copy();
				return;
			}
			try
			{
				Directory.CreateDirectory(System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(path)));
				string sourceFileName = path + ".tmp";
				File.WriteAllText(sourceFileName, JsonSerializer.Serialize(state, SerializerOptions));
				File.Move(sourceFileName, path, overwrite: true);
			}
			catch (Exception ex) when ((ex is IOException || ex is UnauthorizedAccessException) ? true : false)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(17, 1, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("State not saved: ");
					message.AppendFormatted(ex.GetType().Name);
				}
				DiagnosticLog.Write("Updates", ref message);
			}
		}
	}
