	public enum ScriptReading
	{
		Undetermined,
		Persian,
		Latin
	}
	internal static class TranslationDirectionPolicy
	{
		public static TranslationLanguage ResolveTarget(string? targetCode, string source)
		{
			if (!TranslationLanguageCatalog.IsAutomatic(targetCode))
			{
				return TranslationLanguageCatalog.Resolve(targetCode);
			}
			return Read(source) switch
			{
				ScriptReading.Persian => TranslationLanguageCatalog.English, 
				ScriptReading.Latin => TranslationLanguageCatalog.Persian, 
				_ => TranslationLanguageCatalog.English, 
			};
		}

		public static ScriptReading Read(string text)
		{
			int num = 0;
			int num2 = 0;
			foreach (char c in text)
			{
				if (char.IsLetter(c))
				{
					if (IsArabicScript(c))
					{
						num++;
					}
					else if (IsLatinScript(c))
					{
						num2++;
					}
				}
			}
			if (num == 0 && num2 == 0)
			{
				return ScriptReading.Undetermined;
			}
			if (num <= num2)
			{
				return ScriptReading.Latin;
			}
			return ScriptReading.Persian;
		}

		private static bool IsArabicScript(char character)
		{
			if (character >= 'ﭐ')
			{
				if (character >= 'ﹰ')
				{
					if (character <= '\ufeff')
					{
						goto IL_0058;
					}
				}
				else if (character <= '﷿')
				{
					goto IL_0058;
				}
			}
			else if (character >= 'ݐ')
			{
				if (character >= 'ࢠ')
				{
					if (character <= '\u08ff')
					{
						goto IL_0058;
					}
				}
				else if (character <= 'ݿ')
				{
					goto IL_0058;
				}
			}
			else if (character >= '\u0600' && character <= 'ۿ')
			{
				goto IL_0058;
			}
			return false;
			IL_0058:
			return true;
		}

		private static bool IsLatinScript(char character)
		{
			if (character >= 'À')
			{
				if (character >= 'Ḁ')
				{
					if (character <= 'ỿ')
					{
						goto IL_003a;
					}
				}
				else if (character <= 'ɏ')
				{
					goto IL_003a;
				}
			}
			else if (character >= 'a')
			{
				if (character <= 'z')
				{
					goto IL_003a;
				}
			}
			else if (character >= 'A' && character <= 'Z')
			{
				goto IL_003a;
			}
			return false;
			IL_003a:
			return true;
		}
	}
