		internal static string TookTooLongMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationTookTooLong);

		internal static string CancelledByClientMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationCancelledNothingChanged);

		internal static string NoConfirmedTranslationMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationNoConfirmedToUndo);

