		public Task<TranslationActionResult> TranslateSelectedTextAsync(CancellationToken cancellationToken = default(CancellationToken))
		{
			return TranslateSelectedTextAsync(_selectionEditor.CaptureMarker(), cancellationToken);
		}

		public async Task<TranslationActionResult> TranslateSelectedTextAsync(InputMarker marker, CancellationToken cancellationToken = default(CancellationToken))
		{
			if (!(await _operationGate.WaitAsync(0, cancellationToken)))
			{
				return new TranslationActionResult(TranslationActionState.Busy, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationAlreadyRunning));
			}
			long started = Stopwatch.GetTimestamp();
			TranslationAttempt attempt = new TranslationAttempt();
			TranslationActionResult translationActionResult;
			Exception ex;
			try
			{
				(translationActionResult, ex) = await GuardAsync(() => TranslateSelectionAsync(marker, attempt, cancellationToken), cancellationToken);
			}
			finally
			{
				_operationGate.Release();
			}
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(79, 8, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("translate: provider ");
				message.AppendFormatted(attempt.Provider);
				message.AppendLiteral(", target ");
				message.AppendFormatted(attempt.TargetLanguage);
				message.AppendLiteral(", source ");
				message.AppendFormatted(attempt.SourceLength);
				message.AppendLiteral(" chars, route ");
				message.AppendFormatted(attempt.Route);
				message.AppendLiteral(", write ");
				message.AppendFormatted(attempt.WriteOutcome);
				message.AppendLiteral(", ");
				message.AppendFormatted(translationActionResult.State);
				message.AppendLiteral(", ");
				message.AppendFormatted(Stopwatch.GetElapsedTime(started).TotalMilliseconds, "F0");
				message.AppendLiteral(" ms, exception ");
				message.AppendFormatted(ex?.GetType().Name ?? "none");
			}
			DiagnosticLog.Write("Translation", ref message);
			return translationActionResult;
		}

		public async Task<TranslationActionResult> TranslateClipboardAsync(CancellationToken cancellationToken = default(CancellationToken))
		{
			if (!(await _operationGate.WaitAsync(0, cancellationToken)))
			{
				return new TranslationActionResult(TranslationActionState.Busy, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationAlreadyRunning));
			}
			long started = Stopwatch.GetTimestamp();
			TranslationAttempt attempt = new TranslationAttempt
			{
				Route = "ClipboardOnly"
			};
			TranslationActionResult translationActionResult;
			Exception ex;
			try
			{
				(translationActionResult, ex) = await GuardAsync(() => TranslateClipboardTextAsync(attempt, cancellationToken), cancellationToken);
			}
			finally
			{
				_operationGate.Release();
			}
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(88, 8, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("translate-clipboard: provider ");
				message.AppendFormatted(attempt.Provider);
				message.AppendLiteral(", target ");
				message.AppendFormatted(attempt.TargetLanguage);
				message.AppendLiteral(", source ");
				message.AppendFormatted(attempt.SourceLength);
				message.AppendLiteral(" chars, read ");
				message.AppendFormatted(attempt.Route);
				message.AppendLiteral(", write ");
				message.AppendFormatted(attempt.WriteOutcome);
				message.AppendLiteral(", ");
				message.AppendFormatted(translationActionResult.State);
				message.AppendLiteral(", ");
				message.AppendFormatted(Stopwatch.GetElapsedTime(started).TotalMilliseconds, "F0");
				message.AppendLiteral(" ms, exception ");
				message.AppendFormatted(ex?.GetType().Name ?? "none");
			}
			DiagnosticLog.Write("Translation", ref message);
			return translationActionResult;
		}

		private static async Task<(TranslationActionResult Result, Exception? Failure)> GuardAsync(Func<Task<TranslationActionResult>> command, CancellationToken cancellationToken)
		{
			try
			{
				return (Result: await command(), Failure: null);
			}
			catch (OperationCanceledException item) when (cancellationToken.IsCancellationRequested)
			{
				return (Result: new TranslationActionResult(TranslationActionState.Failed, TookTooLongMessage), Failure: item);
			}
			catch (OperationCanceledException item2)
			{
				return (Result: new TranslationActionResult(TranslationActionState.Failed, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationServiceNoAnswer)), Failure: item2);
			}
			catch (TranslationProviderException ex)
			{
				return (Result: new TranslationActionResult(TranslationActionState.Failed, ex.Message), Failure: ex);
			}
			catch (HttpRequestException item3)
			{
				return (Result: new TranslationActionResult(TranslationActionState.Failed, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationServiceUnreachable)), Failure: item3);
			}
			catch (Exception item4)
			{
				return (Result: new TranslationActionResult(TranslationActionState.Failed, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationFailed)), Failure: item4);
			}
		}

		private async Task<TranslationActionResult> TranslateSelectionAsync(InputMarker marker, TranslationAttempt attempt, CancellationToken cancellationToken)
		{
			TranslationSettings settings = GetSettings();
			attempt.Provider = settings.Provider;
			if (!settings.Enabled)
			{
				return new TranslationActionResult(TranslationActionState.Disabled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationOff));
			}
			TranslationCapture translationCapture = await _selectionEditor.CaptureAsync(marker, settings.AllowClipboardFallback, cancellationToken);
			if (!translationCapture.IsCaptured)
			{
				return new TranslationActionResult(translationCapture.State, translationCapture.Message);
			}
			TranslationSelection selection = translationCapture.Selection;
			attempt.Route = selection.Route.ToString();
			string source = TranslationTextContract.PrepareSource(selection.Text);
			attempt.SourceLength = source.Length;
			if (source.Length > 4000)
			{
				return new TranslationActionResult(TranslationActionState.InvalidOutput, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.TranslationSelectionTooLong, InterfaceFormat.Count(4000L, TextCatalog.Language)));
			}
			TranslationLanguage targetLanguage = ResolveTarget(settings, source, attempt);
			(string? Text, TranslationActionResult? Result) translation = await TranslateAsync(source, targetLanguage, settings, cancellationToken);
			if ((object)translation.Result != null)
			{
				return translation.Result;
			}
			cancellationToken.ThrowIfCancellationRequested();
			TranslationWrite translationWrite = await _selectionEditor.ReplaceAsync(selection, translation.Text, targetLanguage.IsRightToLeft, settings.UpdateParagraphDirection, marker, cancellationToken);
			attempt.WriteOutcome = translationWrite.Outcome.ToString();
			switch (translationWrite.Outcome)
			{
			case TranslationWriteOutcome.Confirmed:
				_lastTranslation = new TranslationUndo(selection, source, translation.Text, IsRightToLeft(source), settings.UpdateParagraphDirection, DateTimeOffset.UtcNow)
				{
					WrittenText = translationWrite.WrittenText,
					MarkerAfter = translationWrite.MarkerAfter,
					Route = translationWrite.Route,
					DirectionSent = translationWrite.DirectionSent,
					SelectionStart = translationWrite.SelectionStart
				};
				return new TranslationActionResult(TranslationActionState.Succeeded, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.TranslationDone, targetLanguage.DisplayName));
			case TranslationWriteOutcome.Refused:
				return new TranslationActionResult(translationWrite.Cancelled ? TranslationActionState.Cancelled : TranslationActionState.SelectionChanged, translationWrite.Detail);
			case TranslationWriteOutcome.TimedOut:
				_lastTranslation = null;
				return new TranslationActionResult(TranslationActionState.Failed, translationWrite.Detail);
			default:
				_lastTranslation = null;
				return new TranslationActionResult(TranslationActionState.Unconfirmed, translationWrite.Detail);
			}
		}

		private async Task<TranslationActionResult> TranslateClipboardTextAsync(TranslationAttempt attempt, CancellationToken cancellationToken)
		{
			TranslationSettings settings = GetSettings();
			attempt.Provider = settings.Provider;
			if (!settings.Enabled)
			{
				return new TranslationActionResult(TranslationActionState.Disabled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationOff));
			}
			(ClipboardTextRead, string) tuple = await Task.Run(() => (outcome: _clipboard.ReadText(out string text2), text: text2), cancellationToken);
			ClipboardTextRead item = tuple.Item1;
			string item2 = tuple.Item2;
			attempt.Route = $"ClipboardOnly/{item}";
			switch (item)
			{
			case ClipboardTextRead.Unavailable:
				return new TranslationActionResult(TranslationActionState.Failed, TranslationSelectionEditor.ClipboardUnavailableMessage);
			default:
				if (!string.IsNullOrWhiteSpace(item2))
				{
					string text = TranslationTextContract.PrepareSource(item2);
					attempt.SourceLength = text.Length;
					if (text.Length > 4000)
					{
						return new TranslationActionResult(TranslationActionState.InvalidOutput, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.TranslationClipboardTooLong, InterfaceFormat.Count(4000L, TextCatalog.Language)));
					}
					TranslationLanguage targetLanguage = ResolveTarget(settings, text, attempt);
					(string? Text, TranslationActionResult? Result) translation = await TranslateAsync(text, targetLanguage, settings, cancellationToken);
					if ((object)translation.Result != null)
					{
						return translation.Result;
					}
					cancellationToken.ThrowIfCancellationRequested();
					bool flag = await Task.Run(() => _clipboard.TrySetText(translation.Text), CancellationToken.None);
					attempt.WriteOutcome = (flag ? "Placed" : "Refused");
					return flag ? new TranslationActionResult(TranslationActionState.Succeeded, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.TranslationCopiedToClipboard, targetLanguage.DisplayName)) : new TranslationActionResult(TranslationActionState.Failed, ClipboardWriteFailedMessage);
				}
				goto case ClipboardTextRead.NoText;
			case ClipboardTextRead.NoText:
				return new TranslationActionResult(TranslationActionState.NoSelection, ClipboardEmptyMessage);
			}
		}

		private static TranslationLanguage ResolveTarget(TranslationSettings settings, string source, TranslationAttempt attempt)
		{
			TranslationLanguage translationLanguage = TranslationDirectionPolicy.ResolveTarget(settings.TargetLanguage, source);
			attempt.TargetLanguage = (TranslationLanguageCatalog.IsAutomatic(settings.TargetLanguage) ? (translationLanguage.Code + " (automatic)") : translationLanguage.Code);
			return translationLanguage;
		}

		private async Task<(string? Text, TranslationActionResult? Result)> TranslateAsync(string source, TranslationLanguage targetLanguage, TranslationSettings settings, CancellationToken cancellationToken)
		{
			string output;
			try
			{
				output = await _provider.TranslateAsync(source, targetLanguage, settings, cancellationToken).WaitAsync(cancellationToken);
			}
			catch (TranslationModelNotReadyException)
			{
				return (Text: null, Result: new TranslationActionResult(TranslationActionState.ModelNotReady, (settings.Provider == "azure") ? SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationAddAzureKey) : SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationSetUpLocalModel)));
			}
			string text = TranslationTextContract.ValidateAndNormalize(source, output);
			return ((string? Text, TranslationActionResult? Result))((text == null) ? (Text: null, Result: new TranslationActionResult(TranslationActionState.InvalidOutput, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationUnsafeFormat))) : (Text: text, Result: null));
		}

		public TranslationActionResult UndoLastTranslation()
		{
			return Task.Run(() => UndoLastTranslationAsync(CancellationToken.None)).GetAwaiter().GetResult();
		}

		public async Task<TranslationActionResult> UndoLastTranslationAsync(CancellationToken cancellationToken = default(CancellationToken))
		{
			TranslationSettings settings = GetSettings();
			if (!settings.UndoWithUndoShortcut)
			{
				return new TranslationActionResult(TranslationActionState.NothingToUndo, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationUndoOff));
			}
			TranslationUndo translation = _lastTranslation;
			if ((object)translation == null || DateTimeOffset.UtcNow - translation.CreatedAt > UndoWindow)
			{
				_lastTranslation = null;
				return new TranslationActionResult(TranslationActionState.NothingToUndo, ((object)translation == null) ? NoConfirmedTranslationMessage : SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationNothingRecentToUndo));
			}
			if (!(await _operationGate.WaitAsync(0, cancellationToken)))
			{
				return new TranslationActionResult(TranslationActionState.Busy, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationAlreadyRunning));
			}
			try
			{
				TranslationWrite translationWrite = await _selectionEditor.RestoreAsync(translation, settings.AllowClipboardFallback, cancellationToken);
				switch (translationWrite.Outcome)
				{
				case TranslationWriteOutcome.Confirmed:
					_lastTranslation = null;
					return new TranslationActionResult(TranslationActionState.Succeeded, RestoredMessage);
				case TranslationWriteOutcome.Refused:
					return new TranslationActionResult(TranslationActionState.SelectionChanged, translationWrite.Detail);
				case TranslationWriteOutcome.TimedOut:
					_lastTranslation = null;
					return new TranslationActionResult(TranslationActionState.Failed, translationWrite.Detail);
				default:
					_lastTranslation = null;
					return new TranslationActionResult(TranslationActionState.Unconfirmed, translationWrite.Detail);
				}
			}
			finally
			{
				_operationGate.Release();
			}
		}

		private static bool IsRightToLeft(string text)
		{
			foreach (char c in text)
			{
				if (c >= '\u0600' && c <= 'ۿ' && char.IsLetter(c))
				{
					return true;
				}
				bool flag;
				switch (c)
				{
				case 'A':
				case 'B':
				case 'C':
				case 'D':
				case 'E':
				case 'F':
				case 'G':
				case 'H':
				case 'I':
				case 'J':
				case 'K':
				case 'L':
				case 'M':
				case 'N':
				case 'O':
				case 'P':
				case 'Q':
				case 'R':
				case 'S':
				case 'T':
				case 'U':
				case 'V':
				case 'W':
				case 'X':
				case 'Y':
				case 'Z':
				case 'a':
				case 'b':
				case 'c':
				case 'd':
				case 'e':
				case 'f':
				case 'g':
				case 'h':
				case 'i':
				case 'j':
				case 'k':
				case 'l':
				case 'm':
				case 'n':
				case 'o':
				case 'p':
				case 'q':
				case 'r':
				case 's':
				case 't':
				case 'u':
				case 'v':
				case 'w':
				case 'x':
				case 'y':
				case 'z':
					flag = true;
					break;
				default:
					flag = false;
					break;
				}
				if (flag)
				{
					return false;
				}
			}
			return false;
		}

		public void Dispose()
		{
			if (!_disposed)
			{
				_disposed = true;
				_provider.Dispose();
				_operationGate.Dispose();
			}
		}

		private static TranslationSettings Normalize(TranslationSettings settings)
		{
			return settings with
			{
				Provider = TranslationProviderCatalog.Resolve(settings.Provider).Id,
				TargetLanguage = TranslationLanguageCatalog.Resolve(settings.TargetLanguage).Code,
				ModelAlias = TranslationModelCatalog.Resolve(settings.ModelAlias).Alias,
				AzureRegion = (string.IsNullOrWhiteSpace(settings.AzureRegion) ? "global" : settings.AzureRegion.Trim())
			};
		}
	}
	public enum TranslationModelState
	{
		Unknown,
		Ready,
		DownloadRequired,
		Downloading,
		ConfigurationRequired,
		Unavailable,
		Failed
	}
	public sealed record TranslationModelStatus(TranslationModelState State, string Message, float? Progress = null)
	{
		public bool IsReady => State == TranslationModelState.Ready;
	}
	public enum TranslationActionState
	{
		Succeeded,
		Disabled,
		Busy,
		NoSelection,
		ProtectedField,
		ModelNotReady,
		SelectionChanged,
		InvalidOutput,
		NothingToUndo,
		Cancelled,
		Failed,
		Unconfirmed,
		Unsupported
	}
	public sealed record TranslationActionResult(TranslationActionState State, string Message)
	{
		public bool Succeeded => State == TranslationActionState.Succeeded;
	}
	internal enum TranslationWriteRoute
	{
		None,
		ClassicEdit,
		TypeOver,
		Clipboard
	}
	internal sealed record TranslationSelection(string Text, long TargetIdentity, long WindowIdentity, bool CoversParagraph)
	{
		public string RawText { get; init; } = Text;

		public long FocusedControl { get; init; }

		public TranslationWriteRoute Route { get; init; } = TranslationWriteRoute.TypeOver;

		public bool ReadThroughClipboard { get; init; }

		public bool ClipboardFallbackAllowed { get; init; }
	}
	internal sealed record TranslationCapture(TranslationSelection? Selection, TranslationActionState State, string Message)
	{
		public bool IsCaptured => (object)Selection != null;

		public static TranslationCapture Of(TranslationSelection selection)
		{
			return new TranslationCapture(selection, TranslationActionState.Succeeded, string.Empty);
		}

		public static TranslationCapture Refused(TranslationActionState state, string message)
		{
			return new TranslationCapture(null, state, message);
		}
