	internal enum TranslationWriteOutcome
	{
		Confirmed,
		Refused,
		Unconfirmed,
		TimedOut
	}
	internal sealed record TranslationWrite(TranslationWriteOutcome Outcome, string Detail)
	{
		public TranslationWriteRoute Route { get; init; }

		public string WrittenText { get; init; } = string.Empty;

		public InputMarker MarkerAfter { get; init; }

		public bool DirectionSent { get; init; }

		public int SelectionStart { get; init; } = -1;

		public bool IsConfirmed => Outcome == TranslationWriteOutcome.Confirmed;

		public bool Cancelled { get; init; }

		public static TranslationWrite Refuse(string detail)
		{
			return new TranslationWrite(TranslationWriteOutcome.Refused, detail);
		}

		public static TranslationWrite RefuseCancelled(string detail)
		{
			return new TranslationWrite(TranslationWriteOutcome.Refused, detail)
			{
				Cancelled = true
			};
		}
	}
	internal sealed record TranslationUndo(TranslationSelection Selection, string SourceText, string TranslatedText, bool SourceRightToLeft, bool UpdateParagraphDirection, DateTimeOffset CreatedAt)
	{
