	internal sealed class TranslationModelWarmUp : IDisposable
	{
		private readonly ITranslationProvider _provider;

		private readonly Func<TranslationSettings> _getSettings;

		private readonly Func<Func<Task>, Task> _schedule;

		private readonly object _gate = new object();

		private string? _warmedAlias;

		private CancellationTokenSource? _cancellation;

		private Task? _pending;

		private bool _disposed;

		internal Task? Pending
		{
			get
			{
				lock (_gate)
				{
					return _pending;
				}
			}
		}

		public TranslationModelWarmUp(ITranslationProvider provider, Func<TranslationSettings> getSettings, Func<Func<Task>, Task>? schedule = null)
		{
			_provider = provider;
			_getSettings = getSettings;
			_schedule = schedule ?? ((Func<Func<Task>, Task>)((Func<Task> work) => Task.Run(work)));
		}

		public static bool IsWanted(TranslationSettings settings)
		{
			if (settings.Enabled && settings.WarmUpLocalModel)
			{
				return string.Equals(settings.Provider, "local", StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		public bool Apply()
		{
			TranslationSettings settings = _getSettings();
			lock (_gate)
			{
				if (_disposed)
				{
					return false;
				}
				if (!IsWanted(settings))
				{
					_warmedAlias = null;
					_cancellation?.Cancel();
					_cancellation = null;
					return false;
				}
				if (string.Equals(_warmedAlias, settings.ModelAlias, StringComparison.OrdinalIgnoreCase))
				{
					return false;
				}
				_warmedAlias = settings.ModelAlias;
				_cancellation?.Cancel();
				CancellationTokenSource cancellation = (_cancellation = new CancellationTokenSource());
				_pending = _schedule(() => LoadAsync(settings, cancellation.Token));
				return true;
			}
		}

		private async Task LoadAsync(TranslationSettings settings, CancellationToken cancellationToken)
		{
			long started = Stopwatch.GetTimestamp();
			Exception failure = null;
			string value;
			try
			{
				await _provider.WarmUpAsync(settings, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				value = "loaded";
			}
			catch (OperationCanceledException)
			{
				value = "cancelled";
			}
			catch (Exception ex2)
			{
				failure = ex2;
				value = "failed";
			}
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(37, 4, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("warm-up: ");
				message.AppendFormatted(value);
				message.AppendLiteral(", provider ");
				message.AppendFormatted(settings.Provider);
				message.AppendLiteral(", ");
				message.AppendFormatted(Stopwatch.GetElapsedTime(started).TotalMilliseconds, "F0");
				message.AppendLiteral(" ms, exception ");
				message.AppendFormatted(failure?.GetType().Name ?? "none");
			}
			DiagnosticLog.Write("Translation", ref message);
		}

		public void Dispose()
		{
			lock (_gate)
			{
				if (!_disposed)
				{
					_disposed = true;
					_cancellation?.Cancel();
					_cancellation?.Dispose();
					_cancellation = null;
				}
			}
		}
	}
	internal sealed class TranslationProviderRouter : ITranslationProvider, IDisposable
	{
		private readonly Lazy<ITranslationProvider> _local;

		private readonly Lazy<ITranslationProvider> _azure;

		public TranslationProviderRouter(Func<ITranslationProvider> localFactory, Func<ITranslationProvider> azureFactory)
		{
			_local = new Lazy<ITranslationProvider>(localFactory, LazyThreadSafetyMode.ExecutionAndPublication);
			_azure = new Lazy<ITranslationProvider>(azureFactory, LazyThreadSafetyMode.ExecutionAndPublication);
		}

		public Task<TranslationModelStatus> CheckModelAsync(TranslationSettings settings, CancellationToken cancellationToken)
		{
			return Resolve(settings).CheckModelAsync(settings, cancellationToken);
		}

		public Task<TranslationModelStatus> DownloadModelAsync(TranslationSettings settings, IProgress<float>? progress, CancellationToken cancellationToken)
		{
			return Resolve(settings).DownloadModelAsync(settings, progress, cancellationToken);
		}

		public Task WarmUpAsync(TranslationSettings settings, CancellationToken cancellationToken)
		{
			return Resolve(settings).WarmUpAsync(settings, cancellationToken);
		}

		public Task<string> TranslateAsync(string text, TranslationLanguage targetLanguage, TranslationSettings settings, CancellationToken cancellationToken)
		{
			return Resolve(settings).TranslateAsync(text, targetLanguage, settings, cancellationToken);
		}

		public bool HasCloudCredential()
		{
			return _azure.Value.HasCloudCredential();
		}

		public bool SaveCloudCredential(string credential)
		{
			return _azure.Value.SaveCloudCredential(credential);
		}

		public void DeleteCloudCredential()
		{
			_azure.Value.DeleteCloudCredential();
		}

		public Task<TranslationModelStatus> TestCloudConnectionAsync(TranslationSettings settings, CancellationToken cancellationToken)
		{
			return _azure.Value.TestCloudConnectionAsync(settings, cancellationToken);
		}

		public void Dispose()
		{
			if (_azure.IsValueCreated)
			{
				_azure.Value.Dispose();
			}
			if (_local.IsValueCreated)
			{
				_local.Value.Dispose();
			}
		}

		private ITranslationProvider Resolve(TranslationSettings settings)
		{
			if (!string.Equals(settings.Provider, "azure", StringComparison.OrdinalIgnoreCase))
			{
				return _local.Value;
			}
			return _azure.Value;
		}
	}
	internal sealed class TranslationRun : IDisposable
	{
		private readonly TranslationRunGate _gate;

		private readonly CancellationTokenSource _timeLimit;

		private readonly CancellationTokenSource _client = new CancellationTokenSource();

		private readonly CancellationTokenSource _linked;

		private bool _disposed;

		public int Command { get; }

		public CancellationToken Token => _linked.Token;

		public bool CancelledByClient => _client.IsCancellationRequested;

		public bool TimedOut => _timeLimit.IsCancellationRequested;

		internal TranslationRun(TranslationRunGate gate, int command, TimeSpan timeLimit)
		{
			_gate = gate;
			Command = command;
			_timeLimit = new CancellationTokenSource(timeLimit);
			_linked = CancellationTokenSource.CreateLinkedTokenSource(_timeLimit.Token, _client.Token);
		}

		public void Cancel()
		{
			if (_disposed)
			{
				return;
			}
			try
			{
				_client.Cancel();
			}
			catch (ObjectDisposedException)
			{
			}
		}

		public string Describe(TranslationActionResult result)
		{
			bool flag = CancelledByClient;
			if (flag)
			{
				TranslationActionState state = result.State;
				bool flag2 = (uint)(state - 9) <= 1u;
				flag = flag2;
			}
			if (!flag)
			{
				return result.Message;
			}
			return TranslationFeature.CancelledByClientMessage;
		}

		public void Dispose()
		{
			if (!_disposed)
			{
				_disposed = true;
				_gate.End(this);
				_linked.Dispose();
				_client.Dispose();
				_timeLimit.Dispose();
			}
		}
	}
	internal sealed class TranslationRunGate
	{
		private TranslationRun? _current;

		public TranslationRun? Current => Volatile.Read(in _current);

		public bool IsRunning => Current != null;

		public event Action<TranslationRun?>? RunningChanged;

		public TranslationRun? Begin(int command, TimeSpan timeLimit)
		{
			TranslationRun translationRun = new TranslationRun(this, command, timeLimit);
			if (Interlocked.CompareExchange(ref _current, translationRun, null) != null)
			{
				translationRun.Dispose();
				return null;
			}
			RunningChanged?.Invoke(translationRun);
			return translationRun;
		}

		public bool CancelCurrent()
		{
			TranslationRun current = Current;
			if (current == null)
			{
				return false;
			}
			current.Cancel();
			return true;
		}

		internal void End(TranslationRun run)
		{
			if (Interlocked.CompareExchange(ref _current, null, run) == run)
			{
				RunningChanged?.Invoke(null);
			}
		}
	}
	internal sealed class TranslationSelectionEditor : ITranslationSelectionEditor
	{
		private const ushort VkC = 67;

		private const ushort VkV = 86;

		private readonly IInputInjector _injector;

		private readonly ExplicitSelectionWorker _worker;

		private readonly Func<InputMarker> _captureMarker;

		private readonly Func<InputMarker, bool> _isInputCurrent;

		private readonly Func<bool> _targetRestricted;

		private readonly Func<IFocusedControlEditor> _controlEditor;

		private readonly Func<ITranslationClipboard> _clipboard;

		internal static string NoSelectionMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationSelectText);

		internal static string ProtectedMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationProtectedField);

		internal static string CancelledMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.CancelledAfterShortcut);

		internal static string SelectionChangedMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationSelectionChanged);

		internal static string UnreadableSelectionMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationSelectionUnreadable);

		internal static string UnsupportedEditorMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationEditorUnsupported);

		internal static string MultiLineMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationMultiLineUnsupported);

		internal static string BusyMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationPreviousCommandBusy);

		internal static string ReadTimedOutMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationReadTimedOut);

		internal static string ReadFailedMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationReadFailed);

		internal static string WriteTimedOutMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationWriteTimedOut);

		internal static string WriteFailedMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationWriteFailed);

		internal static string UnconfirmedMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationUnconfirmed);

		internal static string UnconfirmedRestoreMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationRestoreUnconfirmed);

		internal static string ClipboardUnavailableMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationClipboardUnavailable);

		internal static string UndoMovedMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationUndoMoved);

		internal static string UndoContradictedMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationUndoContradicted);

		internal static string UndoClipboardOffMessage => SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationUndoClipboardOff);

		internal TimeSpan ReadTimeout { get; set; } = TimeSpan.FromSeconds(3L);

		internal TimeSpan WriteTimeout { get; set; } = TimeSpan.FromSeconds(5L);

		internal int ReadBackAttempts { get; set; } = 6;

		internal int ReadBackDelayMilliseconds { get; set; } = 40;

		internal int ClipboardWaitAttempts { get; set; } = 16;

		internal int ClipboardWaitStepMilliseconds { get; set; } = 25;

		internal int PasteSettleMilliseconds { get; set; } = 150;

		public TranslationSelectionEditor(IInputInjector injector, ExplicitSelectionWorker worker, Func<InputMarker> captureMarker, Func<InputMarker, bool> isInputCurrent, Func<bool> targetRestricted, Func<IFocusedControlEditor> controlEditor, Func<ITranslationClipboard> clipboard)
		{
			_injector = injector;
			_worker = worker;
			_captureMarker = captureMarker;
			_isInputCurrent = isInputCurrent;
			_targetRestricted = targetRestricted;
			_controlEditor = controlEditor;
			_clipboard = clipboard;
		}

		public InputMarker CaptureMarker()
		{
			return _captureMarker();
		}

		public async Task<TranslationCapture> CaptureAsync(InputMarker marker, bool allowClipboardFallback, CancellationToken cancellationToken)
		{
			if (!_isInputCurrent(marker))
			{
				return TranslationCapture.Refused(TranslationActionState.Cancelled, CancelledMessage);
			}
			WorkerAttempt<TranslationCapture> workerAttempt = await _worker.RunAsync(() => Capture(marker, allowClipboardFallback), ReadTimeout).ConfigureAwait(continueOnCapturedContext: true);
			TranslationCapture translationCapture = workerAttempt.State switch
			{
				ExplicitSelectionAttemptState.Busy => TranslationCapture.Refused(TranslationActionState.Busy, BusyMessage), 
				ExplicitSelectionAttemptState.TimedOut => TranslationCapture.Refused(TranslationActionState.Failed, ReadTimedOutMessage), 
				ExplicitSelectionAttemptState.Failed => TranslationCapture.Refused(TranslationActionState.Failed, ReadFailedMessage), 
				_ => workerAttempt.Result, 
			};
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(18, 2, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("capture: worker ");
				message.AppendFormatted(workerAttempt.State);
				message.AppendLiteral(", ");
				message.AppendFormatted(translationCapture.IsCaptured ? $"route {translationCapture.Selection.Route}, {translationCapture.Selection.RawText.Length} chars, coversParagraph {translationCapture.Selection.CoversParagraph}, viaClipboard {translationCapture.Selection.ReadThroughClipboard}" : $"refused {translationCapture.State}");
			}
			DiagnosticLog.Write("Translation", ref message);
			return translationCapture;
		}

		private TranslationCapture Capture(InputMarker marker, bool allowClipboardFallback)
		{
			if (!_isInputCurrent(marker))
			{
				return TranslationCapture.Refused(TranslationActionState.Cancelled, CancelledMessage);
			}
			if (_targetRestricted())
			{
				return TranslationCapture.Refused(TranslationActionState.ProtectedField, ProtectedMessage);
			}
			long foregroundTargetIdentity = _injector.GetForegroundTargetIdentity();
			long foregroundWindowIdentity = _injector.GetForegroundWindowIdentity();
			if (foregroundTargetIdentity == 0L || foregroundWindowIdentity == 0L)
			{
				return TranslationCapture.Refused(TranslationActionState.NoSelection, NoSelectionMessage);
			}
			long num = _controlEditor().FocusedControl();
			if (!_injector.TryGetSelectedText(out string selectedText))
			{
				if (!allowClipboardFallback)
				{
					return TranslationCapture.Refused(TranslationActionState.NoSelection, UnreadableSelectionMessage);
				}
				string text = ReadSelectionThroughClipboard();
				if (text == null)
				{
					return TranslationCapture.Refused(TranslationActionState.Failed, ClipboardUnavailableMessage);
				}
				if (string.IsNullOrWhiteSpace(text))
				{
					return TranslationCapture.Refused(TranslationActionState.NoSelection, NoSelectionMessage);
				}
				if (!IdentitiesMatch(foregroundTargetIdentity, foregroundWindowIdentity) || !_isInputCurrent(marker))
				{
					return TranslationCapture.Refused(TranslationActionState.SelectionChanged, SelectionChangedMessage);
				}
				return TranslationCapture.Of(new TranslationSelection(text, foregroundTargetIdentity, foregroundWindowIdentity, CoversParagraph: false)
				{
					RawText = text,
					FocusedControl = num,
					Route = ((num != 0L && _controlEditor().IsSupportedControl(num)) ? TranslationWriteRoute.ClassicEdit : TranslationWriteRoute.Clipboard),
					ReadThroughClipboard = true,
					ClipboardFallbackAllowed = true
				});
			}
			if (string.IsNullOrWhiteSpace(selectedText))
			{
				return TranslationCapture.Refused(TranslationActionState.NoSelection, NoSelectionMessage);
			}
			bool coversParagraph = _injector.SelectionCoversCurrentParagraph();
			if (!IdentitiesMatch(foregroundTargetIdentity, foregroundWindowIdentity))
			{
				return TranslationCapture.Refused(TranslationActionState.SelectionChanged, SelectionChangedMessage);
			}
			TranslationWriteRoute translationWriteRoute = ChooseRoute(num, selectedText, allowClipboardFallback, out TranslationCapture refusal);
			if (translationWriteRoute == TranslationWriteRoute.None)
			{
				return refusal;
			}
			return TranslationCapture.Of(new TranslationSelection(selectedText, foregroundTargetIdentity, foregroundWindowIdentity, coversParagraph)
			{
				RawText = selectedText,
				FocusedControl = num,
				Route = translationWriteRoute,
				ClipboardFallbackAllowed = allowClipboardFallback
			});
		}

		private TranslationWriteRoute ChooseRoute(long control, string raw, bool allowClipboardFallback, out TranslationCapture? refusal)
		{
			refusal = null;
			if (control != 0L && _controlEditor().IsSupportedControl(control))
			{
				return TranslationWriteRoute.ClassicEdit;
			}
			if (_injector.FocusedEditorLosesUnicodeBatches())
			{
				if (allowClipboardFallback)
				{
					return TranslationWriteRoute.Clipboard;
				}
				refusal = TranslationCapture.Refused(TranslationActionState.Unsupported, UnsupportedEditorMessage);
				return TranslationWriteRoute.None;
			}
			if (IsMultiLine(TranslationTextContract.PrepareSource(raw)))
			{
				if (allowClipboardFallback)
				{
					return TranslationWriteRoute.Clipboard;
				}
				refusal = TranslationCapture.Refused(TranslationActionState.Unsupported, MultiLineMessage);
				return TranslationWriteRoute.None;
			}
			return TranslationWriteRoute.TypeOver;
		}

		public async Task<TranslationWrite> ReplaceAsync(TranslationSelection selection, string replacement, bool rightToLeft, bool updateParagraphDirection, InputMarker marker, CancellationToken cancellationToken)
		{
			if (!_isInputCurrent(marker))
			{
				return TranslationWrite.RefuseCancelled(CancelledMessage);
			}
			WorkerAttempt<TranslationWrite> workerAttempt = await _worker.RunAsync(() => Write(selection, replacement, rightToLeft, updateParagraphDirection, marker), WriteTimeout).ConfigureAwait(continueOnCapturedContext: true);
			TranslationWrite translationWrite = workerAttempt.State switch
			{
				ExplicitSelectionAttemptState.Busy => TranslationWrite.Refuse(BusyMessage), 
				ExplicitSelectionAttemptState.TimedOut => new TranslationWrite(TranslationWriteOutcome.TimedOut, WriteTimedOutMessage)
				{
					Route = selection.Route
				}, 
				ExplicitSelectionAttemptState.Failed => new TranslationWrite(TranslationWriteOutcome.Unconfirmed, WriteFailedMessage)
				{
					Route = selection.Route
				}, 
				_ => workerAttempt.Result, 
			};
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(46, 6, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("write: worker ");
				message.AppendFormatted(workerAttempt.State);
				message.AppendLiteral(", route ");
				message.AppendFormatted(translationWrite.Route);
				message.AppendLiteral(", ");
				message.AppendFormatted(translationWrite.Outcome);
				message.AppendLiteral(", ");
				message.AppendFormatted(translationWrite.WrittenText.Length);
				message.AppendLiteral(" chars, direction ");
				message.AppendFormatted(translationWrite.DirectionSent);
				message.AppendLiteral(", ");
				message.AppendFormatted(translationWrite.Detail);
			}
			DiagnosticLog.Write("Translation", ref message);
			return translationWrite;
		}

		private TranslationWrite Write(TranslationSelection selection, string replacement, bool rightToLeft, bool updateParagraphDirection, InputMarker marker)
		{
			string written = BidiControlCharacters.Isolate(BidiControlCharacters.Remove(replacement), rightToLeft);
			if (!_isInputCurrent(marker))
			{
				return TranslationWrite.RefuseCancelled(CancelledMessage);
			}
			if (!IdentitiesMatch(selection))
			{
				return TranslationWrite.Refuse(SelectionChangedMessage);
			}
			TranslationWrite translationWrite;
			switch (selection.Route)
			{
			case TranslationWriteRoute.ClassicEdit:
				translationWrite = WriteThroughControl(selection, written);
				if (translationWrite.Outcome == TranslationWriteOutcome.Refused)
				{
					DiagnosticMessageHandler message = new DiagnosticMessageHandler(33, 2, out var shouldAppend);
					if (shouldAppend)
					{
						message.AppendLiteral("route A refused (");
						message.AppendFormatted(translationWrite.Detail);
						message.AppendLiteral("); trying route ");
						message.AppendFormatted(selection.ReadThroughClipboard ? "C" : "B");
					}
					DiagnosticLog.Write("Translation", ref message);
					translationWrite = (selection.ReadThroughClipboard ? WriteThroughClipboard(selection, written, marker) : WriteByTyping(selection, written, marker));
				}
				break;
			case TranslationWriteRoute.TypeOver:
				translationWrite = WriteByTyping(selection, written, marker);
				break;
			case TranslationWriteRoute.Clipboard:
				translationWrite = WriteThroughClipboard(selection, written, marker);
				break;
			default:
				return TranslationWrite.Refuse(UnsupportedEditorMessage);
			}
			if (!translationWrite.IsConfirmed)
			{
				return translationWrite;
			}
			bool directionSent = updateParagraphDirection && selection.CoversParagraph && _injector.ApplyParagraphDirection(rightToLeft);
			return translationWrite with
			{
				DirectionSent = directionSent,
				MarkerAfter = _captureMarker()
			};
		}

		private TranslationWrite WriteThroughControl(TranslationSelection selection, string written)
		{
			IFocusedControlEditor focusedControlEditor = _controlEditor();
			if (selection.FocusedControl == 0L || focusedControlEditor.FocusedControl() != selection.FocusedControl)
			{
				return TranslationWrite.Refuse(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationFocusChanged));
			}
			EditReplacementResult editReplacementResult = focusedControlEditor.ReplaceSelection(selection.FocusedControl, selection.RawText, written, out var selectionStart);
			return editReplacementResult.Outcome switch
			{
				EditReplacementOutcome.Replaced => new TranslationWrite(TranslationWriteOutcome.Confirmed, editReplacementResult.Detail)
				{
					Route = TranslationWriteRoute.ClassicEdit,
					WrittenText = written,
					SelectionStart = selectionStart
				}, 
				EditReplacementOutcome.Refused => RefuseByControl(editReplacementResult.Detail), 
				_ => new TranslationWrite(TranslationWriteOutcome.Unconfirmed, UnconfirmedMessage)
				{
					Route = TranslationWriteRoute.ClassicEdit,
					WrittenText = written,
					SelectionStart = selectionStart
				}, 
			};
		}

		private static TranslationWrite RefuseByControl(string detail)
		{
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(28, 1, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("write: the control refused: ");
				message.AppendFormatted(detail);
			}
			DiagnosticLog.Write("Translation", ref message);
			return TranslationWrite.Refuse(SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TranslationControlRefused));
		}

		private TranslationWrite WriteByTyping(TranslationSelection selection, string written, InputMarker marker)
		{
			if (_injector.FocusedEditorLosesUnicodeBatches())
			{
				return TranslationWrite.Refuse(UnsupportedEditorMessage);
			}
			if (IsMultiLine(written))
			{
				return TranslationWrite.Refuse(MultiLineMessage);
			}
			if (!_injector.TryGetSelectedText(out string selectedText) || !string.Equals(selectedText, selection.RawText, StringComparison.Ordinal))
			{
				return TranslationWrite.Refuse(SelectionChangedMessage);
			}
			if (!_isInputCurrent(marker))
			{
				return TranslationWrite.RefuseCancelled(CancelledMessage);
			}
			if (!_injector.SendUnicodeText(written))
			{
				return new TranslationWrite(TranslationWriteOutcome.Unconfirmed, UnconfirmedMessage)
				{
					Route = TranslationWriteRoute.TypeOver,
					WrittenText = written
				};
			}
			return ReadBack(written, selection.CoversParagraph, TranslationWriteRoute.TypeOver, UnconfirmedMessage);
		}

		private TranslationWrite WriteThroughClipboard(TranslationSelection selection, string written, InputMarker marker)
		{
			if (!selection.ClipboardFallbackAllowed)
			{
				return TranslationWrite.Refuse(UnsupportedEditorMessage);
			}
			if (!selection.ReadThroughClipboard && (!_injector.TryGetSelectedText(out string selectedText) || !string.Equals(selectedText, selection.RawText, StringComparison.Ordinal)))
			{
				return TranslationWrite.Refuse(SelectionChangedMessage);
			}
			ITranslationClipboard translationClipboard = _clipboard();
			ClipboardTextRead clipboardTextRead = translationClipboard.ReadText(out string text);
			if (clipboardTextRead == ClipboardTextRead.Unavailable)
			{
				return TranslationWrite.Refuse(ClipboardUnavailableMessage);
			}
			bool hadText = clipboardTextRead == ClipboardTextRead.Text;
			if (!translationClipboard.TrySetText(written))
			{
				RestoreClipboard(translationClipboard, hadText, text, translationClipboard.SequenceNumber);
				return TranslationWrite.Refuse(ClipboardUnavailableMessage);
			}
			uint sequenceNumber = translationClipboard.SequenceNumber;
			if (!_isInputCurrent(marker) || !IdentitiesMatch(selection))
			{
				RestoreClipboard(translationClipboard, hadText, text, sequenceNumber);
				return TranslationWrite.RefuseCancelled(CancelledMessage);
			}
			TranslationWrite translationWrite = (_injector.SendControlShortcutWithoutActiveModifiers(86) ? ReadBack(written, selection.CoversParagraph, TranslationWriteRoute.Clipboard, UnconfirmedMessage) : new TranslationWrite(TranslationWriteOutcome.Unconfirmed, UnconfirmedMessage)
			{
				Route = TranslationWriteRoute.Clipboard,
				WrittenText = written
			});
			if (!translationWrite.IsConfirmed)
			{
				Thread.Sleep(PasteSettleMilliseconds);
			}
			RestoreClipboard(translationClipboard, hadText, text, sequenceNumber);
			return translationWrite;
		}

		public async Task<TranslationWrite> RestoreAsync(TranslationUndo translation, bool allowClipboardFallback, CancellationToken cancellationToken)
		{
			if (!_isInputCurrent(translation.MarkerAfter))
			{
				return TranslationWrite.Refuse(UndoMovedMessage);
			}
			WorkerAttempt<TranslationWrite> workerAttempt = await _worker.RunAsync(() => Restore(translation, allowClipboardFallback), WriteTimeout).ConfigureAwait(continueOnCapturedContext: true);
			TranslationWrite translationWrite = workerAttempt.State switch
			{
				ExplicitSelectionAttemptState.Busy => TranslationWrite.Refuse(BusyMessage), 
				ExplicitSelectionAttemptState.TimedOut => new TranslationWrite(TranslationWriteOutcome.TimedOut, WriteTimedOutMessage)
				{
					Route = translation.Route
				}, 
				ExplicitSelectionAttemptState.Failed => new TranslationWrite(TranslationWriteOutcome.Unconfirmed, WriteFailedMessage)
				{
					Route = translation.Route
				}, 
				_ => workerAttempt.Result, 
			};
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(40, 5, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("restore: worker ");
				message.AppendFormatted(workerAttempt.State);
				message.AppendLiteral(", route ");
				message.AppendFormatted(translationWrite.Route);
				message.AppendLiteral(", ");
				message.AppendFormatted(translationWrite.Outcome);
				message.AppendLiteral(", direction ");
				message.AppendFormatted(translationWrite.DirectionSent);
				message.AppendLiteral(", ");
				message.AppendFormatted(translationWrite.Detail);
			}
			DiagnosticLog.Write("Translation", ref message);
			return translationWrite;
		}

		private TranslationWrite Restore(TranslationUndo translation, bool allowClipboardFallback)
		{
			if (!_isInputCurrent(translation.MarkerAfter) || !IdentitiesMatch(translation.Selection))
			{
				return TranslationWrite.Refuse(UndoMovedMessage);
			}
			string sourceText = translation.SourceText;
			string writtenText = translation.WrittenText;
			if (sourceText.Length == 0 || writtenText.Length == 0)
			{
				return TranslationWrite.Refuse(UndoContradictedMessage);
			}
			TranslationWrite translationWrite;
			switch (translation.Route)
			{
			case TranslationWriteRoute.ClassicEdit:
			{
				EditReplacementResult editReplacementResult = _controlEditor().RestoreSelection(translation.Selection.FocusedControl, translation.SelectionStart, writtenText, sourceText);
				translationWrite = editReplacementResult.Outcome switch
				{
					EditReplacementOutcome.Replaced => new TranslationWrite(TranslationWriteOutcome.Confirmed, editReplacementResult.Detail), 
					EditReplacementOutcome.Refused => TranslationWrite.Refuse(UndoContradictedMessage), 
					_ => new TranslationWrite(TranslationWriteOutcome.Unconfirmed, UnconfirmedRestoreMessage), 
				};
				break;
			}
			case TranslationWriteRoute.TypeOver:
				if (_injector.FocusedEditorLosesUnicodeBatches())
				{
					return TranslationWrite.Refuse(UnsupportedEditorMessage);
				}
				if (!_injector.TryReplaceExactTextBeforeCaret(writtenText, sourceText))
				{
					return TranslationWrite.Refuse(UndoContradictedMessage);
				}
				translationWrite = ReadBack(sourceText, translation.Selection.CoversParagraph, TranslationWriteRoute.TypeOver, UnconfirmedRestoreMessage);
				break;
			case TranslationWriteRoute.Clipboard:
			{
				if (!allowClipboardFallback)
				{
					return TranslationWrite.Refuse(UndoClipboardOffMessage);
				}
				ITranslationClipboard translationClipboard = _clipboard();
				ClipboardTextRead clipboardTextRead = translationClipboard.ReadText(out string text);
				if (clipboardTextRead == ClipboardTextRead.Unavailable)
				{
					return TranslationWrite.Refuse(ClipboardUnavailableMessage);
				}
				bool hadText = clipboardTextRead == ClipboardTextRead.Text;
				if (!translationClipboard.TrySetText(sourceText))
				{
					RestoreClipboard(translationClipboard, hadText, text, translationClipboard.SequenceNumber);
					return TranslationWrite.Refuse(ClipboardUnavailableMessage);
				}
				uint sequenceNumber = translationClipboard.SequenceNumber;
				if (!_injector.TryReplaceExactTextBeforeCaret(writtenText, sourceText, () => _injector.SendControlShortcutWithoutActiveModifiers(86)))
				{
					RestoreClipboard(translationClipboard, hadText, text, sequenceNumber);
					return TranslationWrite.Refuse(UndoContradictedMessage);
				}
				translationWrite = ReadBack(sourceText, translation.Selection.CoversParagraph, TranslationWriteRoute.Clipboard, UnconfirmedRestoreMessage);
				if (!translationWrite.IsConfirmed)
				{
					Thread.Sleep(PasteSettleMilliseconds);
				}
				RestoreClipboard(translationClipboard, hadText, text, sequenceNumber);
				break;
			}
			default:
				return TranslationWrite.Refuse(UndoContradictedMessage);
			}
			translationWrite = translationWrite with
			{
				Route = translation.Route,
				WrittenText = sourceText
			};
			if (translationWrite.IsConfirmed && translation.DirectionSent)
			{
				return translationWrite with
				{
					DirectionSent = _injector.ApplyParagraphDirection(translation.SourceRightToLeft)
				};
			}
			return translationWrite;
		}

		private TranslationWrite ReadBack(string expectedWritten, bool coversParagraph, TranslationWriteRoute route, string unconfirmedDetail)
		{
			string text = Comparable(expectedWritten);
			int num = 0;
			for (int i = 0; i < ReadBackAttempts; i++)
			{
				if (i > 0)
				{
					Thread.Sleep(ReadBackDelayMilliseconds);
				}
				if (!((!coversParagraph) ? _injector.TryGetCurrentParagraphPrefixText(string.Empty, out string paragraphPrefix) : _injector.TryGetCurrentParagraphText(out paragraphPrefix)))
				{
					if (++num >= 2)
					{
						break;
					}
					continue;
				}
				string text2 = Comparable(paragraphPrefix);
				if (coversParagraph ? string.Equals(text2, text, StringComparison.Ordinal) : text2.EndsWith(text, StringComparison.Ordinal))
				{
					return new TranslationWrite(TranslationWriteOutcome.Confirmed, $"confirmed by read-back after {i + 1} read(s)")
					{
						Route = route,
						WrittenText = expectedWritten
					};
				}
			}
			return new TranslationWrite(TranslationWriteOutcome.Unconfirmed, unconfirmedDetail)
			{
				Route = route,
				WrittenText = expectedWritten
			};
		}

		private string? ReadSelectionThroughClipboard()
		{
			ITranslationClipboard translationClipboard = _clipboard();
			ClipboardTextRead clipboardTextRead = translationClipboard.ReadText(out string text);
			if (clipboardTextRead == ClipboardTextRead.Unavailable)
			{
				return null;
			}
			bool hadText = clipboardTextRead == ClipboardTextRead.Text;
			if (!translationClipboard.TryClear())
			{
				return null;
			}
			_injector.SendControlShortcutWithoutActiveModifiers(67);
			string result = string.Empty;
			for (int i = 0; i < ClipboardWaitAttempts; i++)
			{
				Thread.Sleep(ClipboardWaitStepMilliseconds);
				if (translationClipboard.TryGetText(out string text2) && text2.Length > 0)
				{
					result = text2;
					break;
				}
			}
			RestoreClipboard(translationClipboard, hadText, text, translationClipboard.SequenceNumber);
			return result;
		}

		private static void RestoreClipboard(ITranslationClipboard clipboard, bool hadText, string previous, uint placedSequence)
		{
			if (clipboard.SequenceNumber == placedSequence)
			{
				if (hadText)
				{
					clipboard.TrySetText(previous);
				}
				else
				{
					clipboard.TryClear();
				}
			}
		}

		private bool IdentitiesMatch(TranslationSelection selection)
		{
			return IdentitiesMatch(selection.TargetIdentity, selection.WindowIdentity);
		}

		private bool IdentitiesMatch(long target, long window)
		{
			if (target == _injector.GetForegroundTargetIdentity())
			{
				return window == _injector.GetForegroundWindowIdentity();
			}
			return false;
		}

		private static bool IsMultiLine(string text)
		{
			if (!text.Contains('\n'))
			{
				return text.Contains('\r');
			}
			return true;
		}

		private static string Comparable(string text)
		{
			return BidiControlCharacters.Remove(text).Replace('\u00a0', ' ').TrimEnd(new char[2] { '\r', '\n' });
		}
	}
	internal static class TranslationTextContract
	{
		public const int MaximumInputLength = 4000;

		public static string PrepareSource(string source)
		{
			return BidiControlCharacters.Remove(source);
		}

		public static string? ValidateAndNormalize(string source, string output)
		{
			if (string.IsNullOrWhiteSpace(output))
			{
				return null;
			}
			string text = StripCommonWrappers(source, output.Trim());
			if (text.Length == 0 || text.Length > 16000)
			{
				return null;
			}
			int num = source.Count((char character) => character == '\n');
			int num2 = text.Count((char character) => character == '\n');
			if (num != num2)
			{
				return null;
			}
			return PreserveOuterWhitespace(source, text);
		}

		private static string PreserveOuterWhitespace(string source, string translated)
		{
			int i;
			for (i = 0; i < source.Length && char.IsWhiteSpace(source[i]); i++)
			{
			}
			int num = source.Length;
			while (num > i && char.IsWhiteSpace(source[num - 1]))
			{
				num--;
			}
			return source.Substring(0, i) + translated.Trim() + source.Substring(num);
		}

		private static string StripCommonWrappers(string source, string value)
		{
			string text = source.Trim();
			if (value.StartsWith("```", StringComparison.Ordinal) && value.EndsWith("```", StringComparison.Ordinal) && !IsFenced(text))
			{
				int num = value.IndexOf('\n');
				if (num >= 0)
				{
					string text2 = value;
					int num2 = num + 1;
					value = text2.Substring(num2, text2.Length - 3 - num2).Trim();
				}
			}
			if (value.Length >= 2)
			{
				if (value[0] == '"')
				{
					string text3 = value;
					if (text3[text3.Length - 1] == '"')
					{
						goto IL_0099;
					}
				}
				if (value[0] == '\'')
				{
					string text4 = value;
					if (text4[text4.Length - 1] == '\'')
					{
						goto IL_0099;
					}
				}
			}
			goto IL_00c2;
			IL_0099:
			if (!IsQuotedWith(text, value[0]))
			{
				string text2 = value;
				value = text2.Substring(1, text2.Length - 1 - 1).Trim();
			}
			goto IL_00c2;
			IL_00c2:
			return value;
		}

		private static bool IsFenced(string text)
		{
			if (text.StartsWith("```", StringComparison.Ordinal))
			{
				return text.EndsWith("```", StringComparison.Ordinal);
			}
			return false;
		}

		private static bool IsQuotedWith(string text, char quote)
		{
			if (text.Length >= 2 && text[0] == quote)
			{
				return text[text.Length - 1] == quote;
			}
			return false;
		}
	}
	internal interface ITranslationCredentialStore
	{
		bool Exists();

		string? Read();

		bool Save(string credential);

		void Delete();
	}
	internal sealed class WindowsTranslationCredentialStore : ITranslationCredentialStore
	{
		[StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
		private struct NativeCredential
		{
			public uint Flags;

			public uint Type;

			public string TargetName;

			public string? Comment;

			public FILETIME LastWritten;

			public uint CredentialBlobSize;

			public nint CredentialBlob;

			public uint Persist;

			public uint AttributeCount;

			public nint Attributes;

			public string? TargetAlias;

			public string UserName;
		}

		private const string CredentialTarget = "CoCoTyping/AzureTranslator";

		private const uint CredTypeGeneric = 1u;

		private const uint CredPersistLocalMachine = 2u;

		private const int ErrorNotFound = 1168;

		public bool Exists()
		{
			if (!CredRead("CoCoTyping/AzureTranslator", 1u, 0u, out var credential))
			{
				if (Marshal.GetLastWin32Error() != 1168)
				{
					throw new Win32Exception(Marshal.GetLastWin32Error());
				}
				return false;
			}
			CredFree(credential);
			return true;
		}

		public string? Read()
		{
			if (!CredRead("CoCoTyping/AzureTranslator", 1u, 0u, out var credential))
			{
				if (Marshal.GetLastWin32Error() != 1168)
				{
					throw new Win32Exception(Marshal.GetLastWin32Error());
				}
				return null;
			}
			try
			{
				NativeCredential nativeCredential = Marshal.PtrToStructure<NativeCredential>(credential);
				if (nativeCredential.CredentialBlob == IntPtr.Zero || nativeCredential.CredentialBlobSize == 0)
				{
					return null;
				}
				byte[] array = new byte[nativeCredential.CredentialBlobSize];
				Marshal.Copy(nativeCredential.CredentialBlob, array, 0, array.Length);
				return Encoding.UTF8.GetString(array);
			}
			finally
			{
				CredFree(credential);
			}
		}

		public bool Save(string credential)
		{
			string text = credential.Trim();
			if (text.Length == 0)
			{
				return false;
			}
			byte[] bytes = Encoding.UTF8.GetBytes(text);
			nint num = Marshal.AllocHGlobal(bytes.Length);
			try
			{
				Marshal.Copy(bytes, 0, num, bytes.Length);
				NativeCredential credential2 = new NativeCredential
				{
					Type = 1u,
					TargetName = "CoCoTyping/AzureTranslator",
					CredentialBlobSize = (uint)bytes.Length,
					CredentialBlob = num,
					Persist = 2u,
					UserName = Environment.UserName
				};
				return CredWrite(ref credential2, 0u);
			}
			finally
			{
				for (int i = 0; i < bytes.Length; i++)
				{
					Marshal.WriteByte(num, i, 0);
				}
				Marshal.FreeHGlobal(num);
			}
		}

		public void Delete()
		{
			if (!CredDelete("CoCoTyping/AzureTranslator", 1u, 0u) && Marshal.GetLastWin32Error() != 1168)
			{
				throw new Win32Exception(Marshal.GetLastWin32Error());
			}
		}

		[DllImport("advapi32.dll", CharSet = CharSet.Unicode, EntryPoint = "CredReadW", SetLastError = true)]
		[return: MarshalAs(UnmanagedType.Bool)]
		private static extern bool CredRead(string target, uint type, uint flags, out nint credential);

		[DllImport("advapi32.dll", CharSet = CharSet.Unicode, EntryPoint = "CredWriteW", SetLastError = true)]
		[return: MarshalAs(UnmanagedType.Bool)]
		private static extern bool CredWrite(ref NativeCredential credential, uint flags);

		[DllImport("advapi32.dll", CharSet = CharSet.Unicode, EntryPoint = "CredDeleteW", SetLastError = true)]
		[return: MarshalAs(UnmanagedType.Bool)]
		private static extern bool CredDelete(string target, uint type, uint flags);

		[DllImport("advapi32.dll")]
		private static extern void CredFree(nint credential);
	}
