		public static string MessageFor(string code, string reason, string result)
		{
			switch (code)
			{
			case "no-selection":
				return SelectedWordOperation.Sentence(SelectedWordPlanner.SelectFirst);
			case "no-word":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.NoWordBeforeCaret);
			case "has-selection":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.TextIsSelected);
			case "too-long":
				return SelectedWordOperation.Sentence(SelectedWordPlanner.SelectOne);
			case "protected":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.ProtectedFieldNothingRead);
			case "read-only":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FieldReadOnly);
			case "composing":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FinishComposing);
			case "unsupported-field":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FieldUnsupported);
			case "unsupported-host":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.HostUnsupported);
			case "broker-timeout":
			case "broker-unavailable":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.BrokerNoAnswer);
			case "cancelled":
				return SelectedWordOperation.Cancelled;
			case "busy":
				return SelectedWordOperation.Busy;
			case "editor-refused":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.EditorRefusedChange);
			case "nothing-to-undo":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.NothingToUndoHere);
			case "edited-since":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.EditedSinceCorrection);
			case "other-field":
				return SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.OtherFieldCorrection);
			case "plan-refused":
				if (reason.Length > 0)
				{
					return SelectedWordOperation.Sentence(reason);
				}
				break;
			}
			return (result == "CancelledBeforeMutation") ? SelectedWordOperation.Cancelled : SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.NothingWasChanged);
		}

		private static string Num(ulong value)
		{
			return value.ToString(CultureInfo.InvariantCulture);
		}

		private static Dictionary<string, string> Reply(string type, params (string Key, string Value)[] fields)
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.Ordinal)
			{
				["v"] = "1",
