				(string Key, string Value) tuple = fields[i];
				string item = tuple.Key;
				string item2 = tuple.Value;
				dictionary[item] = item2;
			}
			return dictionary;
		}
	}
	internal sealed class TextServiceBroker : IDisposable
	{
		public const int MaxConnections = 16;

		private static readonly TimeSpan HelloTimeout = TimeSpan.FromSeconds(5L);

		private readonly ManualCorrectionCoordinator _coordinator;

		private readonly CancellationTokenSource _stop = new CancellationTokenSource();

		private readonly SemaphoreSlim _slots = new SemaphoreSlim(16, 16);

		private long _nextConnection;

		private Task? _accept;

		public string PipeName { get; }

		public string FullPipeName => "\\\\.\\pipe\\" + PipeName;

		public string Token { get; }

		public int ConnectionsAccepted { get; private set; }

		public string? LastAcceptError { get; private set; }

		public TextServiceBroker(ManualCorrectionCoordinator coordinator, string? pipeName = null, string? token = null)
		{
			_coordinator = coordinator;
			PipeName = pipeName ?? ("CoCoTyping.TextService.v1." + WindowsIdentity.GetCurrent().User.Value);
			Token = token ?? TextServicePublication.NewToken();
		}

		public void Start()
