						message.AppendFormatted(ex2.GetType().Name);
						message.AppendLiteral(": ");
						message.AppendFormatted(ex2.Message);
					}
					DiagnosticLog.Write("TextService", ref message);
					LastAcceptError = ex2.Message;
					await Task.Delay(500, _stop.Token).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
		}

		private async Task ServeAsync(NamedPipeServerStream pipe)
		{
			_ = 3;
			bool shouldAppend = default;
			try
			{
				using (pipe)
				{
					if (!GetNamedPipeClientProcessId(pipe.SafePipeHandle.DangerousGetHandle(), out var pid) || pid == 0)
					{
