					helloTimeout.CancelAfter(HelloTimeout);
					Dictionary<string, string> dictionary = await TextServiceWire.ReadAsync(pipe, helloTimeout.Token).ConfigureAwait(continueOnCapturedContext: false);
					if (dictionary == null || dictionary.GetValueOrDefault("type") != "hello" || !TokenMatches(dictionary.GetValueOrDefault("token")) || dictionary.GetValueOrDefault("pid") != pid.ToString(CultureInfo.InvariantCulture))
