						if (shouldAppend)
						{
							message.AppendLiteral("broker refused a client (pid ");
							message.AppendFormatted(pid);
							message.AppendLiteral("): bad hello");
						}
						DiagnosticLog.Write("TextService", ref message);
						return;
					}
					string executable = ExecutableOf((int)pid) ?? dictionary.GetValueOrDefault("exe") ?? string.Empty;
					TextServiceClient client = new TextServiceClient(Interlocked.Increment(ref _nextConnection), (int)pid, executable);
					string session = Convert.ToHexString(RandomNumberGenerator.GetBytes(16)).ToLowerInvariant();
					await TextServiceWire.WriteAsync(pipe, new Dictionary<string, string>
					{
						["v"] = "1",
						["type"] = "welcome",
						["session"] = session
					}, _stop.Token).ConfigureAwait(continueOnCapturedContext: false);
					DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(23, 2, out shouldAppend);
					if (shouldAppend)
					{
						message2.AppendLiteral("broker connected: pid ");
						message2.AppendFormatted(pid);
						message2.AppendLiteral(" ");
						message2.AppendFormatted(executable);
