			}
		}

		private bool TokenMatches(string? offered)
		{
			if (offered != null)
			{
				return CryptographicOperations.FixedTimeEquals(Encoding.ASCII.GetBytes(offered), Encoding.ASCII.GetBytes(Token));
			}
			return false;
		}

		private static string? ExecutableOf(int pid)
		{
			try
			{
				using Process process = Process.GetProcessById(pid);
				return System.IO.Path.GetFileName(process.MainModule?.FileName) ?? (process.ProcessName + ".exe");
			}
			catch (Exception ex) when ((ex is ArgumentException || ex is InvalidOperationException || ex is Win32Exception) ? true : false)
			{
				return null;
			}
		}

		[DllImport("kernel32.dll", SetLastError = true)]
		[return: MarshalAs(UnmanagedType.Bool)]
		private static extern bool GetNamedPipeClientProcessId(nint pipe, out uint clientProcessId);

		public void Dispose()
		{
			_stop.Cancel();
			try
			{
				_accept?.Wait(TimeSpan.FromSeconds(2L));
			}
			catch (AggregateException)
			{
			}
			_stop.Dispose();
		}
	}
	internal readonly record struct TextServiceChord(uint VirtualKey, uint Modifiers)
	{
		public bool IsValid
		{
			get
			{
				uint virtualKey = VirtualKey;
				if (virtualKey != 0 && virtualKey < 256 && (Modifiers & 0xFFFFFFF8u) == 0)
				{
					return (Modifiers & 3) != 0;
				}
				return false;
			}
		}
	}
	internal sealed record TextServicePublicationContent(int BrokerProcessId, string PipeName, string Token, long Revision, bool Enabled, IReadOnlyList<string> Hosts, TextServiceChord Convert, TextServiceChord Undo, TextServiceChord LastWord = default(TextServiceChord), bool DirectionMarksAreWordBoundary = false);
	internal sealed class TextServicePublication : IDisposable
	{
		public const string DisarmEventName = "Local\\CoCoTyping.TextService.Disarm";

		private readonly string _directory;

		private readonly EventWaitHandle _disarm;

		private bool _published;

		public string FilePath => System.IO.Path.Combine(_directory, "ARMED");

		public TextServicePublication(string? directory = null)
		{
			_directory = directory ?? System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "SmartInput", "TextService");
			_disarm = new EventWaitHandle(initialState: false, EventResetMode.ManualReset, "Local\\CoCoTyping.TextService.Disarm");
		}

		public static string NewToken()
		{
			return Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();
		}

		public static string Format(TextServicePublicationContent content, long stamp)
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.Ordinal)
			{
				["v"] = "1",
				["pid"] = content.BrokerProcessId.ToString(CultureInfo.InvariantCulture),
				["pipe"] = content.PipeName,
				["token"] = content.Token,
				["revision"] = content.Revision.ToString(CultureInfo.InvariantCulture),
				["enabled"] = (content.Enabled ? "1" : "0"),
				["hosts"] = string.Join('|', content.Hosts),
				["convertvk"] = content.Convert.VirtualKey.ToString(CultureInfo.InvariantCulture),
				["convertmods"] = content.Convert.Modifiers.ToString(CultureInfo.InvariantCulture),
				["undovk"] = content.Undo.VirtualKey.ToString(CultureInfo.InvariantCulture),
				["undomods"] = content.Undo.Modifiers.ToString(CultureInfo.InvariantCulture)
			};
			if (content.LastWord.IsValid)
			{
				dictionary["lastvk"] = content.LastWord.VirtualKey.ToString(CultureInfo.InvariantCulture);
				dictionary["lastmods"] = content.LastWord.Modifiers.ToString(CultureInfo.InvariantCulture);
			}
			if (content.DirectionMarksAreWordBoundary)
			{
				dictionary["markboundary"] = "1";
			}
			string text = Encoding.UTF8.GetString(TextServiceWire.Encode(dictionary) ?? throw new InvalidDataException("publication cannot be encoded"));
			return stamp.ToString(CultureInfo.InvariantCulture) + "\n" + text;
		}

		public void Publish(TextServicePublicationContent content)
		{
			Directory.CreateDirectory(_directory);
			if (!_published)
			{
				_disarm.Reset();
			}
			string text = System.IO.Path.Combine(_directory, $"ARMED.{Environment.ProcessId}.tmp");
			File.WriteAllText(text, Format(content, DateTime.UtcNow.ToFileTimeUtc()), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
			File.Move(text, FilePath, overwrite: true);
			_published = true;
		}

		public void Withdraw()
		{
			_disarm.Set();
			try
			{
				File.Delete(FilePath);
			}
			catch (IOException)
			{
			}
			catch (UnauthorizedAccessException)
			{
			}
			_published = false;
		}

		public void Dispose()
		{
			Withdraw();
			_disarm.Dispose();
		}
	}
