			BitConverter.TryWriteBytes(array2.AsSpan(0, 4), array.Length);
			array.CopyTo(array2, 4);
			await stream.WriteAsync(array2, token).ConfigureAwait(continueOnCapturedContext: false);
			await stream.FlushAsync(token).ConfigureAwait(continueOnCapturedContext: false);
		}

		public static async Task<Dictionary<string, string>?> ReadAsync(Stream stream, CancellationToken token)
		{
			byte[] head = new byte[4];
			if (!(await ReadExactlyAsync(stream, head, token).ConfigureAwait(continueOnCapturedContext: false)))
			{
				return null;
			}
			int num = BitConverter.ToInt32(head, 0);
			if (num <= 0 || num > 16384)
			{
				return null;
			}
			byte[] payload = new byte[num];
			if (!(await ReadExactlyAsync(stream, payload, token).ConfigureAwait(continueOnCapturedContext: false)))
			{
				return null;
			}
			Dictionary<string, string> dictionary = Decode(payload);
			string value;
			return (dictionary != null && dictionary.TryGetValue("v", out value) && value == "1") ? dictionary : null;
		}

		private static async Task<bool> ReadExactlyAsync(Stream stream, byte[] buffer, CancellationToken token)
		{
			int num;
			for (int done = 0; done < buffer.Length; done += num)
			{
				num = await stream.ReadAsync(buffer.AsMemory(done), token).ConfigureAwait(continueOnCapturedContext: false);
				if (num == 0)
				{
					return false;
				}
			}
			return true;
		}

		public static bool ValidKey(string key)
		{
			int length = key.Length;
			if (length > 0 && length <= 32)
			{
				return key.All((char c) => c >= 'a' && c <= 'z');
			}
			return false;
		}

		public static string Escape(string value)
		{
			StringBuilder stringBuilder = new StringBuilder(value.Length);
			for (int i = 0; i < value.Length; i++)
			{
				char c = value[i];
				StringBuilder stringBuilder2 = stringBuilder;
				stringBuilder2.Append(c switch
				{
					'%' => "%25", 
					'\n' => "%0A", 
					'\r' => "%0D", 
					'=' => "%3D", 
					_ => c.ToString(), 
				});
			}
			return stringBuilder.ToString();
		}

		public static string? Unescape(string value)
		{
			StringBuilder stringBuilder = new StringBuilder(value.Length);
			for (int i = 0; i < value.Length; i++)
			{
				if (value[i] != '%')
				{
					stringBuilder.Append(value[i]);
					continue;
				}
				if (i + 2 >= value.Length)
				{
					return null;
				}
				char c = value.Substring(i + 1, 2) switch
				{
					"25" => '%', 
					"0A" => '\n', 
					"0D" => '\r', 
					"3D" => '=', 
					_ => '\0', 
				};
				if (c == '\0')
				{
					return null;
				}
				stringBuilder.Append(c);
				i += 2;
			}
			return stringBuilder.ToString();
		}
	}
