	internal sealed class ManualTypingMode(Func<AppSettings> settings, Func<AutoCorrectionEngineStack> engine, ForegroundLayoutService layoutService, Func<PersianKeyboardLayout> mappingLayout, Func<bool?>? targetRestricted = null, Func<bool>? environmentRestricts = null, Func<IInputInjector>? injector = null, Func<bool>? editorLosesUnicodeBatches = null)
