			{
				_rightToLeftOpen = value;
			}
		}

		internal bool CapitalPending => _capitalPending;

		internal void NoteEnglishKeyUnderHold(int virtualKey)
		{
			_capitalPending = false;
			if (virtualKey != 8)
			{
				_currentWordIsPersian = false;
			}
		}

		public void Reset()
		{
			_wordIsEnglish = false;
			_rightToLeftOpen = false;
			_wordRestricted = null;
			_currentWordIsPersian = false;
			_capitalPending = false;
		}

		public bool HandleKeyDown(int virtualKey, bool shiftDown, bool controlDown, bool altDown, bool windowsDown, bool persianTypingDirect = false)
		{
			if (controlDown | altDown | windowsDown)
			{
				Reset();
				return false;
			}
			bool shouldAppend;
			if (EndsWord(virtualKey))
			{
				shouldAppend = ((virtualKey == 9 || virtualKey == 13) ? true : false);
				if (shouldAppend)
				{
					_rightToLeftOpen = false;
				}
				_capitalPending = virtualKey == 32 && _currentWordIsPersian;
				_currentWordIsPersian = false;
				if (_capitalPending)
				{
					DiagnosticLog.Write("Manual", "Previous word Persian: capital pending for the next held letter.");
				}
				_wordRestricted = null;
				return false;
			}
			if (virtualKey == 8)
			{
				_capitalPending = false;
				return false;
			}
			if (_wordIsEnglish || !IsEnglishLayoutActive())
			{
				_capitalPending = false;
				_currentWordIsPersian = false;
				return false;
			}
			if (!EnglishUsKeyRenderer.TryCreateStroke(virtualKey, shiftDown, out var stroke))
			{
				Reset();
				return false;
			}
			bool? flag = _wordRestricted ?? ((targetRestricted == null) ? new bool?(false) : targetRestricted());
			if (flag.HasValue)
			{
				bool valueOrDefault = flag == true;
				_wordRestricted = valueOrDefault;
			}
			Func<bool>? func = environmentRestricts;
			if (func == null || !func())
			{
				bool? flag2 = flag;
				shouldAppend = false;
				if (flag2 == shouldAppend)
				{
					if (!TryConvertOneKey(stroke, out string persian) && (!persianTypingDirect || !TryGetShiftedLayoutCharacter(stroke, out persian)))
					{
						_capitalPending = false;
						_currentWordIsPersian = false;
						return false;
					}
					string text = OpenRightToLeftRunIfNeeded(persian);
					if (!(injector?.Invoke() ?? engine().Injector).SendUnicodeText(text))
					{
						return false;
					}
					_currentWordIsPersian = true;
					_capitalPending = false;
					DiagnosticMessageHandler message = new DiagnosticMessageHandler(53, 2, out shouldAppend);
					if (shouldAppend)
					{
						message.AppendLiteral("Typed '");
						message.AppendFormatted(stroke.SourceCharacter);
						message.AppendLiteral("' as '");
						message.AppendFormatted(persian);
						message.AppendLiteral("' directly; nothing was read or deleted.");
					}
					DiagnosticLog.Write("Manual", ref message);
					return true;
				}
			}
			DiagnosticLog.Write("Manual", "A key was left as typed: this field is protected or English-only.");
			_capitalPending = false;
			_currentWordIsPersian = false;
			return false;
		}

		private bool TryConvertOneKey(BufferedKeyStroke stroke, out string persian)
		{
			persian = string.Empty;
			if (TryGetPersianProsePunctuation(stroke, mappingLayout(), out var mark))
			{
				persian = mark.ToString();
				return true;
			}
			KeyboardLayoutSnapshot activeLayout = layoutService.GetActiveLayout();
			if (!engine().Conversion.TryConvert(new BufferedToken(new <>z__ReadOnlySingleElementList<BufferedKeyStroke>(stroke), StartsSentence: false), activeLayout, mappingLayout(), settings().Correction, PersianConversionTrigger.Forced, 0, allowSingleCharacterTarget: true, out PersianConversion conversion))
			{
				return false;
			}
			if (!conversion.Target.Any((char character) => IsPersianLetter(character) || character == '\u200c'))
			{
				return false;
			}
			persian = conversion.Target;
			return true;
		}

		private bool TryGetShiftedLayoutCharacter(BufferedKeyStroke stroke, out string output)
		{
			output = string.Empty;
			AppSettings appSettings = settings();
			if (!stroke.ShiftDown || !appSettings.Correction.DirectTypingTypesAllLayoutCharacters || appSettings.General.TypingMode != TypingMode.ManualCorrection)
			{
				return false;
			}
			string text = null;
			foreach (KeyboardLayoutDefinition persianTarget in KeyboardLayoutRegistry.GetPersianTargets(mappingLayout()))
			{
				string text2 = persianTarget.MapKey(stroke.VirtualKey, KeyModifiers.Shift);
				if (string.IsNullOrEmpty(text2) || (text != null && !string.Equals(text, text2, StringComparison.Ordinal)))
				{
					return false;
				}
				text = text2;
			}
			if (text != null)
			{
				if (text != null && text.Length == 1)
				{
					char c = text[0];
					if (IsPersianLetter(c) || c == '\u200c')
					{
						goto IL_0104;
					}
				}
				if (!text.Any((char character) => char.GetUnicodeCategory(character) == UnicodeCategory.Format) && !(text == stroke.SourceCharacter.ToString()))
				{
					output = text;
					DiagnosticLog.Write("Manual", "Shift+key typed from the Persian layout definition (DirectTypingTypesAllLayoutCharacters).");
					return true;
				}
			}
			goto IL_0104;
			IL_0104:
			return false;
		}

		private static bool TryGetPersianProsePunctuation(BufferedKeyStroke stroke, PersianKeyboardLayout setting, out char mark)
		{
			mark = '\0';
			KeyModifiers modifiers = (stroke.ShiftDown ? KeyModifiers.Shift : KeyModifiers.None);
			char c = default;
			foreach (KeyboardLayoutDefinition persianTarget in KeyboardLayoutRegistry.GetPersianTargets(setting))
			{
				string text = persianTarget.MapKey(stroke.VirtualKey, modifiers);
				int num;
				if (text != null && text.Length == 1)
				{
					c = text[0];
					num = 1;
				}
				else
				{
					num = 0;
				}
				bool flag = num == 0;
				if (!flag)
				{
					bool flag2 = ((c == '،' || c == '؛' || c == '؟') ? true : false);
					flag = !flag2;
				}
				if (flag || (mark != '\0' && mark != c))
				{
					mark = '\0';
					return false;
				}
				mark = c;
			}
			return mark != '\0';
		}

		private static bool IsPersianLetter(char character)
		{
			if (character >= '\u0600' && character <= 'ۿ')
			{
				return char.IsLetter(character);
			}
			return false;
		}

		private string OpenRightToLeftRunIfNeeded(string persian)
		{
			CorrectionSettings correction = settings().Correction;
			if (_rightToLeftOpen || !correction.StabilizeMixedDirectionText)
			{
				return persian;
			}
			Func<bool>? func = editorLosesUnicodeBatches;
			if (func != null && func())
			{
				return persian;
			}
			_rightToLeftOpen = true;
			if (!correction.ParagraphDirectionPrefix)
			{
				return BidiControlCharacters.StartRightToLeftEmbedding(persian);
			}
			return ParagraphDirectionPolicy.Mark(persian);
		}

		private bool IsEnglishLayoutActive()
		{
			return layoutService.GetActiveLayout().Language == ActiveLanguage.English;
		}

		internal static bool EndsWord(int virtualKey)
		{
			if (virtualKey == 9 || virtualKey == 13 || virtualKey == 32)
			{
				return true;
			}
			return false;
		}
	}
