	internal sealed record AutoCorrectionEngineStack(TypingEngine Engine, IDetectionEngine Detection, IPhysicalKeyTranslator Translator, IPersianConversionEngine Conversion, IInputInjector Injector)
	{
		public string DisplayName
		{
			get
