		public bool SupportsReopenOnBackspace => Engine == TypingEngine.Smart;

		public static AutoCorrectionEngineStack Create(TypingEngine engine, LexiconStore lexicon, IInputInjector? injector = null)
		{
			if (engine != TypingEngine.Classic)
			{
				return CreateSmart(lexicon, injector);
			}
			return CreateClassic(lexicon, injector);
		}

		private static AutoCorrectionEngineStack CreateClassic(LexiconStore lexicon, IInputInjector? injector)
		{
			ClassicDetectionEngine classicDetectionEngine = new ClassicDetectionEngine(lexicon, new TechnicalPatternDetector());
			ClassicPhysicalKeyTranslator translator = new ClassicPhysicalKeyTranslator();
			return new AutoCorrectionEngineStack(TypingEngine.Classic, classicDetectionEngine, translator, new ClassicPersianConversionEngine(translator, classicDetectionEngine, lexicon), injector ?? new ClassicInputInjector());
		}

		private static AutoCorrectionEngineStack CreateSmart(LexiconStore lexicon, IInputInjector? injector)
		{
			SmartDetectionEngine smartDetectionEngine = new SmartDetectionEngine(lexicon, new TechnicalPatternDetector());
			PhysicalKeyTranslator translator = new PhysicalKeyTranslator();
			return new AutoCorrectionEngineStack(TypingEngine.Smart, smartDetectionEngine, translator, new PersianConversionEngine(translator, smartDetectionEngine, lexicon), injector ?? new InputInjector());
		}
	}
