		private readonly ClassicPhysicalKeyTranslator _translator;

		private readonly ClassicDetectionEngine _detectionEngine;

		private readonly LexiconStore _lexiconStore;

		private readonly PersianTypoCorrector _typoCorrector;

		private readonly TechnicalPatternDetector _technicalPatterns = new TechnicalPatternDetector();

		public ClassicPersianConversionEngine(ClassicPhysicalKeyTranslator translator, ClassicDetectionEngine detectionEngine, LexiconStore lexiconStore)
		{
			_translator = translator;
			_detectionEngine = detectionEngine;
			_lexiconStore = lexiconStore;
			_typoCorrector = new PersianTypoCorrector(lexiconStore);
		}

		public bool TryConvert(BufferedToken token, KeyboardLayoutSnapshot sourceLayout, PersianKeyboardLayout persianKeyboardLayout, CorrectionSettings settings, PersianConversionTrigger trigger, int persianContextScore, bool allowSingleCharacterTarget, out PersianConversion conversion, bool allowUnknownPersianTarget = false, bool previousWordIsPersian = false, int persianWordsInParagraph = 0, int englishWordsInParagraph = 0, bool wordBeforePreviousIsPersian = false, string? previousWordText = null, bool allowPersianDigits = false)
		{
			conversion = null;
			if (!_translator.TryGetCandidates(token, sourceLayout, persianKeyboardLayout, out IReadOnlyList<PhysicalTranslationCandidate> candidates))
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(57, 1, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("Decision: keep as typed (no Persian mapping for ");
					message.AppendFormatted(token.Count);
					message.AppendLiteral(" key(s)).");
				}
				DiagnosticLog.Write("Engine", ref message);
				return false;
			}
			return TrySelectCandidate(candidates, settings, trigger, persianContextScore, allowSingleCharacterTarget, out conversion, allowUnknownPersianTarget);
		}

		public string? ConvertEnglishVisibleText(string text, PersianKeyboardLayout persianKeyboardLayout, CorrectionSettings settings, bool protectKnownEnglish)
		{
			return ConvertEnglishVisibleTextWithDetails(text, persianKeyboardLayout, settings, protectKnownEnglish)?.Text;
		}

		public VisibleTextConversionResult? ConvertEnglishVisibleTextWithDetails(string text, PersianKeyboardLayout persianKeyboardLayout, CorrectionSettings settings, bool protectKnownEnglish)
		{
			if (string.IsNullOrWhiteSpace(text))
			{
				return null;
			}
			StringBuilder stringBuilder = null;
			List<PersianConversion> list = null;
			int num = -1;
			bool flag = false;
			for (int i = 0; i <= text.Length; i++)
			{
				if (i < text.Length && num < 0 && (i == 0 || char.IsWhiteSpace(text[i - 1])))
				{
					int j;
					for (j = i; j < text.Length && !char.IsWhiteSpace(text[j]); j++)
					{
					}
					int num2 = i;
					string text2 = text.Substring(num2, j - num2);
					if (_technicalPatterns.IsSourceProtectionPattern(text2))
					{
						stringBuilder?.Append(text2);
						i = j - 1;
						flag = false;
						continue;
					}
				}
				if (i < text.Length && (IsEnglishPhysicalKeyWordCharacter(text[i], persianKeyboardLayout) || (settings.CorrectPersianTypos && PersianTypoCorrector.IsPersianLetter(text[i]))))
				{
					num = ((num < 0) ? i : num);
					continue;
				}
				if (num >= 0)
				{
					int num2 = num;
					string text3 = text.Substring(num2, i - num2);
					VisibleRunConversion visibleRunConversion = TryConvertVisibleRun(text3, persianKeyboardLayout, settings, protectKnownEnglish);
					if ((object)visibleRunConversion != null)
					{
						if (stringBuilder == null)
						{
							stringBuilder = new StringBuilder(text.Length + 8).Append(text, 0, num);
						}
						stringBuilder.Append(visibleRunConversion.Text);
						if (list == null)
						{
							list = new List<PersianConversion>();
						}
						list.Add(visibleRunConversion.Conversion);
						flag = true;
					}
					else
					{
						stringBuilder?.Append(text3);
						flag = false;
					}
					num = -1;
				}
				if (i >= text.Length)
				{
					break;
				}
				char c = text[i];
				if (stringBuilder != null)
				{
					if (flag && PersianPunctuation.TryLocalize(c, out var localized))
					{
						stringBuilder.Append(localized);
					}
					else
					{
						stringBuilder.Append(c);
					}
				}
				if (char.IsWhiteSpace(c))
				{
					flag = false;
				}
			}
			if (stringBuilder != null && list != null)
			{
				return new VisibleTextConversionResult(stringBuilder.ToString(), list);
			}
			return null;
