		public bool TryToggleVisibleText(string text, PersianKeyboardLayout persianKeyboardLayout, CorrectionSettings settings, out string converted)
		{
			converted = string.Empty;
			int num = text.Count(IsPersianCharacter);
			int num2 = text.Count(IsLatinCharacter);
			if (num > num2)
			{
				return _translator.TryToggleVisibleText(text, persianKeyboardLayout, out converted);
			}
			converted = ConvertEnglishVisibleText(text, persianKeyboardLayout, settings, protectKnownEnglish: false) ?? string.Empty;
			return converted.Length > 0;
		}

		private VisibleRunConversion? TryConvertVisibleRun(string source, PersianKeyboardLayout persianKeyboardLayout, CorrectionSettings settings, bool protectKnownEnglish)
		{
			var (text, text2, text3) = SplitPairedWrappers(source);
			if (settings.CorrectPersianTypos && text2.Length > 0 && text2.All(PersianTypoCorrector.IsPersianLetter))
			{
				if (!_typoCorrector.TryCorrect(text2, out string corrected))
				{
					return null;
				}
				return new VisibleRunConversion(text + corrected + text3, new PersianConversion(text2, corrected, text2, corrected));
			}
			if (protectKnownEnglish && IsKnownEnglishToken(text2))
			{
				return null;
			}
			if (!_translator.TryGetVisibleCandidates(text2, persianKeyboardLayout, out IReadOnlyList<PhysicalTranslationCandidate> candidates) || !TrySelectCandidate(candidates, settings, PersianConversionTrigger.Forced, 0, allowSingleCharacterTarget: true, out PersianConversion conversion))
			{
				return null;
			}
			return new VisibleRunConversion(text + conversion.Target + text3, conversion);
		}

		private static (string Prefix, string Core, string Suffix) SplitPairedWrappers(string token)
		{
			if (token.Length >= 3)
			{
