			}
			return shiftedWordMap.TryGetValue(stroke.VirtualKey, out persian);
		}

		private static bool IsShiftedPersianWordCharacter(BufferedKeyStroke stroke, IReadOnlyDictionary<int, char> shiftedWordMap)
		{
