			IReadOnlyDictionary<int, char> readOnlyDictionary = ((persianKeyboardLayout == PersianKeyboardLayout.Persian) ? PersianLegacyMap : PersianStandardMap);
			foreach (int key2 in readOnlyDictionary.Keys)
