				if (EnglishUsKeyRenderer.TryCreateStroke(key2, shiftDown: false, out var stroke))
				{
					char value = readOnlyDictionary[key2];
					dictionary[stroke.SourceCharacter] = value;
					dictionary[char.ToUpperInvariant(stroke.SourceCharacter)] = value;
				}
			}
			int key;
			char value2;
			foreach (KeyValuePair<int, char> item in GetShiftedWordMap(persianKeyboardLayout))
			{
				item.Deconstruct(out key, out value2);
				int virtualKey = key;
				char value3 = value2;
				if (EnglishUsKeyRenderer.TryCreateStroke(virtualKey, shiftDown: true, out var stroke2))
				{
					dictionary[stroke2.SourceCharacter] = value3;
				}
			}
			if (persianKeyboardLayout != PersianKeyboardLayout.Automatic)
			{
				return dictionary;
			}
			foreach (KeyValuePair<int, char> item2 in PersianLegacyMap)
			{
				item2.Deconstruct(out key, out value2);
				int num = key;
				char value4 = value2;
				if (!PersianStandardMap.ContainsKey(num) && EnglishUsKeyRenderer.TryCreateStroke(num, shiftDown: false, out var stroke3))
				{
					dictionary[stroke3.SourceCharacter] = value4;
				}
			}
			return dictionary;
		}

		private static IReadOnlyDictionary<char, char> BuildPersianToEnglishCharMap(PersianKeyboardLayout persianKeyboardLayout)
		{
