			foreach (KeyValuePair<int, char> item in GetShiftedWordMap(persianKeyboardLayout))
			{
				item.Deconstruct(out key, out value);
				int virtualKey = key;
				char key2 = value;
				if (EnglishUsKeyRenderer.TryCreateStroke(virtualKey, shiftDown: true, out var stroke))
				{
					dictionary[key2] = stroke.SourceCharacter;
				}
			}
			foreach (KeyValuePair<int, char> item2 in (persianKeyboardLayout == PersianKeyboardLayout.Persian) ? PersianLegacyMap : PersianStandardMap)
			{
				item2.Deconstruct(out key, out value);
				int virtualKey2 = key;
				char key3 = value;
				if (EnglishUsKeyRenderer.TryCreateStroke(virtualKey2, shiftDown: false, out var stroke2))
				{
					dictionary[key3] = stroke2.SourceCharacter;
				}
			}
			return dictionary;
		}

		private static bool IsLatinCharacter(char ch)
		{
			switch (ch)
			{
			case 'A':
			case 'B':
			case 'C':
			case 'D':
			case 'E':
			case 'F':
			case 'G':
