	internal sealed class ApplicationFontBackupStore
	{
		private sealed class ApplicationFontBackupDocument
		{
			public int SchemaVersion { get; set; } = 2;

			public Dictionary<string, Dictionary<string, Dictionary<string, string?>>> Targets { get; init; } = new Dictionary<string, Dictionary<string, Dictionary<string, string>>>(StringComparer.OrdinalIgnoreCase);

			public Dictionary<string, string> AppliedFonts { get; init; } = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

			public Dictionary<string, DateTimeOffset> AppliedAt { get; init; } = new Dictionary<string, DateTimeOffset>(StringComparer.OrdinalIgnoreCase);
		}

		private static readonly JsonSerializerOptions SerializerOptions = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			WriteIndented = true
		};

		private readonly string _filePath;

		private ApplicationFontBackupDocument? _document;

		private const int CurrentSchemaVersion = 2;

		public ApplicationFontBackupStore(string? settingsDirectoryPath = null)
		{
			string text = settingsDirectoryPath ?? Environment.GetEnvironmentVariable("SMARTINPUT_SETTINGS_DIRECTORY");
			string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
			_filePath = System.IO.Path.Combine(string.IsNullOrWhiteSpace(text) ? System.IO.Path.Combine(folderPath, "SmartInput") : text, "application-font-backups.json");
		}

		public IReadOnlyDictionary<string, string?> GetOrAdd(string targetId, string itemId, Func<IReadOnlyDictionary<string, string?>> createValues)
		{
			ApplicationFontBackupDocument applicationFontBackupDocument = Load();
			if (!applicationFontBackupDocument.Targets.TryGetValue(targetId, out Dictionary<string, Dictionary<string, string>> value))
			{
				value = new Dictionary<string, Dictionary<string, string>>(StringComparer.OrdinalIgnoreCase);
				applicationFontBackupDocument.Targets[targetId] = value;
			}
			if (value.TryGetValue(itemId, out var value2))
			{
				return value2;
			}
			Dictionary<string, string> result = (value[itemId] = new Dictionary<string, string>(createValues(), StringComparer.Ordinal));
			Save();
			return result;
		}

		public IReadOnlyDictionary<string, Dictionary<string, string?>> GetTarget(string targetId)
		{
			if (!Load().Targets.TryGetValue(targetId, out Dictionary<string, Dictionary<string, string>> value))
			{
				return new Dictionary<string, Dictionary<string, string>>();
			}
			return value;
		}

		public string? GetAppliedFont(string targetId)
		{
			return Load().AppliedFonts.GetValueOrDefault(targetId);
		}

		public DateTimeOffset? GetAppliedAt(string targetId)
		{
			if (!Load().AppliedAt.TryGetValue(targetId, out var value))
			{
				return null;
			}
			return value;
		}

		public bool WasApplied(string targetId, string fontFamily)
		{
			if (!string.IsNullOrWhiteSpace(fontFamily))
			{
				return string.Equals(GetAppliedFont(targetId), fontFamily, StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		public void SetAppliedFont(string targetId, string fontFamily)
		{
			ApplicationFontBackupDocument applicationFontBackupDocument = Load();
			applicationFontBackupDocument.AppliedFonts[targetId] = fontFamily;
			applicationFontBackupDocument.AppliedAt[targetId] = DateTimeOffset.UtcNow;
			applicationFontBackupDocument.SchemaVersion = 2;
			Save();
		}

		public void ClearTarget(string targetId)
		{
			ApplicationFontBackupDocument applicationFontBackupDocument = Load();
			applicationFontBackupDocument.Targets.Remove(targetId);
			applicationFontBackupDocument.AppliedFonts.Remove(targetId);
			applicationFontBackupDocument.AppliedAt.Remove(targetId);
			Save();
		}

		private ApplicationFontBackupDocument Load()
		{
			if (_document != null)
			{
				return _document;
			}
			try
			{
				_document = (File.Exists(_filePath) ? JsonSerializer.Deserialize<ApplicationFontBackupDocument>(File.ReadAllText(_filePath), SerializerOptions) : null);
			}
			catch
			{
				_document = null;
			}
			if (_document == null)
			{
				_document = new ApplicationFontBackupDocument();
			}
			return _document;
		}

		private void Save()
		{
			Directory.CreateDirectory(System.IO.Path.GetDirectoryName(_filePath) ?? throw new InvalidOperationException("The application font backup path has no directory."));
			string text = _filePath + ".tmp";
			File.WriteAllText(text, JsonSerializer.Serialize(Load(), SerializerOptions));
			File.Move(text, _filePath, overwrite: true);
		}
	}
