		public Task<IReadOnlyList<ApplicationFontTargetInfo>> InspectAsync(string fontFamily, bool thorough = false)
		{
			return Task.Run((Func<IReadOnlyList<ApplicationFontTargetInfo>>)(() =>
			{
				FontCheck font = CheckFont(fontFamily);
				ApplicationFontTargetInfo[] array = _adapters.Select((IApplicationFontAdapter adapter) => SafeInspect(adapter, font, thorough)).ToArray();
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(47, 4, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("inspect font=\"");
					message.AppendFormatted(fontFamily);
					message.AppendLiteral("\" installed=");
					message.AppendFormatted(font.Installed);
					message.AppendLiteral(" thorough=");
					message.AppendFormatted(thorough);
					message.AppendLiteral(" targets=[");
					message.AppendFormatted(string.Join(", ", from result in array
						where result.IsInstalled
						select $"{result.Id}:{result.State}"));
					message.AppendLiteral("]");
				}
				Log(ref message);
				return array;
			}));
		}

		public Task<IReadOnlyList<ApplicationFontTargetInfo>> ApplyAsync(IEnumerable<string> targetIds, string fontFamily)
		{
			HashSet<string> selected = targetIds.ToHashSet(StringComparer.OrdinalIgnoreCase);
			return Task.Run((Func<IReadOnlyList<ApplicationFontTargetInfo>>)(() =>
			{
				FontCheck font = CheckFont(fontFamily);
				return (from adapter in _adapters
					where selected.Contains(adapter.Id)
					select SafeOperation(adapter, "apply", fontFamily, (IApplicationFontAdapter current) => (!font.Installed) ? WithFontCheck(current.Inspect(fontFamily), font) : current.Apply(fontFamily))).ToArray();
			}));
		}

