					if ((!System.IO.Path.IsPathRooted(executable) || File.Exists(executable)) && _launch(executable, absoluteUri))
					{
						DiagnosticMessageHandler message = new DiagnosticMessageHandler(31, 3, out shouldAppend);
						if (shouldAppend)
						{
							message.AppendLiteral("check target=");
							message.AppendFormatted(targetId);
							message.AppendLiteral(" font=\"");
							message.AppendFormatted(fontFamily);
							message.AppendLiteral("\" opened=\"");
							message.AppendFormatted(System.IO.Path.GetFileName(executable));
							message.AppendLiteral("\"");
						}
						Log(ref message);
						shouldAppend = true;
						return shouldAppend;
					}
				}
				DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(57, 2, out shouldAppend2);
				if (shouldAppend2)
				{
					message2.AppendLiteral("check target=");
					message2.AppendFormatted(targetId);
					message2.AppendLiteral(" font=\"");
					message2.AppendFormatted(fontFamily);
					message2.AppendLiteral("\" opened=none (no executable started)");
