		private FontCheck CheckFont(string fontFamily)
		{
			bool flag = _isFontInstalled(fontFamily);
			string alternative = ((!flag && !string.IsNullOrWhiteSpace(fontFamily) && _isFontInstalled(fontFamily + " FD")) ? (fontFamily + " FD") : null);
			return new FontCheck(fontFamily, flag, alternative);
		}

		private static ApplicationFontTargetInfo WithFontCheck(ApplicationFontTargetInfo info, FontCheck font)
		{
			bool flag = font.Installed || !info.IsInstalled;
			ApplicationFontTargetState state;
			if (!flag)
			{
				state = info.State;
				bool flag2 = (uint)(state - 4) <= 2u;
				flag = flag2;
			}
			if (flag)
			{
				return info;
			}
			state = info.State;
			flag = ((state == ApplicationFontTargetState.Applied || (uint)(state - 7) <= 1u) ? true : false);
			bool flag3 = flag;
			string alternative = font.Alternative;
			string status = ((alternative != null) ? SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusFontNotInstalledUse, font.Family, alternative) : SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusFontNotInstalled, font.Family));
			return info with
			{
				CanApply = (info.CanApply & flag3),
				State = ApplicationFontTargetState.FontNotInstalled,
				Status = status
			};
		}

		private static ApplicationFontTargetInfo SafeInspect(IApplicationFontAdapter adapter, FontCheck font, bool thorough)
		{
			try
			{
				return WithFontCheck(adapter.Inspect(font.Family, thorough), font);
			}
			catch (Exception ex)
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(34, 3, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("failed target=");
					message.AppendFormatted(adapter.Id);
					message.AppendLiteral(" op=inspect error=");
					message.AppendFormatted(ex.GetType().Name);
					message.AppendLiteral(": ");
					message.AppendFormatted(ex.Message);
				}
				Log(ref message);
				return Failed(adapter.Id);
			}
		}

