		private static Dictionary<string, FontCheckLauncher> CreateFontChecks(string localAppData)
		{
			string[] roots = new string[3]
			{
				Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),
				Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),
				localAppData
			};
			return new Dictionary<string, FontCheckLauncher>(StringComparer.OrdinalIgnoreCase)
			{
				["edge"] = Launcher("Microsoft Edge", System.IO.Path.Combine("Microsoft", "Edge", "Application", "msedge.exe"), "msedge.exe"),
				["edge-beta"] = Launcher("Microsoft Edge Beta", System.IO.Path.Combine("Microsoft", "Edge Beta", "Application", "msedge.exe")),
