				["edge-canary"] = Launcher("Microsoft Edge Canary", System.IO.Path.Combine("Microsoft", "Edge SxS", "Application", "msedge.exe")),
				["chrome"] = Launcher("Google Chrome", System.IO.Path.Combine("Google", "Chrome", "Application", "chrome.exe"), "chrome.exe"),
				["chrome-beta"] = Launcher("Google Chrome Beta", System.IO.Path.Combine("Google", "Chrome Beta", "Application", "chrome.exe")),
				["chrome-dev"] = Launcher("Google Chrome Dev", System.IO.Path.Combine("Google", "Chrome Dev", "Application", "chrome.exe")),
				["chrome-canary"] = Launcher("Google Chrome Canary", System.IO.Path.Combine("Google", "Chrome SxS", "Application", "chrome.exe")),
				["brave"] = Launcher("Brave", System.IO.Path.Combine("BraveSoftware", "Brave-Browser", "Application", "brave.exe"), "brave.exe"),
				["vivaldi"] = Launcher("Vivaldi", System.IO.Path.Combine("Vivaldi", "Application", "vivaldi.exe"), "vivaldi.exe"),
				["opera"] = Launcher("Opera", System.IO.Path.Combine("Programs", "Opera", "opera.exe"), "opera.exe"),
				["firefox"] = Launcher("Mozilla Firefox", System.IO.Path.Combine("Mozilla Firefox", "firefox.exe"), "firefox.exe")
			};
			FontCheckLauncher Launcher(string displayName, string relativePath, string? appPath = null)
			{
				IEnumerable<string> first = from root in roots
					where !string.IsNullOrEmpty(root)
					select System.IO.Path.Combine(root, relativePath);
				IEnumerable<string> second;
				if (appPath != null)
				{
					IEnumerable<string> enumerable = new <>z__ReadOnlySingleElementList<string>(appPath);
					second = enumerable;
				}
				else
				{
					IEnumerable<string> enumerable = Array.Empty<string>();
