		private static bool Launch(string executable, string address)
		{
			try
			{
				using (Process.Start(new ProcessStartInfo(executable, "\"" + address + "\"")
				{
					UseShellExecute = true
				}))
				{
					return true;
				}
			}
			catch (Exception ex) when ((ex is Win32Exception || ex is InvalidOperationException || ex is FileNotFoundException) ? true : false)
			{
				return false;
			}
		}

		private static List<(Process Process, bool PathKnown)> FindProcesses(string processName, string? installFolder)
		{
			int value = CurrentSession.Value;
			List<(Process, bool)> list = new List<(Process, bool)>();
			Process[] processesByName = Process.GetProcessesByName(processName);
			foreach (Process process in processesByName)
			{
				bool flag = true;
				bool item = true;
				try
				{
					flag = process.SessionId == value;
				}
				catch
				{
				}
				if (flag && installFolder != null)
				{
					try
					{
						string text = process.MainModule?.FileName;
						item = text != null;
						flag = text?.Contains(System.IO.Path.DirectorySeparatorChar + installFolder + System.IO.Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) ?? true;
					}
					catch
					{
						item = false;
					}
				}
				if (flag)
				{
					list.Add((process, item));
				}
				else
				{
					process.Dispose();
				}
			}
			return list;
		}

		private static void Dispose(List<(Process Process, bool PathKnown)> processes)
		{
			foreach (var process in processes)
			{
				process.Process.Dispose();
			}
		}

		private static bool IsProcessRunning(string processName, string? installFolder)
		{
			List<(Process, bool)> list = FindProcesses(processName, installFolder);
			try
			{
				return list.Count > 0;
			}
			finally
			{
				Dispose(list);
			}
		}

		private static bool HasOpenWindows(string processName, string? installFolder)
		{
			List<(Process, bool)> list = FindProcesses(processName, installFolder);
			try
			{
				return list.Any(((Process Process, bool PathKnown) item) => OwnsWindow(item.Process));
			}
			finally
			{
				Dispose(list);
			}
		}

		private static bool StopWindowlessProcesses(string processName, string? installFolder)
		{
			List<(Process, bool)> list = FindProcesses(processName, installFolder);
			try
			{
				if (list.Count == 0)
				{
					return true;
				}
				if (list.Any(((Process Process, bool PathKnown) tuple) => OwnsWindow(tuple.Process) || !tuple.PathKnown))
				{
					return false;
				}
				foreach (var item3 in list)
				{
					Process item = item3.Item1;
					try
					{
						item.Kill(entireProcessTree: true);
					}
					catch
					{
					}
				}
				foreach (var item4 in list)
				{
					Process item2 = item4.Item1;
					try
					{
						item2.WaitForExit(5000);
					}
					catch
					{
					}
				}
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(32, 2, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("stopped ");
					message.AppendFormatted(list.Count);
					message.AppendLiteral(" windowless ");
					message.AppendFormatted(processName);
					message.AppendLiteral(" process(es)");
				}
				Log(ref message);
				return true;
			}
			finally
			{
				Dispose(list);
			}
		}

		private static bool OwnsWindow(Process process)
		{
			try
			{
				return !process.HasExited && process.MainWindowHandle != IntPtr.Zero;
			}
			catch
			{
				return true;
			}
		}

