				System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86), "LibreOffice", "program", "swriter.exe")
			}.Any(File.Exists);
		}
	}
	internal sealed record FontCheckLauncher(string DisplayName, IReadOnlyList<string> Executables);
	internal sealed class ManualApplicationFontAdapter(string id, string displayName, MessageKey scope, Func<bool> isInstalled) : IApplicationFontAdapter
	{
		public string Id => id;

		public ApplicationFontTargetInfo Inspect(string fontFamily, bool thorough = false)
		{
			bool flag = isInstalled();
			return new ApplicationFontTargetInfo(id, displayName, SmartInput.Core.Text.Localization.MessageText.Get(scope), flag, CanApply: false, flag ? ApplicationFontTargetState.ManualSetup : ApplicationFontTargetState.NotInstalled, flag ? SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusManualSetup) : SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNotInstalled));
		}

		public ApplicationFontTargetInfo Apply(string fontFamily)
		{
			return Inspect(fontFamily);
		}

		public ApplicationFontTargetInfo Restore()
		{
			return Inspect(string.Empty);
		}
	}
	internal sealed class ChromiumApplicationFontAdapter : IApplicationFontAdapter
	{
		private static readonly string[] FontPreferencePaths = new string[6] { "webkit.webprefs.fonts.standard.Zyyy", "webkit.webprefs.fonts.sansserif.Zyyy", "webkit.webprefs.fonts.serif.Zyyy", "webkit.webprefs.fonts.standard.Arab", "webkit.webprefs.fonts.sansserif.Arab", "webkit.webprefs.fonts.serif.Arab" };

		private readonly string _displayName;

		private readonly MessageKey _scope;

		private readonly string _userDataPath;

		private readonly string _processName;

		private readonly ApplicationFontBackupStore _backups;

		private readonly Func<string, bool> _isProcessRunning;

		private readonly Func<string, bool> _hasOpenWindows;

		private readonly Func<string, bool> _stopWindowlessProcesses;

		public string Id { get; }

		public ChromiumApplicationFontAdapter(string id, string displayName, MessageKey scope, string userDataPath, string processName, ApplicationFontBackupStore backups, Func<string, bool> isProcessRunning, Func<string, bool>? hasOpenWindows = null, Func<string, bool>? stopWindowlessProcesses = null)
		{
			Id = id;
			_displayName = displayName;
			_scope = scope;
			_userDataPath = userDataPath;
			_processName = processName;
			_backups = backups;
			_isProcessRunning = isProcessRunning;
			_hasOpenWindows = hasOpenWindows ?? ((Func<string, bool>)((string _) => true));
			_stopWindowlessProcesses = stopWindowlessProcesses ?? ((Func<string, bool>)((string _) => false));
		}

		public ApplicationFontTargetInfo Inspect(string fontFamily, bool thorough = false)
		{
			if (!Directory.Exists(_userDataPath))
			{
				return Result(installed: false, canApply: false, ApplicationFontTargetState.NotInstalled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNotInstalled));
			}
			IReadOnlyList<string> preferenceFiles = GetPreferenceFiles();
			if (preferenceFiles.Count == 0)
			{
				return Result(installed: true, canApply: false, ApplicationFontTargetState.ManualSetup, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusOpenAppOnce));
			}
			if (ProfilesUseFont(preferenceFiles, fontFamily))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Written, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusWrittenToProfiles, preferenceFiles.Count));
			}
			if (_backups.WasApplied(Id, fontFamily))
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(58, 4, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("inspect target=");
					message.AppendFormatted(Id);
					message.AppendLiteral(" font=\"");
					message.AppendFormatted(fontFamily);
					message.AppendLiteral("\" appliedAt=");
					message.AppendFormatted(_backups.GetAppliedAt(Id), "O");
					message.AppendLiteral(" found={");
					message.AppendFormatted(DescribeProfiles(preferenceFiles));
					message.AppendLiteral("} state=Reverted");
				}
				Log(ref message);
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Reverted, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusReverted, _displayName));
			}
			if (!_isProcessRunning(_processName))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusReadyProfiles, preferenceFiles.Count));
			}
			if (!_hasOpenWindows(_processName))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusReadyStopBackground, preferenceFiles.Count, _displayName));
			}
			return CloseWindowsResult();
		}

		private bool EnsureNotRunning()
		{
			if (!_isProcessRunning(_processName))
			{
				return true;
			}
			if (_hasOpenWindows(_processName))
			{
				return false;
			}
			if (_stopWindowlessProcesses(_processName))
			{
				return !_isProcessRunning(_processName);
			}
			return false;
		}

		private ApplicationFontTargetInfo CloseWindowsResult()
		{
			return Result(installed: true, canApply: true, ApplicationFontTargetState.CloseApplication, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusCloseAllWindows, _displayName));
		}

		public ApplicationFontTargetInfo Apply(string fontFamily)
		{
			ApplicationFontTargetInfo applicationFontTargetInfo = Inspect(fontFamily);
			if (!applicationFontTargetInfo.CanApply || applicationFontTargetInfo.State == ApplicationFontTargetState.Written)
			{
				return applicationFontTargetInfo;
			}
			bool shouldAppend;
			if (!EnsureNotRunning())
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(94, 2, out shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("apply target=");
					message.AppendFormatted(Id);
					message.AppendLiteral(" font=\"");
					message.AppendFormatted(fontFamily);
					message.AppendLiteral("\" state=CloseApplication (a window is open or a process survived the stop)");
				}
				Log(ref message);
				return CloseWindowsResult();
			}
			List<(string, string, string)> list = new List<(string, string, string)>();
			foreach (string preferenceFile in GetPreferenceFiles())
			{
				string text = File.ReadAllText(preferenceFile);
				JsonObject root = ParseObject(text, preferenceFile);
				_backups.GetOrAdd(Id, preferenceFile, () => FontPreferencePaths.ToDictionary((string key) => key, (string key) => GetString(root, key), StringComparer.Ordinal));
				string[] fontPreferencePaths = FontPreferencePaths;
				foreach (string path in fontPreferencePaths)
				{
					SetString(root, path, fontFamily);
				}
				list.Add((preferenceFile, text, root.ToJsonString()));
			}
			if (_isProcessRunning(_processName))
			{
				DiagnosticMessageHandler message2 = new DiagnosticMessageHandler(89, 2, out shouldAppend);
				if (shouldAppend)
				{
					message2.AppendLiteral("apply target=");
					message2.AppendFormatted(Id);
					message2.AppendLiteral(" font=\"");
					message2.AppendFormatted(fontFamily);
					message2.AppendLiteral("\" state=CloseApplication (the browser started again before the write)");
				}
				Log(ref message2);
				return CloseWindowsResult();
			}
			WriteTransaction(list);
			string[] array = list.Select(((string Path, string Original, string Updated) item) => item.Path).ToArray();
			if (!ProfilesUseFont(array, fontFamily))
			{
				throw new InvalidOperationException("The browser font preferences could not be verified.");
			}
			_backups.SetAppliedFont(Id, fontFamily);
			DiagnosticMessageHandler message3 = new DiagnosticMessageHandler(54, 4, out shouldAppend);
			if (shouldAppend)
			{
				message3.AppendLiteral("apply target=");
				message3.AppendFormatted(Id);
				message3.AppendLiteral(" font=\"");
				message3.AppendFormatted(fontFamily);
				message3.AppendLiteral("\" wrote=");
				message3.AppendFormatted(array.Length);
				message3.AppendLiteral(" profiles=[");
				message3.AppendFormatted(string.Join(", ", array.Select(ProfileName)));
				message3.AppendLiteral("] state=Written");
			}
			Log(ref message3);
			return Result(installed: true, canApply: true, ApplicationFontTargetState.Written, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusWrittenToProfiles, array.Length));
		}

		public ApplicationFontTargetInfo Restore()
		{
			if (!Directory.Exists(_userDataPath))
			{
				return Result(installed: false, canApply: false, ApplicationFontTargetState.NotInstalled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNotInstalled));
			}
			if (!EnsureNotRunning())
			{
				return CloseWindowsResult();
			}
			IReadOnlyDictionary<string, Dictionary<string, string>> target = _backups.GetTarget(Id);
			if (target.Count == 0)
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNoBackup));
			}
			List<(string, string, string)> list = new List<(string, string, string)>();
			foreach (KeyValuePair<string, Dictionary<string, string>> item in target)
			{
				item.Deconstruct(out var key, out var value);
				string text = key;
				Dictionary<string, string> dictionary = value;
				if (!File.Exists(text))
				{
					continue;
				}
				string text2 = File.ReadAllText(text);
				JsonObject jsonObject = ParseObject(text2, text);
				foreach (KeyValuePair<string, string> item2 in dictionary)
				{
					item2.Deconstruct(out key, out var value2);
					string path = key;
					string text3 = value2;
					if (text3 == null)
					{
						Remove(jsonObject, path);
					}
					else
					{
						SetString(jsonObject, path, text3);
					}
				}
				list.Add((text, text2, jsonObject.ToJsonString()));
			}
			WriteTransaction(list);
			_backups.ClearTarget(Id);
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(34, 2, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("restore target=");
				message.AppendFormatted(Id);
				message.AppendLiteral(" wrote=");
				message.AppendFormatted(list.Count);
				message.AppendLiteral(" state=Ready");
			}
			Log(ref message);
			return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusRestored));
		}

		private IReadOnlyList<string> GetPreferenceFiles()
		{
			try
			{
				IEnumerable<string> source = from path in Directory.EnumerateDirectories(_userDataPath).Where((string path) =>
					{
						string fileName = System.IO.Path.GetFileName(path);
						return string.Equals(fileName, "Default", StringComparison.OrdinalIgnoreCase) || fileName.StartsWith("Profile ", StringComparison.OrdinalIgnoreCase);
					})
					select System.IO.Path.Combine(path, "Preferences");
				string element = System.IO.Path.Combine(_userDataPath, "Preferences");
				return source.Append(element).Where(File.Exists).Distinct(StringComparer.OrdinalIgnoreCase)
					.OrderBy((string path) => path, StringComparer.OrdinalIgnoreCase)
					.ToArray();
			}
			catch
			{
				return Array.Empty<string>();
			}
		}

		private static string ProfileName(string preferencesPath)
		{
			return System.IO.Path.GetFileName(System.IO.Path.GetDirectoryName(preferencesPath)) ?? string.Empty;
		}

		private static string DescribeProfiles(IEnumerable<string> paths)
		{
			return string.Join(", ", paths.Select((string path) =>
			{
				try
				{
					return ProfileName(path) + ":" + DiagnosticLog.Escaped(GetString(ParseObject(File.ReadAllText(path), path), FontPreferencePaths[0]));
				}
				catch (Exception ex)
				{
					return ProfileName(path) + ":unreadable " + ex.GetType().Name;
				}
			}));
		}

		private static void Log(ref DiagnosticMessageHandler message)
		{
			DiagnosticLog.Write("Fonts", ref message);
		}

		private static bool ProfilesUseFont(IEnumerable<string> paths, string fontFamily)
		{
			if (string.IsNullOrWhiteSpace(fontFamily))
			{
				return false;
			}
			foreach (string path in paths)
			{
				try
				{
					JsonObject root = ParseObject(File.ReadAllText(path), path);
					if (FontPreferencePaths.Any((string key) => !string.Equals(GetString(root, key), fontFamily, StringComparison.OrdinalIgnoreCase)))
					{
						return false;
					}
				}
				catch
				{
					return false;
				}
			}
			return true;
		}

		private static JsonObject ParseObject(string json, string path)
		{
			return (JsonNode.Parse(json) as JsonObject) ?? throw new InvalidDataException("Invalid browser preferences: " + path);
		}

		private static string? GetString(JsonObject root, string path)
		{
			JsonNode jsonNode = root;
			string[] array = path.Split('.');
			foreach (string propertyName in array)
			{
				jsonNode = (jsonNode as JsonObject)?[propertyName];
				if (jsonNode == null)
				{
					return null;
				}
			}
			try
			{
				return jsonNode.GetValue<string>();
			}
			catch
			{
				return null;
			}
		}

		private static void SetString(JsonObject root, string path, string value)
		{
			string[] array = path.Split('.');
			JsonObject jsonObject = root;
			for (int i = 0; i < array.Length - 1; i++)
			{
				JsonObject jsonObject2 = jsonObject[array[i]] as JsonObject;
				if (jsonObject2 == null)
				{
					jsonObject2 = new JsonObject();
					jsonObject[array[i]] = jsonObject2;
				}
				jsonObject = jsonObject2;
			}
			jsonObject[array[^1]] = value;
		}

		private static void Remove(JsonObject root, string path)
		{
			string[] array = path.Split('.');
			JsonObject jsonObject = root;
			for (int i = 0; i < array.Length - 1; i++)
			{
				if (!(jsonObject[array[i]] is JsonObject jsonObject2))
				{
					return;
				}
				jsonObject = jsonObject2;
			}
			jsonObject.Remove(array[^1]);
		}

		private static void WriteTransaction(IReadOnlyList<(string Path, string Original, string Updated)> files)
		{
			List<(string, string)> list = new List<(string, string)>();
			try
			{
				foreach (var file in files)
				{
					WriteAtomic(file.Path, file.Updated);
					list.Add((file.Path, file.Original));
				}
			}
			catch
			{
				foreach (var item in list)
				{
					WriteAtomic(item.Item1, item.Item2);
				}
				throw;
			}
		}

		private static void WriteAtomic(string path, string content)
		{
			string text = path + ".coco.tmp";
			File.WriteAllText(text, content);
			File.Move(text, path, overwrite: true);
		}

		private ApplicationFontTargetInfo Result(bool installed, bool canApply, ApplicationFontTargetState state, string status)
		{
			return new ApplicationFontTargetInfo(Id, _displayName, SmartInput.Core.Text.Localization.MessageText.Get(_scope), installed, canApply, state, status);
		}
	}
	internal sealed class FirefoxApplicationFontAdapter : IApplicationFontAdapter
	{
		private const string ManagedStart = "// Diyar application fonts - begin";

		private const string ManagedEnd = "// Diyar application fonts - end";

		private static readonly string[] FontPreferences = new string[6] { "font.default.x-unicode", "font.name.sans-serif.x-unicode", "font.name.serif.x-unicode", "font.default.ar", "font.name.sans-serif.ar", "font.name.serif.ar" };

		private static readonly string[] FamilyPreferences = new string[4] { "font.name.sans-serif.x-unicode", "font.name.serif.x-unicode", "font.name.sans-serif.ar", "font.name.serif.ar" };

		private readonly string _profilesPath;

		private readonly ApplicationFontBackupStore _backups;

		private readonly Func<string, bool> _isProcessRunning;

		private readonly string _displayName;

		private readonly string _processName;

		public string Id { get; }

		private MessageKey Scope { get; }

		public FirefoxApplicationFontAdapter(string profilesPath, ApplicationFontBackupStore backups, Func<string, bool> isProcessRunning, string id = "firefox", string displayName = "Mozilla Firefox", string processName = "firefox", MessageKey scope = MessageKey.FontScopeWebFallback)
		{
			_profilesPath = profilesPath;
			_backups = backups;
			_isProcessRunning = isProcessRunning;
			Id = id;
			_displayName = displayName;
			_processName = processName;
			Scope = scope;
		}

		public ApplicationFontTargetInfo Inspect(string fontFamily, bool thorough = false)
		{
			if (!Directory.Exists(_profilesPath))
			{
				return Result(installed: false, canApply: false, ApplicationFontTargetState.NotInstalled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNotInstalled));
			}
			IReadOnlyList<string> profiles = GetProfiles();
			if (profiles.Count == 0)
			{
				return Result(installed: true, canApply: false, ApplicationFontTargetState.ManualSetup, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusOpenAppOnce));
			}
			if (profiles.All((string profile) => ManagedBlockMatches(profile, fontFamily)))
			{
				if (!profiles.All((string profile) => PrefsCarryFont(profile, fontFamily)))
				{
					return Result(installed: true, canApply: true, ApplicationFontTargetState.Written, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusWrittenRestart, profiles.Count, _displayName));
				}
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Applied, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusAppliedToProfiles, profiles.Count));
			}
			if (_backups.WasApplied(Id, fontFamily))
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(59, 4, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("inspect target=");
					message.AppendFormatted(Id);
					message.AppendLiteral(" font=\"");
					message.AppendFormatted(fontFamily);
					message.AppendLiteral("\" appliedAt=");
					message.AppendFormatted(_backups.GetAppliedAt(Id), "O");
					message.AppendLiteral(" profiles=");
					message.AppendFormatted(profiles.Count);
					message.AppendLiteral(" state=Reverted");
				}
				Log(ref message);
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Reverted, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusReverted, _displayName));
			}
			if (!_isProcessRunning(_processName))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusReadyProfiles, profiles.Count));
			}
			return Result(installed: true, canApply: true, ApplicationFontTargetState.CloseApplication, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusClose, _displayName));
		}

		public ApplicationFontTargetInfo Apply(string fontFamily)
		{
			ApplicationFontTargetInfo applicationFontTargetInfo = Inspect(fontFamily);
			bool shouldAppend = !applicationFontTargetInfo.CanApply;
			if (!shouldAppend)
			{
				ApplicationFontTargetState state = applicationFontTargetInfo.State;
				bool flag = ((state == ApplicationFontTargetState.Applied || state == ApplicationFontTargetState.Written) ? true : false);
				shouldAppend = flag;
			}
			if (shouldAppend)
			{
				return applicationFontTargetInfo;
			}
			if (_isProcessRunning(_processName))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.CloseApplication, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusClose, _displayName));
			}
			IReadOnlyList<string> profiles = GetProfiles();
			List<(string, string, string)> list = new List<(string, string, string)>();
			foreach (string item in profiles)
			{
				string path = System.IO.Path.Combine(item, "prefs.js");
				string prefs = (File.Exists(path) ? File.ReadAllText(path) : string.Empty);
				_backups.GetOrAdd(Id, item, () => FontPreferences.ToDictionary((string key) => key, (string key) => GetPreferenceValue(prefs, key), StringComparer.Ordinal));
				string text = System.IO.Path.Combine(item, "user.js");
				string text2 = (File.Exists(text) ? File.ReadAllText(text) : string.Empty);
				list.Add((text, text2, ReplaceManagedBlock(text2, CreateManagedBlock(fontFamily))));
			}
			WriteTransaction(list);
			if (!profiles.All((string profile) => ManagedBlockMatches(profile, fontFamily)))
			{
				throw new InvalidOperationException("The Firefox font preferences could not be verified.");
			}
			_backups.SetAppliedFont(Id, fontFamily);
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(42, 3, out shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("apply target=");
				message.AppendFormatted(Id);
				message.AppendLiteral(" font=\"");
				message.AppendFormatted(fontFamily);
				message.AppendLiteral("\" wrote=");
				message.AppendFormatted(profiles.Count);
				message.AppendLiteral(" state=Written");
			}
			Log(ref message);
			return Result(installed: true, canApply: true, ApplicationFontTargetState.Written, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusWrittenRestart, profiles.Count, _displayName));
		}

		public ApplicationFontTargetInfo Restore()
		{
			if (!Directory.Exists(_profilesPath))
			{
				return Result(installed: false, canApply: false, ApplicationFontTargetState.NotInstalled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNotInstalled));
			}
			if (_isProcessRunning(_processName))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.CloseApplication, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusClose, _displayName));
			}
			IReadOnlyDictionary<string, Dictionary<string, string>> target = _backups.GetTarget(Id);
			if (target.Count == 0)
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNoBackup));
			}
			List<(string, string, string)> list = new List<(string, string, string)>();
			foreach (KeyValuePair<string, Dictionary<string, string>> item in target)
			{
				item.Deconstruct(out var key, out var value);
				string text = key;
				Dictionary<string, string> dictionary = value;
				if (!Directory.Exists(text))
				{
					continue;
				}
				string text2 = System.IO.Path.Combine(text, "user.js");
				string text3 = (File.Exists(text2) ? File.ReadAllText(text2) : string.Empty);
				list.Add((text2, text3, ReplaceManagedBlock(text3, null)));
				string text4 = System.IO.Path.Combine(text, "prefs.js");
				string text5 = (File.Exists(text4) ? File.ReadAllText(text4) : string.Empty);
				foreach (KeyValuePair<string, string> item2 in dictionary)
				{
					item2.Deconstruct(out key, out var value2);
					string key2 = key;
					string rawValue = value2;
					text5 = SetPreferenceValue(text5, key2, rawValue);
				}
				list.Add((text4, File.Exists(text4) ? File.ReadAllText(text4) : string.Empty, text5));
			}
			WriteTransaction(list);
			_backups.ClearTarget(Id);
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(44, 2, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("restore target=");
				message.AppendFormatted(Id);
				message.AppendLiteral(" wrote=");
				message.AppendFormatted(list.Count);
				message.AppendLiteral(" state=RestartRequired");
			}
			Log(ref message);
			return Result(installed: true, canApply: true, ApplicationFontTargetState.RestartRequired, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusRestoredRestart, _displayName));
		}

		private IReadOnlyList<string> GetProfiles()
		{
			try
			{
				return (from path in Directory.EnumerateDirectories(_profilesPath)
					where File.Exists(System.IO.Path.Combine(path, "prefs.js"))
					select path).OrderBy((string path) => path, StringComparer.OrdinalIgnoreCase).ToArray();
			}
			catch
			{
				return Array.Empty<string>();
			}
		}

		private static bool ManagedBlockMatches(string profilePath, string fontFamily)
		{
			if (string.IsNullOrWhiteSpace(fontFamily))
			{
				return false;
			}
			string path = System.IO.Path.Combine(profilePath, "user.js");
			if (!File.Exists(path))
			{
				return false;
			}
			string value = CreateManagedBlock(fontFamily);
			return File.ReadAllText(path).Contains(value, StringComparison.Ordinal);
		}

		private static bool PrefsCarryFont(string profilePath, string fontFamily)
		{
			try
			{
				string path = System.IO.Path.Combine(profilePath, "prefs.js");
				if (!File.Exists(path))
				{
					return false;
				}
				string prefs = File.ReadAllText(path);
				return FamilyPreferences.All((string key) => string.Equals(DecodeString(GetPreferenceValue(prefs, key)), fontFamily, StringComparison.OrdinalIgnoreCase));
			}
			catch (IOException)
			{
				return false;
			}
		}

		private static string? DecodeString(string? rawValue)
		{
			if (rawValue == null)
			{
				return null;
			}
			try
			{
				return JsonSerializer.Deserialize<string>(rawValue);
			}
			catch (JsonException)
			{
				return null;
			}
		}

		private static void Log(ref DiagnosticMessageHandler message)
		{
			DiagnosticLog.Write("Fonts", ref message);
		}

		private static string CreateManagedBlock(string fontFamily)
		{
			string text = JsonSerializer.Serialize(fontFamily);
			string newLine = Environment.NewLine;
			InlineArray8<string> buffer = default;
			buffer[0] = "// Diyar application fonts - begin";
			buffer[1] = "user_pref(\"font.default.x-unicode\", \"sans-serif\");";
			buffer[2] = "user_pref(\"font.name.sans-serif.x-unicode\", " + text + ");";
			buffer[3] = "user_pref(\"font.name.serif.x-unicode\", " + text + ");";
			buffer[4] = "user_pref(\"font.default.ar\", \"sans-serif\");";
			buffer[5] = "user_pref(\"font.name.sans-serif.ar\", " + text + ");";
			buffer[6] = "user_pref(\"font.name.serif.ar\", " + text + ");";
			buffer[7] = "// Diyar application fonts - end";
			return string.Join(newLine, (ReadOnlySpan<string?>)buffer);
		}

		private static string ReplaceManagedBlock(string content, string? replacement)
		{
			string text = ManagedBlockRegex().Replace(content, string.Empty).TrimEnd();
			if (string.IsNullOrEmpty(replacement))
			{
				if (!string.IsNullOrEmpty(text))
				{
					return text + Environment.NewLine;
				}
				return string.Empty;
			}
			if (!string.IsNullOrEmpty(text))
			{
				return text + Environment.NewLine + Environment.NewLine + replacement + Environment.NewLine;
			}
			return replacement + Environment.NewLine;
		}

		private static string? GetPreferenceValue(string content, string key)
		{
			return PreferenceRegex(key).Matches(content).Cast<Match>().LastOrDefault()?.Groups["value"].Value.Trim();
		}

		private static string SetPreferenceValue(string content, string key, string? rawValue)
		{
			string text = PreferenceRegex(key).Replace(content, string.Empty).TrimEnd();
			if (rawValue == null)
			{
				if (!string.IsNullOrEmpty(text))
				{
					return text + Environment.NewLine;
				}
				return string.Empty;
			}
			string text2 = $"user_pref(\"{key}\", {rawValue});";
			if (!string.IsNullOrEmpty(text))
			{
				return text + Environment.NewLine + text2 + Environment.NewLine;
			}
			return text2 + Environment.NewLine;
		}

		private static Regex PreferenceRegex(string key)
		{
			return new Regex("^[ \\t]*user_pref\\(\\\"" + Regex.Escape(key) + "\\\"[ \\t]*,[ \\t]*(?<value>.*?)[ \\t]*\\);[ \\t]*(?:\\r?\\n|$)", RegexOptions.Multiline | RegexOptions.CultureInvariant);
		}

