		private static void WriteTransaction(IReadOnlyList<(string Path, string Original, string Updated)> files)
		{
			List<(string, string)> list = new List<(string, string)>();
			try
			{
				foreach (var file in files)
				{
					WriteAtomic(file.Path, file.Updated);
					list.Add((file.Path, file.Original));
				}
			}
			catch
			{
				foreach (var item in list)
				{
					WriteAtomic(item.Item1, item.Item2);
				}
				throw;
			}
		}

		private static void WriteAtomic(string path, string content)
		{
			Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path) ?? throw new InvalidOperationException("The Firefox preference path has no directory."));
			string text = path + ".coco.tmp";
			File.WriteAllText(text, content);
			File.Move(text, path, overwrite: true);
		}

		private ApplicationFontTargetInfo Result(bool installed, bool canApply, ApplicationFontTargetState state, string status)
		{
			return new ApplicationFontTargetInfo(Id, _displayName, SmartInput.Core.Text.Localization.MessageText.Get(Scope), installed, canApply, state, status);
		}
	}
	internal static class InstalledFonts
	{
		public static bool Contains(string family)
		{
			if (string.IsNullOrWhiteSpace(family))
			{
				return false;
			}
			try
			{
				using InstalledFontCollection installedFontCollection = new InstalledFontCollection();
				if (installedFontCollection.Families.Any((System.Drawing.FontFamily installed) => string.Equals(installed.Name, family, StringComparison.OrdinalIgnoreCase)))
				{
					return true;
				}
			}
			catch
			{
			}
			try
			{
				return Fonts.SystemFontFamilies.Any((System.Windows.Media.FontFamily installed) => string.Equals(installed.Source, family, StringComparison.OrdinalIgnoreCase) || installed.FamilyNames.Values.Any((string name) => string.Equals(name, family, StringComparison.OrdinalIgnoreCase)));
			}
			catch
			{
				return true;
			}
		}
	}
	internal sealed class JsonSettingsApplicationFontAdapter : IApplicationFontAdapter
	{
		internal const string OriginalFileBackupKey = "__originalFile";

		private static readonly JsonDocumentOptions ParseOptions = new JsonDocumentOptions
		{
			CommentHandling = JsonCommentHandling.Skip,
			AllowTrailingCommas = true
		};

		private static readonly JsonSerializerOptions WriteOptions = new JsonSerializerOptions
		{
			WriteIndented = true
		};

		private readonly string _displayName;

		private readonly MessageKey _scope;

		private readonly string _settingsPath;

		private readonly IReadOnlyList<string[]> _fontKeys;

		private readonly ApplicationFontBackupStore _backups;

		public string Id { get; }

		public JsonSettingsApplicationFontAdapter(string id, string displayName, MessageKey scope, string settingsPath, IReadOnlyList<string[]> fontKeys, ApplicationFontBackupStore backups)
		{
			Id = id;
			_displayName = displayName;
			_scope = scope;
			_settingsPath = settingsPath;
			_fontKeys = fontKeys;
			_backups = backups;
		}

		public ApplicationFontTargetInfo Inspect(string fontFamily, bool thorough = false)
		{
			if (!File.Exists(_settingsPath))
			{
				string directoryName = System.IO.Path.GetDirectoryName(_settingsPath);
				if (directoryName == null || !Directory.Exists(directoryName))
				{
					return Result(installed: false, canApply: false, ApplicationFontTargetState.NotInstalled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNotInstalled));
				}
				return Result(installed: true, canApply: false, ApplicationFontTargetState.ManualSetup, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusOpenAppOnce));
			}
			if (!TryReadRoot(out JsonObject root))
			{
				return Result(installed: true, canApply: false, ApplicationFontTargetState.ManualSetup, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusInvalidJson));
			}
			if (UsesFont(root, fontFamily))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Applied, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusApplied));
			}
			if (_backups.WasApplied(Id, fontFamily))
			{
				DiagnosticMessageHandler message = new DiagnosticMessageHandler(58, 4, out var shouldAppend);
				if (shouldAppend)
				{
					message.AppendLiteral("inspect target=");
					message.AppendFormatted(Id);
					message.AppendLiteral(" font=\"");
					message.AppendFormatted(fontFamily);
					message.AppendLiteral("\" appliedAt=");
					message.AppendFormatted(_backups.GetAppliedAt(Id), "O");
					message.AppendLiteral(" found=\"");
					message.AppendFormatted(DiagnosticLog.Escaped(GetValue(root, _fontKeys[0])));
					message.AppendLiteral("\" state=Reverted");
				}
				Log(ref message);
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Reverted, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusReverted, _displayName));
			}
			return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusReady));
		}

		public ApplicationFontTargetInfo Apply(string fontFamily)
		{
			ApplicationFontTargetInfo applicationFontTargetInfo = Inspect(fontFamily);
			if (!applicationFontTargetInfo.CanApply || applicationFontTargetInfo.State == ApplicationFontTargetState.Applied)
			{
				return applicationFontTargetInfo;
			}
			string original = File.ReadAllText(_settingsPath);
			if (!TryReadRoot(out JsonObject root))
			{
				return Result(installed: true, canApply: false, ApplicationFontTargetState.ManualSetup, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusInvalidJson));
			}
			_backups.GetOrAdd(Id, _settingsPath, () => new Dictionary<string, string>(StringComparer.Ordinal) { ["__originalFile"] = original });
			foreach (string[] fontKey in _fontKeys)
			{
				SetValue(root, fontKey, fontFamily);
			}
			Write(root.ToJsonString(WriteOptions));
			if (!TryReadRoot(out JsonObject root2) || !UsesFont(root2, fontFamily))
			{
				throw new InvalidOperationException("The " + _displayName + " font setting could not be verified.");
			}
			_backups.SetAppliedFont(Id, fontFamily);
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(41, 3, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("apply target=");
				message.AppendFormatted(Id);
				message.AppendLiteral(" font=\"");
				message.AppendFormatted(fontFamily);
				message.AppendLiteral("\" keys=");
				message.AppendFormatted(_fontKeys.Count);
				message.AppendLiteral(" state=Applied");
			}
			Log(ref message);
			return Result(installed: true, canApply: true, ApplicationFontTargetState.Applied, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusApplied));
		}

		public ApplicationFontTargetInfo Restore()
		{
			if (!File.Exists(_settingsPath))
			{
				return Result(installed: false, canApply: false, ApplicationFontTargetState.NotInstalled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNotInstalled));
			}
			if (!_backups.GetTarget(Id).TryGetValue(_settingsPath, out Dictionary<string, string> value) || !value.TryGetValue("__originalFile", out var value2) || value2 == null)
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNoBackup));
			}
			Write(value2);
			_backups.ClearTarget(Id);
			return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusRestored));
		}

		private static void Log(ref DiagnosticMessageHandler message)
		{
			DiagnosticLog.Write("Fonts", ref message);
		}

		private bool TryReadRoot(out JsonObject root)
		{
			try
			{
				string text = File.ReadAllText(_settingsPath);
				root = (JsonNode.Parse(string.IsNullOrWhiteSpace(text) ? "{}" : text, null, ParseOptions) as JsonObject) ?? throw new InvalidOperationException("The settings root is not a JSON object.");
				return true;
			}
			catch
			{
				root = new JsonObject();
				return false;
			}
		}

		private bool UsesFont(JsonObject root, string fontFamily)
		{
			if (!string.IsNullOrWhiteSpace(fontFamily))
			{
				return _fontKeys.All((string[] key) => string.Equals(GetValue(root, key), fontFamily, StringComparison.OrdinalIgnoreCase));
			}
			return false;
		}

		private static string? GetValue(JsonObject root, IReadOnlyList<string> key)
		{
			JsonNode jsonNode = root;
			foreach (string item in key)
			{
				if (!(jsonNode is JsonObject jsonObject) || !jsonObject.TryGetPropertyValue(item, out jsonNode))
				{
					return null;
				}
			}
			return jsonNode?.GetValue<string>();
		}

		private static void SetValue(JsonObject root, IReadOnlyList<string> key, string value)
		{
			JsonObject jsonObject = root;
			for (int i = 0; i < key.Count - 1; i++)
			{
				JsonObject jsonObject2 = jsonObject[key[i]] as JsonObject;
				if (jsonObject2 == null)
				{
					jsonObject2 = new JsonObject();
					jsonObject[key[i]] = jsonObject2;
				}
				jsonObject = jsonObject2;
			}
			jsonObject[key[key.Count - 1]] = value;
		}

		private void Write(string content)
		{
			string text = _settingsPath + ".coco.tmp";
			File.WriteAllText(text, content);
			File.Move(text, _settingsPath, overwrite: true);
		}

		private ApplicationFontTargetInfo Result(bool installed, bool canApply, ApplicationFontTargetState state, string status)
		{
			return new ApplicationFontTargetInfo(Id, _displayName, SmartInput.Core.Text.Localization.MessageText.Get(_scope), installed, canApply, state, status);
		}
	}
	internal sealed record WordFontSnapshot(string Name, string NameBi);
	internal interface IWordFontBridge
	{
		bool IsInstalled { get; }

		WordFontSnapshot Read();

		WordFontSnapshot Write(string name, string nameBi);
	}
	internal sealed class WordApplicationFontAdapter : IApplicationFontAdapter
	{
		private const string BackupItemId = "normal-template";

		private const string DisplayName = "Microsoft Word";

		private readonly ApplicationFontBackupStore _backups;

		private readonly IWordFontBridge _bridge;

		private readonly Func<string, bool> _isProcessRunning;

		public string Id => "word";

		public WordApplicationFontAdapter(ApplicationFontBackupStore backups, IWordFontBridge bridge, Func<string, bool> isProcessRunning)
		{
			_backups = backups;
			_bridge = bridge;
			_isProcessRunning = isProcessRunning;
		}

		public ApplicationFontTargetInfo Inspect(string fontFamily, bool thorough = false)
		{
			if (!_bridge.IsInstalled)
			{
				return Result(installed: false, canApply: false, ApplicationFontTargetState.NotInstalled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNotInstalled));
			}
			if (_backups.WasApplied(Id, fontFamily))
			{
				if (thorough && !_isProcessRunning("WINWORD"))
				{
					WordFontSnapshot wordFontSnapshot = _bridge.Read();
					if (!UsesFont(wordFontSnapshot, fontFamily))
					{
						DiagnosticMessageHandler message = new DiagnosticMessageHandler(64, 5, out var shouldAppend);
						if (shouldAppend)
						{
							message.AppendLiteral("inspect target=");
							message.AppendFormatted(Id);
							message.AppendLiteral(" font=\"");
							message.AppendFormatted(fontFamily);
							message.AppendLiteral("\" appliedAt=");
							message.AppendFormatted(_backups.GetAppliedAt(Id), "O");
							message.AppendLiteral(" found=(\"");
							message.AppendFormatted(DiagnosticLog.Escaped(wordFontSnapshot.Name));
							message.AppendLiteral("\", \"");
							message.AppendFormatted(DiagnosticLog.Escaped(wordFontSnapshot.NameBi));
							message.AppendLiteral("\") state=Reverted");
						}
						Log(ref message);
						return Result(installed: true, canApply: true, ApplicationFontTargetState.Reverted, SmartInput.Core.Text.Localization.MessageText.Format(MessageKey.FontStatusReverted, "Microsoft Word"));
					}
				}
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Applied, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusAppliedNewDocuments));
			}
			if (!_isProcessRunning("WINWORD"))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusReady));
			}
			return Result(installed: true, canApply: true, ApplicationFontTargetState.CloseApplication, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusCloseWord));
		}

		public ApplicationFontTargetInfo Apply(string fontFamily)
		{
			ApplicationFontTargetInfo applicationFontTargetInfo = Inspect(fontFamily);
			if (!applicationFontTargetInfo.CanApply || applicationFontTargetInfo.State == ApplicationFontTargetState.Applied)
			{
				return applicationFontTargetInfo;
			}
			if (_isProcessRunning("WINWORD"))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.CloseApplication, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusCloseWord));
			}
			WordFontSnapshot previous = _bridge.Read();
			_backups.GetOrAdd(Id, "normal-template", () => new Dictionary<string, string>
			{
				["Name"] = previous.Name,
				["NameBi"] = previous.NameBi
			});
			WordFontSnapshot wordFontSnapshot = _bridge.Write(fontFamily, fontFamily);
			if (!UsesFont(wordFontSnapshot, fontFamily))
			{
				throw new InvalidOperationException("Word did not retain the selected font.");
			}
			_backups.SetAppliedFont(Id, fontFamily);
			DiagnosticMessageHandler message = new DiagnosticMessageHandler(53, 4, out var shouldAppend);
			if (shouldAppend)
			{
				message.AppendLiteral("apply target=");
				message.AppendFormatted(Id);
				message.AppendLiteral(" font=\"");
				message.AppendFormatted(fontFamily);
				message.AppendLiteral("\" readback=(\"");
				message.AppendFormatted(DiagnosticLog.Escaped(wordFontSnapshot.Name));
				message.AppendLiteral("\", \"");
				message.AppendFormatted(DiagnosticLog.Escaped(wordFontSnapshot.NameBi));
				message.AppendLiteral("\") state=Applied");
			}
			Log(ref message);
			return Result(installed: true, canApply: true, ApplicationFontTargetState.Applied, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusAppliedNewDocuments));
		}

		public ApplicationFontTargetInfo Restore()
		{
			if (!_bridge.IsInstalled)
			{
				return Result(installed: false, canApply: false, ApplicationFontTargetState.NotInstalled, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNotInstalled));
			}
			if (_isProcessRunning("WINWORD"))
			{
				return Result(installed: true, canApply: true, ApplicationFontTargetState.CloseApplication, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusCloseWord));
			}
			if (_backups.GetTarget(Id).TryGetValue("normal-template", out Dictionary<string, string> value))
			{
				string valueOrDefault = value.GetValueOrDefault("Name");
				if (valueOrDefault != null)
				{
					string nameBi = value.GetValueOrDefault("NameBi") ?? valueOrDefault;
					_bridge.Write(valueOrDefault, nameBi);
					_backups.ClearTarget(Id);
					return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusRestored));
				}
			}
			return Result(installed: true, canApply: true, ApplicationFontTargetState.Ready, SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontStatusNoBackup));
		}

		private static bool UsesFont(WordFontSnapshot snapshot, string fontFamily)
		{
			if (string.Equals(snapshot.Name, fontFamily, StringComparison.OrdinalIgnoreCase))
			{
				return string.Equals(snapshot.NameBi, fontFamily, StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		private static void Log(ref DiagnosticMessageHandler message)
		{
			DiagnosticLog.Write("Fonts", ref message);
		}

		private static ApplicationFontTargetInfo Result(bool installed, bool canApply, ApplicationFontTargetState state, string status)
		{
			return new ApplicationFontTargetInfo("word", "Microsoft Word", SmartInput.Core.Text.Localization.MessageText.Get(MessageKey.FontScopeNewDocuments), installed, canApply, state, status);
		}
	}
	internal sealed class WordFontBridge : IWordFontBridge
	{
		private const int WordNormalStyle = -1;

		public bool IsInstalled => (object)Type.GetTypeFromProgID("Word.Application") != null;

		public WordFontSnapshot Read()
		{
			return AccessNormalStyle(null);
		}

		public WordFontSnapshot Write(string name, string nameBi)
		{
			return AccessNormalStyle((name, nameBi));
		}

		private static WordFontSnapshot AccessNormalStyle((string Name, string NameBi)? write)
		{
			dynamic val = null;
			object obj = null;
			object obj2 = null;
			object obj3 = null;
			object obj4 = null;
			object obj5 = null;
			try
			{
				val = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application") ?? throw new InvalidOperationException("Microsoft Word is not installed.")) ?? throw new InvalidOperationException("Microsoft Word could not be started.");
				dynamic val2 = val;
				val2.Visible = false;
				val2.DisplayAlerts = 0;
				obj = val2.NormalTemplate;
				dynamic val3 = obj;
				obj2 = val3.OpenAsDocument();
				dynamic val4 = obj2;
				obj3 = val4.Styles;
				dynamic val5 = obj3;
				obj4 = val5[-1];
				dynamic val6 = obj4;
				obj5 = val6.Font;
				dynamic val7 = obj5;
				if (write.HasValue)
				{
					(string, string) valueOrDefault = write.GetValueOrDefault();
					val7.Name = valueOrDefault.Item1;
					val7.NameBi = valueOrDefault.Item2;
					val4.Save();
				}
				WordFontSnapshot result = new WordFontSnapshot(Convert.ToString(val7.Name) ?? string.Empty, Convert.ToString(val7.NameBi) ?? string.Empty);
				val4.Close(false);
				return result;
			}
			finally
			{
				Release(obj5);
				Release(obj4);
				Release(obj3);
				Release(obj2);
				Release(obj);
				if ((object)val != null)
				{
					try
					{
						val.Quit(false);
					}
					catch
					{
					}
				}
				Release((object?)val);
			}
		}

		private static void Release(object? value)
		{
			if (value != null && Marshal.IsComObject(value))
			{
				Marshal.FinalReleaseComObject(value);
			}
		}
	}
}
namespace SmartInput.App.Converters
{
	public class EnglishNumeralConverter : IValueConverter
	{
		public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if (value == null)
			{
				return string.Empty;
			}
			return (value.ToString() ?? string.Empty).Replace("۰", "0").Replace("۱", "1").Replace("۲", "2")
				.Replace("۳", "3")
				.Replace("۴", "4")
				.Replace("۵", "5")
				.Replace("۶", "6")
				.Replace("۷", "7")
				.Replace("۸", "8")
				.Replace("۹", "9")
				.Replace("٠", "0")
				.Replace("١", "1")
				.Replace("٢", "2")
				.Replace("٣", "3")
				.Replace("٤", "4")
				.Replace("٥", "5")
				.Replace("٦", "6")
				.Replace("٧", "7")
				.Replace("٨", "8")
				.Replace("٩", "9");
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException("EnglishNumeralConverter supports one-way conversion only.");
		}
	}
